    /// @notice Dress your banny body with outfits and a background.
    /// @dev Decoration is allowed when ALL of the following hold:
    ///
    /// 1. The caller owns the banny body (via `_checkIfSenderIsOwner`).
    /// 2. The banny body is not currently locked (`outfitLockedUntil` has not yet passed).
    /// 3. For each outfit supplied:
    ///    a. The caller is the outfit's current owner, OR
    ///    b. The outfit is currently worn by another banny body and the caller owns that banny body.
    ///    (If the outfit is unworn, only (a) applies — the outfit owner must be the caller.)
    /// 4. For the background supplied (if non-zero):
    ///    a. The caller is the background's current owner, OR
    ///    b. The background is currently used by another banny body and the caller owns that banny body.
    ///    (If the background is unused, only (a) applies — the background owner must be the caller.)
    /// 5. Outfit categories must be valid (within recognized range) and passed in ascending order.
    /// 6. Conflicting categories are rejected (e.g., a full head blocks individual face pieces;
    ///    a full suit blocks separate top/bottom).
    ///
    /// @dev WARNING: Equipped outfits and backgrounds are held by this contract on behalf of the banny body. When the
    /// banny body NFT is transferred to a new owner, all equipped assets remain associated with that body. The new
    /// owner of the body effectively gains control of all equipped items. They can unequip them, receiving the outfit
    /// NFTs, or re-equip different items. Sellers should unequip valuable outfits before transferring a banny body.
    ///
    /// @param hook The hook storing the assets.
    /// @param bannyBodyId The ID of the banny body to dress.
    /// @param backgroundId The ID of the background that'll be associated with the specified banny.
    /// @param outfitIds The IDs of the outfits that'll be associated with the specified banny. Only one outfit per
    /// outfit category allowed at a time and they must be passed in order.
    function decorateBannyWith(
        address hook,
        uint256 bannyBodyId,
        uint256 backgroundId,
        uint256[] calldata outfitIds
    )
        external
        override
        nonReentrant
    {
        // Cache the sender once to avoid repeated ERC-2771 context reads throughout the call chain.
        address sender = _msgSender();

        address bannyBodyOwner = IERC721(hook).ownerOf(bannyBodyId);
        if (bannyBodyOwner != sender) {
            revert Banny721TokenUriResolver_UnauthorizedBannyBody({
                hook: hook, bannyBodyId: bannyBodyId, sender: sender, owner: bannyBodyOwner
            });
        }

        // Make sure the bannyBodyId belongs to a body-category tier.
        uint256 bannyBodyCategory = _productOfTokenId({hook: hook, tokenId: bannyBodyId}).category;
        if (bannyBodyCategory != _BODY_CATEGORY) {
            revert Banny721TokenUriResolver_BannyBodyNotBodyCategory({
                hook: hook, bannyBodyId: bannyBodyId, category: bannyBodyCategory
            });
        }

        // Can't decorate a banny that's locked.
        // Outfit locks are user-selected display locks; timestamp tolerance is acceptable here.
        // forge-lint: disable-next-line(block-timestamp)
        if (outfitLockedUntil[hook][bannyBodyId] > block.timestamp) {
            revert Banny721TokenUriResolver_OutfitChangesLocked({
                hook: hook, bannyBodyId: bannyBodyId, lockedUntil: outfitLockedUntil[hook][bannyBodyId]
            });
        }

        emit DecorateBanny({
            hook: hook, bannyBodyId: bannyBodyId, backgroundId: backgroundId, outfitIds: outfitIds, caller: sender
        });

        // Add the background.
        _decorateBannyWithBackground({hook: hook, bannyBodyId: bannyBodyId, backgroundId: backgroundId, sender: sender});

        // Add the outfits.
        _decorateBannyWithOutfits({hook: hook, bannyBodyId: bannyBodyId, outfitIds: outfitIds, sender: sender});
    }

    /// @notice Locks a banny body ID so that it can't change its outfit for a period of time.
    /// @param hook The hook address of the collection.
    /// @param bannyBodyId The ID of the banny body to lock.
    function lockOutfitChangesFor(address hook, uint256 bannyBodyId) public override {
        // Make sure only the banny body's owner can lock it.
        _checkIfSenderIsOwner({hook: hook, upc: bannyBodyId});

        // Keep a reference to the current lock.
        uint256 currentLockedUntil = outfitLockedUntil[hook][bannyBodyId];

        // Calculate the new time at which the lock will expire.
        uint256 newLockUntil = block.timestamp + _LOCK_DURATION;

        // Make sure the new lock is at least as big as the current lock.
        if (currentLockedUntil > newLockUntil) {
            revert Banny721TokenUriResolver_CantAccelerateTheLock({
                hook: hook, bannyBodyId: bannyBodyId, currentLockedUntil: currentLockedUntil, newLockUntil: newLockUntil
            });
        }

        // Set the lock.
        outfitLockedUntil[hook][bannyBodyId] = newLockUntil;
    }

    /// @notice Handles the receipt of an ERC-721 token, only accepting transfers initiated by this contract.
    /// @dev Make sure tokens can be received if the transaction was initiated by this contract.
    /// @dev NFTs sent via transferFrom (not safeTransferFrom) bypass onERC721Received and cannot be tracked or
    /// recovered. This is an inherent ERC-721 limitation — the contract cannot prevent non-safe transfers. Users and
    /// UIs should always use safeTransferFrom.
    /// @param operator The address that initiated the transaction.
    /// @param from The address that initiated the transfer.
    /// @param tokenId The ID of the token to transfer.
    /// @param data The data of the transfer.
    /// @return The ERC-721 receiver selector.
    function onERC721Received(
        address operator,
        address from,
        uint256 tokenId,
        bytes calldata data
    )
        external
        view
        override
        returns (bytes4)
    {
        from; // unused.
        tokenId; // unused.
        data; // unused.

        // Make sure the transaction's operator is this contract.
        if (operator != address(this)) {
            revert Banny721TokenUriResolver_UnauthorizedTransfer({operator: operator, expectedOperator: address(this)});
        }

        return IERC721Receiver.onERC721Received.selector;
    }

    /// @notice Allows the owner of this contract to set the token metadata description, external URL, and SVG base URI.
    /// @dev All fields are always written. Pass the current value for any field you do not want to change,
    /// or pass an empty string to clear a field.
    /// @param description The description to use in token metadata.
    /// @param url The external URL to use in token metadata.
    /// @param baseUri The base URI of the SVG files.
    function setMetadata(
        string calldata description,
        string calldata url,
        string calldata baseUri
    )
        external
        override
        onlyOwner
    {
        svgDescription = description;
        svgExternalUrl = url;
        svgBaseUri = baseUri;

        emit SetMetadata({description: description, externalUrl: url, baseUri: baseUri, caller: _msgSender()});
    }

    /// @notice Allows the owner to set the product's name.
    /// @dev Product names are mutable — the owner can update them at any time. This is intentional to allow
    /// corrections and localization. Names are only used in metadata and do not affect on-chain logic.
    /// @param upcs The universal product codes of the products having their name stored.
    /// @param names The names of the products.
    function setProductNames(uint256[] memory upcs, string[] memory names) external override onlyOwner {
        if (upcs.length != names.length) {
            revert Banny721TokenUriResolver_ArrayLengthMismatch({firstLength: upcs.length, secondLength: names.length});
        }

        address sender = _msgSender();
        for (uint256 i; i < upcs.length;) {
            uint256 upc = upcs[i];
            string memory name = names[i];

            _customProductNameOf[upc] = name;

            emit SetProductName({upc: upc, name: name, caller: sender});
            unchecked {
                ++i;
            }
        }
    }

    /// @notice Permissionless: anyone can store the SVG bytes for a product code, as long as they match the owner-
    /// precommitted hash. The hash is set by the owner via `setSvgHashesOf`; this function only finalizes the bytes.
    /// @dev See `setSvgHashesOf` for the trust model. The function reverts on hash mismatch, missing hash, or
    /// already-stored content. Publication is one-shot — wrong-hash commitments are unrecoverable by design.
    /// @param upcs The universal product codes of the products having SVGs stored.
    /// @param svgContents The svg contents to store, not including the parent <svg></svg> element.
    function setSvgContentsOf(uint256[] memory upcs, string[] calldata svgContents) external override {
        if (upcs.length != svgContents.length) {
            revert Banny721TokenUriResolver_ArrayLengthMismatch({
                firstLength: upcs.length, secondLength: svgContents.length
            });
        }

        address sender = _msgSender();
        for (uint256 i; i < upcs.length;) {
            uint256 upc = upcs[i];
            string memory svgContent = svgContents[i];

            // Make sure there isn't already contents for the specified universal product code.
            if (bytes(_svgContentOf[upc]).length != 0) {
                revert Banny721TokenUriResolver_ContentsAlreadyStored({upc: upc});
            }

            // Get the stored svg hash for the product.
            bytes32 svgHash = svgHashOf[upc];

            // Make sure a hash exists.
            if (svgHash == bytes32(0)) revert Banny721TokenUriResolver_HashNotFound({upc: upc});

            // Make sure the content matches the hash.
            bytes32 actualHash = keccak256(abi.encodePacked(svgContent));
            if (actualHash != svgHash) {
                revert Banny721TokenUriResolver_ContentsMismatch({
                    upc: upc, expectedHash: svgHash, actualHash: actualHash
                });
            }

            // Store the svg contents.
            _svgContentOf[upc] = svgContent;

            emit SetSvgContent({upc: upc, svgContent: svgContent, caller: sender});
            unchecked {
                ++i;
            }
        }
    }

    /// @notice Allows the owner of this contract to upload the hash of an svg file for a universal product code.
    /// @dev This allows anyone to lazily upload the correct svg file.
    /// @param upcs The universal product codes of the products having SVG hashes stored.
    /// @param svgHashes The svg hashes to store, not including the parent <svg></svg> element.
    function setSvgHashesOf(uint256[] memory upcs, bytes32[] memory svgHashes) external override onlyOwner {
        if (upcs.length != svgHashes.length) {
            revert Banny721TokenUriResolver_ArrayLengthMismatch({
                firstLength: upcs.length, secondLength: svgHashes.length
            });
        }

        address sender = _msgSender();
        for (uint256 i; i < upcs.length;) {
            uint256 upc = upcs[i];
            bytes32 svgHash = svgHashes[i];

            // Make sure there isn't already contents for the specified universal product code.
            if (svgHashOf[upc] != bytes32(0)) {
                revert Banny721TokenUriResolver_HashAlreadyStored({upc: upc, existingHash: svgHashOf[upc]});
            }

            // Store the svg contents.
            svgHashOf[upc] = svgHash;

            emit SetSvgHash({upc: upc, svgHash: svgHash, caller: sender});
            unchecked {
                ++i;
            }
        }
    }

    //*********************************************************************//
    // ---------------------- internal transactions ---------------------- //
    //*********************************************************************//

    /// @notice Add a background to a banny body.
    /// @param hook The hook storing the assets.
    /// @param bannyBodyId The ID of the banny body to dress.
    /// @param backgroundId The ID of the background that'll be associated with the specified banny.
    /// @param sender The cached msg sender.
    function _decorateBannyWithBackground(
        address hook,
        uint256 bannyBodyId,
        uint256 backgroundId,
        address sender
    )
        internal
    {
        // Keep a reference to the previous background attached.
        uint256 previousBackgroundId = _attachedBackgroundIdOf[hook][bannyBodyId];

        // Keep a reference to the user of the previous background.
        uint256 userOfPreviousBackground = userOf({hook: hook, backgroundId: previousBackgroundId});

        // If the background is changing, add the latest background and transfer the old one back to the owner.
        if (backgroundId != previousBackgroundId || userOfPreviousBackground != bannyBodyId) {
            // Add the background if needed.
            if (backgroundId != 0) {
                // Keep a reference to the background's owner.
                address owner = IERC721(hook).ownerOf(backgroundId);

                // Check if the call is being made by the background's owner, or the owner of a banny body using it.
                if (sender != owner) {
                    // Get the banny body currently using this background.
                    uint256 userId = userOf({hook: hook, backgroundId: backgroundId});

                    // If the background is not currently used, only the background's owner can use it for decoration.
                    if (userId == 0) {
                        revert Banny721TokenUriResolver_UnauthorizedBackground({
                            hook: hook, backgroundId: backgroundId, sender: sender, owner: owner
                        });
                    }

                    // If the background is used, the banny body's owner can also authorize its use.
                    address userOwner = IERC721(hook).ownerOf(userId);
                    if (sender != userOwner) {
                        revert Banny721TokenUriResolver_UnauthorizedBackground({
                            hook: hook, backgroundId: backgroundId, sender: sender, owner: userOwner
                        });
                    }

                    // A locked source body keeps its equipped background until the lock expires.
                    _revertIfBodyLocked({hook: hook, bannyBodyId: userId, exemptBodyId: bannyBodyId});
                }

                // Get the background's product info.
                JB721Tier memory backgroundProduct = _productOfTokenId({hook: hook, tokenId: backgroundId});

                // Background must exist and must be a background category.
                if (backgroundProduct.id == 0 || backgroundProduct.category != _BACKGROUND_CATEGORY) {
                    revert Banny721TokenUriResolver_UnrecognizedBackground({
                        hook: hook, backgroundId: backgroundId, category: backgroundProduct.category
                    });
                }

                // Try to transfer the previous background back before updating state.
                // If the transfer fails, the old background stays attached to prevent NFT stranding.
                if (userOfPreviousBackground == bannyBodyId) {
                    if (!_tryTransferFrom({hook: hook, from: address(this), to: sender, assetId: previousBackgroundId}))
                    {
                        // Transfer failed — skip the background change entirely so the old background
                        // remains tracked and recoverable. The new background is not equipped.
                        return;
                    }
                }

                // Update state after the old background has been successfully returned.
                _attachedBackgroundIdOf[hook][bannyBodyId] = backgroundId;
                _userOf[hook][backgroundId] = bannyBodyId;

                // Transfer the new background to this contract if it's not already owned by this contract.
                if (owner != address(this)) {
                    _transferFrom({hook: hook, from: sender, to: address(this), assetId: backgroundId});
                }
            } else {
                // Try to transfer the previous background back before clearing state.
                if (userOfPreviousBackground == bannyBodyId) {
                    // Only clear attachment state if the transfer succeeded. If it fails (e.g. recipient rejects
                    // ERC-721), the background stays attached so the owner can retry or recover.
                    if (_tryTransferFrom({hook: hook, from: address(this), to: sender, assetId: previousBackgroundId}))
                    {
                        _attachedBackgroundIdOf[hook][bannyBodyId] = 0;
                    }
                } else {
                    // No transfer is needed; clear the stale attachment record.
                    _attachedBackgroundIdOf[hook][bannyBodyId] = 0;
                }
            }
        }
    }

    /// @notice Add outfits to a banny body.
    /// @dev The caller must own the banny body to dress and all outfits to wear.
    /// @param hook The hook storing the assets.
    /// @param bannyBodyId The ID of the banny body to dress.
    /// @param outfitIds The IDs of the outfits that'll be associated with the specified banny. Only one outfit per
    /// outfit category allowed at a time and they must be passed in order.
    /// @param sender The cached msg sender.
    function _decorateBannyWithOutfits(
        address hook,
        uint256 bannyBodyId,
        uint256[] memory outfitIds,
        address sender
    )
        internal
    {
        // Keep track of certain outfits being used along the way to prevent conflicting outfits.
        bool hasHead;
        bool hasSuit;

        // Keep a reference to the category of the last outfit iterated on.
        uint256 lastAssetCategory;

        // Keep a reference to the currently attached outfits on the banny body.
        uint256[] memory previousOutfitIds = _attachedOutfitIdsOf[hook][bannyBodyId];

        // Keep a index counter that'll help with tracking progress.
        uint256 previousOutfitIndex;

        // Keep a reference to the previous outfit being iterated on when removing.
        uint256 previousOutfitId;

        // Get the outfit's product info.
        uint256 previousOutfitProductCategory;

        // Set the previous values if there are previous outfits.
        if (previousOutfitIds.length > 0) {
            previousOutfitId = previousOutfitIds[0];
            previousOutfitProductCategory = _productOfTokenId({hook: hook, tokenId: previousOutfitId}).category;
        }

        // Iterate through each outfit, transferring it in and adding it to the banny if needed, while transferring
        // out and removing old outfits no longer being worn.
        for (uint256 i; i < outfitIds.length;) {
            // Set the outfit ID being iterated on.
            uint256 outfitId = outfitIds[i];

            // Check if the call is being made either by the outfit's owner or the owner of the banny body currently
            // wearing it.
            if (sender != IERC721(hook).ownerOf(outfitId)) {
                // Get the banny body currently wearing this outfit.
                uint256 wearerId = wearerOf({hook: hook, outfitId: outfitId});

                // If the outfit is not currently worn, only the outfit's owner can use it for decoration.
                if (wearerId == 0) {
                    revert Banny721TokenUriResolver_UnauthorizedOutfit({
                        hook: hook, outfitId: outfitId, sender: sender, owner: IERC721(hook).ownerOf(outfitId)
                    });
                }

                // If the outfit is worn, the banny body's owner can also authorize its use.
                address wearerOwner = IERC721(hook).ownerOf(wearerId);
                if (sender != wearerOwner) {
                    revert Banny721TokenUriResolver_UnauthorizedOutfit({
                        hook: hook, outfitId: outfitId, sender: sender, owner: wearerOwner
                    });
                }

                // A locked source body keeps its equipped outfits until the lock expires.
                _revertIfBodyLocked({hook: hook, bannyBodyId: wearerId, exemptBodyId: bannyBodyId});
            }

            // Get the outfit's product info.
            uint256 outfitProductCategory = _productOfTokenId({hook: hook, tokenId: outfitId}).category;

            // The product's category must be a known category.
            if (outfitProductCategory < _BACKSIDE_CATEGORY || outfitProductCategory > _SPECIAL_BODY_CATEGORY) {
                revert Banny721TokenUriResolver_UnrecognizedCategory({category: outfitProductCategory});
            }

            // Make sure the category is an increment of the previous outfit's category.
            if (i != 0 && outfitProductCategory <= lastAssetCategory) {
                revert Banny721TokenUriResolver_UnorderedCategories({
                    previousCategory: lastAssetCategory, nextCategory: outfitProductCategory
                });
            }

            if (outfitProductCategory == _HEAD_CATEGORY) {
                hasHead = true;
            } else if (outfitProductCategory == _SUIT_CATEGORY) {
                hasSuit = true;
            } else if (
                (outfitProductCategory == _EYES_CATEGORY
                        || outfitProductCategory == _GLASSES_CATEGORY
                        || outfitProductCategory == _MOUTH_CATEGORY
                        || outfitProductCategory == _HEADTOP_CATEGORY) && hasHead
            ) {
                revert Banny721TokenUriResolver_HeadAlreadyAdded({category: outfitProductCategory});
            } else if (
                (outfitProductCategory == _SUIT_TOP_CATEGORY || outfitProductCategory == _SUIT_BOTTOM_CATEGORY)
                    && hasSuit
            ) {
                revert Banny721TokenUriResolver_SuitAlreadyAdded({category: outfitProductCategory});
            }

            // Remove all previous assets up to and including the current category being iterated on.
            // This inner loop advances through `previousOutfitIds` (bounded by outfit category count) and
            // terminates when it passes the current category or exhausts the array.
            // Note: previousOutfitId != 0 guards against re-entering after exhaustion.
            // Category 0 means the tier was removed — these entries are always processed (transferred out and
            // skipped) so the index advances past them.
            while (previousOutfitId != 0 && previousOutfitProductCategory <= outfitProductCategory) {
                // Transfer the previous outfit to the owner of the banny if it's not being worn.
                // `_attachedOutfitIdsOf` has not been rewritten yet, so the wearer should still be the banny body being
                // decorated.
                if (previousOutfitId != outfitId && wearerOf({hook: hook, outfitId: previousOutfitId}) == bannyBodyId) {
                    // Use try-transfer: the previous outfit may have been burned or its tier removed.
                    // If transfer fails, zero is NOT written to previousOutfitIds — the entry is preserved
                    // so it can be retained in the attached list (preventing NFT stranding).
                    if (_tryTransferFrom({hook: hook, from: address(this), to: sender, assetId: previousOutfitId})) {
                        // Mark as successfully transferred so it won't be retained.
                        previousOutfitIds[previousOutfitIndex] = 0;
                    }
                } else {
                    // Not transferring (same outfit being re-equipped or not worn by this banny) — mark as handled.
                    previousOutfitIds[previousOutfitIndex] = 0;
                }

                if (++previousOutfitIndex < previousOutfitIds.length) {
                    // Advance to the next previous outfit.
                    previousOutfitId = previousOutfitIds[previousOutfitIndex];
                    // Get the next previous outfit's category.
                    previousOutfitProductCategory = _productOfTokenId({hook: hook, tokenId: previousOutfitId}).category;
                } else {
                    previousOutfitId = 0;
                    previousOutfitProductCategory = 0;
                }
            }

            // If the outfit is not already being worn by the banny, transfer it to this contract.
            if (wearerOf({hook: hook, outfitId: outfitId}) != bannyBodyId) {
                // Track the banny body now wearing this outfit.
                _wearerOf[hook][outfitId] = bannyBodyId;

                // Transfer the outfit to this contract.
                if (IERC721(hook).ownerOf(outfitId) != address(this)) {
                    _transferFrom({hook: hook, from: sender, to: address(this), assetId: outfitId});
                }
            }

            // Keep a reference to the last outfit's category.
            lastAssetCategory = outfitProductCategory;
            unchecked {
                ++i;
            }
        }

        // Remove and transfer out any remaining assets no longer being worn.
        // This loop is bounded by `previousOutfitIds.length`, which equals the number of outfits previously
        // attached to this banny. Since only one outfit per category is allowed, this is bounded by the number of
        // outfit categories (a small, fixed set).
        while (previousOutfitId != 0) {
            // `_attachedOutfitIdsOf` has not been rewritten yet, so the wearer should still be the banny body being
            // decorated.
            // Skip outfits that are being re-equipped in the new outfit set.
            if (_isInArray({value: previousOutfitId, array: outfitIds})) {
                // This outfit is being re-equipped — mark as handled.
                previousOutfitIds[previousOutfitIndex] = 0;
            } else if (wearerOf({hook: hook, outfitId: previousOutfitId}) == bannyBodyId) {
                // Use try-transfer: the previous outfit may have been burned or its tier removed.
                // If transfer fails, the entry stays non-zero and is retained (preventing NFT stranding).
                if (_tryTransferFrom({hook: hook, from: address(this), to: sender, assetId: previousOutfitId})) {
                    previousOutfitIds[previousOutfitIndex] = 0;
                }
            } else {
                // Not worn by this banny — mark as handled.
                previousOutfitIds[previousOutfitIndex] = 0;
            }

            if (++previousOutfitIndex < previousOutfitIds.length) {
                // Advance to the next previous outfit.
                previousOutfitId = previousOutfitIds[previousOutfitIndex];
            } else {
                previousOutfitId = 0;
            }
        }

        // Store the outfits, merging in any retained outfits whose transfers failed.
        _storeOutfitsWithRetained({
            hook: hook, bannyBodyId: bannyBodyId, outfitIds: outfitIds, previousOutfitIds: previousOutfitIds
        });
    }

    /// @notice Store outfit IDs, merging in any retained outfits (failed transfers) from the previous list.
    /// @dev Entries in `previousOutfitIds` that are still non-zero represent outfits whose transfer back to the
    /// owner failed. These are appended to `outfitIds` so the attachment record is preserved and the owner can retry.
    /// @param hook The hook storing the assets.
    /// @param bannyBodyId The ID of the banny body to dress.
    /// @param outfitIds The new outfit IDs to store.
    /// @param previousOutfitIds The previous outfit IDs array (zeroed entries were successfully transferred or
    /// handled).
    function _storeOutfitsWithRetained(
        address hook,
        uint256 bannyBodyId,
        uint256[] memory outfitIds,
        uint256[] memory previousOutfitIds
    )
        internal
    {
        // Count how many previous outfits failed to transfer (non-zero entries remain).
        uint256 retainedCount;
        for (uint256 i; i < previousOutfitIds.length;) {
            if (previousOutfitIds[i] != 0) retainedCount++;
            unchecked {
                ++i;
            }
        }

        if (retainedCount == 0) {
            _attachedOutfitIdsOf[hook][bannyBodyId] = outfitIds;
        } else {
            // Merge new outfits with retained outfits that couldn't be transferred back.
            uint256[] memory mergedOutfitIds = new uint256[](outfitIds.length + retainedCount);
            for (uint256 i; i < outfitIds.length;) {
                mergedOutfitIds[i] = outfitIds[i];
                unchecked {
                    ++i;
                }
            }
            uint256 mergeIndex = outfitIds.length;
            for (uint256 i; i < previousOutfitIds.length;) {
                if (previousOutfitIds[i] != 0) {
                    mergedOutfitIds[mergeIndex++] = previousOutfitIds[i];
                }
                unchecked {
                    ++i;
                }
            }

            // Revalidate category exclusivity on the merged set. Retained outfits may conflict with the new outfits
            // (e.g., a retained HEAD outfit combined with new EYES/GLASSES/MOUTH/HEADTOP outfits).
            _validateCategoryExclusivity({hook: hook, outfitIds: mergedOutfitIds});
            // Restore canonical category ordering before persisting, since retained outfits are appended after the
            // caller-supplied set.
            _sortOutfitsByCategory({hook: hook, outfitIds: mergedOutfitIds});

            // After sorting, verify no two outfits share the same category. A retained outfit whose transfer
            // failed could duplicate a category supplied in the new outfit set.
            for (uint256 i = 1; i < mergedOutfitIds.length;) {
                if (
                    _productOfTokenId({hook: hook, tokenId: mergedOutfitIds[i]}).category
                        == _productOfTokenId({hook: hook, tokenId: mergedOutfitIds[i - 1]}).category
                ) {
                    revert Banny721TokenUriResolver_DuplicateCategory({
                        category: _productOfTokenId({hook: hook, tokenId: mergedOutfitIds[i]}).category
                    });
                }
                unchecked {
                    ++i;
                }
            }

            // Persist the merged-and-sorted attachment list so later reads and redecorations see a stable order.
            _attachedOutfitIdsOf[hook][bannyBodyId] = mergedOutfitIds;
        }
    }

    /// @notice Transfer a token from one address to another.
    /// @param hook The 721 contract of the token to transfer.
    /// @param from The address to transfer the token from.
    /// @param to The address to transfer the token to.
    /// @param assetId The ID of the token to transfer.
    function _transferFrom(address hook, address from, address to, uint256 assetId) internal {
        IERC721(hook).safeTransferFrom({from: from, to: to, tokenId: assetId});
    }

    /// @notice Try to transfer a token, returning whether the transfer succeeded.
    /// @dev Used when returning previously equipped items that may no longer exist.
    /// @param hook The 721 contract of the token to transfer.
    /// @param from The address to transfer the token from.
    /// @param to The address to transfer the token to.
    /// @param assetId The ID of the token to transfer.
    /// @return success Whether the transfer succeeded.
    function _tryTransferFrom(address hook, address from, address to, uint256 assetId) internal returns (bool success) {
        try IERC721(hook).safeTransferFrom({from: from, to: to, tokenId: assetId}) {
            success = true;
        } catch {}
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/// @notice Manages Banny NFT assets — bodies, backgrounds, and outfits — and resolves on-chain SVG token URIs for
/// dressed Banny compositions. Owners dress their banny bodies with outfits and backgrounds; the resolver composes
/// all attached assets into a single SVG returned as a base64-encoded data URI.
interface IBanny721TokenUriResolver {
    /// @notice Emitted when a banny body is decorated with a background and outfits.
    /// @param hook The hook address of the collection.
    /// @param bannyBodyId The ID of the banny body that was decorated.
    /// @param backgroundId The ID of the background attached.
    /// @param outfitIds The IDs of the outfits attached.
    /// @param caller The address that decorated the banny.
    event DecorateBanny(
        address indexed hook,
        uint256 indexed bannyBodyId,
        uint256 indexed backgroundId,
        uint256[] outfitIds,
        address caller
    );

    /// @notice Emitted when metadata (description, external URL, base URI) is updated.
    /// @param description The new description.
    /// @param externalUrl The new external URL.
    /// @param baseUri The new base URI.
    /// @param caller The address that updated the metadata.
    event SetMetadata(string description, string externalUrl, string baseUri, address caller);

    /// @notice Emitted when a product name is set.
    /// @param upc The universal product code.
    /// @param name The name assigned to the product.
    /// @param caller The address that set the name.
    event SetProductName(uint256 indexed upc, string name, address caller);

    /// @notice Emitted when SVG content is stored for a product.
    /// @param upc The universal product code.
    /// @param svgContent The SVG content that was stored.
    /// @param caller The address that stored the content.
    event SetSvgContent(uint256 indexed upc, string svgContent, address caller);

    /// @notice Emitted when an SVG content hash is stored for a product.
    /// @param upc The universal product code.
    /// @param svgHash The SVG content hash that was stored.
    /// @param caller The address that stored the hash.
    event SetSvgHash(uint256 indexed upc, bytes32 indexed svgHash, address caller);

    /// @notice The background and outfit IDs currently attached to a banny body.
    /// @param hook The hook address of the collection.
    /// @param bannyBodyId The ID of the banny body.
    /// @return backgroundId The ID of the attached background.
    /// @return outfitIds The IDs of the attached outfits.
    function assetIdsOf(
        address hook,
        uint256 bannyBodyId
    )
        external
        view
        returns (uint256 backgroundId, uint256[] memory outfitIds);

    /// @notice The base SVG content for a banny body.
    /// @return The SVG string.
    function bannyBody() external view returns (string memory);

    /// @notice The default SVG content for alien banny eyes.
    /// @return The SVG string.
    function defaultAlienEyes() external view returns (string memory);

    /// @notice The default SVG content for a banny mouth.
    /// @return The SVG string.
    function defaultMouth() external view returns (string memory);

    /// @notice The default SVG content for a banny necklace.
    /// @return The SVG string.
    function defaultNecklace() external view returns (string memory);

    /// @notice The default SVG content for standard banny eyes.
    /// @return The SVG string.
    function defaultStandardEyes() external view returns (string memory);

    /// @notice Get the names associated with a token (product name, category name, and display name).
    /// @param hook The hook address of the collection.
    /// @param tokenId The token ID to look up.
    /// @return The product name, the category name, and the display name.
    function namesOf(address hook, uint256 tokenId) external view returns (string memory, string memory, string memory);

    /// @notice The timestamp until which a banny body's outfit is locked and cannot be changed.
    /// @param hook The hook address of the collection.
    /// @param upc The ID of the banny body.
    /// @return The lock expiration timestamp, or 0 if not locked.
    function outfitLockedUntil(address hook, uint256 upc) external view returns (uint256);

    /// @notice The base URI used to lazily resolve SVG content from IPFS.
    /// @return The base URI string.
    function svgBaseUri() external view returns (string memory);

    /// @notice The description used in token metadata.
    /// @return The description string.
    function svgDescription() external view returns (string memory);

    /// @notice The external URL used in token metadata.
    /// @return The external URL string.
    function svgExternalUrl() external view returns (string memory);

    /// @notice The stored SVG content hash for a given product.
    /// @param upc The universal product code to look up.
    /// @return The SVG content hash.
    function svgHashOf(uint256 upc) external view returns (bytes32);

    /// @notice Get the composed SVG for a token, optionally dressed and with a background.
    /// @param hook The hook address of the collection.
    /// @param tokenId The token ID to render.
    /// @param shouldDressBannyBody Whether to include the banny body's attached outfits.
    /// @param shouldIncludeBackgroundOnBannyBody Whether to include the banny body's attached background.
    /// @return The composed SVG string.
    function svgOf(
        address hook,
        uint256 tokenId,
        bool shouldDressBannyBody,
        bool shouldIncludeBackgroundOnBannyBody
    )
        external
        view
        returns (string memory);

    /// @notice The banny body ID that is currently using a given background.
    /// @param hook The hook address of the collection.
    /// @param backgroundId The ID of the background.
    /// @return The banny body ID using the background, or 0 if none.
    function userOf(address hook, uint256 backgroundId) external view returns (uint256);

    /// @notice The banny body ID that is currently wearing a given outfit.
    /// @param hook The hook address of the collection.
    /// @param outfitId The ID of the outfit.
    /// @return The banny body ID wearing the outfit, or 0 if none.
    function wearerOf(address hook, uint256 outfitId) external view returns (uint256);

    /// @notice Dress a banny body with a background and outfits.
    /// @param hook The hook address of the collection.
    /// @param bannyBodyId The ID of the banny body to dress.
    /// @param backgroundId The ID of the background to attach (0 for none).
    /// @param outfitIds The IDs of the outfits to attach.
    function decorateBannyWith(
        address hook,
        uint256 bannyBodyId,
        uint256 backgroundId,
        uint256[] calldata outfitIds
    )
        external;

    /// @notice Lock a banny body so its outfit cannot be changed for a period of time.
    /// @param hook The hook address of the collection.
    /// @param bannyBodyId The ID of the banny body to lock.
    function lockOutfitChangesFor(address hook, uint256 bannyBodyId) external;

    /// @notice Set the token metadata description, external URL, and SVG base URI. Only the contract owner can call
    /// this.
    /// @param description The new description.
    /// @param url The new external URL.
    /// @param baseUri The new base URI.
    function setMetadata(string calldata description, string calldata url, string calldata baseUri) external;

    /// @notice Set custom display names for products. Only the contract owner can call this.
    /// @param upcs The universal product codes to set names for.
    /// @param names The names to assign to each product.
    function setProductNames(uint256[] memory upcs, string[] memory names) external;

    /// @notice Store SVG contents for products, validated against previously stored hashes.
    /// @param upcs The universal product codes to store SVG contents for.
    /// @param svgContents The SVG contents to store (must match stored hashes).
    function setSvgContentsOf(uint256[] memory upcs, string[] calldata svgContents) external;

    /// @notice Store SVG content hashes for products. Only the contract owner can call this.
    /// @param upcs The universal product codes to store SVG hashes for.
    /// @param svgHashes The SVG content hashes to store.
    function setSvgHashesOf(uint256[] memory upcs, bytes32[] memory svgHashes) external;
}

