}));

// Current lookup state for registered V6 buyback pools. Unlike the event table
// below, this has a deterministic (chainId, poolId) key so indexing handlers
// can use Ponder's transaction-aware `db.find` during historical batches.
export const buybackPool = onchainTable(
  "buyback_pool",
  (t) => ({
    ...chainId(t),
    ...projectId(t),
    ...version(t),
    ...createdAt(t),
    poolId: t.hex().notNull(),
    terminalToken: t.hex().notNull(),
    currency0: t.hex().notNull(),
    currency1: t.hex().notNull(),
    projectTokenIsCurrency0: t.boolean().notNull(),
    initialSqrtPriceX96: t.bigint(),
  }),
  (t) => ({
    pk: primaryKey({ columns: [t.chainId, t.poolId] }),
  })
);

/**
 * An LP position in a Juicebox buyback pool, so clients can list a pool's
 * providers — or a wallet's own positions — without walking PoolManager logs
 * back to the pool's Initialize. Only positions in registered `buyback_pool`
 * rows are stored; every other Uniswap V4 position is ignored.
 */
export const buybackPoolPosition = onchainTable(
  "buyback_pool_position",
  (t) => ({
    ...chainId(t),
    ...projectId(t),
    ...version(t),
    ...createdAt(t),
    poolId: t.hex().notNull(),
    /** PositionManager NFT id, which is also the position's salt in the pool. */
    tokenId: t.bigint().notNull(),
    owner: t.hex().notNull(),
    tickLower: t.integer().notNull(),
    tickUpper: t.integer().notNull(),
    /** Live liquidity, as the pool records it. */
    liquidity: t.bigint().notNull(),
    /**
     * The position's fee checkpoint, mirroring the pool's. Stored so the next
     * modification can price the interval that just ended.
     */
    feeGrowthInside0LastX128: t.bigint().notNull(),
    feeGrowthInside1LastX128: t.bigint().notNull(),
    /**
     * Fees this position has already taken, summed over every modification.
     * The pool rewrites its checkpoint on each collect, so this total cannot be
     * recovered from live state — lifetime earnings are this plus whatever is
     * currently unclaimed.
     */
    feesClaimed0: t.bigint().notNull(),
    feesClaimed1: t.bigint().notNull(),
    /** Last block timestamp at which ownership or existence changed. */
    updatedAt: t.integer().notNull(),
    /** Burned positions are kept so a client can tell "gone" from "never seen". */
    burned: t.boolean().notNull().default(false),
  }),
  (t) => ({
    pk: primaryKey({ columns: [t.chainId, t.tokenId] }),
    poolIdx: index().on(t.chainId, t.poolId),
    ownerIdx: index().on(t.owner),
  })
);

/**
 * Every liquidity change in a registered buyback pool, as it happened. The
 * position table above holds only LIVE liquidity — each modification
 * overwrites it and a burn hides the row — so it cannot say what the pool held
 * last month. Replaying these deltas in order (each with the pool's price at
 * that block) rebuilds the pool's reserves at any past point.
 */
export const buybackPoolLiquidityEvent = onchainTable(
  "buyback_pool_liquidity_event",
  (t) => ({
    ...uniqueId(t),
    ...chainId(t),
    ...projectId(t),
    ...version(t),
    ...txHash(t),
    ...timestamp(t),
    ...logIndex(t),
    poolId: t.hex().notNull(),
    /** PositionManager NFT id, which is also the position's salt in the pool. */
    tokenId: t.bigint().notNull(),
    tickLower: t.integer().notNull(),
    tickUpper: t.integer().notNull(),
    /** Signed: negative for a decrease. Zero for a bare fee collect. */
    liquidityDelta: t.bigint().notNull(),
    /** The position's liquidity once this change applied. */
    liquidityAfter: t.bigint().notNull(),
    /** The pool's price at this block, so the change can be valued in place. */
    sqrtPriceX96: t.bigint(),
  }),
  (t) => ({
    poolHistoryIdx: index().on(t.chainId, t.poolId, t.timestamp),
    projectHistoryIdx: index().on(
      t.chainId,
      t.projectId,
      t.version,
      t.timestamp
    ),
  })
);

