/// @notice Deploys and manages Defifa games — prediction-market-style contests built on Juicebox. Each game has
/// tiers representing outcomes (teams, players, events). Players mint tier NFTs during the mint phase, then after
/// the event concludes, a scorecard assigns cash-out weights to each tier. The treasury is distributed proportionally
/// to winning NFT holders. Games progress through phases: COUNTDOWN → MINT → REFUND → SCORING → COMPLETE (or
/// NO_CONTEST if minimum participation isn't met or scorecard ratification times out).
contract DefifaDeployer is
    ERC2771Context,
    IDefifaDeployer,
    IDefifaGamePhaseReporter,
    IDefifaGamePotReporter,
    IERC721Receiver,
    IJBPayerTracker
{
    using Strings for uint256;
    using SafeERC20 for IERC20;

    //*********************************************************************//
    // --------------------------- custom errors ------------------------- //
    //*********************************************************************//

    /// @notice Thrown when fulfilling a game's commitments before its cash-out weights have been set.
    error DefifaDeployer_CantFulfillYet(uint256 gameId);

    /// @notice Thrown when launching a game with non-sequential phase timestamps, no mint duration, more than 128
    /// tiers, no scorecard timeout, or a scorecard timeout shorter than the full ratification window.
    error DefifaDeployer_InvalidGameConfiguration(
        uint256 start, uint256 mintPeriodDuration, uint256 refundPeriodDuration, uint256 tierCount
    );

    /// @notice Thrown when launching an ERC-20 game with a zero base currency.
    error DefifaDeployer_InvalidCurrency(address token, uint256 currency);

    /// @notice Thrown when triggering no-contest for a game that is not in its NO_CONTEST phase.
    error DefifaDeployer_NotNoContest(uint256 gameId, DefifaGamePhase phase);

    /// @notice Thrown when triggering no-contest for a game where it has already been triggered.
    error DefifaDeployer_NoContestAlreadyTriggered(uint256 gameId);

    /// @notice Thrown when the configured fee splits sum to more than 100%.
    error DefifaDeployer_SplitsDontAddUp(uint256 totalPercent, uint256 maxPercent);

    //*********************************************************************//
    // ------------------------- public constants ------------------------ //
    //*********************************************************************//

    /// @notice The divisor that describes the protocol fee that should be taken.
    /// @dev This is equal to 100 divided by the fee percent (e.g. 40 = 2.5% fee).
    uint256 public constant override BASE_PROTOCOL_FEE_DIVISOR = 40;

    /// @notice The divisor that describes the Defifa fee that should be taken.
    /// @dev This is equal to 100 divided by the fee percent (e.g. 20 = 5% fee).
    uint256 public constant override DEFIFA_FEE_DIVISOR = 20;

    //*********************************************************************//
    // --------------- public immutable stored properties ---------------- //
    //*********************************************************************//

    /// @notice The project ID that will receive protocol fees as commitments are fulfilled.
    uint256 public immutable override BASE_PROTOCOL_PROJECT_ID;

    /// @notice The controller with which new projects should be deployed.
    IJBController public immutable override CONTROLLER;

    /// @notice The project ID that receives Defifa game fees as commitments are fulfilled.
    uint256 public immutable override DEFIFA_PROJECT_ID;

    /// @notice The directory of terminals and controllers for each project.
    IJBDirectory public immutable override DIRECTORY;

    /// @notice The governance contract that ratifies scorecards for each game.
    IDefifaGovernor public immutable override GOVERNOR;

    /// @notice The original code for the Defifa hook to base subsequent instances on.
    address public immutable override HOOK_CODE_ORIGIN;

    /// @notice The 721 tiers hook store used by all games.
    IJB721TiersHookStore public immutable override HOOK_STORE;

    /// @notice The contract which mints ERC-721s that represent project ownership and transfers.
    IJBProjects public immutable override PROJECTS;

    /// @notice The Juicebox 721 tiers hook registry used to register deployed games.
    IJBAddressRegistry public immutable override REGISTRY;

    /// @notice The contract storing and managing project rulesets.
    IJBRulesets public immutable override RULESETS;

    /// @notice The default Defifa token URI resolver.
    IJB721TokenUriResolver public immutable override TOKEN_URI_RESOLVER;

    //*********************************************************************//
    // --------------------- public stored properties -------------------- //
    //*********************************************************************//

    /// @notice The amount of commitments a game has fulfilled.
    /// @custom:param gameId The ID of the game to check.
    mapping(uint256 => uint256) public override fulfilledCommitmentsOf;

    /// @notice Whether commitments have been fulfilled for a game.
    /// @custom:param gameId The ID of the game to check.
    mapping(uint256 => bool) public commitmentsFulfilledFor;

    /// @notice Whether the no-contest refund ruleset has been triggered for a game.
    /// @dev Once triggered, the game stays in NO_CONTEST and refunds are enabled.
    /// @custom:param gameId The ID of the game to check.
    mapping(uint256 => bool) public noContestTriggeredFor;

    //*********************************************************************//
    // ------------------- public transient properties ------------------- //
    //*********************************************************************//

    /// @notice The account that paid the creation fee for the game currently being launched.
    /// @dev This contract owns the games it launches, so it advertises the resolved fee payer (the `launchGameWith`
    /// ERC-2771 caller, or that caller's upstream payer when the caller is itself an `IJBPayerTracker`) while
    /// `JBProjects.createFor` runs, letting a `pay`-routing fee receiver credit the true payer instead of this
    /// deployer. Cleared back to `address(0)` once the call returns.
    address public transient override originalPayer;

    //*********************************************************************//
    // -------------------- internal stored properties ------------------- //
    //*********************************************************************//

    /// @notice The game's ops.
    /// @custom:param gameId The ID of the game whose ops are stored.
    mapping(uint256 => DefifaOpsData) internal _opsOf;

    /// @notice The total absolute split percent for each game (out of SPLITS_TOTAL_PERCENT).
    /// @custom:param gameId The ID of the game whose total absolute split percent is stored.
    mapping(uint256 => uint256) internal _commitmentPercentOf;

    /// @notice This contract's nonce for deterministic hook deployment and registry entries.
    /// @dev Initialized at 1 because the hook implementation is deployed before the first game clone.
    uint256 internal _nonce;

    //*********************************************************************//
    // ------------------------- external views -------------------------- //
    //*********************************************************************//

    /// @notice The current pot the game is played with.
    /// @param gameId The ID of the game for which the pot applies.
    /// @param includeCommitments A flag indicating if the portion of the pot committed to fulfill preprogrammed
    /// obligations should be included.
    /// @return The game's pot amount, as a fixed point number.
    /// @return The token address the game's pot is measured in.
    /// @return The number of decimals included in the amount.
    function currentGamePotOf(
        uint256 gameId,
        bool includeCommitments
    )
        external
        view
        returns (uint256, address, uint256)
    {
        // Get a reference to the token being used by the project.
        address token = _opsOf[gameId].token;

        // Get a reference to the terminal via the directory.
        IJBTerminal terminal = DIRECTORY.primaryTerminalOf({projectId: gameId, token: token});

        // Get the accounting context for the project.
        JBAccountingContext memory context = terminal.accountingContextForTokenOf({projectId: gameId, token: token});

        // Get the current balance from the terminal's store.
        uint256 pot = IJBMultiTerminal(address(terminal)).STORE()
            .balanceOf({terminal: address(terminal), projectId: gameId, token: token});

        // Add any fulfilled commitments.
        if (includeCommitments) pot += fulfilledCommitmentsOf[gameId];

        return (pot, token, context.decimals);
    }

    /// @notice Whether or not the next phase still needs queuing.
    /// @param gameId The ID of the game to get the queue status of.
    /// @return Whether or not the next phase still needs queuing.
    function nextPhaseNeedsQueueing(uint256 gameId) external view override returns (bool) {
        // Get the game's current funding cycle along with its metadata.
        JBRuleset memory currentRuleset = RULESETS.currentOf(gameId);
        // Get the game's queued funding cycle along with its metadata.
        (JBRuleset memory queuedRuleset,) = RULESETS.latestQueuedOf(gameId);

        // If the configurations are the same and the game hasn't ended, queueing is still needed.
        return currentRuleset.duration != 0 && currentRuleset.id == queuedRuleset.id;
    }

    /// @notice The safety mechanism parameters of a game.
    /// @param gameId The ID of the game to get the safety params of.
    /// @return minParticipation The minimum cumulative NFT mint cost for the game to proceed to scoring.
    /// @return scorecardTimeout The maximum time after scoring begins for a scorecard to be ratified.
    function safetyParamsOf(uint256 gameId)
        external
        view
        override
        returns (uint256 minParticipation, uint32 scorecardTimeout)
    {
        DefifaOpsData memory ops = _opsOf[gameId];
        return (ops.minParticipation, ops.scorecardTimeout);
    }

    /// @notice Get the countdown, minting, and refund deadline timestamps for a game.
    /// @param gameId The ID of the game for which the game times apply.
    /// @return The game's start time, as a unix timestamp.
    /// @return The game's minting period duration, in seconds.
    /// @return The game's refund period duration, in seconds.
    function timesFor(uint256 gameId) external view override returns (uint48, uint24, uint24) {
        DefifaOpsData memory ops = _opsOf[gameId];
        return (ops.start, ops.mintPeriodDuration, ops.refundPeriodDuration);
    }

    /// @notice Get the ERC-20 token address associated with a given game.
    /// @param gameId The ID of the game to get the token of.
    /// @return The game's token.
    function tokenOf(uint256 gameId) external view override returns (address) {
        return _opsOf[gameId].token;
    }

    //*********************************************************************//
    // -------------------------- public views --------------------------- //
    //*********************************************************************//

    /// @notice Returns the number of the game phase.
    /// @dev The game phase corresponds to the game's current funding cycle number.
    /// @dev NO_CONTEST is returned if the minimum participation threshold is not met, or if the scorecard timeout has
    /// elapsed without ratification.
    /// @param gameId The ID of the game to get the phase number of.
    /// @return The game phase.
    function currentGamePhaseOf(uint256 gameId) public view override returns (DefifaGamePhase) {
        // Get the game's current funding cycle along with its metadata.
        (JBRuleset memory currentRuleset, JBRulesetMetadata memory metadata) = CONTROLLER.currentRulesetOf(gameId);

        // Cache the cycle number to avoid repeated memory reads.
        uint256 cycleNumber = currentRuleset.cycleNumber;

        // Return early for the first three phases based on cycle number.
        if (cycleNumber == 0) return DefifaGamePhase.COUNTDOWN;
        if (cycleNumber == 1) return DefifaGamePhase.MINT;
        if (cycleNumber == 2 && _opsOf[gameId].refundPeriodDuration != 0) {
            return DefifaGamePhase.REFUND;
        }

        // Check if the scorecard has been ratified (game is COMPLETE).
        // This takes priority over all NO_CONTEST checks — a ratified scorecard is final.
        if (IDefifaHook(metadata.dataHook).cashOutWeightIsSet()) return DefifaGamePhase.COMPLETE;

        // If no-contest has already been triggered, stay in NO_CONTEST.
        if (noContestTriggeredFor[gameId]) return DefifaGamePhase.NO_CONTEST;

        // Get the game's ops data for the safety mechanism checks. Cache to avoid repeated SLOAD.
        DefifaOpsData memory ops = _opsOf[gameId];

        // Check minimum participation threshold using cumulative NFT mint cost from the hook.
        // Terminal balance is NOT used because `addToBalanceOf` can inflate it without minting NFTs.
        // `totalMintCost` tracks only actual paid mint value and is decremented on refunds/burns.
        if (ops.minParticipation > 0) {
            if (IDefifaHook(metadata.dataHook).totalMintCost() < ops.minParticipation) {
                return DefifaGamePhase.NO_CONTEST;
            }
        }

        // Check scorecard ratification timeout: if enough time has passed without a ratified scorecard, the game is
        // NO_CONTEST.
        // Game phase timing is timestamp-based by design.
        // forge-lint: disable-next-line(block-timestamp)
        if (ops.scorecardTimeout > 0 && block.timestamp > currentRuleset.start + ops.scorecardTimeout) {
            return DefifaGamePhase.NO_CONTEST;
        }

        return DefifaGamePhase.SCORING;
    }

    //*********************************************************************//
    // -------------------------- constructor ---------------------------- //
    //*********************************************************************//

    /// @param hookCodeOrigin The code of the Defifa hook.
    /// @param tokenUriResolver The standard default token URI resolver.
    /// @param governor The Defifa governor.
    /// @param controller The controller to use to launch the game from.
    /// @param registry The contract storing references to the deployer of each hook.
    /// @param defifaProjectId The ID of the project that should take the fee from the games.
    /// @param baseProtocolProjectId The ID of the protocol project that will receive fees from fulfilling commitments.
    /// @param hookStore The store used by Defifa hooks.
    /// @param trustedForwarder The trusted forwarder for the ERC2771Context.
    constructor(
        address hookCodeOrigin,
        IJB721TokenUriResolver tokenUriResolver,
        IDefifaGovernor governor,
        IJBController controller,
        IJBAddressRegistry registry,
        uint256 defifaProjectId,
        uint256 baseProtocolProjectId,
        IJB721TiersHookStore hookStore,
        address trustedForwarder
    )
        ERC2771Context(trustedForwarder)
    {
        HOOK_CODE_ORIGIN = hookCodeOrigin;
        TOKEN_URI_RESOLVER = tokenUriResolver;
        GOVERNOR = governor;
        CONTROLLER = controller;
        DIRECTORY = controller.DIRECTORY();
        PROJECTS = controller.PROJECTS();
        RULESETS = controller.RULESETS();
        REGISTRY = registry;
        DEFIFA_PROJECT_ID = defifaProjectId;
        BASE_PROTOCOL_PROJECT_ID = baseProtocolProjectId;
        HOOK_STORE = hookStore;
    }

    //*********************************************************************//
    // ---------------------- external transactions ---------------------- //
    //*********************************************************************//

    /// @notice Fulfill split amounts between all splits for a game.
    /// @param gameId The ID of the game to fulfill splits for.
    function fulfillCommitmentsOf(uint256 gameId) external virtual override {
        // Make sure commitments haven't already been fulfilled.
        if (commitmentsFulfilledFor[gameId]) return;
        commitmentsFulfilledFor[gameId] = true;

        // Get the game's current funding cycle along with its metadata.
        (, JBRulesetMetadata memory metadata) = CONTROLLER.currentRulesetOf(gameId);

        // Make sure the game's commitments can be fulfilled.
        if (!IDefifaHook(metadata.dataHook).cashOutWeightIsSet()) {
            revert DefifaDeployer_CantFulfillYet({gameId: gameId});
        }

        // Get the game token and the terminal.
        address token = _opsOf[gameId].token;
        IJBMultiTerminal terminal =
            IJBMultiTerminal(address(DIRECTORY.primaryTerminalOf({projectId: gameId, token: token})));

        // Get the current pot and store it. This also prevents re-entrance since the check above will return early.
        uint256 pot = terminal.STORE().balanceOf({terminal: address(terminal), projectId: gameId, token: token});

        // If the pot is empty, queue the final ruleset without attempting payouts.
        if (pot == 0) {
            _queueFinalRuleset({gameId: gameId, metadata: metadata});
            emit FulfilledCommitments({gameId: gameId, pot: 0, caller: _msgSender()});
            return;
        }

        // Compute the fee amount based on the total absolute split percent stored at game creation.
        uint256 feeAmount =
            mulDiv({x: pot, y: _commitmentPercentOf[gameId], denominator: JBConstants.SPLITS_TOTAL_PERCENT});

        // Store the actual fee amount for accurate currentGamePotOf reporting.
        fulfilledCommitmentsOf[gameId] = feeAmount;

        // Send only the fee portion as payouts. The remaining balance stays as surplus for cash-outs.
        // Use the ruleset's baseCurrency — this matches the currency under which payout limits were stored
        // at launch time, regardless of whether the token is native ETH or an ERC-20. Wrapped in try-catch so
        // the final ruleset is always queued even if payout fails.
        try terminal.sendPayoutsOf({
            projectId: gameId, token: token, amount: feeAmount, currency: metadata.baseCurrency, minTokensPaidOut: 0
        }) {}
        catch (bytes memory reason) {
            // Payout failed — fee stays in pot. Reset to 0 so currentGamePotOf
            // doesn't double-count the fee.
            fulfilledCommitmentsOf[gameId] = 0;
            emit CommitmentPayoutFailed({gameId: gameId, amount: feeAmount, reason: reason, caller: _msgSender()});
        }

        // Queue the final ruleset and emit.
        _queueFinalRuleset({gameId: gameId, metadata: metadata});

        emit FulfilledCommitments({gameId: gameId, pot: pot, caller: _msgSender()});
    }

    /// @notice Launches a new game owned by this contract with a DefifaHook attached.
    /// @param launchProjectData Data necessary to fulfill the transaction to launch a game.
    /// @return gameId The ID of the newly configured game.
    /// @dev Forwards `msg.value` to `JBProjects.createFor` to cover any configured project creation fee.
    function launchGameWith(DefifaLaunchProjectData memory launchProjectData)
        external
        payable
        override
        returns (uint256 gameId)
    {
        // Game launch timing is timestamp-based by design.
        uint256 currentTimestamp = block.timestamp;

        // If no explicit game start is provided, start after the configured mint and refund windows.
        if (launchProjectData.start == 0) {
            uint256 start =
                currentTimestamp + launchProjectData.mintPeriodDuration + launchProjectData.refundPeriodDuration;
            if (start > type(uint48).max) {
                revert DefifaDeployer_InvalidGameConfiguration({
                    start: start,
                    mintPeriodDuration: launchProjectData.mintPeriodDuration,
                    refundPeriodDuration: launchProjectData.refundPeriodDuration,
                    tierCount: launchProjectData.tiers.length
                });
            }

            // Casting to uint48 is safe because `start` was bounded above.
            // forge-lint: disable-next-line(unsafe-typecast)
            launchProjectData.start = uint48(start);
        }
        // If callers provide a future start with no mint duration, derive a mint window that begins now and ends
        // before the refund window. This preserves the requested start while keeping minting immediately available.
        else if (
            launchProjectData.mintPeriodDuration == 0
                && launchProjectData.start > currentTimestamp + launchProjectData.refundPeriodDuration
        ) {
            launchProjectData.mintPeriodDuration =
                uint24(launchProjectData.start - (currentTimestamp + launchProjectData.refundPeriodDuration));
        }

        // Make sure the provided gameplay timestamps are sequential and that there is a mint duration.
        if (
            launchProjectData.mintPeriodDuration == 0
                || launchProjectData.start
                    < currentTimestamp + launchProjectData.refundPeriodDuration + launchProjectData.mintPeriodDuration
        ) {
            revert DefifaDeployer_InvalidGameConfiguration({
                start: launchProjectData.start,
                mintPeriodDuration: launchProjectData.mintPeriodDuration,
                refundPeriodDuration: launchProjectData.refundPeriodDuration,
                tierCount: launchProjectData.tiers.length
            });
        }

        // The hook and governor hardcode uint256[128] tier-weight tables, so reject games with more than 128 tiers.
        if (launchProjectData.tiers.length > 128) {
            revert DefifaDeployer_InvalidGameConfiguration({
                start: launchProjectData.start,
                mintPeriodDuration: launchProjectData.mintPeriodDuration,
                refundPeriodDuration: launchProjectData.refundPeriodDuration,
                tierCount: launchProjectData.tiers.length
            });
        }

        // Every game needs a timeout so scoring can resolve to NO_CONTEST if no scorecard is ratified.
        if (launchProjectData.scorecardTimeout == 0) {
            revert DefifaDeployer_InvalidGameConfiguration({
                start: launchProjectData.start,
                mintPeriodDuration: launchProjectData.mintPeriodDuration,
                refundPeriodDuration: launchProjectData.refundPeriodDuration,
                tierCount: launchProjectData.tiers.length
            });
        }

        // Reject ERC-20 games with a zero currency. A zero baseCurrency would cause payout limit lookups
        // in fulfillCommitmentsOf to silently fail, skipping all commitment payouts.
        if (launchProjectData.token.token != JBConstants.NATIVE_TOKEN && launchProjectData.token.currency == 0) {
            revert DefifaDeployer_InvalidCurrency({
                token: launchProjectData.token.token, currency: launchProjectData.token.currency
            });
        }

        // If a scorecard timeout is set, it must exceed the full ratification window:
        // attestation delay (time from scoring start to attestation start) + grace period + timelock.
        // Otherwise the game would enter NO_CONTEST before a scorecard could ever reach SUCCEEDED.
        if (launchProjectData.scorecardTimeout > 0) {
            // Attestation delay: how long after scoring starts before attestations can begin.
            uint256 attestationDelay = launchProjectData.attestationStartTime > launchProjectData.start
                ? launchProjectData.attestationStartTime - launchProjectData.start
                : 0;
            if (
                launchProjectData.scorecardTimeout
                    <= attestationDelay + launchProjectData.attestationGracePeriod + launchProjectData.timelockDuration
            ) {
                revert DefifaDeployer_InvalidGameConfiguration({
                    start: launchProjectData.start,
                    mintPeriodDuration: launchProjectData.mintPeriodDuration,
                    refundPeriodDuration: launchProjectData.refundPeriodDuration,
                    tierCount: launchProjectData.tiers.length
                });
            }
        }

        address caller = _msgSender();

        // Expose the resolved fee payer so a `pay`-routing fee receiver credits the true payer, not this deployer.
        // Cleared immediately after.
        originalPayer = JBPayerTrackerLib.resolve(caller);

        // Reserve the game ID up front so permissionless project creations cannot invalidate hook deployment.
        gameId = PROJECTS.createFor{value: msg.value}(address(this));

        originalPayer = address(0);

        // Store the timestamps that define the game phases.
        _opsOf[gameId] = DefifaOpsData({
            token: launchProjectData.token.token,
            mintPeriodDuration: launchProjectData.mintPeriodDuration,
            refundPeriodDuration: launchProjectData.refundPeriodDuration,
            start: launchProjectData.start,
            minParticipation: launchProjectData.minParticipation,
            scorecardTimeout: launchProjectData.scorecardTimeout
        });

        // Keep track of the number of tiers.
        uint256 numberOfTiers = launchProjectData.tiers.length;

        // Create the standard tiers struct that will be populated from the defifa tiers.
        JB721TierConfig[] memory hookTiers = new JB721TierConfig[](launchProjectData.tiers.length);

        // Group all the tier names together.
        string[] memory tierNames = new string[](launchProjectData.tiers.length);

        // Keep a reference to the tier being iterated on.
        DefifaTierParams memory defifaTier;

        // Create the hook tiers from the Defifa tiers.
        for (uint256 i; i < numberOfTiers;) {
            defifaTier = launchProjectData.tiers[i];

            // Set the tier. All tiers use the same price so that price-based voting power is equal.
            hookTiers[i] = JB721TierConfig({
                price: launchProjectData.tierPrice,
                initialSupply: 999_999_999, // Uncapped minting — max value allowed by the 721 store.
                votingUnits: 0,
                reserveFrequency: defifaTier.reservedRate,
                reserveBeneficiary: defifaTier.reservedTokenBeneficiary,
                encodedIpfsUri: defifaTier.encodedIpfsUri,
                category: 0,
                discountPercent: 0,
                flags: JB721TierConfigFlags({
                    allowOwnerMint: false,
                    useReserveBeneficiaryAsDefault: defifaTier.shouldUseReservedTokenBeneficiaryAsDefault,
                    transfersPausable: false,
                    useVotingUnits: false,
                    cantBeRemoved: true,
                    cantIncreaseDiscountPercent: true,
                    cantBuyWithCredits: false
                }),
                splitPercent: 0,
                splits: new JBSplit[](0)
            });

            // Set the name.
            tierNames[i] = defifaTier.name;

            unchecked {
                ++i;
            }
        }

        // Increment the nonce for this deployment.
        uint256 currentNonce = ++_nonce;

        // Clone deterministically using caller and nonce to prevent front-running.
        // Clones.clone() creates the proxy before initialize() is called, allowing an
        // attacker to front-run initialization and DOS the game deployment. Using
        // cloneDeterministic with the ERC-2771 caller in the salt prevents this since a different
        // caller produces a different address.
        DefifaHook hook = DefifaHook(
            Clones.cloneDeterministic({
                implementation: HOOK_CODE_ORIGIN, salt: keccak256(abi.encodePacked(caller, currentNonce))
            })
        );

        // Use the default uri resolver if provided, else use the hardcoded generic default.
        IJB721TokenUriResolver uriResolver = launchProjectData.defaultTokenUriResolver
            != IJB721TokenUriResolver(address(0))
            ? launchProjectData.defaultTokenUriResolver
            : TOKEN_URI_RESOLVER;

        hook.initialize({
            _gameId: gameId,
            _name: launchProjectData.name,
            _symbol: string.concat("DEFIFA #", gameId.toString()),
            _rulesets: RULESETS,
            _baseUri: launchProjectData.baseUri,
            _tokenUriResolver: uriResolver,
            _contractUri: launchProjectData.contractUri,
            _tiers: hookTiers,
            _currency: launchProjectData.token.currency,
            _store: HOOK_STORE,
            _gamePhaseReporter: this,
            _gamePotReporter: this,
            _defaultAttestationDelegate: launchProjectData.defaultAttestationDelegate,
            _tierNames: tierNames
        });

        // Launch the Juicebox rulesets for the reserved project.
        _launchGame({launchProjectData: launchProjectData, gameId: gameId, dataHook: address(hook)});

        // Clone and initialize the new governor.
        GOVERNOR.initializeGame({
            gameId: gameId,
            attestationStartTime: uint256(launchProjectData.attestationStartTime),
            attestationGracePeriod: uint256(launchProjectData.attestationGracePeriod),
            timelockDuration: launchProjectData.timelockDuration
        });

        // Transfer ownership to the specified owner.
        hook.transferOwnership(address(GOVERNOR));

        // Register the actual CREATE2 clone address using the same salt and minimal-proxy init code
        // that produced the deployed hook.
        REGISTRY.registerAddress({
            deployer: address(this),
            salt: keccak256(abi.encodePacked(caller, currentNonce)),
            bytecode: _cloneCreationCodeFor(address(HOOK_CODE_ORIGIN))
        });

        emit LaunchGame({gameId: gameId, hook: hook, governor: GOVERNOR, tokenUriResolver: uriResolver, caller: caller});
    }

    /// @notice Allows this contract to receive 721s.
    function onERC721Received(address, address, uint256, bytes calldata) external pure override returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }

    /// @notice Triggers the no-contest refund mechanism for a game.
    /// @dev Anyone can call this once the game is in the NO_CONTEST phase. This queues a new ruleset without
    /// payout limits, making the surplus equal to the balance so users can cash out at their mint price.
    /// @dev Analogous to fulfillCommitmentsOf for COMPLETE — must be called before NO_CONTEST cash-outs work.
    /// @param gameId The ID of the game to trigger no-contest for.
    function triggerNoContestFor(uint256 gameId) external override {
        // Make sure the game is currently in NO_CONTEST phase.
        DefifaGamePhase phase = currentGamePhaseOf(gameId);
        if (phase != DefifaGamePhase.NO_CONTEST) {
            revert DefifaDeployer_NotNoContest({gameId: gameId, phase: phase});
        }

        // Make sure no-contest hasn't already been triggered.
        if (noContestTriggeredFor[gameId]) revert DefifaDeployer_NoContestAlreadyTriggered({gameId: gameId});

        // Mark as triggered.
        // Note: the queued ruleset does not take effect until the current ruleset's cycle ends (or immediately
        // if duration is 0). During this gap, the game reports NO_CONTEST but the on-chain ruleset still has
        // payout limits, so cash-out reclaim values may differ from the full-refund expectation. Callers
        // should verify the active ruleset before cashing out.
        noContestTriggeredFor[gameId] = true;

        // Get the game's current ruleset metadata for the data hook address.
        (, JBRulesetMetadata memory metadata) = CONTROLLER.currentRulesetOf(gameId);

        // Queue a new ruleset without payout limits so surplus = balance, enabling refunds.
        JBRulesetConfig[] memory rulesetConfigs = new JBRulesetConfig[](1);
        rulesetConfigs[0] = JBRulesetConfig({
            mustStartAtOrAfter: 0,
            duration: 0,
            weight: 0,
            weightCutPercent: 0,
            approvalHook: IJBRulesetApprovalHook(address(0)),
            metadata: JBRulesetMetadata({
                reservedPercent: 0,
                cashOutTaxRate: 0,
                baseCurrency: metadata.baseCurrency,
                pausePay: true,
                pauseCreditTransfers: false,
                allowOwnerMinting: false,
                allowSetCustomToken: false,
                allowTerminalMigration: false,
                allowSetTerminals: false,
                allowSetController: false,
                allowAddAccountingContext: false,
                allowAddPriceFeed: false,
                ownerMustSendPayouts: true,
                holdFees: false,
                scopeCashOutsToLocalBalances: true,
                useDataHookForPay: true,
                useDataHookForCashOut: true,
                dataHook: metadata.dataHook,
                metadata: uint16(
                    JB721TiersRulesetMetadataResolver.pack721TiersRulesetMetadata(
                        JB721TiersRulesetMetadata({pauseTransfers: false, pauseMintPendingReserves: false})
                    )
                )
            }),
            splitGroups: new JBSplitGroup[](0),
            fundAccessLimitGroups: new JBFundAccessLimitGroup[](0)
        });

        // Queue the no-contest refund ruleset.
        CONTROLLER.queueRulesetsOf({
            projectId: gameId, rulesetConfigurations: rulesetConfigs, memo: "Defifa game: no contest."
        });

        emit QueuedNoContest({gameId: gameId, caller: _msgSender()});
    }

    //*********************************************************************//
    // ------------------------ internal functions ----------------------- //
    //*********************************************************************//

    function _buildSplits(
        uint256 gameId,
        address dataHook,
        address token,
        JBSplit[] memory initialSplits
    )
        internal
        returns (JBSplitGroup[] memory)
    {
        uint256 numberOfUserSplits = initialSplits.length;

        // Compute absolute percents for protocol fees.
        uint256 nanaAbsolutePercent = JBConstants.SPLITS_TOTAL_PERCENT / BASE_PROTOCOL_FEE_DIVISOR;
        uint256 defifaAbsolutePercent = JBConstants.SPLITS_TOTAL_PERCENT / DEFIFA_FEE_DIVISOR;

        // Sum all absolute percents.
        uint256 totalAbsolutePercent = nanaAbsolutePercent + defifaAbsolutePercent;
        for (uint256 i; i < numberOfUserSplits;) {
            totalAbsolutePercent += initialSplits[i].percent;
            unchecked {
                ++i;
            }
        }

        // Validate that total fee splits don't exceed 100%.
        if (totalAbsolutePercent > JBConstants.SPLITS_TOTAL_PERCENT) {
            revert DefifaDeployer_SplitsDontAddUp({
                totalPercent: totalAbsolutePercent, maxPercent: JBConstants.SPLITS_TOTAL_PERCENT
            });
        }

        // Store the total absolute percent for use in fulfillCommitmentsOf.
        _commitmentPercentOf[gameId] = totalAbsolutePercent;

        // Build the splits array: user splits + Defifa + NANA (NANA last to absorb rounding).
        uint256 splitCount = numberOfUserSplits + 2;
        JBSplit[] memory splits = new JBSplit[](splitCount);

        // Normalize user splits and copy them over.
        uint256 normalizedTotal;
        for (uint256 i; i < numberOfUserSplits;) {
            splits[i] = initialSplits[i];
            splits[i].percent = uint32(
                mulDiv({
                    x: initialSplits[i].percent, y: JBConstants.SPLITS_TOTAL_PERCENT, denominator: totalAbsolutePercent
                })
            );
            normalizedTotal += splits[i].percent;
            unchecked {
                ++i;
            }
        }

        // Add Defifa fee split (normalized).
        uint256 defifaNormalized =
            mulDiv({x: defifaAbsolutePercent, y: JBConstants.SPLITS_TOTAL_PERCENT, denominator: totalAbsolutePercent});
        splits[numberOfUserSplits] = JBSplit({
            preferAddToBalance: false,
            // forge-lint: disable-next-line(unsafe-typecast)
            percent: uint32(defifaNormalized),
            // forge-lint: disable-next-line(unsafe-typecast)
            projectId: uint64(DEFIFA_PROJECT_ID),
            beneficiary: payable(address(dataHook)),
            lockedUntil: 0,
            hook: IJBSplitHook(address(0))
        });
        normalizedTotal += defifaNormalized;

        // Add NANA protocol fee split last — absorbs rounding remainder from normalization.
        // Because mulDiv rounds down, the sum of normalized percents can be slightly less than SPLITS_TOTAL_PERCENT.
        // The NANA split receives the difference, so its effective percent may be a few basis points above its
        // proportional share. This is economically negligible (< 1 bps at typical split counts).
        // Beneficiary is the data hook so the hook receives NANA tokens for distribution during cash-outs.
        splits[splitCount - 1] = JBSplit({
            preferAddToBalance: false,
            // forge-lint: disable-next-line(unsafe-typecast)
            percent: uint32(JBConstants.SPLITS_TOTAL_PERCENT - normalizedTotal),
            // forge-lint: disable-next-line(unsafe-typecast)
            projectId: uint64(BASE_PROTOCOL_PROJECT_ID),
            beneficiary: payable(address(dataHook)),
            lockedUntil: 0,
            hook: IJBSplitHook(address(0))
        });

        // Build the grouped split for the payment of the game token.
        JBSplitGroup[] memory groupedSplits = new JBSplitGroup[](1);
        groupedSplits[0] = JBSplitGroup({groupId: uint256(uint160(token)), splits: splits});

        return groupedSplits;
    }

    /// @notice Launch the Juicebox project rulesets that define a Defifa game's lifecycle.
    /// @dev The project ID is reserved before the hook clone is initialized, so this function launches rulesets for
    /// that existing project instead of creating a new one. It also forwards `projectUri` to the controller so the
    /// project metadata is set atomically with the first rulesets.
    /// @param launchProjectData The normalized launch data for the game.
    /// @param gameId The reserved Juicebox project ID for the game.
    /// @param dataHook The initialized Defifa hook clone used by every ruleset.
    function _launchGame(DefifaLaunchProjectData memory launchProjectData, uint256 gameId, address dataHook) internal {
        // Accept exactly the token/accounting context the game was configured to use.
        JBAccountingContext[] memory accountingContexts = new JBAccountingContext[](1);
        accountingContexts[0] = launchProjectData.token;

        // Build the terminal configuration for the Defifa project.
        JBTerminalConfig[] memory terminalConfigurations = new JBTerminalConfig[](1);
        terminalConfigurations[0] =
            JBTerminalConfig({terminal: launchProjectData.terminal, accountingContextsToAccept: accountingContexts});

        // Build the rulesets that this Defifa game will go through. Games always have MINT and SCORING phases; the
        // REFUND phase is omitted entirely when its duration is zero so the scoring ruleset can follow minting.
        bool hasRefundPhase = launchProjectData.refundPeriodDuration != 0;
        JBRulesetConfig[] memory rulesetConfigs = new JBRulesetConfig[](hasRefundPhase ? 3 : 2);

        // MINT cycle: payments are accepted, cash-outs are enabled, and pending reserved tokens are paused so the
        // scoring/final phases decide how reserved tokens are distributed.
        rulesetConfigs[0] = JBRulesetConfig({
            mustStartAtOrAfter: launchProjectData.start - launchProjectData.mintPeriodDuration
                - launchProjectData.refundPeriodDuration,
            duration: launchProjectData.mintPeriodDuration,
            weight: 0,
            weightCutPercent: 0,
            approvalHook: IJBRulesetApprovalHook(address(0)),
            metadata: JBRulesetMetadata({
                reservedPercent: 0,
                cashOutTaxRate: 0,
                baseCurrency: launchProjectData.token.currency,
                pausePay: false,
                pauseCreditTransfers: false,
                allowOwnerMinting: false,
                allowSetCustomToken: false,
                allowTerminalMigration: false,
                allowSetTerminals: false,
                allowSetController: false,
                allowAddAccountingContext: false,
                allowAddPriceFeed: false,
                ownerMustSendPayouts: false,
                holdFees: false,
                scopeCashOutsToLocalBalances: true,
                useDataHookForPay: true,
                useDataHookForCashOut: true,
                dataHook: dataHook,
                metadata: uint16(
                    JB721TiersRulesetMetadataResolver.pack721TiersRulesetMetadata(
                        JB721TiersRulesetMetadata({
                            pauseTransfers: false,
                            // Reserved tokens can't be minted during this funding cycle.
                            pauseMintPendingReserves: true
                        })
                    )
                )
            }),
            splitGroups: new JBSplitGroup[](0),
            fundAccessLimitGroups: new JBFundAccessLimitGroup[](0)
        });

        uint256 cycleNumber = 1;
        if (hasRefundPhase) {
            // REFUND cycle: payments are paused while cash-outs remain available at pre-scoring terms.
            rulesetConfigs[cycleNumber++] = JBRulesetConfig({
                mustStartAtOrAfter: launchProjectData.start - launchProjectData.refundPeriodDuration,
                duration: launchProjectData.refundPeriodDuration,
                weight: 0,
                weightCutPercent: 0,
                approvalHook: IJBRulesetApprovalHook(address(0)),
                metadata: JBRulesetMetadata({
                    reservedPercent: 0,
                    cashOutTaxRate: 0,
                    baseCurrency: launchProjectData.token.currency,
                    // Refund phase does not allow new payments.
                    pausePay: true,
                    pauseCreditTransfers: false,
                    allowOwnerMinting: false,
                    allowSetCustomToken: false,
                    allowTerminalMigration: false,
                    allowSetTerminals: false,
                    allowSetController: false,
                    allowAddAccountingContext: false,
                    allowAddPriceFeed: false,
                    ownerMustSendPayouts: false,
                    holdFees: false,
                    scopeCashOutsToLocalBalances: true,
                    useDataHookForPay: true,
                    useDataHookForCashOut: true,
                    dataHook: dataHook,
                    metadata: uint16(
                        JB721TiersRulesetMetadataResolver.pack721TiersRulesetMetadata(
                            JB721TiersRulesetMetadata({
                                pauseTransfers: false,
                                // Reserved tokens can't be minted during this funding cycle.
                                pauseMintPendingReserves: true
                            })
                        )
                    )
                }),
                splitGroups: new JBSplitGroup[](0),
                fundAccessLimitGroups: new JBFundAccessLimitGroup[](0)
            });
        }

        // The scoring ruleset can send the whole pot as payouts. `fulfillCommitmentsOf` only sends the commitment
        // portion and leaves the rest as surplus for the final cash-out ruleset.
        JBCurrencyAmount[] memory payoutAmounts = new JBCurrencyAmount[](1);
        payoutAmounts[0] = JBCurrencyAmount({
            // We allow a payout of the full amount, this will then mostly be added back to the balance of the project.
            amount: type(uint224).max,
            currency: launchProjectData.token.currency
        });

        JBFundAccessLimitGroup[] memory fundAccessConstraints = new JBFundAccessLimitGroup[](1);
        fundAccessConstraints[0] = JBFundAccessLimitGroup({
            terminal: address(launchProjectData.terminal),
            token: launchProjectData.token.token,
            payoutLimits: payoutAmounts,
            surplusAllowances: new JBCurrencyAmount[](0)
        });

        // SCORING cycle: payments pause, the game owner must send payouts, and the Defifa hook determines the final
        // cash-out weights once a scorecard is ratified.
        rulesetConfigs[cycleNumber++] = JBRulesetConfig({
            mustStartAtOrAfter: launchProjectData.start,
            duration: 0,
            weight: 0,
            weightCutPercent: 0,
            approvalHook: IJBRulesetApprovalHook(address(0)),
            metadata: JBRulesetMetadata({
                reservedPercent: 0,
                cashOutTaxRate: 0,
                baseCurrency: launchProjectData.token.currency,
                pausePay: true,
                pauseCreditTransfers: false,
                allowOwnerMinting: false,
                allowSetCustomToken: false,
                allowTerminalMigration: false,
                allowSetTerminals: false,
                allowSetController: false,
                allowAddAccountingContext: false,
                allowAddPriceFeed: false,
                // Set this to true so only the deployer can fulfill the commitments.
                ownerMustSendPayouts: true,
                holdFees: false,
                scopeCashOutsToLocalBalances: true,
                useDataHookForPay: true,
                useDataHookForCashOut: true,
                dataHook: dataHook,
                metadata: uint16(
                    JB721TiersRulesetMetadataResolver.pack721TiersRulesetMetadata(
                        JB721TiersRulesetMetadata({pauseTransfers: false, pauseMintPendingReserves: false})
                    )
                )
            }),
            splitGroups: _buildSplits({
                gameId: gameId,
                dataHook: dataHook,
                token: launchProjectData.token.token,
                initialSplits: launchProjectData.splits
            }),
            fundAccessLimitGroups: fundAccessConstraints
        });

        // Launch the rulesets for the reserved project and set the project URI in the same controller call.
        CONTROLLER.launchRulesetsFor({
            projectId: gameId,
            projectUri: launchProjectData.projectUri,
            rulesetConfigurations: rulesetConfigs,
            terminalConfigurations: terminalConfigurations,
            memo: "Launching Defifa game."
        });
    }

    /// @notice Queues the final ruleset for a game: no payouts, no fund access limits, surplus = entire balance.
    /// @param gameId The ID of the game.
    /// @param metadata The current ruleset metadata (used to carry forward baseCurrency and dataHook).
    function _queueFinalRuleset(uint256 gameId, JBRulesetMetadata memory metadata) internal {
        JBRulesetConfig[] memory rulesetConfigs = new JBRulesetConfig[](1);
        rulesetConfigs[0] = JBRulesetConfig({
            mustStartAtOrAfter: 0,
            duration: 0,
            weight: 0,
            weightCutPercent: 0,
            approvalHook: IJBRulesetApprovalHook(address(0)),
            metadata: JBRulesetMetadata({
                reservedPercent: 0,
                cashOutTaxRate: 0,
                baseCurrency: metadata.baseCurrency,
                pausePay: true,
                pauseCreditTransfers: false,
                allowOwnerMinting: false,
                allowSetCustomToken: false,
                allowTerminalMigration: false,
                allowSetTerminals: false,
                allowSetController: false,
                allowAddAccountingContext: false,
                allowAddPriceFeed: false,
                ownerMustSendPayouts: false,
                holdFees: false,
                scopeCashOutsToLocalBalances: true,
                useDataHookForPay: true,
                useDataHookForCashOut: true,
                dataHook: metadata.dataHook,
                metadata: uint16(
                    JB721TiersRulesetMetadataResolver.pack721TiersRulesetMetadata(
                        JB721TiersRulesetMetadata({pauseTransfers: false, pauseMintPendingReserves: false})
                    )
                )
            }),
            // No more payouts.
            splitGroups: new JBSplitGroup[](0),
            fundAccessLimitGroups: new JBFundAccessLimitGroup[](0)
        });

        CONTROLLER.queueRulesetsOf({
            projectId: gameId, rulesetConfigurations: rulesetConfigs, memo: "Defifa game has finished."
        });
    }

    /// @notice Returns the minimal-proxy init code used to deploy a clone for the provided implementation.
    /// @dev Defifa deploys hooks with `Clones.cloneDeterministic`, which uses `CREATE2`.
    /// The address registry's CREATE2 path must be given the exact init code hash that was used at deployment time,
    /// not the runtime bytecode and not a CREATE nonce. This helper reconstructs the standard EIP-1167 creation code
    /// by inserting the implementation address into OpenZeppelin's minimal-proxy init-code template.
    /// @param implementation The contract address the clone will delegate all calls to.
    /// @return bytecode The full EIP-1167 creation bytecode hashed by CREATE2 to derive the clone address.
    function _cloneCreationCodeFor(address implementation) internal pure returns (bytes memory bytecode) {
        // EIP-1167 minimal proxy init code, mirroring OpenZeppelin's Clones.sol layout:
        // [prefix (20 bytes)] [implementation address (20 bytes)] [suffix (15 bytes)]
        bytecode = abi.encodePacked(
            hex"3d602d80600a3d3981f3363d3d373d3d3d363d73", bytes20(implementation), hex"5af43d82803e903d91602b57fd5bf3"
        );
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IJBController} from "@bananapus/core-v6/src/interfaces/IJBController.sol";
import {JBRulesetMetadata} from "@bananapus/core-v6/src/structs/JBRulesetMetadata.sol";
import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {mulDiv} from "@prb/math/src/Common.sol";

import {DefifaHook} from "./DefifaHook.sol";
import {DefifaGamePhase} from "./enums/DefifaGamePhase.sol";
import {DefifaScorecardState} from "./enums/DefifaScorecardState.sol";
import {IDefifaDeployer} from "./interfaces/IDefifaDeployer.sol";
import {IDefifaGovernor} from "./interfaces/IDefifaGovernor.sol";
import {IJB721TiersHookStore} from "@bananapus/721-hook-v6/src/interfaces/IJB721TiersHookStore.sol";
import {JB721Tier} from "@bananapus/721-hook-v6/src/structs/JB721Tier.sol";
import {IDefifaHook} from "./interfaces/IDefifaHook.sol";
import {DefifaAttestations} from "./structs/DefifaAttestations.sol";
import {DefifaScorecard} from "./structs/DefifaScorecard.sol";
import {DefifaTierCashOutWeight} from "./structs/DefifaTierCashOutWeight.sol";
import {DefifaHookLib} from "./libraries/DefifaHookLib.sol";

/// @notice Manages the ratification of Defifa scorecards through token-weighted attestation. After a game ends,
/// anyone can submit a scorecard proposing cash-out weights for each tier. NFT holders attest to scorecards using
/// their voting power (proportional to NFTs held). A scorecard is ratified once it reaches quorum and survives the
/// grace period, after which the deployer applies the weights to the game's treasury.
contract DefifaGovernor is Ownable, IDefifaGovernor {
    //*********************************************************************//
    // --------------------------- custom errors ------------------------- //
    //*********************************************************************//

    /// @notice Thrown when an account tries to attest to a scorecard it has already attested to.
    error DefifaGovernor_AlreadyAttested(uint256 gameId, uint256 scorecardId, address account);

    /// @notice Thrown when initializing a game whose scorecard info has already been set.
    error DefifaGovernor_AlreadyInitialized(uint256 gameId);

    /// @notice Thrown when submitting or ratifying a scorecard for a game that has already ratified one.
    error DefifaGovernor_AlreadyRatified(uint256 gameId, uint256 scorecardId);

    /// @notice Thrown when submitting a scorecard that has already been submitted for the game.
    error DefifaGovernor_DuplicateScorecard(uint256 gameId, uint256 scorecardId);

    /// @notice Thrown when submitting a scorecard for a game that has not been initialized.
    error DefifaGovernor_GameNotFound(uint256 gameId);

    /// @notice Thrown when initializing a game with an attestation grace period shorter than the minimum allowed.
    error DefifaGovernor_GracePeriodTooShort(uint256 gracePeriod, uint256 minGracePeriod);

    /// @notice Thrown when the action is not allowed: the game is not in its scoring phase, the scorecard is not in an
    /// eligible state, or the caller's attestation weight is zero.
    error DefifaGovernor_NotAllowed(uint256 gameId, uint256 scorecardId, address caller);

    /// @notice Thrown when revoking an attestation that the account never made for the scorecard.
    error DefifaGovernor_NotAttested(uint256 gameId, uint256 scorecardId, address account);

    /// @notice Thrown when a timestamp or duration value exceeds the maximum that fits in a uint48.
    error DefifaGovernor_Uint48Overflow(uint256 value, uint256 max);

    /// @notice Thrown when querying the state of a scorecard that has never been submitted.
    error DefifaGovernor_UnknownProposal(uint256 gameId, uint256 scorecardId);

    /// @notice Thrown when a submitted scorecard assigns a nonzero cash-out weight to a tier that has no live supply.
    error DefifaGovernor_UnownedProposedCashoutValue(uint256 gameId, uint256 tierId, uint256 cashOutWeight);

    //*********************************************************************//
    // ------------------------- public constants ------------------------ //
    //*********************************************************************//

    /// @notice The max attestation power each tier has if every token within the tier attests.
    uint256 public constant override MAX_ATTESTATION_POWER_TIER = 1_000_000_000;

    /// @notice The minimum attestation grace period enforced during game initialization.
    uint256 public constant override MIN_ATTESTATION_GRACE_PERIOD = 1 days;

    //*********************************************************************//
    // --------------- public immutable stored properties ---------------- //
    //*********************************************************************//

    /// @notice The controller with which new projects should be deployed.
    IJBController public immutable override CONTROLLER;

    //*********************************************************************//
    // --------------------- public stored properties -------------------- //
    //*********************************************************************//

    /// @notice The latest proposal submitted by the default attestation delegate.
    /// @custom:param gameId The ID of the game of the default attestation delegate proposal.
    mapping(uint256 => uint256) public override defaultAttestationDelegateProposalOf;

    /// @notice The scorecard that has been ratified.
    /// @custom:param gameId The ID of the game of the ratified scorecard.
    mapping(uint256 => uint256) public override ratifiedScorecardIdOf;

    //*********************************************************************//
    // -------------------- internal stored properties ------------------- //
    //*********************************************************************//

    /// @notice The scorecard information, packed into a uint256.
    /// @dev Bits 0-47: attestationStartTime, bits 48-95: attestationGracePeriod, bits 96-143: timelockDuration.
    /// @custom:param gameId The ID of the game for which the scorecard info applies.
    mapping(uint256 => uint256) internal _packedScorecardInfoOf;

    /// @notice The scorecards.
    /// @custom:param gameId The ID of the game the scorecard affects.
    /// @custom:param scorecardId The ID of the scorecard to retrieve.
    mapping(uint256 => mapping(uint256 => DefifaScorecard)) internal _scorecardOf;

    /// @notice The attestations to a scorecard.
    /// @custom:param gameId The ID of the game the scorecard affects.
    /// @custom:param scorecardId The ID of the scorecard that has been attested to.
    mapping(uint256 => mapping(uint256 => DefifaAttestations)) internal _scorecardAttestationsOf;

    /// @notice Snapshot of pending reserves per tier at scorecard submission time.
    /// @dev Used to keep unminted reserve units in the BWA denominator.
    /// @custom:param gameId The ID of the game.
    /// @custom:param scorecardId The ID of the scorecard.
    /// @custom:param tierId The tier ID (1-indexed).
    mapping(uint256 => mapping(uint256 => mapping(uint256 => uint256))) internal _pendingReservesSnapshotOf;

    /// @notice Snapshot of each tier's minted attestation units at scorecard submission time.
    /// @dev Caps later checkpoint reads so reserve mints after submission can't increase the denominator
    /// before the pending-reserve snapshot is added back in.
    /// @custom:param gameId The ID of the game.
    /// @custom:param scorecardId The ID of the scorecard.
    /// @custom:param tierId The tier ID (1-indexed).
    mapping(uint256 => mapping(uint256 => mapping(uint256 => uint256))) internal _submittedTierAttestationUnitsOf;

    /// @notice Tier weights per scorecard for BWA computation.
    /// @custom:param gameId The ID of the game.
    /// @custom:param scorecardId The ID of the scorecard.
    /// @custom:param tierId The tier ID (0-indexed).
    mapping(uint256 => mapping(uint256 => mapping(uint256 => uint256))) internal _scorecardTierWeightsOf;

    /// @notice The timestamp when quorum was first reached for a scorecard.
    /// @dev Reset to 0 if attestations drop below quorum via revocation.
    /// @custom:param gameId The ID of the game.
    /// @custom:param scorecardId The ID of the scorecard.
    mapping(uint256 => mapping(uint256 => uint48)) internal _quorumReachedAtOf;

    //*********************************************************************//
    // -------------------------- constructor ---------------------------- //
    //*********************************************************************//

    constructor(IJBController controller, address owner) Ownable(owner) {
        CONTROLLER = controller;
    }

    //*********************************************************************//
    // ---------------------- external transactions ---------------------- //
    //*********************************************************************//

    /// @notice Cast an attestation supporting a proposed scorecard, weighted by the caller's tier voting power.
    /// @param gameId The ID of the game to which the scorecard belongs.
    /// @param scorecardId The scorecard ID.
    /// @return weight The attestation weight that was applied.
    function attestToScorecardFrom(uint256 gameId, uint256 scorecardId) external override returns (uint256 weight) {
        // Get the game's current funding cycle along with its metadata.
        (, JBRulesetMetadata memory metadata) = CONTROLLER.currentRulesetOf(gameId);

        // Make sure the game is in its scoring phase.
        if (IDefifaHook(metadata.dataHook).gamePhaseReporter().currentGamePhaseOf(gameId) != DefifaGamePhase.SCORING) {
            revert DefifaGovernor_NotAllowed({gameId: gameId, scorecardId: scorecardId, caller: msg.sender});
        }

        // Keep a reference to the scorecard being attested to.
        DefifaScorecard storage scorecard = _scorecardOf[gameId][scorecardId];

        // Keep a reference to the scorecard state.
        DefifaScorecardState state = stateOf({gameId: gameId, scorecardId: scorecardId});

        // Attestations are only allowed during ACTIVE, SUCCEEDED, or QUEUED states.
        if (
            state != DefifaScorecardState.ACTIVE && state != DefifaScorecardState.SUCCEEDED
                && state != DefifaScorecardState.QUEUED
        ) {
            revert DefifaGovernor_NotAllowed({gameId: gameId, scorecardId: scorecardId, caller: msg.sender});
        }

        // Keep a reference to the attestations for the scorecard.
        DefifaAttestations storage attestations = _scorecardAttestationsOf[gameId][scorecardId];

        // Make sure the account isn't attesting to the same scorecard again.
        if (attestations.attestedWeightOf[msg.sender] != 0) {
            revert DefifaGovernor_AlreadyAttested({gameId: gameId, scorecardId: scorecardId, account: msg.sender});
        }

        // Get a reference to the BWA-adjusted attestation weight, read at the scorecard's frozen snapshot
        // timestamp (one second before submission). This excludes the entire submission block, so a mint or
        // transfer sharing that block cannot grant or move attestation power for this scorecard.
        weight = getBWAAttestationWeight({
            gameId: gameId, scorecardId: scorecardId, account: msg.sender, timestamp: scorecard.snapshotTimestamp
        });

        // Revert if BWA reduces this account's power to zero (e.g. 100% beneficiary of the scorecard).
        // Without this guard, zero-weight attestors could call repeatedly since attestedWeightOf stays 0.
        if (weight == 0) {
            revert DefifaGovernor_NotAllowed({gameId: gameId, scorecardId: scorecardId, caller: msg.sender});
        }

        // Increase the attestation count.
        attestations.count += weight;

        // Record when quorum is first reached so the timelock anchors to this moment.
        if (_quorumReachedAtOf[gameId][scorecardId] == 0 && attestations.count >= scorecard.quorumSnapshot) {
            _quorumReachedAtOf[gameId][scorecardId] = uint48(block.timestamp);
        }

        // Store the BWA weight that was added (used for accurate subtraction on revoke).
        attestations.attestedWeightOf[msg.sender] = weight;

        emit ScorecardAttested({gameId: gameId, scorecardId: scorecardId, weight: weight, caller: msg.sender});
    }

    /// @notice Ratifies a scorecard that has been approved.
    /// @param gameId The ID of the game.
    /// @param tierWeights The weights of each tier in the approved scorecard.
    /// @return scorecardId The scorecard ID that was ratified.
    function ratifyScorecardFrom(
        uint256 gameId,
        DefifaTierCashOutWeight[] calldata tierWeights
    )
        external
        override
        returns (uint256 scorecardId)
    {
        // Make sure a scorecard hasn't been ratified yet.
        if (ratifiedScorecardIdOf[gameId] != 0) {
            revert DefifaGovernor_AlreadyRatified({gameId: gameId, scorecardId: ratifiedScorecardIdOf[gameId]});
        }

        // Get the game's current funding cycle along with its metadata.
        (, JBRulesetMetadata memory metadata) = CONTROLLER.currentRulesetOf(gameId);

        // Build the calldata to the target.
        bytes memory scorecardCalldata = _buildScorecardCalldataFor(tierWeights);

        // Hash the scorecard to derive its ID.
        scorecardId = _hashScorecardOf({gameHook: metadata.dataHook, calldataBytes: scorecardCalldata});

        // Make sure the proposal being ratified has succeeded.
        if (stateOf({gameId: gameId, scorecardId: scorecardId}) != DefifaScorecardState.SUCCEEDED) {
            revert DefifaGovernor_NotAllowed({gameId: gameId, scorecardId: scorecardId, caller: msg.sender});
        }

        // Set the ratified scorecard.
        ratifiedScorecardIdOf[gameId] = scorecardId;

        // Execute the scorecard via low-level call since the governor is the delegate's owner.
        (bool success, bytes memory returndata) = metadata.dataHook.call(scorecardCalldata);
        Address.verifyCallResult({success: success, returndata: returndata});

        // Fulfill any commitments for the game. The internal try-catch in fulfillCommitmentsOf
        // handles sendPayoutsOf failures, ensuring the final ruleset is always queued.
        IDefifaDeployer(CONTROLLER.PROJECTS().ownerOf(gameId)).fulfillCommitmentsOf(gameId);

        emit ScorecardRatified({gameId: gameId, scorecardId: scorecardId, caller: msg.sender});
    }

    /// @notice Revoke a previously submitted attestation. Only allowed during the ACTIVE phase.
    /// @dev Once a scorecard enters QUEUED (grace period ended + quorum met), revocations are disabled.
    /// This prevents the griefing loop (attest/revoke cycling) while allowing corrective action during debate.
    /// @param gameId The ID of the game.
    /// @param scorecardId The ID of the scorecard to revoke attestation from.
    function revokeAttestationFrom(uint256 gameId, uint256 scorecardId) external virtual override {
        // Only allow revocation during ACTIVE phase.
        if (stateOf({gameId: gameId, scorecardId: scorecardId}) != DefifaScorecardState.ACTIVE) {
            revert DefifaGovernor_NotAllowed({gameId: gameId, scorecardId: scorecardId, caller: msg.sender});
        }

        DefifaAttestations storage attestations = _scorecardAttestationsOf[gameId][scorecardId];
        uint256 weight = attestations.attestedWeightOf[msg.sender];

        // Must have previously attested.
        if (weight == 0) {
            revert DefifaGovernor_NotAttested({gameId: gameId, scorecardId: scorecardId, account: msg.sender});
        }

        // Subtract the weight and clear the attestation.
        attestations.count -= weight;
        attestations.attestedWeightOf[msg.sender] = 0;

        // Reset quorum timestamp if attestations drop below quorum.
        DefifaScorecard storage scorecard = _scorecardOf[gameId][scorecardId];
        if (attestations.count < scorecard.quorumSnapshot) {
            _quorumReachedAtOf[gameId][scorecardId] = 0;
        }

        emit AttestationRevoked({
            gameId: gameId, scorecardId: scorecardId, account: msg.sender, weight: weight, caller: msg.sender
        });
    }

    /// @notice Submits a scorecard to be attested to.
    /// @param gameId The ID of the game.
    /// @param tierWeights The weights of each tier in the scorecard.
    /// @return scorecardId The scorecard's ID.
    function submitScorecardFor(
        uint256 gameId,
        DefifaTierCashOutWeight[] calldata tierWeights
    )
        external
        override
        returns (uint256 scorecardId)
    {
        // Make sure a proposal hasn't yet been ratified.
        if (ratifiedScorecardIdOf[gameId] != 0) {
            revert DefifaGovernor_AlreadyRatified({gameId: gameId, scorecardId: ratifiedScorecardIdOf[gameId]});
        }

        // Make sure the game has been initialized.
        if (_packedScorecardInfoOf[gameId] == 0) revert DefifaGovernor_GameNotFound({gameId: gameId});

        // Keep a reference to the number of tier weights in the proposed scorecard.
        uint256 numberOfTierWeights = tierWeights.length;

        // Get the game's current funding cycle along with its metadata.
        (, JBRulesetMetadata memory metadata) = CONTROLLER.currentRulesetOf(gameId);

        // Make sure the game is in its scoring phase.
        if (IDefifaHook(metadata.dataHook).gamePhaseReporter().currentGamePhaseOf(gameId) != DefifaGamePhase.SCORING) {
            revert DefifaGovernor_NotAllowed({gameId: gameId, scorecardId: 0, caller: msg.sender});
        }

        // If there's a weight assigned to the tier, make sure there is a token backed by it.
        for (uint256 i; i < numberOfTierWeights;) {
            // A nonzero cash-out weight is only valid once that tier has live ownership.
            uint256 currentTierSupply = IDefifaHook(metadata.dataHook).currentSupplyOfTier(tierWeights[i].id);
            if (tierWeights[i].cashOutWeight > 0 && currentTierSupply == 0) {
                revert DefifaGovernor_UnownedProposedCashoutValue({
                    gameId: gameId, tierId: tierWeights[i].id, cashOutWeight: tierWeights[i].cashOutWeight
                });
            }
            unchecked {
                ++i;
            }
        }

        // Cache the hook store to avoid repeated external calls.
        IJB721TiersHookStore hookStore = IDefifaHook(metadata.dataHook).store();

        // Run the same structural validation the hook will apply at ratification time so malformed
        // scorecards fail on submission instead of reaching a misleading SUCCEEDED state first.
        DefifaHookLib.validateAndBuildWeights({tierWeights: tierWeights, hookStore: hookStore, hook: metadata.dataHook});

        // Hash the scorecard.
        scorecardId =
            _hashScorecardOf({gameHook: metadata.dataHook, calldataBytes: _buildScorecardCalldataFor(tierWeights)});

        // Store the scorecard.
        DefifaScorecard storage scorecard = _scorecardOf[gameId][scorecardId];
        if (scorecard.attestationsBegin != 0) {
            revert DefifaGovernor_DuplicateScorecard({gameId: gameId, scorecardId: scorecardId});
        }

        uint256 attestationStartTime = attestationStartTimeOf(gameId);

        // Game phase timing is timestamp-based by design. If attestations would otherwise open immediately,
        // wait until the next timestamp so the attestation window opens in a later block than submission,
        // preventing same-block attestation. The BWA snapshot is taken separately, one second before submission.
        uint256 currentTimestamp = block.timestamp;
        uint256 attestationsBeginTimestamp = attestationStartTime;
        if (currentTimestamp >= attestationStartTime) attestationsBeginTimestamp = currentTimestamp + 1;

        if (attestationsBeginTimestamp > type(uint48).max) {
            revert DefifaGovernor_Uint48Overflow({value: attestationsBeginTimestamp, max: type(uint48).max});
        }

        // Safe after the explicit max check above.
        // forge-lint: disable-next-line(unsafe-typecast)
        uint48 attestationsBegin = uint48(attestationsBeginTimestamp);
        scorecard.attestationsBegin = attestationsBegin;
        // Grace period extends from when attestations begin, not from submission time.
        // This prevents the grace period from expiring before attestations even start
        // when a scorecard is submitted early.
        uint256 gracePeriodEnds = uint256(attestationsBegin) + attestationGracePeriodOf(gameId);
        if (gracePeriodEnds > type(uint48).max) {
            revert DefifaGovernor_Uint48Overflow({value: gracePeriodEnds, max: type(uint48).max});
        }
        // Safe after the explicit max check above.
        // forge-lint: disable-next-line(unsafe-typecast)
        scorecard.gracePeriodEnds = uint48(gracePeriodEnds);

        // Freeze the BWA snapshot one second before submission. `getPastTier*AttestationUnitsOf` reads checkpoints
        // keyed by `block.timestamp`, and same-timestamp checkpoint writes overwrite in place — so reading at the
        // submission timestamp would let a mint or transfer in the submission block (in either order relative to
        // submission) change this scorecard's attestation power. Reading one second earlier excludes the entire
        // submission block.
        // Safe: `currentTimestamp - 1 < attestationsBeginTimestamp <= type(uint48).max` per the check above.
        // forge-lint: disable-next-line(unsafe-typecast)
        scorecard.snapshotTimestamp = uint48(currentTimestamp - 1);

        // Store tier weights for BWA computation.
        for (uint256 i; i < numberOfTierWeights;) {
            _scorecardTierWeightsOf[gameId][scorecardId][tierWeights[i].id - 1] = tierWeights[i].cashOutWeight;
            unchecked {
                ++i;
            }
        }

        // Snapshot each tier's pending reserves and minted attestation units at submission time.
        // BWA later reads an account checkpoint at `attestationsBegin - 1`. If reserve mints happen
        // after submission but before that checkpoint, clamp the live total back down to the minted
        // units that existed at submission and only then add the snapshotted pending reserves.
        {
            // Cache the number of tiers to avoid re-reading from storage.
            uint256 numberOfTiers = hookStore.maxTierIdOf(metadata.dataHook);
            for (uint256 i; i < numberOfTiers;) {
                uint256 tierId = i + 1;
                JB721Tier memory tier =
                    hookStore.tierOf({hook: metadata.dataHook, id: tierId, includeResolvedUri: false});
                // Use adjusted pending reserves that account for refund-phase burns.
                uint256 pendingReserves = IDefifaHook(metadata.dataHook).adjustedPendingReservesFor(tierId);
                uint256 submittedTierAttestationUnits =
                    IDefifaHook(metadata.dataHook).currentSupplyOfTier(tierId) * tier.votingUnits;
                _pendingReservesSnapshotOf[gameId][scorecardId][tierId] = pendingReserves;
                _submittedTierAttestationUnitsOf[gameId][scorecardId][tierId] = submittedTierAttestationUnits;
                unchecked {
                    ++i;
                }
            }
        }

        // Concentration-adjusted quorum: penalty = headroom * maxShare².
        // Headroom = max achievable BWA - base quorum = (N-2) * MAX / 2.
        // This is the gap honest attestors can fill above base quorum.
        // maxShare² is nonlinear: gentle for moderate concentration, steep for extreme.
        // The penalty can never exceed headroom, so quorum is always reachable by non-beneficiaries.
        uint256 baseQuorum = quorum(gameId);
        uint256 adjustedQuorum = baseQuorum;

        if (baseQuorum >= MAX_ATTESTATION_POWER_TIER) {
            // headroom = maxBWA - baseQuorum = (N-1)*MAX - N*MAX/2 = (N-2)*MAX/2.
            uint256 headroom = baseQuorum - MAX_ATTESTATION_POWER_TIER;
            // Subtract numberOfTierWeights to account for per-tier mulDiv truncation in BWA.
            if (headroom > numberOfTierWeights) headroom -= numberOfTierWeights;

            // Find the largest tier weight.
            uint256 totalCashOutWeight = IDefifaHook(metadata.dataHook).TOTAL_CASHOUT_WEIGHT();
            uint256 maxWeight;
            for (uint256 i; i < numberOfTierWeights;) {
                if (tierWeights[i].cashOutWeight > maxWeight) maxWeight = tierWeights[i].cashOutWeight;
                unchecked {
                    ++i;
                }
            }

            // maxShare² in totalCashOutWeight scale (nonlinear: gentle for moderate, steep for extreme).
            uint256 maxShareSquared = mulDiv({x: maxWeight, y: maxWeight, denominator: totalCashOutWeight});

            // Penalty fills headroom proportional to concentration².
            adjustedQuorum += mulDiv({x: headroom, y: maxShareSquared, denominator: totalCashOutWeight});
        }

        scorecard.quorumSnapshot = adjustedQuorum;

        // Keep a reference to the default attestation delegate.
        address defaultAttestationDelegate = IDefifaHook(metadata.dataHook).defaultAttestationDelegate();

        // If the scorecard is being sent from the default attestation delegate, store it.
        if (msg.sender == defaultAttestationDelegate) {
            defaultAttestationDelegateProposalOf[gameId] = scorecardId;
        }

        emit ScorecardSubmitted({
            gameId: gameId,
            scorecardId: scorecardId,
            tierWeights: tierWeights,
            isDefaultAttestationDelegate: msg.sender == defaultAttestationDelegate,
            caller: msg.sender
        });
    }

    //*********************************************************************//
    // ----------------------- external views ---------------------------- //
    //*********************************************************************//

    /// @notice The number of attestations the given scorecard has.
    /// @param gameId The ID of the game to which the scorecard belongs.
    /// @param scorecardId The ID of the scorecard to get attestations of.
    /// @return The number of attestations the given scorecard has.
    function attestationCountOf(uint256 gameId, uint256 scorecardId) external view returns (uint256) {
        return _scorecardAttestationsOf[gameId][scorecardId].count;
    }

    /// @notice A flag indicating if the given account has already attested to the scorecard.
    /// @param gameId The ID of the game to which the scorecard belongs.
    /// @param scorecardId The ID of the scorecard to query attestations from.
    /// @param account The address to check the attestation status of.
    /// @return A flag indicating if the given account has already attested to the scorecard.
    function hasAttestedTo(uint256 gameId, uint256 scorecardId, address account) external view returns (bool) {
        return _scorecardAttestationsOf[gameId][scorecardId].attestedWeightOf[account] != 0;
    }

    /// @notice The ID of a scorecard representing the provided tier weights.
    /// @param gameHook The address where the game is played.
    /// @param tierWeights The weights of each tier in the scorecard.
    function scorecardIdOf(
        address gameHook,
        DefifaTierCashOutWeight[] calldata tierWeights
    )
        external
        pure
        virtual
        override
        returns (uint256)
    {
        return _hashScorecardOf({gameHook: gameHook, calldataBytes: _buildScorecardCalldataFor(tierWeights)});
    }

    //*********************************************************************//
    // ----------------------- public transactions ----------------------- //
    //*********************************************************************//

    /// @notice Initialize governance for a newly deployed game, setting the initial block number for vote accounting.
    /// @param gameId The ID of the game.
    /// @param attestationStartTime The amount of time between a scorecard submission and attestations becoming enabled,
    /// measured in seconds.
    /// @param attestationGracePeriod The amount of time that must go by before a scorecard can be ratified.
    /// @param timelockDuration The cooling period after quorum is met before a scorecard can be ratified.
    function initializeGame(
        uint256 gameId,
        uint256 attestationStartTime,
        uint256 attestationGracePeriod,
        uint256 timelockDuration
    )
        public
        virtual
        override
        onlyOwner
    {
        // Make sure the game hasn't already been initialized.
        if (_packedScorecardInfoOf[gameId] != 0) revert DefifaGovernor_AlreadyInitialized({gameId: gameId});

        // Set a default attestation start time if needed.
        if (attestationStartTime == 0) attestationStartTime = block.timestamp;

        // Enforce a minimum grace period to prevent instant ratification.
        if (attestationGracePeriod < MIN_ATTESTATION_GRACE_PERIOD) {
            revert DefifaGovernor_GracePeriodTooShort({
                gracePeriod: attestationGracePeriod, minGracePeriod: MIN_ATTESTATION_GRACE_PERIOD
            });
        }

        // Ensure values fit within their allocated 48-bit widths before packing.
        if (attestationStartTime > type(uint48).max) {
            revert DefifaGovernor_Uint48Overflow({value: attestationStartTime, max: type(uint48).max});
        }
        if (attestationGracePeriod > type(uint48).max) {
            revert DefifaGovernor_Uint48Overflow({value: attestationGracePeriod, max: type(uint48).max});
        }
        if (timelockDuration > type(uint48).max) {
            revert DefifaGovernor_Uint48Overflow({value: timelockDuration, max: type(uint48).max});
        }

        // Pack the values.
        uint256 packed;
        // attestation start time in bits 0-47 (48 bits).
        packed |= attestationStartTime;
        // attestation grace period in bits 48-95 (48 bits).
        packed |= attestationGracePeriod << 48;
        // timelock duration in bits 96-143 (48 bits).
        packed |= timelockDuration << 96;

        // Store the packed value.
        _packedScorecardInfoOf[gameId] = packed;

        emit GameInitialized({
            gameId: gameId,
            attestationStartTime: attestationStartTime,
            attestationGracePeriod: attestationGracePeriod,
            timelockDuration: timelockDuration,
            caller: msg.sender
        });
    }

    //*********************************************************************//
    // -------------------------- public views --------------------------- //
    //*********************************************************************//

    /// @notice The amount of time that must go by before a scorecard can be ratified.
    /// @param gameId The ID of the game to get the attestation period of.
    /// @return The attestation grace period, in seconds.
    function attestationGracePeriodOf(uint256 gameId) public view override returns (uint256) {
        // attestation grace period in bits 48-95 (48 bits).
        return uint256(uint48(_packedScorecardInfoOf[gameId] >> 48));
    }

    /// @notice The delay, in seconds, between scorecard submission and enabled attestations.
    /// @dev This can be increased to leave time for users to acquire attestation power, or delegate it, before
    /// a scorecard becomes live.
    /// @param gameId The ID of the game to get the attestation delay of.
    /// @return The delay, in seconds.
    function attestationStartTimeOf(uint256 gameId) public view override returns (uint256) {
        // attestation start time in bits 0-47 (48 bits).
        return uint256(uint48(_packedScorecardInfoOf[gameId]));
    }

    /// @notice Gets an account's attestation power given a number of tiers to look through.
    /// @dev An account's power per tier = MAX_ATTESTATION_POWER_TIER * (account's units / tier's total units).
    /// This means within a tier, power is proportional to token holdings, but across tiers, each tier's
    /// total power is capped at MAX_ATTESTATION_POWER_TIER. A holder of 1-of-1 in a tier gets
    /// MAX_ATTESTATION_POWER_TIER; a holder of 1-of-100 gets MAX_ATTESTATION_POWER_TIER / 100.
    /// This ensures each game outcome (tier) has equal governance weight — the scorecard reflects
    /// consensus across outcomes, not dominance by whichever outcome sold the most tokens.
    /// @param gameId The ID of the game to count attestations for.
    /// @param account The account to get attestations for.
    /// @param timestamp The timestamp to measure attestations from.
    /// @return attestationPower The amount of attestation power of an account.
    function getAttestationWeight(
        uint256 gameId,
        address account,
        uint48 timestamp
    )
        public
        view
        virtual
        returns (uint256 attestationPower)
    {
        // Get the game's current funding cycle along with its metadata.
        (, JBRulesetMetadata memory metadata) = CONTROLLER.currentRulesetOf(gameId);

        // Get a reference to the hook and its store.
        IDefifaHook hook = IDefifaHook(metadata.dataHook);
        IJB721TiersHookStore store = hook.store();

        // Get a reference to the number of tiers.
        uint256 numberOfTiers = store.maxTierIdOf(metadata.dataHook);

        for (uint256 i; i < numberOfTiers;) {
            // Tiers are 1-indexed.
            uint256 tierId = i + 1;

            // Get this account's attestation units within the tier (snapshot at timestamp).
            uint256 tierAttestationUnitsForAccount =
                hook.getPastTierAttestationUnitsOf({account: account, tier: tierId, timestamp: timestamp});

            // Get the total attestation units for this tier (snapshot at timestamp).
            uint256 tierTotalAttestationUnits =
                hook.getPastTierTotalAttestationUnitsOf({tier: tierId, timestamp: timestamp});

            // Include unminted pending reserves in the total (denominator only). This ensures every
            // token holder's voting power already accounts for reserves that will eventually be minted.
            // When the reserve beneficiary later mints, their new NFTs add to the numerator while
            // pending reserves decrease by the same amount — so no one's voting power shifts.
            {
                // Use adjusted pending reserves that account for refund-phase burns.
                uint256 pendingReserves = IDefifaHook(metadata.dataHook).adjustedPendingReservesFor(tierId);
                if (pendingReserves != 0) {
                    JB721Tier memory tier =
                        store.tierOf({hook: metadata.dataHook, id: tierId, includeResolvedUri: false});
                    tierTotalAttestationUnits += pendingReserves * tier.votingUnits;
                }
            }

            // Scale the account's share of the tier to MAX_ATTESTATION_POWER_TIER.
            // e.g. holding 3 of 10 tokens -> 3/10 * MAX_ATTESTATION_POWER_TIER attestation power from this tier.
            unchecked {
                if (tierAttestationUnitsForAccount != 0) {
                    attestationPower += mulDiv({
                        x: MAX_ATTESTATION_POWER_TIER,
                        y: tierAttestationUnitsForAccount,
                        denominator: tierTotalAttestationUnits
                    });
                }
                ++i;
            }
        }
    }

    /// @notice Gets an account's BWA-adjusted attestation power relative to a specific scorecard.
    /// @dev BWA (Benefit-Weighted Attestation) reduces a tier's attestation power by how much
    /// that tier benefits from the scorecard. Power is reduced by `(tierWeight / totalCashOutWeight)`.
    /// This means a tier with 100% of the scorecard weight gets 0 attestation power for that scorecard,
    /// while a tier with 0% weight retains full power. This prevents beneficiaries from self-attesting.
    /// @param gameId The ID of the game.
    /// @param scorecardId The ID of the scorecard (determines tier weight lookup).
    /// @param account The account to compute BWA power for.
    /// @param timestamp The snapshot timestamp.
    /// @return bwaAttestationPower The BWA-adjusted attestation power.
    // forge-lint: disable-next-line(mixed-case-function)
    function getBWAAttestationWeight(
        uint256 gameId,
        uint256 scorecardId,
        address account,
        uint48 timestamp
    )
        public
        view
        virtual
        override
        returns (uint256 bwaAttestationPower)
    {
        // Get the game's current funding cycle along with its metadata.
        (, JBRulesetMetadata memory metadata) = CONTROLLER.currentRulesetOf(gameId);

        // Get a reference to the hook and its store.
        IDefifaHook hook = IDefifaHook(metadata.dataHook);
        IJB721TiersHookStore store = hook.store();

        // Get a reference to the number of tiers.
        uint256 numberOfTiers = store.maxTierIdOf(metadata.dataHook);

        // Cache the total cash-out weight denominator from the hook.
        uint256 totalCashOutWeight = hook.TOTAL_CASHOUT_WEIGHT();

        for (uint256 i; i < numberOfTiers;) {
            // Tiers are 1-indexed.
            uint256 tierId = i + 1;

            // Get this account's attestation units within the tier (snapshot at timestamp).
            uint256 tierAttestationUnitsForAccount =
                hook.getPastTierAttestationUnitsOf({account: account, tier: tierId, timestamp: timestamp});

            if (tierAttestationUnitsForAccount != 0) {
                // Start from the checkpointed tier total at the requested timestamp.
                // If reserve mints happened after submission, clamp them out before adding the
                // pending-reserve snapshot back in so each reserve unit is counted exactly once.
                uint256 tierTotalAttestationUnits =
                    hook.getPastTierTotalAttestationUnitsOf({tier: tierId, timestamp: timestamp});
                uint256 submittedTierAttestationUnits = _submittedTierAttestationUnitsOf[gameId][scorecardId][tierId];
                // Clamp the total to the submitted snapshot to exclude post-submission reserve mints.
                if (tierTotalAttestationUnits > submittedTierAttestationUnits) {
                    tierTotalAttestationUnits = submittedTierAttestationUnits;
                }

                // Add back the snapshotted pending reserves.
                uint256 pendingReserves = _pendingReservesSnapshotOf[gameId][scorecardId][tierId];
                if (pendingReserves != 0) {
                    JB721Tier memory tier =
                        store.tierOf({hook: metadata.dataHook, id: tierId, includeResolvedUri: false});
                    tierTotalAttestationUnits += pendingReserves * tier.votingUnits;
                }

                // Raw power for this tier.
                uint256 rawPower = mulDiv({
                    x: MAX_ATTESTATION_POWER_TIER,
                    y: tierAttestationUnitsForAccount,
                    denominator: tierTotalAttestationUnits
                });

                // BWA reduction: power * (1 - tierWeight / totalCashOutWeight).
                uint256 tierWeight = _scorecardTierWeightsOf[gameId][scorecardId][i];
                uint256 bwaMultiplier = totalCashOutWeight - tierWeight;

                bwaAttestationPower += mulDiv({x: rawPower, y: bwaMultiplier, denominator: totalCashOutWeight});
            }

            unchecked {
                ++i;
            }
        }
    }

    /// @notice The number of attestation units that must have participated in a proposal for it to be ratified.
    /// @dev Each tier with participation contributes MAX_ATTESTATION_POWER_TIER to the total eligible weight.
    /// A tier counts as "participated" if it has circulating tokens OR unminted pending reserves — the latter
    /// means mints occurred (triggering reserve accrual) even if all paid tokens were later burned during REFUND.
    /// Quorum is 50% of this total. Because every tier has equal max attestation power regardless of supply,
    /// each tier's community has equal influence. This prevents high-supply tiers from dominating governance.
    /// @dev No snapshot needed: during SCORING, supply is frozen (no new paid mints, no burns). Reserve minting
    /// doesn't change which tiers are counted because tiers with pending reserves are already included.
    /// @return The quorum number of attestations.
    function quorum(uint256 gameId) public view override returns (uint256) {
        // Get the game's current funding cycle along with its metadata.
        (, JBRulesetMetadata memory metadata) = CONTROLLER.currentRulesetOf(gameId);

        // Get a reference to the hook and its store.
        IDefifaHook hook = IDefifaHook(metadata.dataHook);
        IJB721TiersHookStore store = hook.store();

        // Get a reference to the number of tiers.
        uint256 numberOfTiers = store.maxTierIdOf(metadata.dataHook);

        // Keep a reference to the total eligible tier weight.
        uint256 eligibleTierWeights;

        for (uint256 i; i < numberOfTiers;) {
            uint256 tierId = i + 1;

            // A tier contributes to quorum if it has circulating tokens OR unminted pending reserves.
            // Pending reserves still belong economically to the reserve beneficiary, even after the
            // last paid token in the tier is burned during REFUND, so excluding them would let a
            // burner erase another participant's quorum contribution without erasing their claim.
            uint256 currentTierSupply = hook.currentSupplyOfTier(tierId);
            // Use adjusted pending reserves that account for refund-phase burns.
            uint256 pendingReserves = hook.adjustedPendingReservesFor(tierId);
            if (currentTierSupply != 0 || pendingReserves != 0) {
                eligibleTierWeights += MAX_ATTESTATION_POWER_TIER;
            }

            unchecked {
                ++i;
            }
        }

        // Quorum = 50% of all participated tiers' attestation power.
        return eligibleTierWeights / 2;
    }

    /// @notice Get the current governance state (pending, active, defeated, succeeded) of a scorecard proposal.
    /// @param gameId The ID of the game to get a proposal state of.
    /// @param scorecardId The ID of the proposal to get the state of.
    /// @return The state.
    /// @dev Boundary semantics (inclusive):
    ///   - At exactly `attestationsBegin`, the state transitions from PENDING to ACTIVE (attestations are open).
    ///   - At exactly `gracePeriodEnds`, the grace period has elapsed and the state transitions from ACTIVE to
    ///     QUEUED (if quorum met + timelock > 0) or SUCCEEDED (if quorum met + no timelock).
    function stateOf(uint256 gameId, uint256 scorecardId) public view virtual override returns (DefifaScorecardState) {
        // Keep a reference to the ratified scorecard ID.
        uint256 ratifiedScorecardId = ratifiedScorecardIdOf[gameId];

        // If the game has already ratified a scorecard, return succeeded if the ratified proposal is being checked.
        // Else return defeated.
        if (ratifiedScorecardId != 0) {
            return ratifiedScorecardId == scorecardId ? DefifaScorecardState.RATIFIED : DefifaScorecardState.DEFEATED;
        }

        // Get a reference to the scorecard.
        DefifaScorecard memory scorecard = _scorecardOf[gameId][scorecardId];

        // Make sure the proposal is known.
        if (scorecard.attestationsBegin == 0) {
            revert DefifaGovernor_UnknownProposal({gameId: gameId, scorecardId: scorecardId});
        }

        // If the scorecard has attestations beginning in the future, the state is PENDING.
        // At exactly `attestationsBegin`, attestations are open so the state is ACTIVE.
        // Game phase timing is timestamp-based by design.
        // forge-lint: disable-next-line(block-timestamp)
        if (scorecard.attestationsBegin > block.timestamp) {
            return DefifaScorecardState.PENDING;
        }

        // If the scorecard's grace period has not yet ended, the state is ACTIVE.
        // At exactly `gracePeriodEnds`, the grace period has elapsed so we fall through to the quorum check.
        // Game phase timing is timestamp-based by design.
        // forge-lint: disable-next-line(block-timestamp)
        if (scorecard.gracePeriodEnds > block.timestamp) {
            return DefifaScorecardState.ACTIVE;
        }

        // If quorum has been reached (using the concentration-adjusted snapshot), check timelock.
        if (scorecard.quorumSnapshot <= _scorecardAttestationsOf[gameId][scorecardId].count) {
            uint256 timelockDur = timelockDurationOf(gameId);
            if (timelockDur > 0) {
                // Anchor the timelock to the later of grace period end or when quorum was reached.
                uint256 quorumReachedAt = _quorumReachedAtOf[gameId][scorecardId];
                uint256 timelockAnchor =
                    quorumReachedAt > scorecard.gracePeriodEnds ? quorumReachedAt : uint256(scorecard.gracePeriodEnds);
                // Game phase timing is timestamp-based by design.
                // forge-lint: disable-next-line(block-timestamp)
                if (block.timestamp < timelockAnchor + timelockDur) {
                    return DefifaScorecardState.QUEUED;
                }
            }
            return DefifaScorecardState.SUCCEEDED;
        }

        // Scorecards that fail to reach quorum remain ACTIVE indefinitely — there is no DEFEATED
        // state transition for unratified scorecards. This is by design: new scorecards can always be
        // submitted and the game's no-contest timeout (scorecardTimeout) provides the ultimate backstop.
        return DefifaScorecardState.ACTIVE;
    }

    /// @notice The timelock duration for a game (cooling period after quorum + grace period before ratification).
    /// @param gameId The ID of the game.
    /// @return The timelock duration in seconds.
    function timelockDurationOf(uint256 gameId) public view override returns (uint256) {
        // timelock duration in bits 96-143 (48 bits).
        return uint256(uint48(_packedScorecardInfoOf[gameId] >> 96));
    }

    //*********************************************************************//
    // ----------------------- internal helpers -------------------------- //
    //*********************************************************************//

    /// @notice Build the normalized calldata for ratification.
    /// @param tierWeights The weights of each tier in the scorecard data.
    /// @return The calldata to send alongside the transactions.
    function _buildScorecardCalldataFor(DefifaTierCashOutWeight[] calldata tierWeights)
        internal
        pure
        returns (bytes memory)
    {
        // Build the calldata from the tier weights using the hook's selector.
        return abi.encodeWithSelector(DefifaHook.setTierCashOutWeightsTo.selector, (tierWeights));
    }

    /// @notice A value representing the contents of a scorecard.
    /// @param gameHook The address where the game is played.
    /// @param calldataBytes The calldata that will be sent if the scorecard is ratified.
    function _hashScorecardOf(address gameHook, bytes memory calldataBytes) internal pure virtual returns (uint256) {
        return uint256(keccak256(abi.encode(gameHook, calldataBytes)));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {Checkpoints} from "@openzeppelin/contracts/utils/structs/Checkpoints.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";
import {IJBCashOutHook} from "@bananapus/core-v6/src/interfaces/IJBCashOutHook.sol";
import {IJBDirectory} from "@bananapus/core-v6/src/interfaces/IJBDirectory.sol";
import {IJBPayHook} from "@bananapus/core-v6/src/interfaces/IJBPayHook.sol";
import {IJBRulesetDataHook} from "@bananapus/core-v6/src/interfaces/IJBRulesetDataHook.sol";
import {IJBRulesets} from "@bananapus/core-v6/src/interfaces/IJBRulesets.sol";
import {IJBTerminal} from "@bananapus/core-v6/src/interfaces/IJBTerminal.sol";
import {JBRulesetMetadataResolver} from "@bananapus/core-v6/src/libraries/JBRulesetMetadataResolver.sol";
import {JBAfterCashOutRecordedContext} from "@bananapus/core-v6/src/structs/JBAfterCashOutRecordedContext.sol";
import {JBAfterPayRecordedContext} from "@bananapus/core-v6/src/structs/JBAfterPayRecordedContext.sol";
import {JBBeforeCashOutRecordedContext} from "@bananapus/core-v6/src/structs/JBBeforeCashOutRecordedContext.sol";
import {JBCashOutHookSpecification} from "@bananapus/core-v6/src/structs/JBCashOutHookSpecification.sol";
import {JBRuleset} from "@bananapus/core-v6/src/structs/JBRuleset.sol";
import {JB721Hook} from "@bananapus/721-hook-v6/src/abstract/JB721Hook.sol";
import {IJB721TiersHookStore} from "@bananapus/721-hook-v6/src/interfaces/IJB721TiersHookStore.sol";
import {IJB721TokenUriResolver} from "@bananapus/721-hook-v6/src/interfaces/IJB721TokenUriResolver.sol";
import {
    JB721TiersRulesetMetadataResolver
} from "@bananapus/721-hook-v6/src/libraries/JB721TiersRulesetMetadataResolver.sol";
import {JB721Tier} from "@bananapus/721-hook-v6/src/structs/JB721Tier.sol";
import {JB721TierConfig} from "@bananapus/721-hook-v6/src/structs/JB721TierConfig.sol";
import {JB721TiersMintReservesConfig} from "@bananapus/721-hook-v6/src/structs/JB721TiersMintReservesConfig.sol";

import {JBMetadataResolver} from "@bananapus/core-v6/src/libraries/JBMetadataResolver.sol";
import {DefifaDelegation} from "./structs/DefifaDelegation.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IDefifaHook} from "./interfaces/IDefifaHook.sol";
import {IDefifaGamePhaseReporter} from "./interfaces/IDefifaGamePhaseReporter.sol";
import {IDefifaGamePotReporter} from "./interfaces/IDefifaGamePotReporter.sol";
import {DefifaTierCashOutWeight} from "./structs/DefifaTierCashOutWeight.sol";
import {DefifaGamePhase} from "./enums/DefifaGamePhase.sol";
import {DefifaHookLib} from "./libraries/DefifaHookLib.sol";

/// @notice The 721 hook that powers Defifa games. Extends JB721Hook to enforce game phase rules on minting and
/// cashing out, track per-tier voting power via checkpoints, and apply scorecard-determined cash-out weights after
/// ratification. Mints are only allowed during the MINT phase, refunds during the REFUND phase, and cash-outs
/// with scoring weights only after a scorecard is ratified in the COMPLETE phase.
contract DefifaHook is JB721Hook, Ownable, IDefifaHook {
    using Checkpoints for Checkpoints.Trace208;

    //*********************************************************************//
    // --------------------------- custom errors ------------------------- //
    //*********************************************************************//

    /// @notice Thrown when the Defifa token and base protocol token addresses are the same at construction.
    error DefifaHook_IdenticalTokens(address defifaToken, address baseProtocolToken);

    /// @notice Thrown when a tier delegation specifies the zero address as the delegate.
    error DefifaHook_DelegateAddressZero(uint256 tierId);

    /// @notice Thrown when attempting to change a tier delegation outside of the MINT phase.
    error DefifaHook_DelegateChangesUnavailableInThisPhase(uint256 projectId, DefifaGamePhase phase);

    /// @notice Thrown when setting cash-out weights while the game is not yet in its SCORING phase.
    error DefifaHook_GameIsntScoringYet(uint256 projectId, DefifaGamePhase phase);

    /// @notice Thrown when a cash-out reclaims nothing and the beneficiary received no fee tokens.
    error DefifaHook_NothingToClaim(uint256 reclaimedAmount, bool beneficiaryReceivedTokens);

    /// @notice Thrown when a payment carries no mint metadata or specifies no tiers to mint.
    error DefifaHook_NothingToMint(bool metadataFound, uint256 tierCount);

    /// @notice Thrown when a payment's currency does not match the game's pricing currency.
    error DefifaHook_WrongCurrency(uint256 expectedCurrency, uint256 actualCurrency);

    /// @notice Thrown when a payment leaves an unspent amount after minting the requested tiers.
    error DefifaHook_Overspending(uint256 leftoverAmount);

    /// @notice Thrown when setting cash-out weights for a game whose weights have already been set.
    error DefifaHook_CashoutWeightsAlreadySet(uint256 projectId);

    /// @notice Thrown when minting reserved tokens while reserve minting is paused for the game.
    error DefifaHook_ReservedTokenMintingPaused(uint256 projectId, uint256 tierId);

    /// @notice Thrown when minting reserved tokens while the game is in its NO_CONTEST phase.
    error DefifaHook_ReservedTokenMintingBlockedInNoContest(uint256 projectId, uint256 tierId);

    /// @notice Thrown when transferring an NFT whose tier has transfers paused.
    error DefifaHook_TransfersPaused(uint256 projectId, uint256 tokenId, address from, address to);

    /// @notice Thrown when cashing out a token whose owner is not the cash-out holder.
    error DefifaHook_Unauthorized(uint256 tokenId, address owner, address holder);

    //*********************************************************************//
    // --------------------- public constant properties ------------------ //
    //*********************************************************************//

    /// @notice The total cash-out weight that can be divided among tiers.
    uint256 public constant override TOTAL_CASHOUT_WEIGHT = 1_000_000_000_000_000_000;

    //*********************************************************************//
    // -------------------- internal stored properties ------------------- //
    //*********************************************************************//

    /// @notice The cash-out weight for each tier.
    /// @dev Tiers are limited to ID 128.
    uint256[128] internal _tierCashOutWeights;

    /// @notice The delegation status for each address and for each tier.
    /// @custom:param account The delegator.
    /// @custom:param tierId The ID of the tier to delegate.
    mapping(address => mapping(uint256 => address)) internal _tierDelegation;

    /// @notice The delegation checkpoints for each address and for each tier.
    /// @custom:param account The delegator.
    /// @custom:param tierId The ID of the tier to check.
    mapping(address => mapping(uint256 => Checkpoints.Trace208)) internal _delegateTierCheckpoints;

    /// @notice The total delegation status for each tier.
    /// @custom:param tierId The ID of the tier to check.
    mapping(uint256 => Checkpoints.Trace208) internal _totalTierCheckpoints;

    /// @notice The first owner of each token ID, stored on first transfer out.
    /// @custom:param tokenId The ID of the token to get the stored first owner of.
    mapping(uint256 => address) internal _firstOwnerOf;

    /// @notice The names of each tier.
    /// @custom:param tierId The ID of the tier to get a name for.
    mapping(uint256 => string) internal _tierNameOf;

    //*********************************************************************//
    // ---------------- public immutable stored properties --------------- //
    //*********************************************************************//

    /// @notice The $DEFIFA token that is expected to be issued from paying fees.
    IERC20 public immutable override DEFIFA_TOKEN;

    /// @notice The $BASE_PROTOCOL token that is expected to be issued from paying fees.
    IERC20 public immutable override BASE_PROTOCOL_TOKEN;

    //*********************************************************************//
    // --------------------- public stored properties -------------------- //
    //*********************************************************************//

    /// @notice The cumulative mint price of all paid and reserved NFTs. Decremented on burns/refunds. Used as the
    /// participation metric — immune to `addToBalanceOf` inflation because only actual mints increment it.
    uint256 public override totalMintCost;

    /// @notice The amount redeemed from this game, excluding refunds.
    uint256 public override amountRedeemed;

    /// @notice The common base for token URIs.
    string public override baseURI;

    /// @notice Whether the cash-out weights have been set.
    bool public override cashOutWeightIsSet;

    /// @notice The original DefifaHook implementation address used to distinguish clones during initialization.
    address public immutable override CODE_ORIGIN;

    /// @notice The contract-level metadata URI used by marketplaces to display collection information.
    string public override contractURI;

    /// @notice The address that will be set as the attestation delegate by default.
    address public override defaultAttestationDelegate;

    /// @notice The contract reporting game phases.
    IDefifaGamePhaseReporter public override gamePhaseReporter;

    /// @notice The contract reporting the game pot.
    IDefifaGamePotReporter public override gamePotReporter;

    /// @notice Whether a token was minted through reserves (free) rather than paid for.
    /// @dev Reserve-minted tokens are excluded from refund calculations since no funds were contributed for them.
    /// @custom:param tokenId The ID of the token whose reserve-mint status is stored.
    mapping(uint256 tokenId => bool) public override isReserveMint;

    /// @notice The currency that is accepted when minting tier NFTs.
    uint256 public override pricingCurrency;

    /// @notice The number of tokens burned from a tier during non-COMPLETE phases (refund, no-contest).
    /// @dev Used to adjust pending reserve counts so reserves that correspond to refunded mints
    /// are excluded from the cash-out denominator.
    /// @custom:param tierId The ID of the tier whose non-COMPLETE-phase burn count is stored.
    mapping(uint256 => uint256) public refundedBurnsFrom;

    /// @notice The contract storing all funding cycle configurations.
    IJBRulesets public override rulesets;

    /// @notice The contract that stores and manages the NFT's data.
    IJB721TiersHookStore public override store;

    /// @notice The amount of tokens redeemed from each tier, excluding refunds.
    /// @custom:param tierId The tier from which tokens have been redeemed.
    mapping(uint256 => uint256) public override tokensRedeemedFrom;

    //*********************************************************************//
    // ------------------------- external views -------------------------- //
    //*********************************************************************//

    /// @notice Returns the adjusted pending reserve count for a tier, accounting for refund-phase burns.
    /// @dev Recalculates reserves from (paidMints - burns) / reserveFrequency since the relationship
    /// between burns and reserves is not linear — it depends on the tier's reserve frequency.
    /// @param tierId The tier ID.
    /// @return The adjusted pending reserve count (floored at 0).
    function adjustedPendingReservesFor(uint256 tierId) public view returns (uint256) {
        return DefifaHookLib.adjustedPendingReservesFor({
            tierId: tierId, hookStore: store, hook: address(this), refundBurns: refundedBurnsFrom[tierId]
        });
    }

    /// @notice The first owner of each token ID, which corresponds to the address that originally contributed to the
    /// project to receive the NFT.
    /// @param tokenId The ID of the token to get the first owner of.
    /// @return The first owner of the token.
    function firstOwnerOf(uint256 tokenId) external view override returns (address) {
        // Get a reference to the first owner.
        address storedFirstOwner = _firstOwnerOf[tokenId];

        // If the stored first owner is set, return it.
        if (storedFirstOwner != address(0)) return storedFirstOwner;

        // Otherwise, the first owner must be the current owner.
        return _owners[tokenId];
    }

    /// @notice Returns the past attestation units of a specific address for a specific tier.
    /// @param account The address to check.
    /// @param tier The tier to check within.
    /// @param timestamp The timestamp to check the attestation power at.
    function getPastTierAttestationUnitsOf(
        address account,
        uint256 tier,
        uint48 timestamp
    )
        external
        view
        override
        returns (uint256)
    {
        return _delegateTierCheckpoints[account][tier].upperLookup(timestamp);
    }

    /// @notice Returns the total amount of attestation units that has existed for a tier.
    /// @param tier The tier to check.
    /// @param timestamp The timestamp to check the total attestation units at.
    function getPastTierTotalAttestationUnitsOf(
        uint256 tier,
        uint48 timestamp
    )
        external
        view
        override
        returns (uint256)
    {
        return _totalTierCheckpoints[tier].upperLookup(timestamp);
    }

    /// @notice Returns the current attestation power of an address for a specific tier.
    /// @param account The address to check.
    /// @param tier The tier to check within.
    function getTierAttestationUnitsOf(address account, uint256 tier) external view override returns (uint256) {
        return _delegateTierCheckpoints[account][tier].latest();
    }

    /// @notice Returns the delegate of an account for specific tier.
    /// @param account The account to check for a delegate of.
    /// @param tier The tier to check within.
    function getTierDelegateOf(address account, uint256 tier) external view override returns (address) {
        return _tierDelegation[account][tier];
    }

    /// @notice Returns the total amount of attestation units that exists for a tier.
    /// @param tier The tier to check.
    function getTierTotalAttestationUnitsOf(uint256 tier) external view override returns (uint256) {
        return _totalTierCheckpoints[tier].latest();
    }

    /// @notice The cashOut weight for each tier.
    /// @return The array of weights, indexed by tier.
    function tierCashOutWeights() external view override returns (uint256[128] memory) {
        return _tierCashOutWeights;
    }

    /// @notice The name of the tier with the specified ID.
    /// @param tierId The ID of the tier.
    function tierNameOf(uint256 tierId) external view override returns (string memory) {
        return _tierNameOf[tierId];
    }

    //*********************************************************************//
    // -------------------------- public views --------------------------- //
    //*********************************************************************//

    /// @notice The data calculated before a cash-out is recorded in the terminal store. This data is provided to the
    /// terminal's `cashOutTokensOf(...)` transaction.
    /// @dev Sets this contract as the cash-out hook. Part of `IJBRulesetDataHook`.
    /// @dev This function is used for NFT cash-outs, and will only be called if the project's ruleset has
    /// `useDataHookForCashOut` set to `true`.
    /// @param context The cash-out context passed to this contract by the `cashOutTokensOf(...)` function.
    /// @return cashOutTaxRate The cash-out tax rate influencing the reclaim amount.
    /// @return cashOutCount The amount of tokens that should be considered cashed out.
    /// @return totalSupply The total amount of tokens that are considered to be existing.
    /// @return effectiveSurplusValue The effective surplus value to use for the cash-out.
    /// @return hookSpecifications The amount and data to send to cash-out hooks (this contract) instead of returning
    /// to the beneficiary.
    function beforeCashOutRecordedWith(JBBeforeCashOutRecordedContext calldata context)
        public
        view
        virtual
        override(IJBRulesetDataHook, JB721Hook)
        returns (
            uint256 cashOutTaxRate,
            uint256 cashOutCount,
            uint256 totalSupply,
            uint256 effectiveSurplusValue,
            JBCashOutHookSpecification[] memory hookSpecifications
        )
    {
        // Make sure (fungible) project tokens aren't also being cashed out.
        if (context.cashOutCount > 0) revert JB721Hook_UnexpectedTokenCashedOut({cashOutCount: context.cashOutCount});

        // Fetch the cash-out hook metadata using the corresponding metadata ID.
        (bool metadataExists, bytes memory metadata) = JBMetadataResolver.getDataFor({
            id: JBMetadataResolver.getId({purpose: "cashOut", target: CODE_ORIGIN}), metadata: context.metadata
        });

        uint256[] memory decodedTokenIds;

        // Decode the metadata.
        if (metadataExists) decodedTokenIds = abi.decode(metadata, (uint256[]));

        // Get the current game phase.
        DefifaGamePhase gamePhase = gamePhaseReporter.currentGamePhaseOf(context.projectId);

        // Cache the store reference in a local variable to avoid repeated SLOAD.
        IJB721TiersHookStore hookStore = store;

        // During refund phases, reserve-minted tokens were minted for free and have no paid amount to refund.
        uint256 cumulativeMintPrice = DefifaHookLib.computeCumulativeMintPriceForCashOut({
            tokenIds: decodedTokenIds,
            hookStore: hookStore,
            hook: address(this),
            excludeReserveMints: gamePhase == DefifaGamePhase.MINT || gamePhase == DefifaGamePhase.REFUND
                || gamePhase == DefifaGamePhase.NO_CONTEST
        });

        // Use this contract as the only cash-out hook.
        hookSpecifications = new JBCashOutHookSpecification[](1);
        hookSpecifications[0] =
            JBCashOutHookSpecification({hook: this, noop: false, amount: 0, metadata: abi.encode(cumulativeMintPrice)});

        // Compute the cash-out count based on the game phase.
        cashOutCount = DefifaHookLib.computeCashOutCount({
            gamePhase: gamePhase,
            cumulativeMintPrice: cumulativeMintPrice,
            surplusValue: context.surplus.value,
            totalAmountRedeemed: amountRedeemed,
            cumulativeCashOutWeight: cashOutWeightOf(decodedTokenIds)
        });

        // Use the surplus as the total supply.
        totalSupply = context.surplus.value;

        // Use the surplus as the effective surplus value.
        effectiveSurplusValue = context.surplus.value;

        // Use the cash-out tax rate from the context.
        cashOutTaxRate = context.cashOutTaxRate;
    }

    /// @notice The cumulative weight the given token IDs have in cash-outs compared to the `totalCashOutWeight`.
    /// @param tokenIds The IDs of the tokens to get the cumulative cashOut weight of.
    /// @return cumulativeWeight The weight.
    function cashOutWeightOf(uint256[] memory tokenIds)
        public
        view
        virtual
        override
        returns (uint256 cumulativeWeight)
    {
        // Cache the store in a local variable to avoid repeated SLOAD.
        cumulativeWeight = DefifaHookLib.computeCashOutWeightBatch({
            tokenIds: tokenIds,
            hookStore: store,
            hook: address(this),
            tierCashOutWeights: _tierCashOutWeights,
            tokensRedeemedFrom: tokensRedeemedFrom
        });
    }

    /// @notice The weight the given token ID has in cashOuts.
    /// @param tokenId The ID of the token to get the cashOut weight of.
    /// @return The weight.
    function cashOutWeightOf(uint256 tokenId) public view override returns (uint256) {
        return DefifaHookLib.computeCashOutWeight({
            tokenId: tokenId,
            hookStore: store,
            hook: address(this),
            tierCashOutWeights: _tierCashOutWeights,
            tokensRedeemedFrom: tokensRedeemedFrom
        });
    }

    /// @notice The amount of tokens of a tier that are currently in circulation.
    /// @param tierId The ID of the tier to get the current supply of.
    /// @return The current supply count.
    function currentSupplyOfTier(uint256 tierId) public view returns (uint256) {
        return DefifaHookLib.computeCurrentSupply({hookStore: store, hook: address(this), tierId: tierId});
    }

    /// @notice Indicates if this contract adheres to the specified interface.
    /// @dev See {IERC165-supportsInterface}.
    /// @param interfaceId The ID of the interface to check for adherence to.
    function supportsInterface(bytes4 interfaceId) public view override(JB721Hook, IERC165) returns (bool) {
        return interfaceId == type(IDefifaHook).interfaceId || super.supportsInterface(interfaceId);
    }

    /// @notice The metadata URI of the provided token ID.
    /// @dev Defer to the token URI resolver if set; otherwise, use the token URI set with the token's tier.
    /// @param tokenId The ID of the token to get the tier URI for.
    /// @return The token URI corresponding with the tier or the tokenUriResolver URI.
    function tokenURI(uint256 tokenId) public view virtual override returns (string memory) {
        // Use the resolver.
        return store.tokenUriResolverOf(address(this)).tokenUriOf({nft: address(this), tokenId: tokenId});
    }

    /// @notice The amount of $DEFIFA and $BASE_PROTOCOL tokens claimable for a set of token IDs.
    /// @param tokenIds The IDs of the tokens that justify a $DEFIFA claim.
    /// @return defifaTokenAmount The amount of $DEFIFA that can be claimed.
    /// @return baseProtocolTokenAmount The amount of $BASE_PROTOCOL that can be claimed.
    function tokensClaimableFor(uint256[] memory tokenIds)
        public
        view
        returns (uint256 defifaTokenAmount, uint256 baseProtocolTokenAmount)
    {
        // If the game isn't complete, we do not have any tokens to claim.
        if (_currentGamePhaseOf(projectId) != DefifaGamePhase.COMPLETE) return (0, 0);

        // Include unminted reserves in the denominator. Once reserves are pending, their future recipients are
        // entitled to fee-token claims as if the reserve NFTs had already been minted; otherwise paid holders could
        // claim too large a share before the reserve mint transaction lands.
        return DefifaHookLib.computeTokensClaim({
            tokenIds: tokenIds,
            hookStore: store,
            hook: address(this),
            totalMintCost: totalMintCost + _pendingReserveMintCost(),
            defifaBalance: DEFIFA_TOKEN.balanceOf(address(this)),
            baseProtocolBalance: BASE_PROTOCOL_TOKEN.balanceOf(address(this))
        });
    }

    /// @notice The combined cash-out weight of all outstanding NFTs.
    /// @dev An NFT's cash-out weight is its price.
    /// @return The total cash-out weight.
    function totalCashOutWeight() public view virtual override returns (uint256) {
        return TOTAL_CASHOUT_WEIGHT;
    }

