type LaunchProjectArgs = ContractFunctionArgs<
  typeof jbControllerAbi,
  "payable",
  "launchProjectFor"
>;

/**
 * A terminal to attach to a project at launch, together with the accounting
 * contexts (tokens) it should accept.
 */
export type JBTerminalConfig = LaunchProjectArgs[3][number];

/**
 * A fund access limit group scoping how much of a terminal's token balance
 * the project can pay out / use as surplus allowance.
 */
export type JBFundAccessLimitGroup =
  JBRulesetConfig["fundAccessLimitGroups"][number];

/**
 * Read the fee (in wei) that `JBProjects` charges to create a new project.
 *
 * Launch transactions must send EXACTLY this value as `msg.value` or they
 * revert. The fee is dynamic — read it per chain right before launching, and
 * never reuse a value across chains.
 */
export async function getProjectCreationFee(
  client: PublicClient,
  chainId: JBChainId,
): Promise<bigint> {
  return client.readContract({
    address: v6Address("JBProjects", chainId),
    abi: jbProjectsAbi,
    functionName: "creationFee",
  });
}

/**
 * Build a `JBAccountingContext` for a token.
 *
 * By default the context currency is token-keyed: `uint32(uint160(token))`
 * (native token → 61166). Pass an explicit shared currency such as ETH=1 or
 * USD=2 when the terminal should convert this token through a protocol price
 * feed. A ruleset's `baseCurrency` is the denomination used to interpret its
 * issuance weight.
 *
 * @param token The token address. Defaults to the native token sentinel
 * (`0x…EEEe`).
 * @param decimals The token's decimals. Defaults to 18 for the native token;
 * REQUIRED for any other token (there is no safe default).
 * @param currency The context's currency id. Defaults to the token-keyed id.
 */
export function buildAccountingContext(
  token: Address = NATIVE_TOKEN,
  decimals?: number,
  currency: number = tokenCurrencyId(token),
): JBAccountingContext {
  const isNative = token.toLowerCase() === NATIVE_TOKEN.toLowerCase();
  if (decimals === undefined && !isNative) {
    throw new Error(
      `decimals is required for non-native token ${token} (there is no safe default)`,
    );
  }
  return {
    token,
    decimals: decimals ?? NATIVE_TOKEN_DECIMALS,
    currency,
  };
}

/**
 * Build the standard terminal configurations for a launch:
 *
 * 1. `JBMultiTerminal` accepting the given accounting contexts (the
 *    project's treasury), and
 * 2. `JBRouterTerminalRegistry` with EMPTY accounting contexts — registering
 *    the router registry makes the project accept ANY token via swap
 *    routing. It is skipped on chains where it isn't deployed.
 *
 * @param args.accountingContexts The contexts the multi terminal accepts.
 * Defaults to just the native token context.
 */
export function buildTerminalConfigurations(args: {
  chainId: JBChainId;
  accountingContexts?: readonly JBAccountingContext[];
}): JBTerminalConfig[] {
  const configurations: JBTerminalConfig[] = [
    {
      terminal: v6Address("JBMultiTerminal", args.chainId),
      accountingContextsToAccept: args.accountingContexts ?? [
        buildAccountingContext(),
      ],
    },
  ];
  try {
    configurations.push({
      terminal: v6Address("JBRouterTerminalRegistry", args.chainId),
      accountingContextsToAccept: [],
    });
  } catch {
    // No router terminal registry on this chain — the multi terminal alone
    // is a valid configuration.
  }
  return configurations;
}

/**
 * Build a `JBRulesetMetadata` with safe defaults (v6 field names ONLY):
 * everything false/zero, `baseCurrency` ETH (1), no data hook.
 *
 * Note `scopeCashOutsToLocalBalances` is the v6 spelling — it replaces the
 * old inverted `useTotalSurplusForCashOuts`, and `false` keeps the v6
 * default behavior of cashing out against total surplus.
 *
 * @param overrides Any metadata fields to override.
 */
export function buildRulesetMetadata(
  overrides?: Partial<JBRulesetMetadata>,
): JBRulesetMetadata {
  return {
    reservedPercent: 0,
    cashOutTaxRate: 0,
    baseCurrency: BASE_CURRENCY_ETH,
    pausePay: false,
    pauseCreditTransfers: false,
    allowOwnerMinting: false,
    allowSetCustomToken: false,
    allowTerminalMigration: false,
    allowSetTerminals: false,
    allowSetController: false,
    allowAddAccountingContext: false,
    allowAddPriceFeed: false,
    ownerMustSendPayouts: false,
    holdFees: false,
    scopeCashOutsToLocalBalances: false,
    useDataHookForPay: false,
    useDataHookForCashOut: false,
    dataHook: zeroAddress,
    metadata: 0,
    ...overrides,
  };
}

/**
 * Build a `JBRulesetConfig` with safe defaults: starts as soon as possible,
 * no duration (rules can change any time), no issuance (`weight` 0), no
 * approval hook, default metadata, no splits, and ZERO payouts (an empty
 * `fundAccessLimitGroups` means the project can pay out NOTHING — funds can
 * only leave via cash outs).
 *
 * @param args.mustStartAtOrAfter Earliest start timestamp (uint48). 0 (the
 * default) starts at the deploy block. For omnichain launches pass ONE
 * shared timestamp so every chain's ruleset is byte-identical.
 * @param args.duration Seconds the ruleset is locked for. 0 = no duration.
 * @param args.weight Tokens issued per unit of `baseCurrency` paid, as an
 * 18-decimal fixed point (uint112). Later configurations can use the exported
 * `RULESET_WEIGHT_INHERIT` sentinel (1n); zero means genuine zero issuance.
 * @param args.weightCutPercent Issuance cut applied each cycle, out of 1e9.
 * @param args.approvalHook A deadline contract queued rulesets must clear.
 * @param args.metadata Ruleset metadata; see {@link buildRulesetMetadata}.
 * @param args.splitGroups Split groups to set alongside the ruleset.
 * @param args.fundAccessLimitGroups Payout limits / surplus allowances.
 */
export function buildRulesetConfiguration(args?: {
  mustStartAtOrAfter?: number;
  duration?: number;
  weight?: bigint;
  weightCutPercent?: number;
  approvalHook?: Address;
  metadata?: JBRulesetMetadata;
  splitGroups?: JBRulesetConfig["splitGroups"];
  fundAccessLimitGroups?: JBRulesetConfig["fundAccessLimitGroups"];
}): JBRulesetConfig {
  return {
    mustStartAtOrAfter: args?.mustStartAtOrAfter ?? 0,
    duration: args?.duration ?? 0,
    weight: args?.weight ?? 0n,
    weightCutPercent: args?.weightCutPercent ?? 0,
    approvalHook: args?.approvalHook ?? zeroAddress,
    metadata: args?.metadata ?? buildRulesetMetadata(),
    splitGroups: args?.splitGroups ?? [],
    fundAccessLimitGroups: args?.fundAccessLimitGroups ?? [],
  };
}

/**
 * Build a `JBController.launchProjectFor` transaction request creating a new
 * project on a single chain.
 *
 * The transaction is payable and must send EXACTLY the current project
 * creation fee — read it with {@link getProjectCreationFee} on the same
 * chain right before sending.
 *
 * @param args.owner The address that receives the project NFT (full control).
 * @param args.projectUri An IPFS URI (`ipfs://…`) pointing to the project's
 * metadata.
 * @param args.rulesetConfigurations The project's initial rulesets; see
 * {@link buildRulesetConfiguration}.
 * @param args.terminalConfigurations The project's terminals; see
 * {@link buildTerminalConfigurations}.
 * @param args.memo An optional memo emitted with the launch event.
 * @param args.creationFee The exact fee read from `JBProjects.creationFee()`.
 */
export function buildLaunchProjectTx(args: {
  chainId: JBChainId;
  owner: Address;
  projectUri: string;
  rulesetConfigurations: readonly JBRulesetConfig[];
  terminalConfigurations: readonly JBTerminalConfig[];
  memo?: string;
  creationFee: bigint;
}) {
  return {
    chainId: args.chainId,
    address: v6Address("JBController", args.chainId),
    abi: jbControllerAbi,
    functionName: "launchProjectFor" as const,
    args: [
      args.owner,
      args.projectUri,
      args.rulesetConfigurations,
      args.terminalConfigurations,
      args.memo ?? "",
    ] as const,
    value: args.creationFee,
  };
}

/** Minimal log shape needed to decode a project launch. */
export interface V6LaunchProjectLog {
  address: Address;
  data: Hex;
  topics: readonly Hex[];
}

/**
 * Decode the id of a project launched in a transaction, from one of its logs.
 *
 * Three logs identify a launch, and which one a receipt carries depends on the
 * path taken:
 *
 * - `JBController.LaunchProject` — a direct `launchProjectFor` on the controller.
 * - `JBController.LaunchRulesets` — a deployer-created project. `JBOmnichainDeployer`
 *   (and the 721 project deployer) create the project through `JBProjects.createFor`
 *   and then call `launchRulesetsFor`, so the controller never emits `LaunchProject`
 *   for them.
 * - `JBProjects.Create` — emitted by every path, since every project is an NFT
 *   minted by `JBProjects`.
 *
 * Checking the emitter matters: unrelated contracts can emit an event with the
 * same signature, and ERC-721 `Transfer` logs in a complex receipt are not a
 * reliable way to identify which mint was the Juicebox project NFT.
 */
export function decodeLaunchProjectId(
  log: V6LaunchProjectLog,
  { chainId }: { chainId: JBChainId },
): bigint | null {
  const topics = log.topics as [Hex, ...Hex[]];

  if (isAddressEqual(log.address, v6Address("JBController", chainId))) {
    for (const eventName of ["LaunchProject", "LaunchRulesets"] as const) {
      try {
        const decoded = decodeEventLog({
          abi: jbControllerAbi,
          eventName,
          data: log.data,
          topics,
          strict: true,
        });
        if (decoded.eventName === eventName) return decoded.args.projectId;
      } catch {
        // Not this event; try the next.
      }
    }
    return null;
  }

  if (isAddressEqual(log.address, v6Address("JBProjects", chainId))) {
    try {
      const decoded = decodeEventLog({
        abi: jbProjectsAbi,
        eventName: "Create",
        data: log.data,
        topics,
        strict: true,
      });
      return decoded.eventName === "Create" ? decoded.args.projectId : null;
    } catch {
      return null;
    }
  }

  return null;
}

/** Return the first canonical v6 project id found in a transaction's logs. */
export function projectIdFromLaunchLogs(
  logs: readonly V6LaunchProjectLog[],
  args: { chainId: JBChainId },
): bigint | null {
  for (const log of logs) {
    const projectId = decodeLaunchProjectId(log, args);
    if (projectId !== null) return projectId;
  }
  return null;
}

/**
 * The denominator for REVLoans fee percents: prepaid fee percents and source fee percents
 * are expressed out of 1000.
 */
export const LOANS_MAX_FEE = 1000n;

/**
 * The minimum `prepaidFeePercent` REVLoans accepts when borrowing: 25 of
 * {@link LOANS_MAX_FEE} (2.5%), paid upfront to the source revnet.
 */
export const MIN_PREPAID_FEE_PERCENT = 25n;

/** The largest prepaid source fee REVLoans accepts: 500 / 1000 = 50%. */
export const MAX_PREPAID_FEE_PERCENT = 500n;

/** The upfront fee REVLoans routes to the $REV revnet on every borrow: 1%. */
export const REV_PREPAID_FEE_PERCENT = 10n;

export interface LoanOpeningAmounts {
  grossBorrowAmount: bigint;
  protocolFee: bigint;
  revFee: bigint;
  sourceFee: bigint;
  netBorrowAmount: bigint;
}

/**
 * Calculate spendable loan proceeds using the contracts' floor-rounded fee arithmetic.
 */
export function loanOpeningAmounts({
  grossBorrowAmount,
  prepaidSourceFeePercent = MIN_PREPAID_FEE_PERCENT,
  protocolFeeApplies = true,
  revFeeApplies = true,
}: {
  grossBorrowAmount: bigint;
  prepaidSourceFeePercent?: bigint;
  protocolFeeApplies?: boolean;
  revFeeApplies?: boolean;
}): LoanOpeningAmounts {
  if (grossBorrowAmount < 0n) {
    throw new Error("grossBorrowAmount cannot be negative.");
  }
  if (
    prepaidSourceFeePercent < MIN_PREPAID_FEE_PERCENT ||
    prepaidSourceFeePercent > MAX_PREPAID_FEE_PERCENT
  ) {
    throw new Error(
      `prepaidSourceFeePercent must be between ${MIN_PREPAID_FEE_PERCENT} and ${MAX_PREPAID_FEE_PERCENT}.`,
    );
  }
  const protocolFee = protocolFeeApplies ? grossBorrowAmount / 40n : 0n;
  const revFee = revFeeApplies
    ? (grossBorrowAmount * REV_PREPAID_FEE_PERCENT) / LOANS_MAX_FEE
    : 0n;
  const sourceFee =
    (grossBorrowAmount * prepaidSourceFeePercent) / LOANS_MAX_FEE;
  const totalFees = protocolFee + revFee + sourceFee;
  return {
    grossBorrowAmount,
    protocolFee,
    revFee,
    sourceFee,
    netBorrowAmount:
      grossBorrowAmount > totalFees ? grossBorrowAmount - totalFees : 0n,
  };
}

/** Convenience accessor for {@link loanOpeningAmounts}. */
export function netLoanProceeds(
  grossBorrowAmount: bigint,
  prepaidSourceFeePercent = MIN_PREPAID_FEE_PERCENT,
): bigint {
  return loanOpeningAmounts({
    grossBorrowAmount,
    prepaidSourceFeePercent,
  }).netBorrowAmount;
}

import { Address, Hex, PublicClient } from "viem";
import { revLoansAbi } from "../generated/juicebox.js";
import { JBChainId } from "../types.js";
import { LOANS_MAX_FEE, MIN_PREPAID_FEE_PERCENT } from "./loanMath.js";
import { v6Address } from "./types.js";
export * from "./loanMath.js";

/**
 * The JBPermissions permission id apps grant to the REVLoans contract before borrowing
 * against a holder's tokens: `BURN_TOKENS` (11, per `JBPermissionIds`). REVLoans burns
 * the holder's collateral via `JBController.burnTokensOf`, which is gated on this
 * permission ONLY — never grant ROOT (1) to REVLoans; ROOT silently satisfies every
 * permission check and hands the contract full operator power over the holder.
 */
export const REVLOANS_BURN_PERMISSION_ID = 11;

/**
 * @deprecated Use {@link REVLOANS_BURN_PERMISSION_ID}. This constant previously held
 * ROOT (1) — a grant that gives REVLoans unrestricted operator power over the holder.
 * It now aliases `BURN_TOKENS` (11), the only permission REVLoans needs. Audit any
 * grants made with the old value and revoke ROOT from REVLoans.
 */
export const REVLOANS_PERMISSION_ID = REVLOANS_BURN_PERMISSION_ID;

/**
 * A Permit2 single allowance, passed to `repayLoan` when repaying with an ERC-20 via a
 * signed permit. Pass {@link EMPTY_SINGLE_ALLOWANCE} (the default) when repaying with the
 * native token or a pre-approved ERC-20.
 */
export type JBSingleAllowance = {
  sigDeadline: bigint;
  amount: bigint;
  expiration: number;
  nonce: number;
  signature: Hex;
};

/**
 * An empty Permit2 allowance: use when no permit signature is needed (native-token
 * repayments, or ERC-20s already approved to REVLoans).
 */
export const EMPTY_SINGLE_ALLOWANCE: JBSingleAllowance = {
  sigDeadline: 0n,
  amount: 0n,
  expiration: 0,
  nonce: 0,
  signature: "0x",
};

/**
 * Builds a `borrowFrom` transaction on REVLoans, opening a loan against a holder's revnet
 * tokens.
 *
 * The caller must be the holder or have permission to act on their behalf, and the holder
 * must have granted permission id {@link REVLOANS_BURN_PERMISSION_ID} to REVLoans.
 *
 * @param args.chainId The chain to borrow on.
 * @param args.revnetId The revnet to borrow from.
 * @param args.token The terminal token to borrow.
 * @param args.minBorrowAmount The minimum amount to borrow, denominated in `token`.
 * Defaults to 0.
 * @param args.collateralCount The number of revnet tokens to lock as collateral, as a
 * fixed point number with 18 decimals.
 * @param args.beneficiary The address that receives the borrowed funds and the loan NFT.
 * @param args.prepaidFeePercent The fee percent to prepay, out of {@link LOANS_MAX_FEE}.
 * Must be at least {@link MIN_PREPAID_FEE_PERCENT}.
 * @param args.holder The address whose tokens are used as collateral.
 */
export function buildBorrowTx({
  chainId,
  revnetId,
  token,
  minBorrowAmount = 0n,
  collateralCount,
  beneficiary,
  prepaidFeePercent,
  holder,
}: {
  chainId: JBChainId;
  revnetId: bigint;
  token: Address;
  minBorrowAmount?: bigint;
  collateralCount: bigint;
  beneficiary: Address;
  prepaidFeePercent: bigint;
  holder: Address;
}): {
  chainId: JBChainId;
  address: Address;
  abi: typeof revLoansAbi;
  functionName: "borrowFrom";
  args: readonly [bigint, Address, bigint, bigint, Address, bigint, Address];
} {
  return {
    chainId,
    address: v6Address("REVLoans", chainId),
    abi: revLoansAbi,
    functionName: "borrowFrom",
    args: [
      revnetId,
      token,
      minBorrowAmount,
      collateralCount,
      beneficiary,
      prepaidFeePercent,
      holder,
    ],
  };
}

/**
 * Builds a `repayLoan` transaction on REVLoans, paying down a loan and reclaiming
 * collateral.
 *
 * Payable: when the loan's source token is the native token, send the repayment as
 * `value`.
 *
 * @param args.chainId The chain the loan lives on.
 * @param args.loanId The id of the loan being repaid (also the loan NFT's token id).
 * @param args.maxRepayBorrowAmount The maximum amount to repay, denominated in the loan's
 * source token. Excess above what's owed is refunded.
 * @param args.collateralCountToReturn The number of collateral tokens to reclaim, as a
 * fixed point number with 18 decimals.
 * @param args.beneficiary The address that receives the reclaimed collateral (and any new
 * loan NFT for a partial repayment).
 * @param args.allowance A Permit2 allowance for ERC-20 repayments. Defaults to
 * {@link EMPTY_SINGLE_ALLOWANCE}.
 * @param args.value The native-token repayment to send along. Defaults to 0.
 */
export function buildRepayLoanTx({
  chainId,
  loanId,
  maxRepayBorrowAmount,
  collateralCountToReturn,
  beneficiary,
  allowance = EMPTY_SINGLE_ALLOWANCE,
  value = 0n,
}: {
  chainId: JBChainId;
  loanId: bigint;
  maxRepayBorrowAmount: bigint;
  collateralCountToReturn: bigint;
  beneficiary: Address;
  allowance?: JBSingleAllowance;
  value?: bigint;
}): {
  chainId: JBChainId;
  address: Address;
  abi: typeof revLoansAbi;
  functionName: "repayLoan";
  args: readonly [bigint, bigint, bigint, Address, JBSingleAllowance];
  value: bigint;
} {
  return {
    chainId,
    address: v6Address("REVLoans", chainId),
    abi: revLoansAbi,
    functionName: "repayLoan",
    args: [
      loanId,
      maxRepayBorrowAmount,
      collateralCountToReturn,
      beneficiary,
      allowance,
    ],
    value,
  };
}

/**
 * Builds a `reallocateCollateralFromLoan` transaction on REVLoans, moving collateral out
 * of an existing loan and into a new loan (optionally adding more collateral and borrowing
 * more).
 *
 * Note: this internally opens a new loan with the full current borrow capacity, so it is
 * economically equivalent to borrowing.
 *
 * @param args.chainId The chain the loan lives on.
 * @param args.loanId The id of the loan to reallocate collateral from.
 * @param args.collateralCountToTransfer The number of collateral tokens to move from the
 * existing loan into the new one, as a fixed point number with 18 decimals.
 * @param args.token The terminal token to borrow with the new loan.
 * @param args.minBorrowAmount The minimum amount the new loan must borrow, denominated in
 * `token`. Defaults to 0.
 * @param args.collateralCountToAdd The number of additional collateral tokens to add to
 * the new loan, as a fixed point number with 18 decimals.
 * @param args.beneficiary The address that receives the borrowed funds and the new loan
 * NFT.
 * @param args.prepaidFeePercent The fee percent to prepay on the new loan, out of
 * {@link LOANS_MAX_FEE}. Must be at least {@link MIN_PREPAID_FEE_PERCENT}.
 */
export function buildReallocateCollateralTx({
  chainId,
  loanId,
  collateralCountToTransfer,
  token,
  minBorrowAmount = 0n,
  collateralCountToAdd,
  beneficiary,
  prepaidFeePercent,
}: {
  chainId: JBChainId;
  loanId: bigint;
  collateralCountToTransfer: bigint;
  token: Address;
  minBorrowAmount?: bigint;
  collateralCountToAdd: bigint;
  beneficiary: Address;
  prepaidFeePercent: bigint;
}): {
  chainId: JBChainId;
  address: Address;
  abi: typeof revLoansAbi;
  functionName: "reallocateCollateralFromLoan";
  args: readonly [bigint, bigint, Address, bigint, bigint, Address, bigint];
} {
  return {
    chainId,
    address: v6Address("REVLoans", chainId),
    abi: revLoansAbi,
    functionName: "reallocateCollateralFromLoan",
    args: [
      loanId,
      collateralCountToTransfer,
      token,
      minBorrowAmount,
      collateralCountToAdd,
      beneficiary,
      prepaidFeePercent,
    ],
  };
}

/**
 * Reads how much a given collateral count can borrow from a revnet, via
 * `REVLoans.borrowableAmountFrom`.
 *
 * @param client A viem PublicClient connected to `chainId`.
 * @param args.chainId The chain to read on.
 * @param args.revnetId The revnet to borrow from.
 * @param args.collateralCount The number of revnet tokens that would be locked as
 * collateral, as a fixed point number with 18 decimals.
 * @param args.decimals The decimals the returned amounts should be denominated in.
 * @param args.currency The currency the returned amounts should be denominated in.
 * @returns `borrowableNow` (currently borrowable, net of the revnet's cash-out delay) and
 * `borrowableCapacity` (the full capacity the collateral represents).
 */
export async function getBorrowableAmount(
  client: PublicClient,
  {
    chainId,
    revnetId,
    collateralCount,
    decimals,
    currency,
  }: {
    chainId: JBChainId;
    revnetId: bigint;
    collateralCount: bigint;
    decimals: bigint;
    currency: bigint;
  },
): Promise<{ borrowableNow: bigint; borrowableCapacity: bigint }> {
  const [borrowableNow, borrowableCapacity] = await client.readContract({
    address: v6Address("REVLoans", chainId),
    abi: revLoansAbi,
    functionName: "borrowableAmountFrom",
    args: [revnetId, collateralCount, decimals, currency],
  });

  return { borrowableNow, borrowableCapacity };
}

import { Address, Hex, PublicClient, zeroAddress } from "viem";
import { JBOmnichainDeployerContracts } from "../contracts.js";
import {
  jb721TiersHookAbi,
  jb721TiersHookStoreAbi,
  jbContractAddress,
  jbOmnichainDeployerAbi,
} from "../generated/juicebox.js";
import { JBChainId } from "../types.js";
import { isMissingContractFunctionError } from "../utils/errors.js";
import { ipfsAssetPath, isIpfsCid } from "../utils/ipfs.js";
import { getRevnetTiered721Hook } from "./revnets.js";
import { getCurrentRuleset, type JBRulesetWithMetadata } from "./rulesets.js";

/**
 * App-level sentinel convention used by Juicebox 721 shops for effectively
 * unlimited inventory.
 */
export const TIER_UNLIMITED_SUPPLY = 999_999_999;

/**
 * JB721TiersHookStore's `DISCOUNT_DENOMINATOR`: a tier's `discountPercent` is
 * out of 200, so the shopper-facing "% off" is `discountPercent / 2`.
 */
export const DISCOUNT_DENOMINATOR = 200n;

/** The 721 tiers hook's ruleset-metadata bit which pauses eligible transfers. */
export const JB721_RULESET_METADATA_PAUSE_TRANSFERS = 1 << 0;

/** The 721 tiers hook's ruleset-metadata bit which pauses pending reserve mints. */
export const JB721_RULESET_METADATA_PAUSE_MINT_PENDING_RESERVES = 1 << 1;

/** The protocol stores 14 app-specific bits in `JBRulesetMetadata.metadata`. */
export const JB_RULESET_METADATA_APP_BITS_MAX = 0x3fff;

/** 721-specific overrides accepted by {@link build721RulesetMetadata}. */
export interface JB721RulesetMetadataInput {
  /** Existing app-specific metadata. Unrelated bits are preserved. */
  metadata?: number;
  /** Pause transfers for tiers whose `transfersPausable` flag is enabled. */
  pauseTransfers?: boolean;
  /** Pause minting the hook's pending reserve tokens. */
  pauseMintPendingReserves?: boolean;
}

/** 721-specific flags decoded from app-specific ruleset metadata. */
export interface JB721RulesetMetadata {
  pauseTransfers: boolean;
  pauseMintPendingReserves: boolean;
}

function assertRulesetAppMetadata(metadata: number): void {
  if (
    !Number.isInteger(metadata) ||
    metadata < 0 ||
    metadata > JB_RULESET_METADATA_APP_BITS_MAX
  ) {
    throw new Error(
      `Ruleset app metadata must be an integer between 0 and ${JB_RULESET_METADATA_APP_BITS_MAX}.`,
    );
  }
}

function setMetadataFlag(
  metadata: number,
  flag: number,
  enabled: boolean | undefined,
): number {
  if (enabled === undefined) return metadata;
  return enabled ? metadata | flag : metadata & ~flag;
}

/**
 * Set the 721 tiers hook's ruleset flags while preserving every unrelated app
 * metadata bit. This is important when composing with other hooks; for
 * example, Revnets use another bit to permit sucker deployment.
 *
 * A transfer is only paused when `pauseTransfers` is true AND the transferred
 * tier was created with `transfersPausable`. Mints and burns remain possible.
 * Omitted overrides preserve the corresponding bit in `metadata`.
 */
export function build721RulesetMetadata(
  input: JB721RulesetMetadataInput = {},
): number {
  const metadata = input.metadata ?? 0;
  assertRulesetAppMetadata(metadata);

  return setMetadataFlag(
    setMetadataFlag(
      metadata,
      JB721_RULESET_METADATA_PAUSE_TRANSFERS,
      input.pauseTransfers,
    ),
    JB721_RULESET_METADATA_PAUSE_MINT_PENDING_RESERVES,
    input.pauseMintPendingReserves,
  );
}

/** Decode the 721 tiers hook's flags without interpreting unrelated bits. */
export function decode721RulesetMetadata(
  metadata: number,
): JB721RulesetMetadata {
  assertRulesetAppMetadata(metadata);
  return {
    pauseTransfers: (metadata & JB721_RULESET_METADATA_PAUSE_TRANSFERS) !== 0,
    pauseMintPendingReserves:
      (metadata & JB721_RULESET_METADATA_PAUSE_MINT_PENDING_RESERVES) !== 0,
  };
}

/** Canonical display fields understood across Juicebox 721 metadata writers. */
export interface TierMetadata {
  name?: string;
  description?: string;
  image?: string;
  animationUrl?: string;
  mediaType?: string;
  categoryName?: string;
}

/** Input accepted by {@link buildTierMetadata}. */
export interface TierMetadataInput {
  name: string;
  description?: string;
  image?: string;
  animationUrl?: string;
  mediaType?: string;
  categoryName?: string;
}

/** JSON shape written for a tier's pinned metadata. */
export interface StoredTierMetadata {
  name: string;
  description?: string;
  image?: string;
  animation_url?: string;
  mediaType?: string;
  categoryName?: string;
}

function nonEmptyString(value: unknown): string | undefined {
  return typeof value === "string" && value ? value : undefined;
}

function decodeBase64Utf8(value: string): string {
  const binary = atob(value);
  return new TextDecoder().decode(
    Uint8Array.from(binary, (character) => character.charCodeAt(0)),
  );
}

/**
 * Parse a `data:application/json` tier URI. Invalid, non-object, and non-data
 * values return `null` so callers can fall back to an IPFS metadata fetch.
 */
export function parseTierMetadataJson(
  uri: string,
): Record<string, unknown> | null {
  if (!uri.startsWith("data:application/json")) return null;
  const comma = uri.indexOf(",");
  if (comma === -1) return null;

  try {
    const header = uri.slice(0, comma);
    const payload = uri.slice(comma + 1);
    const json = JSON.parse(
      header.split(";").includes("base64")
        ? decodeBase64Utf8(payload)
        : decodeURIComponent(payload),
    ) as unknown;
    return json !== null && typeof json === "object" && !Array.isArray(json)
      ? (json as Record<string, unknown>)
      : null;
  } catch {
    return null;
  }
}

/**
 * Normalize legacy and current tier metadata field names into one display
 * shape. Only non-empty strings are returned.
 */
export function pickTierMetadata(json: Record<string, unknown>): TierMetadata {
  return {
    name: nonEmptyString(json.productName) ?? nonEmptyString(json.name),
    description:
      nonEmptyString(json.productDescription) ??
      nonEmptyString(json.description),
    image: nonEmptyString(json.image) ?? nonEmptyString(json.imageUri),
    animationUrl:
      nonEmptyString(json.animation_url) ?? nonEmptyString(json.animationUrl),
    mediaType:
      nonEmptyString(json.mediaType) ??
      nonEmptyString(json.animationType) ??
      nonEmptyString(json.mimeType),
    categoryName: nonEmptyString(json.categoryName),
  };
}

/** Whether a tier media value uses an immutable or browser-loadable URI form. */
export function isSafeTierMediaUri(value: string): boolean {
  const uri = value.trim();
  if (!uri || /\s/.test(uri)) return false;

  const ipfsPath = ipfsAssetPath(uri);
  if (ipfsPath && isIpfsCid(ipfsPath.split("/")[0])) return true;
  if (isIpfsCid(uri.split("/")[0])) return true;
  if (/^data:(image|audio|video)\/[a-z0-9.+-]+[;,]/i.test(uri)) return true;

  try {
    const url = new URL(uri);
    return url.protocol === "https:" || url.protocol === "http:";
  } catch {
    return false;
  }
}

/** Build the canonical JSON object pinned for one tier. */
export function buildTierMetadata(
  input: TierMetadataInput,
): StoredTierMetadata {
  const name = input.name.trim();
  if (!name) throw new Error("Tier name is required.");

  const optional = (value: string | undefined) => value?.trim() || undefined;
  const image = optional(input.image);
  const animationUrl = optional(input.animationUrl);
  const mediaType = optional(input.mediaType);
  if (image && !isSafeTierMediaUri(image)) {
    throw new Error(
      "Tier images must use IPFS, HTTP, HTTPS, or an image data URI.",
    );
  }
  if (animationUrl && !isSafeTierMediaUri(animationUrl)) {
    throw new Error(
      "Tier animations must use IPFS, HTTP, HTTPS, or a media data URI.",
    );
  }
  if (
    mediaType &&
    !/^[a-z0-9!#$&^_.+-]+\/[a-z0-9!#$&^_.+-]+$/i.test(mediaType)
  ) {
    throw new Error("Tier media type must be a valid MIME type.");
  }

  return {
    name,
    description: optional(input.description),
    image,
    animation_url: animationUrl,
    mediaType,
    categoryName: optional(input.categoryName),
  };
}

/**
 * Route IPFS media through a caller-selected gateway base URL. Data URIs and
 * ordinary HTTP URLs pass through unchanged.
 */
export function tierMediaAssetUrl(
  value: unknown,
  ipfsGatewayBaseUrl = "https://ipfs.io/ipfs/",
): string | undefined {
  if (typeof value !== "string" || !value) return undefined;
  if (value.startsWith("data:")) return value;
  const trimmed = value.trim();
  const path =
    ipfsAssetPath(trimmed) ??
    (isIpfsCid(trimmed.split("/")[0]) ? trimmed : null);
  if (!path) return value;
  return `${ipfsGatewayBaseUrl.replace(/\/?$/, "/")}${path}`;
}

function svgDataUriMarkup(uri: string): string | null {
  const match = /^data:image\/svg\+xml([^,]*),([\s\S]*)$/.exec(uri);
  if (!match) return null;
  try {
    return match[1].split(";").includes("base64")
      ? decodeBase64Utf8(match[2])
      : decodeURIComponent(match[2]);
  } catch {
    return null;
  }
}

/**
 * Return a browser-renderable tier image URL. SVG data URIs that only wrap an
 * external `<image href>` are unwrapped because browsers block that nested
 * network request when the SVG itself is used as an `<img>` source.
 */
export function tierMediaImageUrl(
  image: unknown,
  ipfsGatewayBaseUrl?: string,
): string | undefined {
  if (typeof image !== "string" || !image) return undefined;
  const markup = svgDataUriMarkup(image);
  if (markup) {
    const href = /<image[^>]+href=["']([^"']+)["']/.exec(markup)?.[1];
    if (href && !href.startsWith("data:")) {
      return tierMediaAssetUrl(href, ipfsGatewayBaseUrl);
    }
    return image;
  }
  return tierMediaAssetUrl(image, ipfsGatewayBaseUrl);
}

/** Pick and resolve all tier metadata fields in one pass. */
export function tierDisplayMetadata(
  json: Record<string, unknown>,
  ipfsGatewayBaseUrl?: string,
): TierMetadata {
  const metadata = pickTierMetadata(json);
  return {
    ...metadata,
    image: tierMediaImageUrl(metadata.image, ipfsGatewayBaseUrl),
    animationUrl: tierMediaAssetUrl(metadata.animationUrl, ipfsGatewayBaseUrl),
  };
}

/** Stable first-seen category ids, with blank categories assigned to 0. */
export function buildTierCategoryPlan(
  tiers: ReadonlyArray<{ id: string; categoryName?: string }>,
): {
  categoryByTierId: Record<string, number>;
  storeCategories: Record<string, string>;
} {
  const categoryIds = new Map<string, number>();
  const categoryByTierId: Record<string, number> = {};
  const storeCategories: Record<string, string> = {};

  for (const tier of tiers) {
    const name = tier.categoryName?.trim() || "";
    if (!name) {
      categoryByTierId[tier.id] = 0;
      continue;
    }
    let category = categoryIds.get(name);
    if (category === undefined) {
      category = categoryIds.size + 1;
      categoryIds.set(name, category);
      storeCategories[String(category)] = name;
    }
    categoryByTierId[tier.id] = category;
  }

  return { categoryByTierId, storeCategories };
}

/**
 * A tier's effective (discounted) price, matching the on-chain formula in
 * JB721TiersHookStore: `price - mulDiv(price, discountPercent, 200)` with
 * integer-floor division.
 *
 * @param price The tier's full (undiscounted) price.
 * @param discountPercent The tier's discount, out of 200 (`DISCOUNT_DENOMINATOR`).
 */
export function effectiveTierPrice(
  price: bigint,
  discountPercent: number | bigint,
): bigint {
  let discount = BigInt(discountPercent);
  if (discount <= 0n) return price;
  if (discount > DISCOUNT_DENOMINATOR) discount = DISCOUNT_DENOMINATOR;
  return price - (price * discount) / DISCOUNT_DENOMINATOR;
}

/**
 * A single 721 tier a project sells.
 */
export interface Project721Tier {
  id: number;
  /** Full (undiscounted) price in the shop's pricing terms. */
  price: bigint;
  remainingSupply: number;
  initialSupply: number;
  votingUnits: bigint;
  reserveFrequency: number;
  category: number;
  /** Out of 200 — see {@link DISCOUNT_DENOMINATOR}. */
  discountPercent: number;
  encodedIpfsUri: Hex;
  /** tokenUriResolver output (data URI), or "" if the hook has no resolver. */
  resolvedUri: string;
}

/**
 * A project's resolved 721 tiers hook ("shop"): the hook, its store, the
 * metadata id target for pay/cash-out metadata, the pricing context, and tiers.
 */
export interface Project721Shop {
  /** The project's 721 tiers hook (the ruleset data hook / revnet hook). */
  hook: Address;
  /** The hook's tiers store. */
  store: Address;
  /**
   * The hook's `METADATA_ID_TARGET` (shared implementation address). Pass this
   * to {@link build721PayMetadata} / {@link build721CashOutMetadata}, never the
   * `hook` address.
   */
  metadataIdTarget: Address;
  /** The hook's pricing context: `currency` id and `decimals`. */
  pricing: { currency: number; decimals: number };
  tiers: Project721Tier[];
  /**
   * The current ruleset (with decoded metadata) when hook resolution had to
   * read it — every non-revnet project. `null` for revnets, whose hook comes
   * from `REVOwner` without a ruleset read. Reuse it instead of calling
   * `getCurrentRuleset` again.
   */
  ruleset: JBRulesetWithMetadata | null;
}

/**
 * Read a JB721 hook's `METADATA_ID_TARGET` — the shared *implementation* address
 * that pay/cash-out metadata ids must key off (a delegatecall clone reports the
 * implementation, not itself). Falls back to `hook` ONLY when the contract
 * itself answered that it has no such getter (a revert or empty return — an
 * older, non-clone hook). Transport/RPC failures are rethrown: treating them as
 * "old hook" would key pay metadata off the clone address, which the hook
 * silently ignores — the payer pays and receives no NFT.
 *
 * @param client A viem public client on the given chain.
 * @param args.hook The project's 721 tiers hook (clone) address.
 */
export async function get721MetadataIdTarget(
  client: PublicClient,
  { hook }: { chainId: JBChainId; hook: Address },
): Promise<Address> {
  return client
    .readContract({
      address: hook,
      abi: jb721TiersHookAbi,
      functionName: "METADATA_ID_TARGET",
    })
    .catch((error: unknown) => {
      if (isMissingContractFunctionError(error)) return hook;
      throw error;
    });
}

/**
 * Resolve a project's 721 tiers hook, its store, metadata id target, pricing
 * context, and tiers in one call.
 *
 * Hook resolution mirrors the app patterns: revnets read
 * `REVOwner.tiered721HookOf`; custom projects read the current ruleset's pay
 * data hook — either the omnichain deployer (the real hook lives in
 * `JBOmnichainDeployer.tiered721HookOf(projectId, rulesetId)`) or the 721 hook
 * itself, verified by probing `STORE()` (a proven revert or empty return means
 * it is not a 721 hook, so the project has no shop).
 *
 * Returns `null` only when the project authoritatively has no 721 shop. RPC and
 * transport failures throw — on authoritative reads and on the `STORE()` probe
 * alike — so a transient error surfaces as an error rather than a false
 * "no shop".
 *
 * @param client A viem public client on the given chain.
 * @param args.projectId The project (or revnet) id.
 * @param args.isRevnet Whether the project is a revnet (changes hook resolution).
 * @param args.tierLimit Max tiers to read from `tiersOf`. Defaults to 100.
 * @param args.categories Tier categories to filter by (empty = all). Defaults to `[]`.
 * @param args.includeResolvedUri Ask the store to run the hook's token URI
 * resolver for every tier (`tiersOf`'s `includeResolvedUri`). Defaults to
 * `false`: resolver output (often inline SVG data URIs) is packed into one
 * eth_call return, and over a large shop the upstream RPC rejects it. Turn it
 * on only for small reads that need `resolvedUri` without an indexer.
 */
export async function getProject721Shop(
  client: PublicClient,
  {
    chainId,
    projectId,
    isRevnet,
    tierLimit = 100,
    categories = [],
    includeResolvedUri = false,
  }: {
    chainId: JBChainId;
    projectId: bigint;
    isRevnet: boolean;
    tierLimit?: number;
    categories?: bigint[];
    includeResolvedUri?: boolean;
  },
): Promise<Project721Shop | null> {
  // 1. Resolve the 721 hook.
  let hook: Address | null = null;
  // A non-authoritative candidate is the ruleset data hook, which might be some
  // other kind of hook; the STORE() probe below decides.
  let authoritative = true;
  let currentRuleset: JBRulesetWithMetadata | null = null;

  if (isRevnet) {
    const revnetHook = await getRevnetTiered721Hook(client, {
      chainId,
      revnetId: projectId,
    });
    hook = revnetHook !== zeroAddress ? revnetHook : null;
  } else {
    currentRuleset = await getCurrentRuleset(client, { chainId, projectId });
    const { ruleset, metadata } = currentRuleset;
    const dataHook = metadata.dataHook as Address;
    if (metadata.useDataHookForPay && dataHook && dataHook !== zeroAddress) {
      const omni = jbContractAddress["6"][
        JBOmnichainDeployerContracts.JBOmnichainDeployer
      ]?.[chainId] as Address | undefined;
      if (omni && dataHook.toLowerCase() === omni.toLowerCase()) {
        // Omnichain project: the real 721 hook lives in the deployer's
        // per-ruleset mapping.
        const [omniHook] = await client.readContract({
          address: omni,
          abi: jbOmnichainDeployerAbi,
          functionName: "tiered721HookOf",
          args: [projectId, BigInt(ruleset.id)],
        });
        hook = omniHook !== zeroAddress ? omniHook : null;
      } else {
        // Single-chain custom project: the data hook may be the 721 hook itself.
        hook = dataHook;
        authoritative = false;
      }
    }
  }
  if (!hook) return null;

  // 2. The hook's store. For a non-authoritative candidate a PROVEN revert (or
  // empty return) means "not a 721 hook" — no shop. Transport failures prove
  // nothing and are rethrown; swallowing them would render "no shop" for a
  // project that has one. For an authoritative hook, let every failure throw.
  const readStore = () =>
    client.readContract({
      address: hook!,
      abi: jb721TiersHookAbi,
      functionName: "STORE",
    });
  const store = authoritative
    ? await readStore()
    : await readStore().catch((error: unknown) => {
        if (isMissingContractFunctionError(error)) return null;
        throw error;
      });
  if (!store) return null;

  // 3. Metadata id target + pricing context. Pricing is meaningless without the
  // hook's exact currency + decimals, so a failure here is an error, not a
  // fallback.
  const [metadataIdTarget, pricingRaw] = await Promise.all([
    get721MetadataIdTarget(client, { chainId, hook }),
    client.readContract({
      address: hook,
      abi: jb721TiersHookAbi,
      functionName: "pricingContext",
    }),
  ]);

  // 4. The tiers. Resolver URIs are opt-in (see `includeResolvedUri`).
  const raw = await client.readContract({
    address: store,
    abi: jb721TiersHookStoreAbi,
    functionName: "tiersOf",
    args: [hook, categories, includeResolvedUri, 0n, BigInt(tierLimit)],
  });

  const tiers: Project721Tier[] = raw
    .filter((tier) => tier.initialSupply > 0)
    .map((tier) => ({
      id: tier.id,
      price: tier.price,
      remainingSupply: tier.remainingSupply,
      initialSupply: tier.initialSupply,
      votingUnits: tier.votingUnits,
      reserveFrequency: tier.reserveFrequency,
      category: tier.category,
      discountPercent: tier.discountPercent,
      encodedIpfsUri: tier.encodedIpfsUri,
      resolvedUri: tier.resolvedUri ?? "",
    }));

  return {
    hook,
    store,
    metadataIdTarget,
    pricing: {
      currency: Number(pricingRaw[0]),
      decimals: Number(pricingRaw[1]),
    },
    tiers,
    ruleset: currentRuleset,
  };
}

import { Address, ContractFunctionArgs, Hex } from "viem";
import { jbOmnichainDeployerAbi } from "../generated/juicebox.js";
import { JBChainId } from "../types.js";
import {
  JBSuckerBridge,
  MappableAsset,
  parseSuckerDeployerConfig,
} from "../utils/deploy.js";
import { JBTerminalConfig } from "./launch.js";
import { JBRulesetConfig } from "./rulesets.js";
import { v6Address } from "./types.js";

type OmnichainLaunchArgs = ContractFunctionArgs<
  typeof jbOmnichainDeployerAbi,
  "payable",
  "launchProjectFor"
>;

type OmnichainLaunchArgs7 = Extract<
  OmnichainLaunchArgs,
  readonly [unknown, unknown, unknown, unknown, unknown, unknown, unknown]
>;

type OmnichainLaunchArgs6 = Exclude<OmnichainLaunchArgs, OmnichainLaunchArgs7>;

/**
 * Configuration for deploying a tiered 721 hook alongside a project:
 * the hook's collection config, whether cash outs route through it, and the
 * salt that determines its deterministic address.
 */
export type JBDeploy721TiersHookConfig = OmnichainLaunchArgs7[2];

/**
 * Configuration for deploying suckers (cross-chain token bridges) alongside
 * a project: one deployer config per remote chain, plus the salt that
 * determines the suckers' deterministic addresses.
 */
export type JBSuckerDeploymentConfig = OmnichainLaunchArgs6[5];

/**
 * Build a `JBOmnichainDeployer.launchProjectFor` transaction request creating
 * a new project wired for cross-chain operation (suckers + omnichain ruleset
 * queueing). Send ONE such transaction per chain in `chainIds`.
 *
 * CROSS-CHAIN DETERMINISM RULES — sucker pairing only works if every chain's
 * deployment derives the SAME deterministic addresses:
 *
 * - Use ONE shared `salt` for every chain's transaction (and the same
 *   sending address — the salt is scoped to the sender).
 * - Ruleset configurations must be BYTE-IDENTICAL across chains: pick ONE
 *   shared `mustStartAtOrAfter` timestamp up front (absolute timestamps are
 *   hashed into the deterministic addresses — per-chain "now" values break
 *   sucker pairing).
 * - When deploying a 721 hook, `deploy721Config` (including its salt) must
 *   also be identical across chains.
 *
 * The transaction is payable and must send EXACTLY the current project
 * creation fee — read it per chain with `getProjectCreationFee` (never reuse
 * a fee across chains).
 *
 * @param args.chainId The chain this transaction is for.
 * @param args.chainIds ALL chains the project deploys to (including
 * `chainId`); sucker deployer configs are built for every other chain.
 * @param args.assets The assets to bridge between chains. Defaults to the
 * native token only.
 * @param args.bridge The bridge infrastructure the suckers use: "ccip" (any
 * chain pair, any asset — the default), "native" (OP/Base/Arbitrum standard
 * bridges: Ethereum<->L2 pairs and the native token only), or "both" (a
 * native AND a CCIP sucker per pair where both exist, for redundancy).
 * @param args.salt The shared salt (use the same value on every chain).
 * @param args.deploy721Config Optional tiered 721 hook to deploy with the
 * project (uses the 7-arg overload when given).
 * @param args.creationFee The exact fee from `JBProjects.creationFee()` on
 * this chain.
 */
export function buildOmnichainLaunchProjectTx(args: {
  chainId: JBChainId;
  chainIds: JBChainId[];
  owner: Address;
  projectUri: string;
  rulesetConfigurations: readonly JBRulesetConfig[];
  terminalConfigurations: readonly JBTerminalConfig[];
  memo?: string;
  creationFee: bigint;
  salt: Hex;
  assets?: MappableAsset[];
  bridge?: JBSuckerBridge;
  deploy721Config?: JBDeploy721TiersHookConfig;
}) {
  // parseSuckerDeployerConfig's return type is a v5/v6 union that TS cannot
  // narrow on the `version` option; passing `version: 6` guarantees the v6
  // shape at runtime.
  const suckerDeploymentConfiguration = parseSuckerDeployerConfig(
    args.chainId,
    args.chainIds,
    args.assets ?? [MappableAsset.NATIVE],
    { salt: args.salt, version: 6, bridge: args.bridge },
  ) as unknown as JBSuckerDeploymentConfig;

  const address = v6Address("JBOmnichainDeployer", args.chainId);
  const memo = args.memo ?? "";

  if (args.deploy721Config) {
    return {
      chainId: args.chainId,
      address,
      abi: jbOmnichainDeployerAbi,
      functionName: "launchProjectFor" as const,
      args: [
        args.owner,
        args.projectUri,
        args.deploy721Config,
        args.rulesetConfigurations,
        args.terminalConfigurations,
        memo,
        suckerDeploymentConfiguration,
      ] as const,
      value: args.creationFee,
    };
  }
  return {
    chainId: args.chainId,
    address,
    abi: jbOmnichainDeployerAbi,
    functionName: "launchProjectFor" as const,
    args: [
      args.owner,
      args.projectUri,
      args.rulesetConfigurations,
      args.terminalConfigurations,
      memo,
      suckerDeploymentConfiguration,
    ] as const,
    value: args.creationFee,
  };
}

/**
 * Build a `JBOmnichainDeployer.queueRulesetsOf` transaction request queuing
 * rulesets for an omnichain project. Send ONE such transaction per chain the
 * project lives on, with BYTE-IDENTICAL ruleset configurations (including a
 * single shared `mustStartAtOrAfter` — per-chain "now" timestamps make the
 * chains' rulesets diverge).
 *
 * The caller must have the `QUEUE_RULESETS` permission for the project (the
 * omnichain deployer holds it when the project was launched through it).
 *
 * @param args.deploy721Config Optionally deploy a NEW tiered 721 hook (e.g.
 * as the queued ruleset's data hook) alongside the queue — uses the 4-arg
 * overload when given; keep it identical across chains.
 */
export function buildOmnichainQueueRulesetsTx(args: {
  chainId: JBChainId;
  projectId: bigint;
  rulesetConfigurations: readonly JBRulesetConfig[];
  memo?: string;
  deploy721Config?: JBDeploy721TiersHookConfig;
}) {
  const address = v6Address("JBOmnichainDeployer", args.chainId);
  const memo = args.memo ?? "";

  if (args.deploy721Config) {
    return {
      chainId: args.chainId,
      address,
      abi: jbOmnichainDeployerAbi,
      functionName: "queueRulesetsOf" as const,
      args: [
        args.projectId,
        args.deploy721Config,
        args.rulesetConfigurations,
        memo,
      ] as const,
    };
  }
  return {
    chainId: args.chainId,
    address,
    abi: jbOmnichainDeployerAbi,
    functionName: "queueRulesetsOf" as const,
    args: [args.projectId, args.rulesetConfigurations, memo] as const,
  };
}

import { Address, Hex, PublicClient, encodeAbiParameters } from "viem";
import { DEFAULT_ALLOW_OVERSPENDING, NATIVE_TOKEN } from "../constants.js";
import { jbMultiTerminalAbi } from "../generated/juicebox.js";
import { JBChainId } from "../types.js";
import { createHookMetadata, hookMetadataId } from "../utils/hook.js";

/**
 * A prepared `pay` transaction request, accepted as-is by viem's
 * `walletClient.writeContract` and wagmi's `writeContract`.
 */
export interface V6PayTxRequest {
  chainId: JBChainId;
  address: Address;
  abi: typeof jbMultiTerminalAbi;
  functionName: "pay";
  args: readonly [bigint, Address, bigint, Address, bigint, string, Hex];
  value: bigint;
}

/**
 * Build a `pay(projectId, token, amount, beneficiary, minReturnedTokens, memo,
 * metadata)` transaction request for a v6 terminal.
 *
 * When `token` is the native token, `value` is set to `amount` (the terminal reads the
 * paid amount from `msg.value`); for ERC-20 payments `value` is 0 and the terminal must
 * be approved to pull `amount` beforehand.
 *
 * @param args.chainId The chain to pay on.
 * @param args.terminal The terminal to pay (resolve with `resolvePaymentTerminal`).
 * @param args.projectId The project's id.
 * @param args.token The token being paid.
 * @param args.amount The amount being paid, as a fixed point number with the token's
 * decimals.
 * @param args.beneficiary The address that receives the minted project tokens.
 * @param args.minReturnedTokens The minimum project token count the beneficiary must
 * receive, else the transaction reverts. Defaults to 0.
 * @param args.memo A memo included in the Pay event. Defaults to "".
 * @param args.metadata Hook metadata (e.g. from {@link build721PayMetadata}). Defaults
 * to "0x".
 * @returns The transaction request.
 */
export function buildPayTx({
  chainId,
  terminal,
  projectId,
  token,
  amount,
  beneficiary,
  minReturnedTokens = 0n,
  memo = "",
  metadata = "0x",
}: {
  chainId: JBChainId;
  terminal: Address;
  projectId: bigint;
  token: Address;
  amount: bigint;
  beneficiary: Address;
  minReturnedTokens?: bigint;
  memo?: string;
  metadata?: Hex;
}): V6PayTxRequest {
  const isNative = token.toLowerCase() === NATIVE_TOKEN.toLowerCase();

  return {
    chainId,
    address: terminal,
    abi: jbMultiTerminalAbi,
    functionName: "pay",
    args: [
      projectId,
      token,
      amount,
      beneficiary,
      minReturnedTokens,
      memo,
      metadata,
    ],
    value: isNative ? amount : 0n,
  };
}

/**
 * The result of previewing a payment.
 */
export interface PayPreview {
  /**
   * The project token count the beneficiary would receive.
   */
  beneficiaryTokenCount: bigint;
  /**
   * The project token count that would be reserved for the project's reserved splits.
   */
  reservedTokenCount: bigint;
}

export type PaySettlement = "issuance" | "swap";

export interface PayRouteCandidate extends PayPreview {
  kind: "pay";
  settlement: PaySettlement;
}

export interface DirectSwapRouteCandidate extends PayPreview {
  kind: "direct-swap";
  settlement: "swap";
  quotedTokenCount: bigint;
}

export type BestPayRoute = PayRouteCandidate | DirectSwapRouteCandidate;

/**
 * Pick the executable route which guarantees the beneficiary the most tokens.
 *
 * A direct pool swap bypasses the terminal, so its reserved token count is always
 * zero. Its quote is reduced by `slippageBps` before comparison: a route is only
 * selected when its on-chain minimum beats the terminal preview, not merely when
 * its optimistic quote does.
 */
export function chooseBestPayRoute({
  pay,
  paySettlement,
  directSwapQuote,
  slippageBps = 100n,
}: {
  pay: PayPreview;
  paySettlement: PaySettlement;
  directSwapQuote?: bigint | null;
  slippageBps?: bigint;
}): BestPayRoute {
  if (slippageBps < 0n || slippageBps >= 10_000n) {
    throw new Error("slippageBps must be between 0 and 9,999.");
  }

  const payRoute: PayRouteCandidate = {
    kind: "pay",
    settlement: paySettlement,
    ...pay,
  };
  if (!directSwapQuote || directSwapQuote <= 0n) return payRoute;

  const minimum = (directSwapQuote * (10_000n - slippageBps)) / 10_000n;
  if (minimum <= pay.beneficiaryTokenCount) return payRoute;

  return {
    kind: "direct-swap",
    settlement: "swap",
    quotedTokenCount: directSwapQuote,
    beneficiaryTokenCount: minimum,
    reservedTokenCount: 0n,
  };
}

/**
 * Preview the project tokens minted by a payment, via the terminal's
 * `previewPayFor(projectId, token, amount, beneficiary, metadata)`.
 *
 * The terminal's `previewPayFor` is used (rather than
 * `JBTerminalStore.previewPayFrom`) because it takes exactly the data a `pay` caller
 * already has — the store variant additionally requires a full `JBTokenAmount` tuple
 * (token, decimals, currency, value), forcing an extra accounting-context lookup.
 *
 * @param client A viem public client on the given chain.
 * @param args.chainId The chain to preview on.
 * @param args.terminal The terminal that would be paid.
 * @param args.projectId The project's id.
 * @param args.token The token being paid.
 * @param args.amount The amount being paid, as a fixed point number with the token's
 * decimals.
 * @param args.beneficiary The address that would receive the minted project tokens.
 * @param args.metadata Hook metadata. Defaults to "0x".
 * @returns The previewed token counts.
 */
export async function previewPay(
  client: PublicClient,
  {
    terminal,
    projectId,
    token,
    amount,
    beneficiary,
    metadata = "0x",
  }: {
    chainId: JBChainId;
    terminal: Address;
    projectId: bigint;
    token: Address;
    amount: bigint;
    beneficiary: Address;
    metadata?: Hex;
  },
): Promise<PayPreview> {
  const [, beneficiaryTokenCount, reservedTokenCount] =
    await client.readContract({
      address: terminal,
      abi: jbMultiTerminalAbi,
      functionName: "previewPayFor",
      args: [projectId, token, amount, beneficiary, metadata],
    });

  return { beneficiaryTokenCount, reservedTokenCount };
}

/**
 * Build pay metadata instructing a project's JB721 tiers hook to mint specific tiers.
 *
 * The tier payload is `abi.encode(bool allowOverspending, uint16[] tierIdsToMint)`,
 * keyed by the hook's metadata id (`bytes4(bytes20(metadataIdTarget) ^
 * bytes20(keccak256("pay")))`) and packed into the JBMetadataResolver
 * word-offset-table format.
 *
 * @param args.metadataIdTarget The hook's `METADATA_ID_TARGET` — the shared
 * *implementation* address, NOT the project's clone hook address (see
 * {@link get721MetadataIdTarget}). Passing the clone address makes the hook ignore
 * the tiers and the payment mints ZERO NFTs (it succeeds, minting only tokens).
 * @param args.hookAddress Deprecated alias for `metadataIdTarget`. Only correct
 * when it already holds `METADATA_ID_TARGET`; prefer `metadataIdTarget`.
 * @param args.tierIdsToMint The tier ids to mint, one entry per NFT.
 * @param args.allowOverspending Whether payment beyond the tiers' total price is
 * allowed (excess mints no NFT). Defaults to true. Note the hook still gates this
 * on its store's `preventOverspending` flag.
 * @returns The metadata to pass as `pay`'s `metadata` argument.
 */
export function build721PayMetadata({
  metadataIdTarget,
  hookAddress,
  tierIdsToMint,
  allowOverspending = DEFAULT_ALLOW_OVERSPENDING,
}: {
  metadataIdTarget?: Address;
  /** @deprecated Use `metadataIdTarget`. */
  hookAddress?: Address;
  tierIdsToMint: bigint[];
  allowOverspending?: boolean;
}): Hex {
  const target = metadataIdTarget ?? hookAddress;
  if (!target) {
    throw new Error("build721PayMetadata requires metadataIdTarget");
  }

  const tierPayload = encodeAbiParameters(
    [{ type: "bool" }, { type: "uint16[]" }],
    [allowOverspending, tierIdsToMint.map(Number)],
  );

  return createHookMetadata(
    [hookMetadataId(target, "pay")],
    [tierPayload],
  ) as Hex;
}

/**
 * Encode the three-word pay quote required by buyback hook 1.4.0.
 * An explicit minimum is a settlement guarantee; zero uses the oracle floor,
 * whose underfill unwinds the swap and falls back to minting. Resolve the
 * project's actual hook before selecting this metadata target.
 */
export function buildBuybackPayMetadata({
  hook,
  amountToSwapWith,
  minimumSwapAmountOut,
  skipSplits = false,
}: {
  hook: Address;
  amountToSwapWith: bigint;
  minimumSwapAmountOut: bigint;
  skipSplits?: boolean;
}): Hex {
  return createHookMetadata(
    [hookMetadataId(hook, "pay")],
    [
      encodeAbiParameters(
        [{ type: "uint256" }, { type: "uint256" }, { type: "bool" }],
        [amountToSwapWith, minimumSwapAmountOut, skipSplits],
      ),
    ],
  );
}

import { Address, PublicClient } from "viem";
import { jbPermissionsAbi } from "../generated/juicebox.js";
import { JBChainId } from "../types.js";
import { v6Address } from "./types.js";

/**
 * The v6 permission ids, transcribed from JBPermissionIds.sol.
 *
 * Projects can grant permissions to other addresses (called "operators") through
 * `JBPermissions`. Each id authorizes the operator to call specific functions on
 * behalf of the project owner or token holder.
 *
 * @link https://github.com/Bananapus/nana-permission-ids-v6/blob/main/src/JBPermissionIds.sol
 */
export const JBPermissionIdsV6 = {
  /**
   * Grants all permissions across every Juicebox contract. Use with extreme caution.
   */
  ROOT: 1,

  // nana-core-v6
  QUEUE_RULESETS: 2,
  LAUNCH_RULESETS: 3,
  CASH_OUT_TOKENS: 4,
  SEND_PAYOUTS: 5,
  MIGRATE_TERMINAL: 6,
  SET_PROJECT_URI: 7,
  DEPLOY_ERC20: 8,
  SET_TOKEN: 9,
  MINT_TOKENS: 10,
  BURN_TOKENS: 11,
  CLAIM_TOKENS: 12,
  TRANSFER_CREDITS: 13,
  SET_CONTROLLER: 14,
  SET_TERMINALS: 15,
  ADD_TERMINALS: 16,
  SET_PRIMARY_TERMINAL: 17,
  USE_ALLOWANCE: 18,
  SET_SPLIT_GROUPS: 19,
  ADD_PRICE_FEED: 20,
  ADD_ACCOUNTING_CONTEXTS: 21,
  SET_TOKEN_METADATA: 22,
  SIGN_FOR_ERC20: 23,

  // nana-721-hook-v6
  ADJUST_721_TIERS: 24,
  SET_721_METADATA: 25,
  MINT_721: 26,
  SET_721_DISCOUNT_PERCENT: 27,

  // nana-buyback-hook-v6
  SET_BUYBACK_TWAP: 28,
  SET_BUYBACK_POOL: 29,
  SET_BUYBACK_HOOK: 30,

  // nana-router-terminal-v6
  SET_ROUTER_TERMINAL: 31,

  // nana-suckers-v6
  MAP_SUCKER_TOKEN: 32,
  DEPLOY_SUCKERS: 33,
  SET_SUCKER_PEER: 34,
  SUCKER_SAFETY: 35,
  SET_SUCKER_DEPRECATION: 36,

  // revnet-core-v6
  OPEN_LOAN: 37,
  REALLOCATE_LOAN: 38,
  REPAY_LOAN: 39,
} as const;

/**
 * A v6 permission id.
 */
export type JBPermissionIdV6 =
  (typeof JBPermissionIdsV6)[keyof typeof JBPermissionIdsV6];

/** A symbolic v6 permission name, such as `QUEUE_RULESETS`. */
export type JBPermissionKeyV6 = keyof typeof JBPermissionIdsV6;

/** Canonical permission names and ids, sorted by id. */
export const JBPermissionCatalogV6: readonly {
  key: JBPermissionKeyV6;
  id: JBPermissionIdV6;
}[] = (
  Object.entries(JBPermissionIdsV6) as [JBPermissionKeyV6, JBPermissionIdV6][]
)
  .map(([key, id]) => ({ key, id }))
  .sort((a, b) => a.id - b.id);

const JB_PERMISSION_KEY_BY_ID = new Map<number, JBPermissionKeyV6>(
  JBPermissionCatalogV6.map(({ key, id }) => [id, key]),
);

/** Return the SDK permission name for an id, or `null` for a newer/unknown id. */
export function permissionKeyV6(id: number): JBPermissionKeyV6 | null {
  return JB_PERMISSION_KEY_BY_ID.get(id) ?? null;
}

/**
 * Decode `JBPermissions.permissionsOf`'s packed bitmap into ascending ids.
 *
 * By default only ids known to this SDK release are returned. Pass
 * `includeUnknown: true` to preserve set bits from future permission-id
 * releases as well.
 */
export function decodePermissionBitmap(
  bitmap: bigint,
  { includeUnknown = false }: { includeUnknown?: boolean } = {},
): number[] {
  if (bitmap < 0n) throw new Error("A permission bitmap cannot be negative.");
  const ids: number[] = [];
  const maxId = includeUnknown
    ? 255
    : (JBPermissionCatalogV6[JBPermissionCatalogV6.length - 1]?.id ?? 0);
  for (let id = 1; id <= maxId; id++) {
    if (((bitmap >> BigInt(id)) & 1n) === 1n) ids.push(id);
  }
  return ids;
}

/** Encode permission ids into the packed bitmap returned by `permissionsOf`. */
export function encodePermissionBitmap(
  permissionIds: readonly number[],
): bigint {
  let bitmap = 0n;
  for (const id of permissionIds) {
    if (!Number.isInteger(id) || id < 1 || id > 255) {
      throw new Error(`Invalid permission id: ${id}.`);
    }
    bitmap |= 1n << BigInt(id);
  }
  return bitmap;
}

/**
 * A prepared `setPermissionsFor` transaction request.
 */
export interface V6SetPermissionsTxRequest {
  chainId: JBChainId;
  address: Address;
  abi: typeof jbPermissionsAbi;
  functionName: "setPermissionsFor";
  args: readonly [
    Address,
    { operator: Address; projectId: bigint; permissionIds: number[] },
  ];
}

/**
 * Build a `JBPermissions.setPermissionsFor(account, { operator, projectId,
 * permissionIds })` transaction request.
 *
 * Replaces ALL of the operator's permissions for the account and project with the
 * given ids — pass an empty array to revoke everything. Must be sent by `account` (or
 * an operator with the ROOT permission for it).
 *
 * @param args.chainId The chain to set permissions on.
 * @param args.account The account granting the permissions.
 * @param args.operator The operator receiving the permissions.
 * @param args.projectId The project the permissions are scoped to, or 0 for all of the
 * account's projects (the wildcard project id).
 * @param args.permissionIds The permission ids to grant (see
 * {@link JBPermissionIdsV6}).
 * @returns The transaction request.
 */
export function buildSetPermissionsTx({
  chainId,
  account,
  operator,
  projectId,
  permissionIds,
}: {
  chainId: JBChainId;
  account: Address;
  operator: Address;
  projectId: bigint;
  permissionIds: number[];
}): V6SetPermissionsTxRequest {
  return {
    chainId,
    address: v6Address("JBPermissions", chainId),
    abi: jbPermissionsAbi,
    functionName: "setPermissionsFor",
    args: [account, { operator, projectId, permissionIds }],
  };
}

/**
 * Check whether an operator holds ALL of the given permissions for an account and
 * project, via `JBPermissions.hasPermissions`.
 *
 * @param client A viem public client on the given chain.
 * @param args.chainId The chain to check on.
 * @param args.operator The operator being checked.
 * @param args.account The account the permissions would be granted by.
 * @param args.projectId The project the permissions are scoped to.
 * @param args.permissionIds The permission ids to check (see
 * {@link JBPermissionIdsV6}).
 * @param args.includeRoot Whether holding the ROOT permission should satisfy the
 * check. Defaults to true.
 * @param args.includeWildcardProjectId Whether permissions granted for the wildcard
 * project id (0) should satisfy the check. Defaults to true.
 * @returns True when the operator holds every given permission.
 */
export async function hasPermissions(
  client: PublicClient,
  {
    chainId,
    operator,
    account,
    projectId,
    permissionIds,
    includeRoot = true,
    includeWildcardProjectId = true,
  }: {
    chainId: JBChainId;
    operator: Address;
    account: Address;
    projectId: bigint;
    permissionIds: number[];
    includeRoot?: boolean;
    includeWildcardProjectId?: boolean;
  },
): Promise<boolean> {
  return client.readContract({
    address: v6Address("JBPermissions", chainId),
    abi: jbPermissionsAbi,
    functionName: "hasPermissions",
    args: [
      operator,
      account,
      projectId,
      permissionIds.map(BigInt),
      includeRoot,
      includeWildcardProjectId,
    ],
  });
}

import type { Address, Hex, PublicClient } from "viem";
import { NATIVE_TOKEN } from "../constants.js";
import type { JBChainId } from "../types.js";
import {
  UNISWAP_PERMIT2_ADDRESS,
  uniswapV4Deployment,
} from "./uniswapV4Deployments.js";

/** Canonical Permit2 deployment shared by supported EVM chains. */
export const PERMIT2_ADDRESS = UNISWAP_PERMIT2_ADDRESS;

/** Permit2 methods used to inspect or establish Universal Router allowances. */
export const permit2Abi = [
  {
    type: "function",
    name: "allowance",
    stateMutability: "view",
    inputs: [
      { name: "owner", type: "address" },
      { name: "token", type: "address" },
      { name: "spender", type: "address" },
    ],
    outputs: [
      { name: "amount", type: "uint160" },
      { name: "expiration", type: "uint48" },
      { name: "nonce", type: "uint48" },
    ],
  },
  {
    type: "function",
    name: "approve",
    stateMutability: "nonpayable",
    inputs: [
      { name: "token", type: "address" },
      { name: "spender", type: "address" },
      { name: "amount", type: "uint160" },
      { name: "expiration", type: "uint48" },
    ],
    outputs: [],
  },
] as const;

/** EIP-712 types for Permit2's one-token, one-spender authorization. */
export const PERMIT2_TYPES = {
  PermitDetails: [
    { name: "token", type: "address" },
    { name: "amount", type: "uint160" },
    { name: "expiration", type: "uint48" },
    { name: "nonce", type: "uint48" },
  ],
  PermitSingle: [
    { name: "details", type: "PermitDetails" },
    { name: "spender", type: "address" },
    { name: "sigDeadline", type: "uint256" },
  ],
} as const;

export interface Permit2SignatureAuthorization {
  chainId: JBChainId;
  token: Address;
  spender: Address;
  amount: bigint;
  expiration: number;
  nonce: number;
  sigDeadline: bigint;
}

export interface Permit2Allowance {
  amount: bigint;
  expiration: number;
  nonce: number;
}

/** Build the exact typed-data payload a wallet signs for PermitSingle. */
export function permit2TypedData(authorization: Permit2SignatureAuthorization) {
  return {
    domain: {
      name: "Permit2" as const,
      chainId: authorization.chainId,
      verifyingContract: PERMIT2_ADDRESS,
    },
    types: PERMIT2_TYPES,
    primaryType: "PermitSingle" as const,
    message: {
      details: {
        token: authorization.token,
        amount: authorization.amount,
        expiration: authorization.expiration,
        nonce: authorization.nonce,
      },
      spender: authorization.spender,
      sigDeadline: authorization.sigDeadline,
    },
  };
}

/** Read an owner's Permit2 allowance, defaulting the spender to Universal Router. */
export async function readPermit2Allowance(
  client: PublicClient,
  {
    chainId,
    owner,
    token,
    spender,
  }: {
    chainId: JBChainId;
    owner: Address;
    token: Address;
    spender?: Address;
  },
): Promise<Permit2Allowance> {
  const resolvedSpender =
    spender ?? uniswapV4Deployment(chainId)?.universalRouter;
  if (!resolvedSpender) {
    throw new Error(
      `No supported Uniswap Universal Router on chain ${chainId}.`,
    );
  }
  const [amount, expiration, nonce] = await client.readContract({
    address: PERMIT2_ADDRESS,
    abi: permit2Abi,
    functionName: "allowance",
    args: [owner, token, resolvedSpender],
  });
  return { amount, expiration, nonce };
}

/** Whether an allowance is too small or expires inside the safety buffer. */
export function permit2AllowanceNeedsRefresh({
  allowance,
  amount,
  now = Math.floor(Date.now() / 1000),
  expirationBufferSeconds = 1_800,
}: {
  allowance: Pick<Permit2Allowance, "amount" | "expiration">;
  amount: bigint;
  now?: number;
  expirationBufferSeconds?: number;
}): boolean {
  if (expirationBufferSeconds < 0) {
    throw new Error("expirationBufferSeconds cannot be negative.");
  }
  return (
    allowance.amount < amount ||
    allowance.expiration <= now + expirationBufferSeconds
  );
}

/** Read whether an ERC-20 needs a fresh Permit2 authorization for Universal Router. */
export async function needsPermit2Approval({
  client,
  chainId,
  owner,
  token,
  amount,
  now,
  expirationBufferSeconds,
}: {
  client: PublicClient;
  chainId: JBChainId;
  owner: Address;
  token: Address;
  amount: bigint;
  now?: number;
  expirationBufferSeconds?: number;
}): Promise<boolean> {
  if (token.toLowerCase() === NATIVE_TOKEN.toLowerCase()) return false;
  const allowance = await readPermit2Allowance(client, {
    chainId,
    owner,
    token,
  });
  return permit2AllowanceNeedsRefresh({
    allowance,
    amount,
    now,
    expirationBufferSeconds,
  });
}

/**
 * Prefer a gasless Permit2 signature for EOAs. Contract wallets generally need
 * the on-chain Permit2 approval path unless their integration handles ERC-1271.
 */
export function shouldUsePermit2Signature({
  needsApproval,
  walletLookupSettled,
  walletBytecode,
  isSafe,
}: {
  needsApproval: boolean;
  walletLookupSettled: boolean;
  walletBytecode?: Hex;
  isSafe: boolean;
}): boolean {
  const isContract = !!walletBytecode && walletBytecode !== "0x";
  return needsApproval && walletLookupSettled && !isContract && !isSafe;
}

/** Fall back only for wallets that cannot sign typed data, never on rejection. */
export function permit2SignatureNeedsOnchainFallback(error: unknown): boolean {
  const messages: string[] = [];
  let current: unknown = error;
  for (let depth = 0; current && depth < 5; depth += 1) {
    if (typeof current !== "object") break;
    const value = current as Record<string, unknown>;
    for (const key of ["code", "shortMessage", "message", "details"]) {
      if (value[key] !== undefined) messages.push(String(value[key]));
    }
    current = value.cause;
  }
  const text = messages.join(" ").toLowerCase();
  if (/user rejected|rejected the request|denied|4001/.test(text)) return false;
  return /(^|\s)-32602(\s|$)|(^|\s)-32601(\s|$)|(^|\s)4200(\s|$)|invalid parameters|method .*not supported|unsupported method|typed data.*not supported/.test(
    text,
  );
}

import { PublicClient } from "viem";
import { jbPricesAbi } from "../generated/juicebox.js";
import { JBChainId } from "../types.js";
import { isContractRevertError } from "../utils/errors.js";
import { JBAccountingContext } from "./terminals.js";
import { v6Address } from "./types.js";

/**
 * One `JBPrices.pricePerUnitOf` lookup a project's configuration depends on at
 * runtime. Pairs are unordered — JBPrices falls back to the inverse feed
 * itself, so reachability is symmetric.
 */
export interface JBFeedPair {
  pricingCurrency: number;
  unitCurrency: number;
  /**
   * The decimals the terminal itself passes: the context's decimals on the
   * pay path, 18 (the store's max fixed-point fidelity) on the cross-context
   * cash-out/surplus path.
   */
  decimals: number;
}

/**
 * Every `JBPrices` pair the terminal will resolve at runtime for a project
 * accepting the given accounting contexts (the exact structs
 * `buildAccountingContext` emits) with the given ruleset `baseCurrency`:
 *
 * - each `context.currency` ↔ `baseCurrency` (the pay/issuance conversion;
 *   skipped when equal — the terminal short-circuits), and
 * - each `context.currency` ↔ each other `context.currency` (cash-out and
 *   surplus views convert every OTHER context's balance into the reclaimed
 *   context's currency, NOT the base currency; skipped for single-context
 *   projects).
 *
 * Pairs are deduped without direction. Feeds resolve direct or inverse only —
 * never transitively through an intermediate currency — so every returned pair
 * must be individually served by a feed or the project's payments and/or cash
 * outs revert on-chain. Accounting contexts are immutable once set, so an
 * unreachable pair must be caught BEFORE launch (see
 * {@link probeFeedReachability}).
 */
export function requiredFeedPairs(
  accountingContexts: readonly JBAccountingContext[],
  baseCurrency: number,
): JBFeedPair[] {
  const pairs: JBFeedPair[] = [];
  const seen = new Set<string>();
  const add = (
    pricingCurrency: number,
    unitCurrency: number,
    decimals: number,
  ) => {
    if (pricingCurrency === unitCurrency) return;
    const key = `${Math.min(pricingCurrency, unitCurrency)}:${Math.max(
      pricingCurrency,
      unitCurrency,
    )}`;
    if (seen.has(key)) return;
    seen.add(key);
    pairs.push({ pricingCurrency, unitCurrency, decimals });
  };
  for (const context of accountingContexts) {
    add(context.currency, baseCurrency, context.decimals);
  }
  for (let i = 0; i < accountingContexts.length; i++) {
    for (let j = i + 1; j < accountingContexts.length; j++) {
      add(accountingContexts[i].currency, accountingContexts[j].currency, 18);
    }
  }
  return pairs;
}

/**
 * A feed-reachability verdict. Anything other than `ok` should block a launch:
 * `missing` because the chain ANSWERED that a required pair has no feed, and
 * `unavailable` because at least one probe could not be completed — an RPC
 * failure is not proof of a missing feed, but it is not proof of a present one
 * either, so it fails closed WITHOUT being reported as `missing`.
 */
export type FeedReachability =
  | { status: "ok" }
  | { status: "missing"; missing: JBFeedPair[] }
  | { status: "unavailable" };

/**
 * Probe on-chain that every given `JBPrices` pair resolves, via the same
 * `pricePerUnitOf` read the terminal performs at runtime. The default
 * `projectId` 0 gives exactly the protocol-default-feed semantics a freshly
 * launched project starts with — and, because the probe is on-chain, a later
 * protocol-side default-feed registration unblocks the combination with no
 * client release.
 *
 * A revert (as opposed to a transport failure) means the chain answered, so a
 * pair is only ever reported `missing` on a proven
 * `ContractFunctionRevertedError`; every other failure — timeouts, HTTP
 * errors, a chain with no known `JBPrices` deployment — yields `unavailable`.
 *
 * @param client A viem public client on the given chain.
 * @param args.chainId The chain to probe on.
 * @param args.pairs The pairs to probe (see {@link requiredFeedPairs}).
 * @param args.projectId The project id to resolve feeds for. Defaults to 0n
 * (the protocol default feeds).
 */
export async function probeFeedReachability(
  client: PublicClient,
  {
    chainId,
    pairs,
    projectId = 0n,
  }: {
    chainId: JBChainId;
    pairs: readonly JBFeedPair[];
    projectId?: bigint;
  },
): Promise<FeedReachability> {
  if (pairs.length === 0) return { status: "ok" };

  let prices;
  try {
    prices = v6Address("JBPrices", chainId);
  } catch {
    return { status: "unavailable" };
  }

  let unverified = false;
  const missing: JBFeedPair[] = [];
  await Promise.all(
    pairs.map(async (pair) => {
      try {
        await client.readContract({
          address: prices,
          abi: jbPricesAbi,
          functionName: "pricePerUnitOf",
          args: [
            projectId,
            BigInt(pair.pricingCurrency),
            BigInt(pair.unitCurrency),
            BigInt(pair.decimals),
          ],
        });
      } catch (error) {
        if (isContractRevertError(error)) {
          missing.push(pair);
        } else {
          unverified = true;
        }
      }
    }),
  );

  if (missing.length > 0) return { status: "missing", missing };
  if (unverified) return { status: "unavailable" };
  return { status: "ok" };
}

import { decodeEventLog, isAddressEqual, type Address, type Hex } from "viem";
import type { JBChainId } from "../types.js";

/**
 * Canonical JBProjectPayerDeployer address. The v6 deployment uses the same
 * CREATE2 address on every chain supported by the SDK.
 */
export const JB_PROJECT_PAYER_DEPLOYER =
  "0x7321740fd0dcf73dd3e2aa8fc060454abfce9517" as Address;

/** JBProjectPayerDeployer surface needed by web clients. */
export const jbProjectPayerDeployerAbi = [
  {
    type: "function",
    name: "deployProjectPayer",
    stateMutability: "nonpayable",
    inputs: [
      { name: "defaultProjectId", type: "uint256" },
      { name: "defaultBeneficiary", type: "address" },
      { name: "defaultMemo", type: "string" },
      { name: "defaultMetadata", type: "bytes" },
      { name: "defaultAddToBalance", type: "bool" },
      { name: "owner", type: "address" },
    ],
    outputs: [{ name: "projectPayer", type: "address" }],
  },
  {
    type: "event",
    name: "DeployProjectPayer",
    anonymous: false,
    inputs: [
      { name: "projectPayer", type: "address", indexed: true },
      { name: "defaultProjectId", type: "uint256", indexed: false },
      { name: "defaultBeneficiary", type: "address", indexed: false },
      { name: "defaultMemo", type: "string", indexed: false },
      { name: "defaultMetadata", type: "bytes", indexed: false },
      { name: "defaultAddToBalance", type: "bool", indexed: false },
      { name: "directory", type: "address", indexed: false },
      { name: "owner", type: "address", indexed: false },
      { name: "caller", type: "address", indexed: false },
    ],
  },
] as const;

/** Validate and normalize metadata bytes forwarded by a project payer. */
export function normalizeProjectPayerMetadata(value?: string): Hex {
  const metadata = value?.trim() || "0x";
  if (!/^0x(?:[0-9a-fA-F]{2})*$/.test(metadata)) {
    throw new Error("Project payer metadata must be whole hex bytes.");
  }
  return metadata as Hex;
}

/** Build a JBProjectPayerDeployer.deployProjectPayer transaction request. */
export function buildDeployProjectPayerTx(args: {
  chainId: JBChainId;
  projectId: bigint;
  beneficiary: Address;
  memo?: string;
  metadata?: string;
  addToBalance?: boolean;
  owner: Address;
}) {
  if (args.projectId <= 0n) {
    throw new Error("A project payer requires a positive project ID.");
  }

  return {
    chainId: args.chainId,
    address: JB_PROJECT_PAYER_DEPLOYER,
    abi: jbProjectPayerDeployerAbi,
    functionName: "deployProjectPayer" as const,
    args: [
      args.projectId,
      args.beneficiary,
      args.memo ?? "",
      normalizeProjectPayerMetadata(args.metadata),
      args.addToBalance ?? false,
      args.owner,
    ] as const,
  };
}

/** Minimal receipt-log shape needed to decode a project-payer deployment. */
export interface ProjectPayerDeployLog {
  address: Address;
  data: Hex;
  topics: readonly Hex[];
}

/**
 * Decode the payer address from a canonical JBProjectPayerDeployer event.
 * Emitter verification prevents an unrelated same-signature log from being
 * mistaken for the newly deployed payer.
 */
export function decodeDeployedProjectPayer(
  log: ProjectPayerDeployLog,
): Address | null {
  if (!isAddressEqual(log.address, JB_PROJECT_PAYER_DEPLOYER)) return null;

  try {
    const decoded = decodeEventLog({
      abi: jbProjectPayerDeployerAbi,
      eventName: "DeployProjectPayer",
      data: log.data,
      topics: log.topics as [Hex, ...Hex[]],
      strict: true,
    });
    return decoded.eventName === "DeployProjectPayer"
      ? decoded.args.projectPayer
      : null;
  } catch {
    return null;
  }
}

/** Return the first canonical project-payer deployment found in a receipt. */
export function projectPayerFromDeployLogs(
  logs: readonly ProjectPayerDeployLog[],
): Address | null {
  for (const log of logs) {
    const payer = decodeDeployedProjectPayer(log);
    if (payer) return payer;
  }
  return null;
}

import { Address, ContractFunctionArgs, PublicClient } from "viem";
import { revDeployerAbi, revOwnerAbi } from "../generated/juicebox.js";
import { JBChainId } from "../types.js";
import { JBAccountingContext } from "./terminals.js";
import { v6Address } from "./types.js";

type RevDeployArgs = ContractFunctionArgs<
  typeof revDeployerAbi,
  "payable",
  "deployFor"
>;

type RevDeployArgs6 = Extract<
  RevDeployArgs,
  readonly [unknown, unknown, unknown, unknown, unknown, unknown]
>;

type RevDeployArgs4 = Extract<
  RevDeployArgs,
  readonly [unknown, unknown, unknown, unknown]
>;

/**
 * A revnet's full configuration: its token description (name/ticker/uri and
 * the salt that fixes the ERC-20's deterministic address), base currency
 * (either a token-keyed currency or a well-known `JBCurrencyIds` id such as
 * ETH=1 or USD=2), operator, and stage configurations.
 */
export type REVConfig = RevDeployArgs4[1];

/**
 * One stage of a revnet's lifecycle. See `buildRevnetStageConfig` for the
 * field encodings.
 */
export type REVStageConfig = REVConfig["stageConfigurations"][number];

/**
 * An auto-issuance: tokens minted without payment when a stage starts, to a
 * beneficiary on a specific chain. `count` is an 18-decimal fixed point.
 */
export type REVAutoIssuance = REVStageConfig["autoIssuances"][number];

/**
 * Sucker deployment configuration for a revnet (same shape the omnichain
 * deployer takes; build with `parseSuckerDeployerConfig(..., { version: 6 })`).
 */
export type REVSuckerDeploymentConfig = RevDeployArgs4[3];

/**
 * Configuration for deploying a tiered 721 hook alongside a revnet.
 */
export type REVDeploy721TiersHookConfig = RevDeployArgs6[4];

/**
 * A croptop allowed-post configuration: which 721 categories third parties
 * may post to, and at what minimum price/supply.
 */
export type REVCroptopAllowedPost = RevDeployArgs6[5][number];

/**
 * Ruleset `extraMetadata` bit 2: allows `REVDeployer.deploySuckersFor` to extend
 * the revnet to new chains while the stage is active (the deployer checks
 * `(metadata >> 2) & 1`). `extraMetadata` is folded into the revnet's immutable
 * encoded-configuration hash, so a stage without this bit can NEVER be extended —
 * there is no later fix.
 */
export const REV_METADATA_ALLOW_SUCKER_DEPLOYMENT = 1 << 2;

/**
 * Build a `REVStageConfig` (spec-exact encodings, documented per field).
 *
 * ENCODINGS:
 * - `startsAtOrAfter`: ABSOLUTE unix timestamp (uint48), strictly increasing
 *   across stages. For omnichain revnets, compute every stage's start as a
 *   cumulative offset from ONE shared deploy-start timestamp so the stage
 *   list is byte-identical on every chain.
 * - `splitPercent`: the share of issuance routed to splits, out of 10,000
 *   (e.g. 3,800 = 38%).
 * - `splits[].percent`: each split's share of the SPLIT BUCKET (not of total
 *   issuance), out of 1e9; the group must total exactly 1e9 — use
 *   `fillSplitPercents`.
 * - `initialIssuance`: tokens minted per unit of base currency, 18-decimal
 *   fixed point (uint112). The exported `RULESET_WEIGHT_INHERIT` sentinel
 *   (1n) means "inherit the previous stage's issuance with its cuts applied";
 *   zero means genuine zero issuance.
 * - `issuanceCutFrequency`: seconds between issuance cuts (should be >= 1
 *   day; it becomes the stage's ruleset duration).
 * - `issuanceCutPercent`: how much issuance drops each period, out of 1e9
 *   (`MAX_WEIGHT_CUT_PERCENT`; e.g. 20% = 200,000,000).
 * - `cashOutTaxRate`: out of 10,000 (`MAX_CASH_OUT_TAX_RATE`). Any non-zero
 *   rate makes EVERY cash out incur the 2.5% protocol fee; zero-tax cash outs
 *   still pay it on `min(reclaimAmount, feeFreeSurplusOf)`, which is often
 *   but not always zero.
 * - `extraMetadata`: extra metadata bits forwarded to hooks.
 *   {@link REV_METADATA_ALLOW_SUCKER_DEPLOYMENT} (bit 2) is ORed in by default
 *   so the revnet stays extendable to new chains; pass
 *   `allowSuckerDeployment: false` to opt out PERMANENTLY for the stage.
 */
export function buildRevnetStageConfig(args: {
  startsAtOrAfter: number;
  initialIssuance: bigint;
  autoIssuances?: readonly REVAutoIssuance[];
  splitPercent?: number;
  splits?: REVStageConfig["splits"];
  issuanceCutFrequency?: number;
  issuanceCutPercent?: number;
  cashOutTaxRate?: number;
  extraMetadata?: number;
  /**
   * Whether `REVDeployer.deploySuckersFor` may extend the revnet to new chains
   * during this stage. Defaults to TRUE — a stage without the bit is
   * un-extendable forever, since stages are immutable once deployed.
   */
  allowSuckerDeployment?: boolean;
}): REVStageConfig {
  const extraMetadata =
    args.allowSuckerDeployment === false
      ? (args.extraMetadata ?? 0)
      : (args.extraMetadata ?? 0) | REV_METADATA_ALLOW_SUCKER_DEPLOYMENT;
  return {
    startsAtOrAfter: args.startsAtOrAfter,
    autoIssuances: args.autoIssuances ?? [],
    splitPercent: args.splitPercent ?? 0,
    splits: args.splits ?? [],
    initialIssuance: args.initialIssuance,
    issuanceCutFrequency: args.issuanceCutFrequency ?? 0,
    issuanceCutPercent: args.issuanceCutPercent ?? 0,
    cashOutTaxRate: args.cashOutTaxRate ?? 0,
    extraMetadata,
  };
}

/**
 * Build a `REVDeployer.deployFor` transaction request deploying a new revnet
 * (or a 721-shop revnet when `tiered721Config` is given).
 *
 * Deploying a NEW revnet (`revnetId` 0n) is payable and must send EXACTLY the
 * current project creation fee — read it with `getProjectCreationFee` on the
 * same chain. Deploying for an EXISTING project must send no value (the
 * deployer reverts otherwise), so `creationFee` is ignored in that case.
 * For omnichain revnets, send one transaction per chain with an identical
 * `config` (shared description salt, shared absolute stage starts) and a
 * shared sucker salt.
 *
 * @param args.config The revnet configuration; see {@link REVConfig}.
 * @param args.accountingContexts The tokens the revnet accepts as reserves;
 * see `buildAccountingContext`.
 * @param args.suckerConfig Cross-chain sucker configuration (empty
 * `deployerConfigurations` for a single-chain revnet); build with
 * `parseSuckerDeployerConfig(chainId, chainIds, assets, { version: 6 })`.
 * @param args.revnetId The revnet to deploy for. Defaults to 0n (create a
 * NEW revnet).
 * @param args.tiered721Config Optional tiered 721 hook config — switches to
 * the 6-arg overload.
 * @param args.allowedPosts Croptop posting rules (only used with
 * `tiered721Config`). Defaults to none.
 */
export function buildDeployRevnetTx(args: {
  chainId: JBChainId;
  config: REVConfig;
  accountingContexts: readonly JBAccountingContext[];
  suckerConfig: REVSuckerDeploymentConfig;
  creationFee?: bigint;
  revnetId?: bigint;
  tiered721Config?: REVDeploy721TiersHookConfig;
  allowedPosts?: readonly REVCroptopAllowedPost[];
}) {
  const address = v6Address("REVDeployer", args.chainId);
  const revnetId = args.revnetId ?? 0n;

  // An omnichain revnet whose stages lack the sucker-deployment bit can never
  // be extended to new chains (or have failed sucker deploys retried): stages
  // are immutable and `deploySuckersFor` checks the CURRENT stage's bit. Refuse
  // to encode that foot-gun — `buildRevnetStageConfig` sets the bit by default.
  if (args.suckerConfig.deployerConfigurations.length > 0) {
    const blockedStage = args.config.stageConfigurations.findIndex(
      (stage) =>
        (Number(stage.extraMetadata) & REV_METADATA_ALLOW_SUCKER_DEPLOYMENT) ===
        0,
    );
    if (blockedStage !== -1) {
      throw new Error(
        `Stage ${blockedStage} does not set REV_METADATA_ALLOW_SUCKER_DEPLOYMENT ` +
          `(extraMetadata bit 2), so this cross-chain revnet could never deploy ` +
          `suckers during that stage — permanently. Build stages with ` +
          `buildRevnetStageConfig (which sets the bit by default), or OR the bit ` +
          `into extraMetadata.`,
      );
    }
  }

  // The deployer forwards msg.value to `JBProjects.createFor` for new revnets and
  // reverts on any value when initializing an existing project.
  if (revnetId === 0n && args.creationFee === undefined) {
    throw new Error("creationFee is required when deploying a new revnet");
  }
  const value = revnetId === 0n ? (args.creationFee as bigint) : 0n;

  if (args.tiered721Config) {
    return {
      chainId: args.chainId,
      address,
      abi: revDeployerAbi,
      functionName: "deployFor" as const,
      args: [
        revnetId,
        args.config,
        args.accountingContexts,
        args.suckerConfig,
        args.tiered721Config,
        args.allowedPosts ?? [],
      ] as const,
      value,
    };
  }
  return {
    chainId: args.chainId,
    address,
    abi: revDeployerAbi,
    functionName: "deployFor" as const,
    args: [
      revnetId,
      args.config,
      args.accountingContexts,
      args.suckerConfig,
    ] as const,
    value,
  };
}

