const jbSuckerV6WriteAbi = [
  {
    type: "function",
    name: "prepare",
    inputs: [
      { name: "projectTokenCount", type: "uint256", internalType: "uint256" },
      { name: "beneficiary", type: "bytes32", internalType: "bytes32" },
      { name: "minTokensReclaimed", type: "uint256", internalType: "uint256" },
