/**
 * Read a holder's internal token credit balance (unclaimed tokens) via
 * `JBTokens.creditBalanceOf(holder, projectId)`.
 *
 * @param client A viem public client on the given chain.
 * @param args.chainId The chain to read from.
 * @param args.projectId The project's id.
 * @param args.holder The holder to read the credit balance of.
 * @returns The holder's credit balance, as a fixed point number with 18 decimals.
 */
export async function getCreditBalance(
  client: PublicClient,
  {
    chainId,
    projectId,
    holder,
  }: {
    chainId: JBChainId;
    projectId: bigint;
    holder: Address;
  },
): Promise<bigint> {
  return client.readContract({
    address: v6Address("JBTokens", chainId),
    abi: jbTokensAbi,
    functionName: "creditBalanceOf",
    args: [holder, projectId],
  });
}

import { Address } from "viem";
import { jbContractAddress } from "../generated/juicebox.js";
import { JBChainId } from "../types.js";

/**
 * The contracts deployed for Juicebox v6.
 */
export type V6Contract = keyof (typeof jbContractAddress)["6"];

/**
 * The address of a v6 contract on a chain.
 */
export function v6Address(contract: V6Contract, chainId: JBChainId): Address {
  const address = (jbContractAddress["6"][contract] as Record<string, Address>)[
    String(chainId)
  ];
  if (!address) {
    throw new Error(`No v6 ${String(contract)} deployment on chain ${chainId}`);
  }
  return address;
}

