    const ETHERSCAN_V2_API = 'https://api.etherscan.io/v2/api';
    const EXPLORERS = {
      1: { name: 'Etherscan', url: 'https://etherscan.io' },
      11155111: { name: 'Sepolia', url: 'https://sepolia.etherscan.io' },
      10: { name: 'Optimism', url: 'https://optimistic.etherscan.io' },
