    /// @notice Fixed haircut for cold-start bootstrap quotes.
    uint256 internal constant _COLD_START_SPOT_SLIPPAGE = 300;

    /// @notice The TWAP window stored when a pool is REGISTERED with a window of exactly `MAX_TWAP_WINDOW`.
    /// @dev Immutable deployers (e.g. REVDeployer) bake `MAX_TWAP_WINDOW` into every pool registration as a
    /// default rather than a tuning choice, and a max-length TWAP floor systematically lags trending pools —
    /// routing every no-quote pay to the mint fallback during exactly the growth phase where buybacks matter.
    /// The remap applies only at registration time (`initializePoolFor`/`setPoolFor`); `setTwapWindowOf` is an
    /// explicit operator action and always stores the requested window, including `MAX_TWAP_WINDOW` itself.
    /// @dev Internal (no getter) to stay under the EIP-170 size limit; the stored window is always readable via
    /// `twapWindowOf`.
    uint256 internal constant _DEFAULT_TWAP_WINDOW = 30 minutes;

    /// @notice Cold-start spot quotes are capped to 5% estimated impact against live in-range liquidity.
    uint256 internal constant _MAX_COLD_START_SPOT_IMPACT = 50e15;

    /// @notice The maximum estimated price impact accepted for an oracle-derived route. `JBSwapLib` scales impact by
    /// 1e18, so this rejects quotes whose input is at least a full-liquidity impact against the effective pool depth.
    uint256 internal constant _MAX_TWAP_IMPACT = 1e18;

    /// @notice The maximum slippage tolerance returned by `JBSwapLib`. Hitting this means the pool is too thin to
    /// quote safely.
    uint256 internal constant _MAX_TWAP_SLIPPAGE = 8800;

    //*********************************************************************//
    // ----------------- public immutable stored properties --------------- //
    //*********************************************************************//

    /// @notice The directory of terminals and controllers.
    IJBDirectory public immutable override DIRECTORY;

    /// @notice The contract that exposes price feeds.
    IJBPrices public immutable override PRICES;

    /// @notice The project registry.
    IJBProjects public immutable override PROJECTS;

    /// @notice The token registry.
    IJBTokens public immutable override TOKENS;

    //*********************************************************************//
    // -------------- internal immutable stored properties -------------- //
    //*********************************************************************//

    /// @notice Pre-computed metadata ID for the "cashOut" purpose (the cash-out reclaim/skip directive).
    /// @dev Hoisted to an immutable so the string is hashed once at deployment instead of on every
    /// `beforeCashOutRecordedWith` call. Keyed to `address(this)` (the value `getId("cashOut")` resolves to), which is
    /// deterministic under CREATE2 — so this immutable is byte-identical on every chain.
    bytes4 internal immutable _CASH_OUT_ID;

    /// @notice The deployer authorized to set the chain-specific Uniswap V4 PoolManager and oracle hook.
    /// @dev Held as immutable so the constructor inputs are byte-identical on every chain. The chain-specific
    /// Uniswap V4 PoolManager (and the matching oracle hook deployed against it) are set by this
    /// deployer in a one-shot call to `setChainSpecificConstants`. This mirrors the
    /// `JBOptimismSuckerDeployer.setChainSpecificConstants` pattern in nana-suckers-v6, and makes this
    /// contract's CREATE2 address identical across chains.
    address internal immutable _DEPLOYER;

    /// @notice Pre-computed metadata ID for the "pay" purpose (the pay-phase swap quote).
    /// @dev Hoisted to an immutable so the string is hashed once at deployment instead of on every
    /// `beforePayRecordedWith` call. Keyed to `address(this)` (the value `getId("pay")` resolves to), which is
    /// deterministic under CREATE2 — so
    /// this immutable is byte-identical on every chain and does not break the unified address.
    bytes4 internal immutable _PAY_ID;

    //*********************************************************************//
    // --------------------- public stored properties -------------------- //
    //*********************************************************************//

    /// @notice The Uniswap V4 PoolManager singleton. Set once by `_DEPLOYER` after construction via
    /// `setChainSpecificConstants` and never changed thereafter.
    IPoolManager public override poolManager;

    /// @notice The oracle hook used for configured Uniswap V4 pools. Set once by `_DEPLOYER`
    /// after construction via `setChainSpecificConstants` and never changed thereafter.
    IHooks public oracleHook;

    /// @notice The PoolKey for a given project's token and terminal token pair.
    /// @custom:param projectId The ID of the project whose token is traded in the pool.
    /// @custom:param terminalToken The address of the terminal token (normalized to address(0) for native).
    mapping(uint256 projectId => mapping(address terminalToken => PoolKey)) internal _poolKeyOf;

    /// @notice The address of each project's token.
    /// @custom:param projectId The ID of the project the token belongs to.
    mapping(uint256 projectId => address) public override projectTokenOf;

    /// @notice The TWAP window for a given project and terminal token pair.
    /// @custom:param projectId The ID of the project to get the TWAP window for.
    /// @custom:param terminalToken The terminal token address (normalized to address(0) for native).
    mapping(uint256 projectId => mapping(address terminalToken => uint256)) public override twapWindowOf;

