    // -------------------------- internal views ------------------------- //
    //*********************************************************************//

    /// @notice The share of a mint that lands with the beneficiary once the reserved percent is taken out.
    /// @dev Mirrors `JBController`'s split rounding exactly so a payer's minimum settles against the same number the
    /// controller mints.
    /// @param tokenCount The full mint count.
    /// @param reservedPercent The ruleset's reserved percent, out of `JBConstants.MAX_RESERVED_PERCENT`.
    /// @return beneficiaryTokenCount The beneficiary's share of `tokenCount`.
    function _beneficiaryShareOf(
        uint256 tokenCount,
        uint256 reservedPercent
    )
        internal
        pure
        returns (uint256 beneficiaryTokenCount)
    {
        return mulDiv({
            x: tokenCount,
            y: JBConstants.MAX_RESERVED_PERCENT - reservedPercent,
            denominator: JBConstants.MAX_RESERVED_PERCENT
        });
    }

    /// @notice Normalize the terminal token, look up the project token, and construct the PoolKey.
    /// @param projectId The ID of the project.
    /// @param fee The Uniswap V4 pool fee tier.
    /// @param tickSpacing The Uniswap V4 pool tick spacing.
    /// @param terminalToken The terminal token address (may be NATIVE_TOKEN).
    /// @return poolKey The constructed PoolKey.
    /// @return normalizedTerminalToken The terminal token normalized to address(0) for native.
    /// @return projectToken The project's ERC-20 token address.
    function _buildPoolKey(
        uint256 projectId,
        uint24 fee,
        int24 tickSpacing,
        address terminalToken
    )
        internal
        view
        returns (PoolKey memory poolKey, address normalizedTerminalToken, address projectToken)
    {
        // Normalize the terminal token — use address(0) for native.
        normalizedTerminalToken = terminalToken == JBConstants.NATIVE_TOKEN ? address(0) : terminalToken;

        // Get the project's token.
        projectToken = address(TOKENS.tokenOf(projectId));

        // Sort currencies numerically (lower address = currency0).
        (Currency currency0, Currency currency1) = normalizedTerminalToken < projectToken
            ? (Currency.wrap(normalizedTerminalToken), Currency.wrap(projectToken))
            : (Currency.wrap(projectToken), Currency.wrap(normalizedTerminalToken));

        // Construct the pool key with the oracle hook.
        poolKey = PoolKey({
            currency0: currency0, currency1: currency1, fee: fee, tickSpacing: tickSpacing, hooks: oracleHook
        });
    }

    /// @dev `ERC-2771` specifies the context as being a single address (20 bytes).
    function _contextSuffixLength() internal view override(ERC2771Context, Context) returns (uint256) {
        return super._contextSuffixLength();
    }

    /// @notice This contract's balance of a V4 currency (native or ERC-20).
    /// @param currency The V4 currency to read the balance of.
    /// @return The balance held by this contract.
    function _currencyBalanceOf(Currency currency) internal view returns (uint256) {
        return
            currency.isAddressZero()
                ? address(this).balance
                : IERC20(Currency.unwrap(currency)).balanceOf(address(this));
    }

    /// @notice Whether the selected terminal can settle the direct protocol reclaim used in route comparison.
    /// @dev Cash-out pricing can use aggregate surplus, but the selected terminal can only pay from its local surplus.
    /// If the direct path cannot settle locally, a live AMM route must be allowed to win even when the aggregate
    /// direct reclaim is numerically higher.
    /// @param grossDirectCashOutAmount The gross terminal-token reclaim before terminal fees.
    /// @param context The before-cashout context the data hook is processing.
    /// @return True if the selected terminal has enough local surplus to settle the direct reclaim.
    function _directCashOutCanSettle(
        uint256 grossDirectCashOutAmount,
        JBBeforeCashOutRecordedContext calldata context
    )
        internal
        view
        returns (bool)
    {
        // `currentSurplusOf(...)` accepts a token list because terminals can price multiple accounting tokens; this
        // route comparison only needs the token used by the selected cash-out terminal.
        address[] memory tokens = new address[](1);

        // Use the same token, decimals, and currency that core used to price `context.surplus`, so the local
        // settlement check is denominated exactly like the direct reclaim.
        tokens[0] = context.surplus.token;

        // Bind the selected terminal from the context so the surplus read cannot accidentally consult another
        // terminal's accounting context.
        IJBTerminal terminal = IJBTerminal(context.terminal);

        // Read the selected terminal's local surplus. Aggregate or remote surplus can affect the reclaim quote, but
        // this terminal can only pay what its own accounting context currently holds.
        uint256 localSurplus = terminal.currentSurplusOf({
            projectId: context.projectId,
            tokens: tokens,
            decimals: context.surplus.decimals,
            currency: context.surplus.currency
        });

        // Direct cash-out settlement needs the gross reclaim available locally; terminal fees are charged from the
        // payout, but the terminal still has to source the gross amount before fee accounting completes.
        return grossDirectCashOutAmount <= localSurplus;
    }

    /// @notice Queries the TWAP oracle for a price quote and applies sigmoid-based slippage to produce the minimum
    /// acceptable swap output. Returns 0 if the oracle is unavailable or liquidity is insufficient.
    /// @dev A TWAP can remain warm after all in-range liquidity has been removed. Live PoolManager liquidity is
    /// checked separately so an initialized-but-empty pool cannot activate a route that would immediately fail.
    /// @param projectId The ID of the project.
    /// @param amountIn The number of input tokens to swap.
    /// @param baseToken The token to swap in.
    /// @param quoteToken The token to swap out.
    /// @param terminalToken The terminal token address (already normalized: address(0) for native). Passed by the
    /// caller to avoid a redundant `projectTokenOf` SLOAD that would otherwise be needed to derive it.
    /// @param allowColdStartSpotFallback Whether to allow the buy-side, bounded spot fallback when no TWAP exists.
    /// @return rawAmountOut The raw oracle quote before slippage adjustment.
    /// @return amountOut The minimum number of tokens to receive after slippage adjustment.
    /// @return twapTick The arithmetic mean tick from the TWAP oracle.
    /// @return twapLiquidity The harmonic mean liquidity from the TWAP oracle.
    /// @return poolId The V4 pool identifier used for the quote.
    /// @return oracleUnseeded True when the pool has live liquidity but no usable TWAP liquidity.
    function _getQuote(
        uint256 projectId,
        uint256 amountIn,
        address baseToken,
        address quoteToken,
        address terminalToken,
        bool allowColdStartSpotFallback
    )
        internal
        view
        returns (
            uint256 rawAmountOut,
            uint256 amountOut,
            int24 twapTick,
            uint128 twapLiquidity,
            PoolId poolId,
            bool oracleUnseeded
        )
    {
        // Check pool existence before loading the full PoolKey struct (~500 gas saved on early exit).
        if (!_poolIsSet[projectId][terminalToken]) return (0, 0, 0, 0, PoolId.wrap(0), false);

        // Get the pool key for this project/terminal token pair.
        PoolKey memory key = _poolKeyOf[projectId][terminalToken];

        // Get the TWAP window for this project/terminal token pair.
        uint256 twapWindow = twapWindowOf[projectId][terminalToken];

        // Keep a reference to the pool ID.
        poolId = key.toId();

        // If there is no current in-range liquidity, the next swap cannot execute against this pool even if the
        // oracle still has historical observations.
        uint128 currentLiquidity = poolManager.getLiquidity(poolId);
        if (currentLiquidity == 0) return (0, 0, 0, 0, poolId, false);

        // Query the oracle hook (or spot if twapWindow is 0).
        (amountOut, twapTick, twapLiquidity) = JBSwapLib.getQuoteFromOracle({
            poolManager: poolManager,
            key: key,
            // Safe: twapWindow is validated <= MAX_TWAP_WINDOW (2 days = 172800), fits in uint32.
            // forge-lint: disable-next-line(unsafe-typecast)
            twapWindow: uint32(twapWindow),
            // Safe: amountIn is a token payment amount, bounded by realistic token supplies well within uint128.
            // forge-lint: disable-next-line(unsafe-typecast)
            amountIn: uint128(amountIn),
            baseToken: baseToken,
            quoteToken: quoteToken
        });

        bool zeroForOne = baseToken < quoteToken;

        // If there's no TWAP liquidity data, the buy side may use a tightly bounded bootstrap quote. Prefer a valid
        // oracle tick when one exists; raw slot0 is only used for the configured oracle hook when no oracle quote is
        // available. Sell-side quotes stay TWAP-only.
        if (twapLiquidity == 0) {
            // Surface the unseeded-oracle state even when guardrails reject routing, so preview clients can explain why
            // the hook minted instead of swapping.
            oracleUnseeded = true;

            // Cash-outs and explicit diagnostic lookups must not use spot pricing, because spot is manipulable inside
            // one block and is only acceptable for the bounded buy-side bootstrap path.
            if (!allowColdStartSpotFallback) return (0, 0, twapTick, 0, poolId, oracleUnseeded);

            // Raw slot0 is only trusted for pools using this hook's configured oracle hook; an arbitrary pool hook can
            // keep TWAP liquidity at zero forever and would otherwise make spot routing a permanent mode.
            if (address(key.hooks) != address(oracleHook)) return (0, 0, twapTick, 0, poolId, oracleUnseeded);

            // Slot0 supplies the fallback spot tick and the live LP fee. The LP fee is dynamic for some V4 pools, so
            // the pool key's fee field is not sufficient for this guardrail.
            (uint160 spotSqrtP, int24 spotTick,, uint24 spotLpFee) = poolManager.getSlot0(poolId);

            // When the oracle produced no quote, report the spot tick used for the bootstrap quote. If the oracle did
            // produce a mean tick, keep that tick in the diagnostics and avoid raw spot for pricing.
            if (amountOut == 0) twapTick = spotTick;

            // Keep the sqrt price paired with the tick that produced the quote, so the impact estimate and raw quote
            // use the same price source.
            uint160 quoteSqrtP;
            if (amountOut == 0) {
                // A zero sqrt price means slot0 cannot describe an initialized price, so there is no safe spot
                // fallback.
                if (spotSqrtP == 0) return (0, 0, twapTick, 0, poolId, oracleUnseeded);

                // Use live slot0 only when the oracle cannot quote at all.
                quoteSqrtP = spotSqrtP;

                // Build the gross spot quote. The fee and impact haircut is applied below before route comparison.
                rawAmountOut = JBSwapLib.getQuoteAtTick({
                    tick: spotTick,
                    // Safe: amountIn is a token payment amount, bounded by realistic token supplies well within
                    // uint128.
                    // forge-lint: disable-next-line(unsafe-typecast)
                    baseAmount: uint128(amountIn),
                    baseToken: baseToken,
                    quoteToken: quoteToken
                });
            } else {
                // The oracle can return a valid mean tick even when harmonic liquidity is zero. Use that mean tick for
                // pricing because it is harder to manipulate than raw slot0.
                quoteSqrtP = TickMath.getSqrtPriceAtTick(twapTick);

                // Preserve the oracle's gross quote so diagnostics show the quote source used for route selection.
                rawAmountOut = amountOut;
            }

            // Bound the first trade by live in-range liquidity so a tiny seed cannot route a large spot-priced payment.
            uint256 spotImpact = JBSwapLib.calculateImpact({
                amountIn: amountIn, liquidity: currentLiquidity, sqrtP: quoteSqrtP, zeroForOne: zeroForOne
            });

            // Reject quotes whose estimated impact exceeds the cold-start cap; returning zero keeps issuance routing.
            if (spotImpact > _MAX_COLD_START_SPOT_IMPACT) return (0, 0, twapTick, 0, poolId, oracleUnseeded);

            // Discount the gross quote by the fixed haircut, the live LP fee, and rounded-up impact so the route
            // comparison has buffer for the bootstrap swap's execution cost. V4 fees are in hundredths of a bip.
            uint256 coldStartDiscount = _COLD_START_SPOT_SLIPPAGE + uint256(spotLpFee) / 100 + spotImpact / 1e14 + 1;

            // If the live fee and guardrail discount consume the full quote, there is no executable AMM route.
            if (coldStartDiscount >= TWAP_SLIPPAGE_DENOMINATOR) {
                return (0, 0, twapTick, 0, poolId, oracleUnseeded);
            }

            // Return both the raw quote for diagnostics and the discounted quote for the routing comparison.
            amountOut = (rawAmountOut * (TWAP_SLIPPAGE_DENOMINATOR - coldStartDiscount)) / TWAP_SLIPPAGE_DENOMINATOR;
            return (rawAmountOut, amountOut, twapTick, 0, poolId, oracleUnseeded);
        }

        // If oracle returned 0, no quote available — trigger mint fallback.
        if (amountOut == 0) return (0, 0, twapTick, twapLiquidity, poolId, false);

        // Calculate price impact.
        uint160 sqrtP = TickMath.getSqrtPriceAtTick(twapTick);

        // Bound quote confidence by the weaker liquidity source. Historical TWAP liquidity can overstate a drained
        // pool, while live in-range liquidity alone does not prove the oracle window was deep.
        uint128 effectiveLiquidity = currentLiquidity < twapLiquidity ? currentLiquidity : twapLiquidity;

        // Estimate the order's impact against the conservative liquidity bound so thin current or historical liquidity
        // can disable routing before execution.
        uint256 impact = JBSwapLib.calculateImpact({
            amountIn: amountIn, liquidity: effectiveLiquidity, sqrtP: sqrtP, zeroForOne: zeroForOne
        });

        // Treat a max-impact quote as unusable. Returning zero keeps route selection on the protocol path.
        if (impact >= _MAX_TWAP_IMPACT) return (0, 0, twapTick, twapLiquidity, poolId, false);

        // Get the actual LP fee from slot0 (key.fee may differ for dynamic-fee pools).
        // V4 fees are in hundredths of a bip, so divide by 100 to get basis points.
        (,,, uint24 lpFee) = poolManager.getSlot0(poolId);
        uint256 poolFeeBps = uint256(lpFee) / 100;

        // Calculate continuous sigmoid slippage tolerance.
        uint256 slippageTolerance = JBSwapLib.getSlippageTolerance({impact: impact, poolFeeBps: poolFeeBps});

        // If the slippage tolerance is the maximum, return 0 to trigger mint.
        if (slippageTolerance >= _MAX_TWAP_SLIPPAGE) return (0, 0, twapTick, twapLiquidity, poolId, false);

        // Save the raw oracle quote before slippage adjustment.
        rawAmountOut = amountOut;

        // Apply slippage to the oracle quote.
        amountOut -= (amountOut * slippageTolerance) / TWAP_SLIPPAGE_DENOMINATOR;
    }

    /// @notice The calldata. Preferred to use over `msg.data`.
    function _msgData() internal view override(ERC2771Context, Context) returns (bytes calldata) {
        return ERC2771Context._msgData();
    }

    /// @notice The message's sender. Preferred to use over `msg.sender`.
    /// @return sender The address which sent this call.
    function _msgSender() internal view override(ERC2771Context, Context) returns (address sender) {
        return ERC2771Context._msgSender();
    }

    /// @notice The exact net the terminal will settle to the beneficiary after applying its fee policy.
    /// @dev Mirrors `JBMultiTerminal._cashOutTokensOf` fee math: feeless beneficiaries pay nothing; non-zero
    /// tax rate charges the full standard fee on the gross; zero tax rate charges only up to
    /// `feeFreeSurplusOf` (the per-(project, token) round-trip exposure counter the terminal exposes
    /// publicly). The hook reads the counter via the terminal address already present in the context.
    /// @param amount The gross reclaim amount before any terminal fee.
    /// @param context The before-cashout context the data hook is processing.
    /// @return The net the beneficiary will receive (gross minus any applicable terminal fee).
    function _netAfterTerminalFee(
        uint256 amount,
        JBBeforeCashOutRecordedContext calldata context
    )
        internal
        view
        returns (uint256)
    {
        if (context.beneficiaryIsFeeless) return amount;

        uint256 feeBase;
        if (context.cashOutTaxRate != 0) {
            // Non-zero tax: terminal charges the full standard fee on the gross.
            feeBase = amount;
        } else {
            // Zero tax: terminal charges only up to its fee-free surplus for this (project, token).
            uint256 feeFreeSurplus = IJBMultiTerminal(context.terminal)
                .feeFreeSurplusOf({projectId: context.projectId, token: context.surplus.token});
            feeBase = amount < feeFreeSurplus ? amount : feeFreeSurplus;
        }

        return amount - JBFees.standardFeeAmountFrom(feeBase);
    }

    /// @notice Reverts when a settled amount falls short of a caller-specified minimum.
    /// @dev A zero minimum is "no floor". One revert site for every explicit-minimum check keeps the error encoding
    /// out of the bytecode eight times.
    /// @param amount The amount actually settled.
    /// @param minimum The caller's minimum.
    function _requireMinimum(uint256 amount, uint256 minimum) internal pure {
        if (minimum != 0 && amount < minimum) {
            revert JBBuybackHook_SpecifiedSlippageExceeded({amount: amount, minimum: minimum});
        }
    }

    /// @notice Returns this contract's balance of the given terminal token.
    /// @param token The terminal token address (NATIVE_TOKEN for ETH).
    /// @return balance The current balance held by this contract.
    function _terminalTokenBalance(address token) internal view returns (uint256 balance) {
        return token == JBConstants.NATIVE_TOKEN ? address(this).balance : IERC20(token).balanceOf(address(this));
    }
}

