    /// @notice Set up a project's terminals.
    /// @param projectId The ID of the project to set up terminals for.
    /// @param terminalConfigurations The terminals to set up.
    function _configureTerminals(uint256 projectId, JBTerminalConfig[] calldata terminalConfigurations) internal {
        // Initialize an array of terminals to populate.
        IJBTerminal[] memory terminals = new IJBTerminal[](terminalConfigurations.length);

        for (uint256 i; i < terminalConfigurations.length;) {
            // Set the terminal configuration being iterated on.
            JBTerminalConfig memory terminalConfig = terminalConfigurations[i];

            // Add the accounting contexts for the specified tokens.
            terminalConfig.terminal
                .addAccountingContextsFor({
                    projectId: projectId, accountingContexts: terminalConfig.accountingContextsToAccept
                });

            // Add the terminal.
            terminals[i] = terminalConfig.terminal;
            unchecked {
                ++i;
            }
        }

        // Set the terminals in the directory.
        if (terminalConfigurations.length > 0) {
            DIRECTORY.setTerminalsOf({projectId: projectId, terminals: terminals});
        }
    }

    /// @notice Queues one or more rulesets and stores information pertinent to the configuration.
    /// @param projectId The ID of the project to queue rulesets for.
    /// @param rulesetConfigurations The rulesets to queue.
    /// @return rulesetId The ID of the last ruleset that was successfully queued.
    function _queueRulesets(
        uint256 projectId,
        JBRulesetConfig[] calldata rulesetConfigurations
    )
        internal
        returns (uint256 rulesetId)
    {
        for (uint256 i; i < rulesetConfigurations.length;) {
            // Get a reference to the ruleset config being iterated on.
            JBRulesetConfig memory rulesetConfig = rulesetConfigurations[i];

            // Make sure its reserved percent is valid.
            if (rulesetConfig.metadata.reservedPercent > JBConstants.MAX_RESERVED_PERCENT) {
                revert JBController_InvalidReservedPercent({
                    percent: rulesetConfig.metadata.reservedPercent, limit: JBConstants.MAX_RESERVED_PERCENT
                });
            }

            // Make sure its cash out tax rate is valid.
            if (rulesetConfig.metadata.cashOutTaxRate > JBConstants.MAX_CASH_OUT_TAX_RATE) {
                revert JBController_InvalidCashOutTaxRate({
                    rate: rulesetConfig.metadata.cashOutTaxRate, limit: JBConstants.MAX_CASH_OUT_TAX_RATE
                });
            }

            // Queue its ruleset.
            JBRuleset memory ruleset = RULESETS.queueFor({
                projectId: projectId,
                duration: rulesetConfig.duration,
                weight: rulesetConfig.weight,
                weightCutPercent: rulesetConfig.weightCutPercent,
                approvalHook: rulesetConfig.approvalHook,
                metadata: JBRulesetMetadataResolver.packRulesetMetadata(rulesetConfig.metadata),
                mustStartAtOrAfter: rulesetConfig.mustStartAtOrAfter
            });

            // Set its split groups.
            SPLITS.setSplitGroupsOf({
                projectId: projectId, rulesetId: ruleset.id, splitGroups: rulesetConfig.splitGroups
            });

            // Set its fund access limits.
            FUND_ACCESS_LIMITS.setFundAccessLimitsFor({
                projectId: projectId, rulesetId: ruleset.id, fundAccessLimitGroups: rulesetConfig.fundAccessLimitGroups
            });

            // If this is the last configuration being queued, return the ruleset's ID.
            if (i == rulesetConfigurations.length - 1) {
                rulesetId = ruleset.id;
            }
            unchecked {
                ++i;
            }
        }
    }

    /// @notice Send project tokens to a split group.
    /// @dev This is used to send reserved tokens to the reserved token split group.
    /// @param projectId The ID of the project the splits belong to.
    /// @param rulesetId The ID of the split group's ruleset.
    /// @param groupId The ID of the split group.
    /// @param tokenCount The number of tokens to send.
    /// @param token The token to send.
    /// @return leftoverTokenCount If the split percents don't add up to 100%, the leftover amount is returned.
    function _sendReservedTokensToSplitGroupOf(
        uint256 projectId,
        uint256 rulesetId,
        uint256 groupId,
        uint256 tokenCount,
        IJBToken token
    )
        internal
        returns (uint256 leftoverTokenCount)
    {
        // Set the leftover amount to the initial amount.
        leftoverTokenCount = tokenCount;

        // Get a reference to the split group.
        JBSplit[] memory splits = SPLITS.splitsOf({projectId: projectId, rulesetId: rulesetId, groupId: groupId});

        // Keep a reference to the number of splits being iterated on.
        uint256 numberOfSplits = splits.length;

        // Cache _msgSender() before the loop.
        address messageSender = _msgSender();

        // Send the tokens to the splits.
        for (uint256 i; i < numberOfSplits;) {
            // Get a reference to the split being iterated on.
            JBSplit memory split = splits[i];

            // Calculate the amount to send to the split.
            uint256 splitTokenCount =
                mulDiv({x: tokenCount, y: split.percent, denominator: JBConstants.SPLITS_TOTAL_PERCENT});

            // Mints tokens for the split if needed.
            if (splitTokenCount > 0) {
                // 1. If the split has a `hook`, call the hook's `processSplitWith` function.
                // 2. Otherwise, if the split has a `projectId`, try to pay the project using the split's `beneficiary`,
                // or the `_msgSender()` if the split has no beneficiary.
                // 3. Otherwise, if the split has a beneficiary, send the tokens to the split's beneficiary.
                // 4. Otherwise, send the tokens to the `_msgSender()`.

                // If the split has a hook, call its `processSplitWith` function.
                if (split.hook != IJBSplitHook(address(0))) {
                    if (token != IJBToken(address(0))) {
                        // ERC-20: grant the hook an allowance and let it pull tokens via transferFrom.
                        IERC20(address(token)).forceApprove({spender: address(split.hook), value: splitTokenCount});
                    } else {
                        // Credits: send directly — there is no allowance mechanism for credits.
                        TOKENS.transferCreditsFrom({
                            holder: address(this),
                            projectId: projectId,
                            recipient: address(split.hook),
                            count: splitTokenCount
                        });
                    }

                    try split.hook
                        .processSplitWith(
                            JBSplitHookContext({
                                token: address(token),
                                amount: splitTokenCount,
                                decimals: 18, // Hard-coded in `JBTokens`.
                                projectId: projectId,
                                groupId: groupId,
                                split: split
                            })
                        ) {}
                    catch (bytes memory reason) {
                        emit SplitHookReverted({
                            projectId: projectId, hook: address(split.hook), reason: reason, caller: messageSender
                        });
                    }

                    // For ERC-20 tokens, burn any tokens the hook did not consume.
                    if (token != IJBToken(address(0))) {
                        uint256 remaining =
                            IERC20(address(token)).allowance({owner: address(this), spender: address(split.hook)});
                        if (remaining > 0) {
                            IERC20(address(token)).forceApprove({spender: address(split.hook), value: 0});
                            TOKENS.burnFrom({holder: address(this), projectId: projectId, count: remaining});
                        }
                    }
                    // If the split has a project ID, try to pay the project. If that fails, pay the beneficiary.
                } else {
                    // Pay the project using the split's beneficiary if one was provided. Otherwise, use the message
                    // sender.
                    address beneficiary = split.beneficiary != address(0) ? split.beneficiary : messageSender;

                    // Reserved token splits with no project ID mint directly to the beneficiary. A non-zero project ID
                    // takes the "pay another project" path, which treats the reserved tokens as revenue for the
                    // destination project and can mint another batch of tokens according to its ruleset.
                    if (split.projectId != 0) {
                        if (split.projectId == projectId) {
                            // The source project is not a valid destination for the terminal-payment path.
                            // `sendReservedTokensToSplitsOf` clears the pending reserve balance before this helper
                            // runs. Paying those freshly minted reserves into the same project's terminal would book
                            // them as new revenue, mint another batch of tokens, and start the reserve cycle again.
                            revert JBController_ReservedTokenSplitProjectSameAsOwner({projectId: projectId});
                        }

                        // Get a reference to the receiving project's primary payment terminal for the token.
                        IJBTerminal terminal = token == IJBToken(address(0))
                            ? IJBTerminal(address(0))
                            : DIRECTORY.primaryTerminalOf({projectId: split.projectId, token: address(token)});

                        // If the project doesn't have a token, or if the receiving project doesn't have a terminal
                        // which accepts the token, send the tokens to the beneficiary.
                        if (address(token) == address(0) || address(terminal) == address(0)) {
                            // Mint the tokens to the beneficiary.
                            _sendTokens({
                                projectId: projectId, tokenCount: splitTokenCount, recipient: beneficiary, token: token
                            });
                        } else {
                            // Use the `projectId` in the pay metadata.
                            bytes memory metadata = bytes(abi.encodePacked(projectId));

                            // Try to fulfill the payment.
                            try this.executePayReservedTokenToTerminal({
                                projectId: split.projectId,
                                terminal: terminal,
                                token: token,
                                splitTokenCount: splitTokenCount,
                                beneficiary: beneficiary,
                                metadata: metadata
                            }) {}
                            catch (bytes memory reason) {
                                emit ReservedDistributionReverted({
                                    projectId: projectId,
                                    split: split,
                                    tokenCount: splitTokenCount,
                                    reason: reason,
                                    caller: messageSender
                                });

                                // If it fails, transfer the tokens from this contract to the beneficiary.
                                IERC20(address(token)).safeTransfer({to: beneficiary, value: splitTokenCount});
                            }
                        }
                    } else if (beneficiary == address(0xdead)) {
                        // If the split has no project ID, and the beneficiary is 0xdead, burn.
                        TOKENS.burnFrom({holder: address(this), projectId: projectId, count: splitTokenCount});
                    } else {
                        // If the split has no project Id, send to beneficiary.
                        _sendTokens({
                            projectId: projectId, tokenCount: splitTokenCount, recipient: beneficiary, token: token
                        });
                    }
                }

                // Subtract the amount sent from the leftover.
                leftoverTokenCount -= splitTokenCount;
            }

            emit SendReservedTokensToSplit({
                projectId: projectId,
                rulesetId: rulesetId,
                groupId: groupId,
                split: split,
                tokenCount: splitTokenCount,
                caller: messageSender
            });
            unchecked {
                ++i;
            }
        }
    }

    /// @notice Sends pending reserved tokens to the project's reserved token splits.
    /// @dev If the project has no reserved token splits, or if they don't add up to 100%, leftovers go to the owner.
    /// @param projectId The ID of the project to send reserved tokens for.
    /// @return tokenCount The amount of reserved tokens minted and sent.
    function _sendReservedTokensToSplitsOf(uint256 projectId) internal returns (uint256 tokenCount) {
        // Get a reference to the number of tokens that need to be minted.
        tokenCount = pendingReservedTokenBalanceOf[projectId];

        // Revert if there are no pending reserved tokens
        if (tokenCount == 0) revert JBController_NoReservedTokens({projectId: projectId});

        // Get the ruleset to read the reserved percent from.
        JBRuleset memory ruleset = _currentRulesetOf(projectId);

        // Get a reference to the project's owner.
        address owner = _ownerOf(projectId);

        // Reset the pending reserved token balance.
        pendingReservedTokenBalanceOf[projectId] = 0;

        // Mint the tokens to this contract.
        IJBToken token = TOKENS.mintFor({holder: address(this), projectId: projectId, count: tokenCount});

        // Send reserved tokens to splits and get a reference to the amount left after the splits have all been paid.
        uint256 leftoverTokenCount = tokenCount == 0
            ? 0
            : _sendReservedTokensToSplitGroupOf({
                projectId: projectId,
                rulesetId: ruleset.id,
                groupId: JBSplitGroupIds.RESERVED_TOKENS,
                tokenCount: tokenCount,
                token: token
            });

        // Mint any leftover tokens to the project owner.
        if (leftoverTokenCount > 0) {
            _sendTokens({projectId: projectId, tokenCount: leftoverTokenCount, recipient: owner, token: token});
        }

        emit SendReservedTokensToSplits({
            rulesetId: ruleset.id,
            rulesetCycleNumber: ruleset.cycleNumber,
            projectId: projectId,
            owner: owner,
            tokenCount: tokenCount,
            leftoverAmount: leftoverTokenCount,
            caller: _msgSender()
        });
    }

    /// @notice Send tokens from this contract to a recipient.
    /// @param projectId The ID of the project the tokens belong to.
    /// @param tokenCount The number of tokens to send.
    /// @param recipient The address to send the tokens to.
    /// @param token The token to send, if one exists
    function _sendTokens(uint256 projectId, uint256 tokenCount, address recipient, IJBToken token) internal {
        if (token != IJBToken(address(0))) {
            IERC20(address(token)).safeTransfer({to: recipient, value: tokenCount});
        } else {
            TOKENS.transferCreditsFrom({
                holder: address(this), projectId: projectId, recipient: recipient, count: tokenCount
            });
        }
    }

    /// @notice Splits a token count into beneficiary and reserved portions.
    /// @param tokenCount The total token count, including reserved tokens.
    /// @param reservedPercent The reserved percent to apply, out of `JBConstants.MAX_RESERVED_PERCENT`.
    /// @return beneficiaryTokenCount The number of tokens for the beneficiary.
    /// @return reservedTokenCount The number of tokens to reserve.
    function _splitTokenCount(
        uint256 tokenCount,
        uint256 reservedPercent
    )
        internal
        pure
        returns (uint256 beneficiaryTokenCount, uint256 reservedTokenCount)
    {
        // Compute the beneficiary's portion after removing the reserved share.
        beneficiaryTokenCount = mulDiv({
            x: tokenCount,
            y: JBConstants.MAX_RESERVED_PERCENT - reservedPercent,
            denominator: JBConstants.MAX_RESERVED_PERCENT
        });

        // The remaining tokens are reserved.
        reservedTokenCount = tokenCount - beneficiaryTokenCount;
    }

    //*********************************************************************//
    // -------------------------- internal views ------------------------- //
    //*********************************************************************//

    /// @dev `ERC-2771` specifies the context as being a single address (20 bytes).
    function _contextSuffixLength() internal view override(ERC2771Context, Context) returns (uint256) {
        return super._contextSuffixLength();
    }

    /// @notice The project's current ruleset.
    /// @param projectId The ID of the project to check.
    /// @return The project's current ruleset.
    function _currentRulesetOf(uint256 projectId) internal view returns (JBRuleset memory) {
        return RULESETS.currentOf(projectId);
    }

    /// @notice Indicates whether the provided address has mint permission for the project by way of the data hook.
    /// @param projectId The ID of the project to check.
    /// @param ruleset The ruleset to check.
    /// @param addr The address to check.
    /// @return A flag indicating if the provided address has mint permission for the project.
    function _hasDataHookMintPermissionFor(
        uint256 projectId,
        JBRuleset memory ruleset,
        address addr
    )
        internal
        view
        returns (bool)
    {
        address dataHook = ruleset.dataHook();

        return dataHook != address(0)
            && IJBRulesetDataHook(dataHook).hasMintPermissionFor({projectId: projectId, ruleset: ruleset, addr: addr});
    }

    /// @notice Indicates whether the provided address is a terminal for the project.
    /// @param projectId The ID of the project to check.
    /// @param terminal The address to check.
    /// @return A flag indicating if the provided address is a terminal for the project.
    function _isTerminalOf(uint256 projectId, address terminal) internal view returns (bool) {
        return DIRECTORY.isTerminalOf({projectId: projectId, terminal: IJBTerminal(terminal)});
    }

    /// @notice The calldata. Preferred to use over `msg.data`.
    /// @return calldata The `msg.data` of this call.
    function _msgData() internal view override(ERC2771Context, Context) returns (bytes calldata) {
        return ERC2771Context._msgData();
    }

    /// @notice The message's sender. Preferred to use over `msg.sender`.
    /// @return sender The address which sent this call.
    function _msgSender() internal view override(ERC2771Context, Context) returns (address sender) {
        return ERC2771Context._msgSender();
    }

    /// @notice The owner of a project.
    /// @param projectId The ID of the project to get the owner of.
    /// @return The owner of the project.
    function _ownerOf(uint256 projectId) internal view returns (address) {
        return PROJECTS.ownerOf(projectId);
    }

    /// @notice The project's upcoming ruleset.
    /// @param projectId The ID of the project to check.
    /// @return The project's upcoming ruleset.
    function _upcomingRulesetOf(uint256 projectId) internal view returns (JBRuleset memory) {
        return RULESETS.upcomingOf(projectId);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";

import {JBApprovalStatus} from "./enums/JBApprovalStatus.sol";
import {IJBRulesetApprovalHook} from "./interfaces/IJBRulesetApprovalHook.sol";
import {JBRuleset} from "./structs/JBRuleset.sol";

/// @notice A ruleset approval hook that enforces a queuing deadline. If a new ruleset is not queued at least `DURATION`
/// seconds before the current ruleset ends, it is rejected and the existing rules continue. This gives token holders
/// a guaranteed notice period before any project configuration changes take effect.
/// @dev If `DURATION` is set longer than the ruleset's cycle duration, no queued ruleset can ever satisfy the deadline
/// and the current ruleset will effectively be locked in perpetuity. Choose a `DURATION` shorter than the shortest
/// cycle it will govern. A ruleset that currently returns `ApprovalExpected` will become `Approved` once the deadline
/// is reached unless it is replaced first.
contract JBDeadline is IJBRulesetApprovalHook {
    //*********************************************************************//
    // ---------------- public immutable stored properties --------------- //
    //*********************************************************************//

    /// @notice The minimum number of seconds between the time a ruleset is queued and the time it starts. If the
    /// difference is greater than this number, the ruleset is `Approved`.
    uint256 public immutable override DURATION;

    //*********************************************************************//
    // -------------------------- constructor ---------------------------- //
    //*********************************************************************//

    /// @param duration The minimum number of seconds between the time a ruleset is queued and the time it starts for it
    /// to be `Approved`.
    constructor(uint256 duration) {
        DURATION = duration;
    }

    //*********************************************************************//
    // -------------------------- public views --------------------------- //
    //*********************************************************************//

    /// @notice The approval status of a given ruleset.
    /// @param ruleset ruleset to check the status of.
    /// @return The ruleset's approval status.
    function approvalStatusOf(
        uint256, /* projectId */
        JBRuleset memory ruleset
    )
        public
        view
        override
        returns (JBApprovalStatus)
    {
        // The ruleset ID is the timestamp at which the ruleset was queued.
        // If the provided `rulesetId` timestamp is after the start timestamp, the ruleset has `Failed`.
        if (ruleset.id > ruleset.start) return JBApprovalStatus.Failed;

        unchecked {
            // If there aren't enough seconds between the time the ruleset was queued and the time it starts, it has
            // `Failed`.
            // Otherwise, if there is still time before the deadline, the ruleset's status is `ApprovalExpected`.
            // If we've already passed the deadline, the ruleset is `Approved`.
            return (ruleset.start - ruleset.id < DURATION)
                ? JBApprovalStatus.Failed
                // forge-lint: disable-next-line(block-timestamp)
                : (block.timestamp + DURATION < ruleset.start)
                    ? JBApprovalStatus.ApprovalExpected
                    : JBApprovalStatus.Approved;
        }
    }

    /// @notice Indicates whether this contract adheres to the specified interface.
    /// @dev See {IERC165-supportsInterface}.
    /// @param interfaceId The ID of the interface to check for adherence to.
    /// @return A flag indicating if this contract adheres to the specified interface.
    function supportsInterface(bytes4 interfaceId) public view virtual override returns (bool) {
        return interfaceId == type(IJBRulesetApprovalHook).interfaceId || interfaceId == type(IERC165).interfaceId;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {JBPermissionIds} from "@bananapus/permission-ids-v6/src/JBPermissionIds.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";

import {JBPermissioned} from "./abstract/JBPermissioned.sol";
import {IJBDirectory} from "./interfaces/IJBDirectory.sol";
import {IJBDirectoryAccessControl} from "./interfaces/IJBDirectoryAccessControl.sol";
import {IJBMigratable} from "./interfaces/IJBMigratable.sol";
import {IJBPermissions} from "./interfaces/IJBPermissions.sol";
import {IJBProjects} from "./interfaces/IJBProjects.sol";
import {IJBTerminal} from "./interfaces/IJBTerminal.sol";

/// @notice The routing table for the protocol. Every project registers which terminals accept its payments and which
/// controller manages its rulesets and tokens. Frontends and other contracts use the directory to discover where to
/// send funds for a given project and token.
/// @dev Also manages controller migration — when a project upgrades its controller, the directory orchestrates the
/// handoff including `beforeReceiveMigrationFrom`, `migrate`, and `afterReceiveMigrationFrom` lifecycle hooks.
contract JBDirectory is JBPermissioned, Ownable, IJBDirectory {
    //*********************************************************************//
    // --------------------------- custom errors ------------------------- //
    //*********************************************************************//

    /// @notice Thrown when the same terminal appears more than once in the provided terminals list.
    error JBDirectory_DuplicateTerminals(IJBTerminal terminal);

    /// @notice Thrown when the project ID is greater than the number of existing projects.
    error JBDirectory_InvalidProjectIdInDirectory(uint256 projectId, uint256 limit);

    /// @notice Thrown when the project's current controller does not allow setting a new controller.
    error JBDirectory_SetControllerNotAllowed(uint256 projectId);

    /// @notice Thrown when the project's current controller does not allow setting terminals.
    error JBDirectory_SetTerminalsNotAllowed(uint256 projectId);

    /// @notice Thrown when the terminal being set as primary does not accept the given token.
    error JBDirectory_TokenNotAccepted(uint256 projectId, address token, IJBTerminal terminal);

    //*********************************************************************//
    // ---------------- public immutable stored properties --------------- //
    //*********************************************************************//

    /// @notice Mints ERC-721s that represent project ownership and transfers.
    IJBProjects public immutable override PROJECTS;

    //*********************************************************************//
    // --------------------- public stored properties -------------------- //
    //*********************************************************************//

    /// @notice The specified project's controller, which dictates how terminals interact with tokens and rulesets.
    /// @custom:param projectId The ID of the project to get the controller of.
    mapping(uint256 projectId => IERC165) public override controllerOf;

    /// @notice Whether the specified address is allowed to set a project's first controller on their behalf.
    /// @dev These addresses/contracts have been vetted by this contract's owner.
    /// @custom:param addr The address to check.
    mapping(address addr => bool) public override isAllowedToSetFirstController;

    //*********************************************************************//
    // --------------------- internal stored properties ------------------ //
    //*********************************************************************//

    /// @notice The primary terminal that a project uses for the specified token.
    /// @custom:param projectId The ID of the project to get the primary terminal of.
    /// @custom:param token The token that the terminal accepts.
    mapping(uint256 projectId => mapping(address token => IJBTerminal)) internal _primaryTerminalOf;

    /// @notice The specified project's terminals.
    /// @custom:param projectId The ID of the project to get the terminals of.
    mapping(uint256 projectId => IJBTerminal[]) internal _terminalsOf;

    //*********************************************************************//
    // -------------------------- constructor ---------------------------- //
    //*********************************************************************//

    /// @param permissions A contract storing permissions.
    /// @param projects A contract which mints ERC-721s that represent project ownership and transfers.
    /// @param owner The address that will own the contract.
    constructor(
        IJBPermissions permissions,
        IJBProjects projects,
        address owner
    )
        JBPermissioned(permissions)
        Ownable(owner)
    {
        PROJECTS = projects;
    }

    //*********************************************************************//
    // ---------------------- external transactions ---------------------- //
    //*********************************************************************//

    /// @notice Assign a new controller to a project. The controller dictates how the project's terminals interact with
    /// its tokens and rulesets. If the project already has a controller, this triggers a full migration lifecycle
    /// (`beforeReceiveMigrationFrom` → `migrate` → state update → `afterReceiveMigrationFrom`).
    /// @dev Can only be called if:
    /// - The ruleset metadata enables `allowSetController`, and the caller owns the project or has `SET_CONTROLLER`.
    /// - OR the caller `isAllowedToSetFirstController` and the project has no controller yet.
    /// @param projectId The ID of the project to set the controller for.
    /// @param controller The address of the controller to set.
    function setControllerOf(uint256 projectId, IERC165 controller) external override {
        // Keep a reference to the current controller.
        IERC165 currentController = controllerOf[projectId];

        // Enforce permissions.
        _requirePermissionAllowingOverrideFrom({
            account: PROJECTS.ownerOf(projectId),
            projectId: projectId,
            permissionId: JBPermissionIds.SET_CONTROLLER,
            alsoGrantAccessIf: (isAllowedToSetFirstController[msg.sender] && address(currentController) == address(0))
        });

        // The project must exist.
        if (projectId > PROJECTS.count()) revert JBDirectory_InvalidProjectIdInDirectory(projectId, PROJECTS.count());

        // Get a reference to a flag indicating whether the project is allowed to set its controller.
        // Setting the controller is allowed if the project doesn't have a controller,
        // OR if the current controller doesn't enforce access control,
        // OR if the project's ruleset allows setting the controller.
        bool allowSetController = address(currentController) == address(0)
            || !currentController.supportsInterface(type(IJBDirectoryAccessControl).interfaceId)
            ? true
            : IJBDirectoryAccessControl(address(currentController)).setControllerAllowed(projectId);

        // If setting the controller is not allowed, revert.
        if (!allowSetController) {
            revert JBDirectory_SetControllerNotAllowed({projectId: projectId});
        }

        // Prepare the new controller to receive the project.
        if (address(currentController) != address(0) && controller.supportsInterface(type(IJBMigratable).interfaceId)) {
            IJBMigratable(address(controller))
                .beforeReceiveMigrationFrom({from: currentController, projectId: projectId});
        }

        // Migrate if needed. The old controller's migrate() runs while the directory still points to it,
        // closing the reentrancy window where the directory would point to the new controller during migration.
        if (
            address(currentController) != address(0)
                && currentController.supportsInterface(type(IJBMigratable).interfaceId)
        ) {
            IJBMigratable(address(currentController)).migrate({projectId: projectId, to: controller});
        }

        // Set the new controller after migration completes.
        controllerOf[projectId] = controller;

        emit SetController({projectId: projectId, controller: controller, caller: msg.sender});

        // Notify the new controller that migration is complete and it is now the active controller.
        if (address(currentController) != address(0) && controller.supportsInterface(type(IJBMigratable).interfaceId)) {
            IJBMigratable(address(controller))
                .afterReceiveMigrationFrom({from: currentController, projectId: projectId});
        }
    }

    /// @notice Allow or disallow an address to set the first controller for new projects. Typically used to whitelist
    /// deployer contracts (like `JBController`) that set a controller during `launchProjectFor`.
    /// @dev Only this contract's owner can call this function. These addresses are vetted controllers and project
    /// launchers. A project owner can always set their own controller — this list only governs *first* controller
    /// assignment by third parties.
    /// @param addr The address to allow or disallow.
    /// @param flag Whether the address is allowed to set first controllers. `true` to allow, `false` to revoke.
    function setIsAllowedToSetFirstController(address addr, bool flag) external override onlyOwner {
        // Set the flag in the allowlist.
        isAllowedToSetFirstController[addr] = flag;

        emit SetIsAllowedToSetFirstController({addr: addr, isAllowed: flag, caller: msg.sender});
    }

    /// @notice Designate which terminal should receive payments by default when someone pays a project in a specific
    /// token. Useful when a project has multiple terminals that accept the same token.
    /// @dev Can only be called by the project's owner or an address with `SET_PRIMARY_TERMINAL` permission. The
    /// terminal must accept the token for this project. If the terminal isn't already in the project's terminal list,
    /// it will be added automatically (requires `ADD_TERMINALS` permission).
    /// @param projectId The ID of the project to set the primary terminal for.
    /// @param token The token to set the primary terminal for.
    /// @param terminal The terminal to set as the primary terminal.
    function setPrimaryTerminalOf(uint256 projectId, address token, IJBTerminal terminal) external override {
        // Enforce permissions.
        _requirePermissionFrom({
            account: PROJECTS.ownerOf(projectId),
            projectId: projectId,
            permissionId: JBPermissionIds.SET_PRIMARY_TERMINAL
        });

        // If the terminal doesn't accept the token, revert.
        if (terminal.accountingContextForTokenOf({projectId: projectId, token: token}).token == address(0)) {
            revert JBDirectory_TokenNotAccepted({projectId: projectId, token: token, terminal: terminal});
        }

        // If the terminal is not already in the project's terminal list, require ADD_TERMINALS permission.
        if (!isTerminalOf({projectId: projectId, terminal: terminal})) {
            _requirePermissionFrom({
                account: PROJECTS.ownerOf(projectId), projectId: projectId, permissionId: JBPermissionIds.ADD_TERMINALS
            });
        }

        // Implicit terminal addition is by design. A primary terminal must be in the terminals list;
        // implicit addition avoids requiring a separate addTerminalsOf call.
        _addTerminalIfNeeded({projectId: projectId, terminal: terminal});

        // Store the terminal as the project's primary terminal for the token.
        _primaryTerminalOf[projectId][token] = terminal;

        emit SetPrimaryTerminal({projectId: projectId, token: token, terminal: terminal, caller: msg.sender});
    }

    /// @notice Replace a project's entire terminal list. Terminals are the contracts that accept payments and process
    /// cash outs for a project. This overwrites the existing list.
    /// @dev Can only be called by the project's owner, an address with `SET_TERMINALS` permission, or the project's
    /// controller. Unless the caller is the controller, the ruleset must have `allowSetTerminals` enabled.
    /// @param projectId The ID of the project to set terminals for.
    /// @param terminals An array of terminal addresses to set for the project.
    function setTerminalsOf(uint256 projectId, IJBTerminal[] calldata terminals) external override {
        // Cache the controller to avoid redundant storage reads.
        IERC165 controller = controllerOf[projectId];

        // Enforce permissions.
        _requirePermissionAllowingOverrideFrom({
            account: PROJECTS.ownerOf(projectId),
            projectId: projectId,
            permissionId: JBPermissionIds.SET_TERMINALS,
            alsoGrantAccessIf: msg.sender == address(controller)
        });

        // Get a reference to the flag indicating whether the project is allowed to set its terminals.
        bool allowSetTerminals = !controller.supportsInterface(type(IJBDirectoryAccessControl).interfaceId)
            || IJBDirectoryAccessControl(address(controller)).setTerminalsAllowed(projectId);

        // If the caller is not the project's controller, the project's ruleset must allow setting terminals.
        if (msg.sender != address(controller) && !allowSetTerminals) {
            revert JBDirectory_SetTerminalsNotAllowed({projectId: projectId});
        }

        // Set the stored terminals for the project.
        _terminalsOf[projectId] = terminals;

        // If there are any duplicates, revert.
        if (terminals.length > 1) {
            for (uint256 i; i < terminals.length;) {
                for (uint256 j = i + 1; j < terminals.length;) {
                    if (terminals[i] == terminals[j]) revert JBDirectory_DuplicateTerminals(terminals[i]);
                    unchecked {
                        ++j;
                    }
                }
                unchecked {
                    ++i;
                }
            }
        }
        emit SetTerminals({projectId: projectId, terminals: terminals, caller: msg.sender});
    }

    //*********************************************************************//
    // ------------------------- external views -------------------------- //
    //*********************************************************************//

    /// @notice Look up the terminal where payments in a given token should be sent for a project. Returns the
    /// explicitly-set primary terminal, or falls back to the first terminal in the project's list that accepts the
    /// token. Returns the zero address if no terminal accepts the token.
    /// @param projectId The ID of the project to get the primary terminal of.
    /// @param token The token that the terminal accepts.
    /// @return The primary terminal's address.
    function primaryTerminalOf(uint256 projectId, address token) external view override returns (IJBTerminal) {
        // Keep a reference to the primary terminal for the provided project ID and token.
        IJBTerminal primaryTerminal = _primaryTerminalOf[projectId][token];

        // If a primary terminal for the token was explicitly set and it's one of the project's terminals, return it.
        if (
            primaryTerminal != IJBTerminal(address(0))
                && isTerminalOf({projectId: projectId, terminal: primaryTerminal})
        ) {
            return primaryTerminal;
        }

        // Keep a storage reference to the project's terminals to avoid copying the array to memory.
        IJBTerminal[] storage terminals = _terminalsOf[projectId];

        // Keep a reference to the number of terminals the project has.
        uint256 numberOfTerminals = terminals.length;

        // Return the first terminal which accepts the specified token.
        for (uint256 i; i < numberOfTerminals;) {
            // Keep a reference to the terminal being iterated on.
            IJBTerminal terminal = terminals[i];

            // If the terminal accepts the specified token, return it.
            if (terminal.accountingContextForTokenOf({projectId: projectId, token: token}).token != address(0)) {
                return terminal;
            }
            unchecked {
                ++i;
            }
        }

        // Not found.
        return IJBTerminal(address(0));
    }

    /// @notice Get all terminals registered for a project. Terminals are the contracts that hold a project's funds and
    /// process payments and cash outs on its behalf.
    /// @param projectId The ID of the project to get the terminals of.
    /// @return An array of the project's terminal addresses.
    function terminalsOf(uint256 projectId) external view override returns (IJBTerminal[] memory) {
        return _terminalsOf[projectId];
    }

    //*********************************************************************//
    // -------------------------- public views --------------------------- //
    //*********************************************************************//

    /// @notice Check whether a specific terminal is in a project's registered terminal list.
    /// @param projectId The ID of the project to check.
    /// @param terminal The terminal to check for.
    /// @return A flag indicating whether the project uses the terminal.
    function isTerminalOf(uint256 projectId, IJBTerminal terminal) public view override returns (bool) {
        // Keep a storage reference to the project's terminals to avoid copying the array to memory.
        IJBTerminal[] storage terminals = _terminalsOf[projectId];

        // Keep a reference to the number of terminals the project has.
        uint256 numberOfTerminals = terminals.length;

        // Loop through and return true if the terminal is found.
        for (uint256 i; i < numberOfTerminals;) {
            if (terminals[i] == terminal) return true;
            unchecked {
                ++i;
            }
        }

        // Otherwise, return false.
        return false;
    }

    //*********************************************************************//
    // ---------------------- internal transactions ---------------------- //
    //*********************************************************************//

    /// @notice If a terminal hasn't already been added to a project's list of terminals, add it.
    /// @dev The project's ruleset must have `allowSetTerminals` set to `true`.
    /// @param projectId The ID of the project to add the terminal to.
    /// @param terminal The terminal to add.
    function _addTerminalIfNeeded(uint256 projectId, IJBTerminal terminal) internal {
        // Ensure that the terminal has not already been added.
        if (isTerminalOf({projectId: projectId, terminal: terminal})) return;

        // Keep a reference to the current controller.
        IERC165 controller = controllerOf[projectId];

        // Get a reference to a flag indicating whether the project is allowed to set its terminals.
        bool allowSetTerminals = !controller.supportsInterface(type(IJBDirectoryAccessControl).interfaceId)
            || IJBDirectoryAccessControl(address(controller)).setTerminalsAllowed(projectId);

        // The project's ruleset must allow setting terminals.
        if (!allowSetTerminals) {
            revert JBDirectory_SetTerminalsNotAllowed({projectId: projectId});
        }

        // Add the new terminal.
        _terminalsOf[projectId].push(terminal);

        emit AddTerminal({projectId: projectId, terminal: terminal, caller: msg.sender});
    }
}

