    /// @notice Accepts an incoming token.
    /// @param projectId The ID of the project to accept the transfer for.
    /// @param token The token to accept.
    /// @param amount The number of tokens to accept.
    /// @param metadata The metadata in which permit2 context is provided.
    /// @return amount The number of tokens which have been accepted.
    function _acceptFundsFor(
        uint256 projectId,
        address token,
        uint256 amount,
        bytes calldata metadata
    )
        internal
        returns (uint256)
    {
        // Make sure the project has an accounting context for the token being paid.
        _accountingContextOf({projectId: projectId, token: token});

        // If the terminal's token is the native token, override `amount` with `msg.value`.
        if (token == JBConstants.NATIVE_TOKEN) return msg.value;

        // If the terminal's token is not native, revert if there is a non-zero `msg.value`.
        if (msg.value != 0) revert JBMultiTerminal_NoMsgValueAllowed(msg.value);

        // Unpack the allowance to use, if any, given by the frontend.
        (bool exists, bytes memory parsedMetadata) =
            JBMetadataResolver.getDataFor({id: JBMetadataResolver.getId("permit2"), metadata: metadata});

        // Check if the metadata contains permit data.
        if (exists) {
            // Keep a reference to the allowance context parsed from the metadata.
            (JBSingleAllowance memory allowance) = abi.decode(parsedMetadata, (JBSingleAllowance));

            // Make sure the permit allowance is enough for this payment. If not we revert early.
            if (amount > allowance.amount) {
                revert JBMultiTerminal_PermitAllowanceNotEnough({amount: amount, allowance: allowance.amount});
            }

            // Keep a reference to the permit rules.
            IAllowanceTransfer.PermitSingle memory permitSingle = IAllowanceTransfer.PermitSingle({
                details: IAllowanceTransfer.PermitDetails({
                    token: token, amount: allowance.amount, expiration: allowance.expiration, nonce: allowance.nonce
                }),
                spender: address(this),
                sigDeadline: allowance.sigDeadline
            });

            // Set the allowance to `spend` tokens for the user.
            try PERMIT2.permit({owner: _msgSender(), permitSingle: permitSingle, signature: allowance.signature}) {}
            catch (bytes memory reason) {
                emit Permit2AllowanceFailed({token: token, owner: _msgSender(), reason: reason});
            }
        }

        // Get a reference to the balance before receiving tokens.
        uint256 balanceBefore = _balanceOf(token);

        // Prevent callback-capable tokens from nesting another incoming ERC-20 transfer inside this balance-delta
        // measurement.
        if (_acceptingToken) revert JBMultiTerminal_ReentrantTokenTransfer(token);
        _acceptingToken = true;

        // Transfer tokens to this terminal from the msg sender.
        _transferFrom({from: _msgSender(), to: payable(address(this)), token: token, amount: amount});

        // The amount should reflect the change in balance.
        uint256 acceptedAmount = _balanceOf(token) - balanceBefore;

        _acceptingToken = false;

        return acceptedAmount;
    }

    /// @notice Adds funds to a project's balance without minting tokens.
    /// @param projectId The ID of the project to add funds to the balance of.
    /// @param token The address of the token to add to the project's balance.
    /// @param amount The amount of tokens to add as a fixed point number with the same number of decimals as this
    /// terminal. If this is a native token terminal, this is ignored and `msg.value` is used instead.
    /// @param shouldReturnHeldFees If true, return held fees proportional to the amount added.
    /// @param memo A memo to pass along to the emitted event.
    /// @param metadata Extra data to pass along to the emitted event.
    function _addToBalanceOf(
        uint256 projectId,
        address token,
        uint256 amount,
        bool shouldReturnHeldFees,
        string memory memo,
        bytes memory metadata
    )
        internal
    {
        // Return held fees if desired. This mechanism means projects don't pay fees multiple times when funds go out of
        // and back into the protocol.
        uint256 returnedFees =
            shouldReturnHeldFees ? _returnHeldFees({projectId: projectId, token: token, amount: amount}) : 0;

        emit AddToBalance({
            projectId: projectId,
            amount: amount,
            returnedFees: returnedFees,
            memo: memo,
            metadata: metadata,
            caller: _msgSender()
        });

        // Record the added funds with any returned fees.
        _recordAddedBalanceFor({projectId: projectId, token: token, amount: amount + returnedFees});
    }

    /// @notice Logic to be triggered before transferring tokens from this terminal.
    /// @param to The address the transfer is going to.
    /// @param token The token to transfer.
    /// @param amount The number of tokens to transfer, as a fixed point number with the same number of decimals
    /// as this terminal.
    /// @return payValue The value to attach to the transaction.
    function _beforeTransferTo(address to, address token, uint256 amount) internal returns (uint256) {
        // If the token is the native token, no allowance needed, and the full amount should be used as the payValue.
        if (token == JBConstants.NATIVE_TOKEN) return amount;

        // Otherwise, set the allowance, and the payValue should be 0.
        IERC20(token).forceApprove({spender: to, value: amount});
        return 0;
    }

    /// @notice Cap fee-free surplus at the project's remaining balance after an outflow.
    /// @dev Non-fee-free funds are considered to leave first. Fee-free surplus only decreases when the remaining
    /// balance can no longer support it. This prevents attackers from using outflows to drain the fee-free counter
    /// and then cashing out without incurring fees.
    /// @param projectId The ID of the project.
    /// @param token The token whose fee-free surplus to cap.
    function _capFeeFreeSurplus(uint256 projectId, address token) internal {
        // Get the current fee-free surplus for this project/token pair.
        uint256 feeFreeSurplus = feeFreeSurplusOf[projectId][token];

        // Nothing to cap if there's no fee-free surplus tracked.
        if (feeFreeSurplus == 0) return;

        // Get the project's remaining balance (already decremented by the store's record call).
        uint256 remainingBalance = STORE.balanceOf({terminal: address(this), projectId: projectId, token: token});

        // Cap fee-free surplus at the remaining balance.
        if (feeFreeSurplus > remainingBalance) {
            feeFreeSurplusOf[projectId][token] = remainingBalance;
        }
    }

    /// @notice Holders can cash out their tokens to reclaim some of a project's surplus, or to trigger rules
    /// determined by the project's current ruleset's data hook.
    /// @dev Only a token holder or an operator with the `CASH_OUT_TOKENS` permission from that holder can cash out
    /// those tokens.
    /// @param holder The account cashing out tokens.
    /// @param projectId The ID of the project cashing out tokens.
    /// @param cashOutCount The number of project tokens to cash out, as a fixed point number with 18 decimals.
    /// @param tokenToReclaim The address of the token to reclaim.
    /// @param beneficiary The address to send the reclaimed terminal tokens to.
    /// @param metadata Bytes to send to the emitted event, data hook, and cash out hook, if applicable.
    /// @return reclaimAmount The number of terminal tokens reclaimed for the `beneficiary`, as a fixed point number
    /// with 18 decimals.
    function _cashOutTokensOf(
        address holder,
        uint256 projectId,
        uint256 cashOutCount,
        address tokenToReclaim,
        address payable beneficiary,
        bytes memory metadata
    )
        internal
        returns (uint256 reclaimAmount)
    {
        // Keep a reference to the ruleset the cash out is being made during.
        JBRuleset memory ruleset;

        // Keep a reference to the cash out hook specifications.
        JBCashOutHookSpecification[] memory hookSpecifications;

        // Keep a reference to the cash out tax rate being used.
        uint256 cashOutTaxRate;

        // Cache whether the beneficiary is feeless.
        bool beneficiaryIsFeeless = _isFeeless({addr: beneficiary, projectId: projectId});

        // Record the cash out.
        (ruleset, reclaimAmount, cashOutTaxRate, hookSpecifications) = STORE.recordCashOutFor({
            holder: holder,
            projectId: projectId,
            cashOutCount: cashOutCount,
            tokenToReclaim: tokenToReclaim,
            beneficiaryIsFeeless: beneficiaryIsFeeless,
            metadata: metadata
        });

        // Burn the project tokens. The controller is only needed for this burn, so it is fetched once and only when
        // there are tokens to burn.
        if (cashOutCount != 0) {
            _controllerOf(projectId)
                .burnTokensOf({holder: holder, projectId: projectId, tokenCount: cashOutCount, memo: ""});
        }

        // Keep a reference to the amount being reclaimed that is subject to fees.
        uint256 amountEligibleForFees;

        // Send the reclaimed funds to the beneficiary.
        if (reclaimAmount != 0) {
            // Determine if a fee should be taken. Fees are not taken if the beneficiary is feeless.
            if (!beneficiaryIsFeeless) {
                if (cashOutTaxRate != 0) {
                    // Non-zero tax: fees apply to the full reclaim amount.
                    amountEligibleForFees += reclaimAmount;
                    unchecked {
                        reclaimAmount -= _feeAmountFrom(reclaimAmount);
                    }
                } else {
                    // Zero tax: fees apply only up to the fee-free surplus (round-trip prevention).
                    uint256 feeFreeSurplus = feeFreeSurplusOf[projectId][tokenToReclaim];
                    if (feeFreeSurplus != 0) {
                        uint256 feeableAmount = reclaimAmount < feeFreeSurplus ? reclaimAmount : feeFreeSurplus;
                        unchecked {
                            feeFreeSurplusOf[projectId][tokenToReclaim] = feeFreeSurplus - feeableAmount;
                        }
                        amountEligibleForFees += feeableAmount;
                        unchecked {
                            reclaimAmount -= _feeAmountFrom(feeableAmount);
                        }
                    }
                }
            }

            // Subtract the fee from the reclaim amount.
            if (reclaimAmount != 0) {
                _transferFrom({from: address(this), to: beneficiary, token: tokenToReclaim, amount: reclaimAmount});
            }
        }

        // If the data hook returned cash out hook specifications, fulfill them.
        if (hookSpecifications.length != 0) {
            // Fulfill the cash out hook specifications.
            amountEligibleForFees += _fulfillCashOutHookSpecificationsFor({
                projectId: projectId,
                holder: holder,
                cashOutCount: cashOutCount,
                ruleset: ruleset,
                cashOutTaxRate: cashOutTaxRate,
                beneficiary: beneficiary,
                beneficiaryReclaimAmount: _tokenAmountOf({
                    projectId: projectId, token: tokenToReclaim, value: reclaimAmount
                }),
                specifications: hookSpecifications,
                metadata: metadata
            });
        }

        // Cap fee-free surplus after every cash-out path so stale `feeFreeSurplusOf` cannot survive after
        // associated surplus leaves. Do this after hook fulfillment so hook-driven balance reductions are included.
        _capFeeFreeSurplus({projectId: projectId, token: tokenToReclaim});

        // Take the fee from all outbound reclaimings.
        if (amountEligibleForFees != 0) {
            _takeFeeFrom({
                projectId: projectId,
                token: tokenToReclaim,
                amount: amountEligibleForFees,
                beneficiary: beneficiary,
                shouldHoldFees: false
            });
        }

        emit CashOutTokens({
            rulesetId: ruleset.id,
            rulesetCycleNumber: ruleset.cycleNumber,
            projectId: projectId,
            holder: holder,
            beneficiary: beneficiary,
            cashOutCount: cashOutCount,
            cashOutTaxRate: cashOutTaxRate,
            reclaimAmount: reclaimAmount,
            metadata: metadata,
            caller: _msgSender()
        });
    }

    /// @notice Revert if a value is less than the specified minimum.
    /// @param value The value to compare against the minimum.
    /// @param min The minimum acceptable value.
    function _checkMin(uint256 value, uint256 min) internal pure {
        if (value < min) revert JBMultiTerminal_UnderMin(value, min);
    }

    /// @notice Fund a project either by calling this terminal's internal `addToBalance` function or by calling the
    /// recipient terminal's `addToBalance` function.
    /// @param terminal The terminal on which the project is expecting to receive funds.
    /// @param projectId The ID of the project to fund.
    /// @param token The token to use.
    /// @param amount The amount to fund, as a fixed point number with the amount of decimals that the terminal's
    /// accounting context specifies.
    /// @param metadata Additional metadata to include with the payment.
    function _efficientAddToBalance(
        IJBTerminal terminal,
        uint256 projectId,
        address token,
        uint256 amount,
        bytes memory metadata
    )
        internal
    {
        // Use the local internal path when staying on this terminal. Otherwise use the efficient external equivalent,
        // which forwards value directly after granting a temporary pull allowance.
        if (terminal == IJBTerminal(address(this))) {
            _addToBalanceOf({
                projectId: projectId,
                token: token,
                amount: amount,
                shouldReturnHeldFees: false,
                memo: "",
                metadata: metadata
            });
        } else {
            _externalAddToBalance({
                terminal: terminal, projectId: projectId, token: token, amount: amount, metadata: metadata
            });
        }
    }

    /// @notice Pay a project either by calling this terminal's internal `pay` function or by calling the recipient
    /// terminal's `pay` function.
    /// @param terminal The terminal on which the project is expecting to receive payments.
    /// @param projectId The ID of the project to pay.
    /// @param token The token to pay with.
    /// @param amount The amount to pay, as a fixed point number with the amount of decimals that the terminal's
    /// accounting context specifies.
    /// @param beneficiary The address to receive any platform tokens minted.
    /// @param metadata Additional metadata to include with the payment.
    function _efficientPay(
        IJBTerminal terminal,
        uint256 projectId,
        address token,
        uint256 amount,
        address beneficiary,
        bytes memory metadata
    )
        internal
    {
        if (terminal == IJBTerminal(address(this))) {
            _pay({
                projectId: projectId,
                token: token,
                amount: amount,
                payer: address(this),
                beneficiary: beneficiary,
                memo: "",
                metadata: metadata
            });
        } else {
            // Trigger any inherited pre-transfer logic.
            // Keep a reference to the amount that'll be paid as a `msg.value`.
            uint256 payValue = _beforeTransferTo({to: address(terminal), token: token, amount: amount});

            // Send the fee.
            // If this terminal's token is ETH, send it in msg.value.
            terminal.pay{value: payValue}({
                projectId: projectId,
                token: token,
                amount: amount,
                beneficiary: beneficiary,
                minReturnedTokens: 0,
                memo: "",
                metadata: metadata
            });

            // Revoke the temporary pull allowance now that the recipient terminal call has finished.
            _afterTransferTo({to: address(terminal), token: token});
        }
    }

    /// @notice Emits a `Pay` event. Extracted from `_pay` so the 9-field event payload gets its own stack frame —
    /// inlining the emit into `_pay` overflows the non-IR build's stack budget.
    function _emitPay(
        JBRuleset memory ruleset,
        uint256 projectId,
        address payer,
        address beneficiary,
        uint256 amount,
        uint256 newlyIssuedTokenCount,
        string memory memo,
        bytes memory metadata
    )
        internal
    {
        emit Pay({
            rulesetId: ruleset.id,
            rulesetCycleNumber: ruleset.cycleNumber,
            projectId: projectId,
            payer: payer,
            beneficiary: beneficiary,
            amount: amount,
            newlyIssuedTokenCount: newlyIssuedTokenCount,
            memo: memo,
            metadata: metadata,
            caller: _msgSender()
        });
    }

    /// @notice Fund a project on another terminal by granting a temporary pull allowance for this call only.
    /// @param terminal The recipient terminal.
    /// @param projectId The ID of the project to fund.
    /// @param token The token to use.
    /// @param amount The amount to fund.
    /// @param metadata Additional metadata to include with the payment.
    function _externalAddToBalance(
        IJBTerminal terminal,
        uint256 projectId,
        address token,
        uint256 amount,
        bytes memory metadata
    )
        internal
    {
        // Trigger any inherited pre-transfer logic.
        // Keep a reference to the amount that'll be paid as a `msg.value`.
        uint256 payValue = _beforeTransferTo({to: address(terminal), token: token, amount: amount});

        // Add to balance on the recipient terminal.
        // If this terminal's token is the native token, send it in `msg.value`.
        terminal.addToBalanceOf{value: payValue}({
            projectId: projectId,
            token: token,
            amount: amount,
            shouldReturnHeldFees: false,
            memo: "",
            metadata: metadata
        });

        // Revoke the temporary pull allowance now that the recipient terminal call has finished.
        _afterTransferTo({to: address(terminal), token: token});
    }

    /// @notice Fulfills a list of cash out hook specifications.
    /// @param projectId The ID of the project to cash out from.
    /// @param beneficiaryReclaimAmount The number of tokens to cash out from the project.
    /// @param holder The address holding the tokens to cash out.
    /// @param cashOutCount The number of tokens to cash out.
    /// @param metadata Bytes to send along to the emitted event and cash out hooks as applicable.
    /// @param ruleset The ruleset active during this cash out as a `JBRuleset` struct.
    /// @param cashOutTaxRate The cash out tax rate influencing the reclaim amount, out of
    /// `JBConstants.MAX_CASH_OUT_TAX_RATE`.
    /// @param beneficiary The address which will receive any cashed out terminal tokens.
    /// @param specifications The hook specifications to fulfill.
    /// @return amountEligibleForFees The amount of funds which were allocated to cash out hooks and are eligible for
    /// fees.
    function _fulfillCashOutHookSpecificationsFor(
        uint256 projectId,
        JBTokenAmount memory beneficiaryReclaimAmount,
        address holder,
        uint256 cashOutCount,
        bytes memory metadata,
        JBRuleset memory ruleset,
        uint256 cashOutTaxRate,
        address payable beneficiary,
        JBCashOutHookSpecification[] memory specifications
    )
        internal
        returns (uint256 amountEligibleForFees)
    {
        // Keep a reference to cash out context for the cash out hooks.
        JBAfterCashOutRecordedContext memory context = JBAfterCashOutRecordedContext({
            holder: holder,
            projectId: projectId,
            rulesetId: ruleset.id,
            cashOutCount: cashOutCount,
            reclaimedAmount: beneficiaryReclaimAmount,
            forwardedAmount: beneficiaryReclaimAmount,
            cashOutTaxRate: cashOutTaxRate,
            beneficiary: beneficiary,
            hookMetadata: "",
            cashOutMetadata: metadata
        });

        for (uint256 i; i < specifications.length;) {
            // Set the specification being iterated on.
            JBCashOutHookSpecification memory specification = specifications[i];

            // A noop specification is informational only and doesn't trigger the hook.
            if (specification.noop) {
                unchecked {
                    ++i;
                }
                continue;
            }

            // Cash-out hooks receive the net amount after the standard fee unless the hook is feeless.
            uint256 specificationAmountFee = _isFeeless({addr: address(specification.hook), projectId: projectId})
                ? 0
                : _feeAmountFrom(specification.amount);

            // Add the specification's amount to the amount eligible for fees.
            if (specificationAmountFee != 0) {
                amountEligibleForFees += specification.amount;
                specification.amount -= specificationAmountFee;
            }

            // Pass the correct token `forwardedAmount` to the hook.
            context.forwardedAmount = JBTokenAmount({
                value: specification.amount,
                token: beneficiaryReclaimAmount.token,
                decimals: beneficiaryReclaimAmount.decimals,
                currency: beneficiaryReclaimAmount.currency
            });

            // Pass the correct metadata from the data hook's specification.
            context.hookMetadata = specification.metadata;

            // Trigger any inherited pre-transfer logic.
            // Keep a reference to the amount that'll be paid as a `msg.value`.
            uint256 payValue = _beforeTransferTo({
                to: address(specification.hook), token: beneficiaryReclaimAmount.token, amount: specification.amount
            });

            // Fulfill the specification.
            specification.hook.afterCashOutRecordedWith{value: payValue}(context);

            // Revoke the temporary pull allowance now that the hook call has finished.
            _afterTransferTo({to: address(specification.hook), token: beneficiaryReclaimAmount.token});

            emit HookAfterRecordCashOut({
                hook: specification.hook,
                context: context,
                specificationAmount: specification.amount,
                fee: specificationAmountFee,
                caller: _msgSender()
            });
            unchecked {
                ++i;
            }
        }
    }

    /// @notice Fulfills a list of pay hook specifications.
    /// @param projectId The ID of the project to pay.
    /// @param specifications The pay hook specifications to be fulfilled.
    /// @param tokenAmount The amount of tokens that the project was paid.
    /// @param payer The address that sent the payment.
    /// @param ruleset The ruleset active during this payment.
    /// @param beneficiary The address which will receive any tokens that the payment yields.
    /// @param newlyIssuedTokenCount The number of tokens issued and sent to the beneficiary.
    /// @param metadata Bytes to send along to the emitted event and pay hooks as applicable.
    /// @param internalSplitPayProjectId The source project when this payment came from a same-terminal split.
    function _fulfillPayHookSpecificationsFor(
        uint256 projectId,
        JBPayHookSpecification[] memory specifications,
        JBTokenAmount memory tokenAmount,
        address payer,
        JBRuleset memory ruleset,
        address beneficiary,
        uint256 newlyIssuedTokenCount,
        bytes memory metadata,
        uint256 internalSplitPayProjectId
    )
        internal
    {
        uint256 amountEligibleForFees;

        // Keep a reference to payment context for the pay hooks.
        JBAfterPayRecordedContext memory context = JBAfterPayRecordedContext({
            payer: payer,
            projectId: projectId,
            rulesetId: ruleset.id,
            amount: tokenAmount,
            forwardedAmount: tokenAmount,
            weight: ruleset.weight,
            newlyIssuedTokenCount: newlyIssuedTokenCount,
            beneficiary: beneficiary,
            hookMetadata: bytes(""),
            payerMetadata: metadata
        });

        // Fulfill each specification through their pay hooks.
        for (uint256 i; i < specifications.length;) {
            // Set the specification being iterated on.
            JBPayHookSpecification memory specification = specifications[i];

            // A noop specification is informational only and doesn't trigger the hook.
            if (specification.noop) {
                unchecked {
                    ++i;
                }
                continue;
            }

            uint256 specificationAmount = specification.amount;

            if (
                internalSplitPayProjectId != 0
                    && !_isFeeless({addr: address(specification.hook), projectId: internalSplitPayProjectId})
            ) {
                // Same-terminal split pays defer source-side fees until the destination data hook is known. Net
                // non-feeless hook forwards here so they match ordinary payout semantics before funds leave.
                // Keep the fee basis local until every hook returns. Writing the transient accumulator before the
                // hook call would let a reentrant payout overwrite the outer split's pending fee basis.
                unchecked {
                    amountEligibleForFees += specificationAmount;
                    specificationAmount -= _feeAmountFrom(specificationAmount);
                }
            }

            // Pass the correct token `forwardedAmount` to the hook.
            context.forwardedAmount = JBTokenAmount({
                value: specificationAmount,
                token: tokenAmount.token,
                decimals: tokenAmount.decimals,
                currency: tokenAmount.currency
            });

            // Pass the correct metadata from the data hook's specification.
            context.hookMetadata = specification.metadata;

            // Trigger any inherited pre-transfer logic.
            // Keep a reference to the amount that'll be paid as a `msg.value`.
            uint256 payValue = _beforeTransferTo({
                to: address(specification.hook), token: tokenAmount.token, amount: specificationAmount
            });

            // Fulfill the specification.
            specification.hook.afterPayRecordedWith{value: payValue}(context);

            // Revoke the temporary pull allowance now that the hook call has finished.
            _afterTransferTo({to: address(specification.hook), token: tokenAmount.token});

            emit HookAfterRecordPay({
                hook: specification.hook,
                context: context,
                specificationAmount: specificationAmount,
                caller: _msgSender()
            });
            unchecked {
                ++i;
            }
        }

        // `_pay` consumed and cleared the source project ID before calling hooks, so the transient slot can now carry
        // the hook-derived fee basis back to `executePayout`. Publish it only after all untrusted hook calls return.
        _internalSplitPayProjectId = amountEligibleForFees;
    }

    /// @notice Internal implementation of payment logic. Records the payment in the store, mints tokens via the
    /// controller, and fulfills any pay hook specifications from the data hook.
    /// @param projectId The ID of the project to pay.
    /// @param token The address of the token to pay the project with.
    /// @param amount The amount of tokens to send, as a fixed point number with the same number of
    /// decimals as the token's accounting context. If this terminal's token is the native token, `amount` is ignored
    /// and `msg.value` is used in its place.
    /// @param payer The address making the payment.
    /// @param beneficiary The token recipient passed to the ruleset's data hook and pay hook, if applicable.
    /// @param memo A memo to pass along to the emitted event.
    /// @param metadata Bytes to send along to the emitted event, as well as the data hook and pay hook if applicable.
    function _pay(
        uint256 projectId,
        address token,
        uint256 amount,
        address payer,
        address beneficiary,
        string memory memo,
        bytes memory metadata
    )
        internal
    {
        // Same-terminal split pays are the only inbound pays whose source-side fee was intentionally deferred. Cache
        // and clear the transient source project before untrusted data/pay hooks can reenter ordinary pay flows.
        uint256 internalSplitPayProjectId = _internalSplitPayProjectId;
        if (internalSplitPayProjectId != 0) delete _internalSplitPayProjectId;

        // Keep a reference to the token amount to forward to the store.
        JBTokenAmount memory tokenAmount = _tokenAmountOf({projectId: projectId, token: token, value: amount});

        // Record the payment.
        // Keep a reference to the ruleset the payment is being made during.
        // Keep a reference to the pay hook specifications.
        // Keep a reference to the token count that'll be minted as a result of the payment.
        (JBRuleset memory ruleset, uint256 tokenCount, JBPayHookSpecification[] memory hookSpecifications) = STORE.recordPaymentFrom({
            payer: payer, amount: tokenAmount, projectId: projectId, beneficiary: beneficiary, metadata: metadata
        });

        // Only the value retained in the destination balance needs later cashout fee recovery. Non-feeless pay-hook
        // forwards pay their source-equivalent fee inline before leaving the project.
        if (internalSplitPayProjectId != 0) {
            uint256 feeFreeAmount = tokenAmount.value;
            for (uint256 i; i < hookSpecifications.length;) {
                // The store already proved the hook-spec total does not exceed the pay amount.
                unchecked {
                    feeFreeAmount -= hookSpecifications[i].amount;
                    ++i;
                }
            }
            feeFreeSurplusOf[projectId][token] += feeFreeAmount;
        }

        // Keep a reference to the number of tokens issued for the beneficiary.
        uint256 newlyIssuedTokenCount;

        // Mint tokens if needed.
        if (tokenCount != 0) {
            // Set the token count to be the number of tokens minted for the beneficiary instead of the total
            // amount.
            newlyIssuedTokenCount = _controllerOf(projectId)
                .mintTokensOf({
                projectId: projectId,
                tokenCount: tokenCount,
                beneficiary: beneficiary,
                memo: "",
                useReservedPercent: true
            });
        }

        // `_pay` already carries ~10 locals (ruleset, tokenCount, hookSpecifications, balanceDiff, tokenAmount,
        // newlyIssuedTokenCount, internalSplitPayProjectId, feeFreeAmount, plus loop-local `i` and `hookAmount`).
        // Inlining the 9-arg `emit Pay` here hits "Stack too deep" under the non-IR build, so the emit is extracted
        // to `_emitPay` which gets its own stack frame.
        _emitPay({
            ruleset: ruleset,
            projectId: projectId,
            payer: payer,
            beneficiary: beneficiary,
            amount: amount,
            newlyIssuedTokenCount: newlyIssuedTokenCount,
            memo: memo,
            metadata: metadata
        });

        // If the data hook returned pay hook specifications, fulfill them.
        if (hookSpecifications.length != 0) {
            _fulfillPayHookSpecificationsFor({
                projectId: projectId,
                specifications: hookSpecifications,
                tokenAmount: tokenAmount,
                payer: payer,
                ruleset: ruleset,
                beneficiary: beneficiary,
                newlyIssuedTokenCount: newlyIssuedTokenCount,
                metadata: metadata,
                internalSplitPayProjectId: internalSplitPayProjectId
            });
        }
    }

    /// @notice Process a fee of the specified amount from a project.
    /// @param projectId The ID of the project paying the fee.
    /// @param token The token the fee is paid in.
    /// @param amount The fee amount, as a fixed point number with 18 decimals.
    /// @param beneficiary The address which will receive any platform tokens minted.
    /// @param feeTerminal The terminal that'll receive the fee.
    /// @param wasHeld A flag indicating if the fee to process was held by this terminal.
    /// @dev Fee-route failures are forgiven instead of reverted so project funds cannot be trapped by project #1
    /// misconfiguration. The failed fee amount is credited back to the payer project's balance on this terminal.
    function _processFee(
        uint256 projectId,
        address token,
        uint256 amount,
        address beneficiary,
        IJBTerminal feeTerminal,
        bool wasHeld
    )
        internal
    {
        try this.executeProcessFee({
            projectId: projectId, token: token, amount: amount, beneficiary: beneficiary, feeTerminal: feeTerminal
        }) {
            emit ProcessFee({
                projectId: projectId,
                token: token,
                amount: amount,
                wasHeld: wasHeld,
                beneficiary: beneficiary,
                caller: _msgSender()
            });
        } catch (bytes memory reason) {
            // Fee processing is fail-open for project liveness: a broken project #1 terminal or fee route must not
            // trap payouts, cash outs, allowances, held-fee processing, or terminal migration. The fee is forgiven,
            // credited back to the originating project on this terminal, and surfaced through `FeeReverted`.
            emit FeeReverted({
                projectId: projectId,
                token: token,
                feeProjectId: JBConstants.FEE_BENEFICIARY_PROJECT_ID,
                amount: amount,
                reason: reason,
                caller: _msgSender()
            });

            _recordAddedBalanceFor({projectId: projectId, token: token, amount: amount});
            // The store balance was credited first; this mirrors that bounded increase for fee recovery.
            unchecked {
                feeFreeSurplusOf[projectId][token] += amount;
            }
        }
    }

    /// @notice Records an added balance for a project.
    /// @param projectId The ID of the project to record the added balance for.
    /// @param token The token to record the added balance for.
    /// @param amount The amount of the token to record, as a fixed point number with the same number of decimals as
    /// this terminal.
    function _recordAddedBalanceFor(uint256 projectId, address token, uint256 amount) private {
        STORE.recordAddedBalanceFor({projectId: projectId, token: token, amount: amount});
    }

    /// @notice Returns held fees to the project that paid them based on the specified amount.
    /// @dev Partial replenishments use the raw floor calculation so repaying a dust amount cannot both credit the
    /// payer project and leave the fee project owed the 1-unit minimum fee.
    /// @param projectId The project to return held fees to.
    /// @param token The token that the held fees are in.
    /// @param amount The amount to base the calculation on, as a fixed point number with the same number of decimals
    /// as the token's accounting context.
    /// @return returnedFees The amount of held fees that were returned, as a fixed point number with the same number of
    /// decimals as the token's accounting context.
    function _returnHeldFees(uint256 projectId, address token, uint256 amount) internal returns (uint256) {
        return JBHeldFees.returnHeldFees({
            heldFeesOf: _heldFeesOf,
            nextHeldFeeIndexOf: _nextHeldFeeIndexOf,
            projectId: projectId,
            token: token,
            amount: amount,
            caller: _msgSender()
        });
    }

    /// @notice Sends payouts to a project's payout split group using the specified ruleset.
    /// @param projectId The ID of the project to send the payouts of.
    /// @param token The token to pay out.
    /// @param amount The number of terminal tokens to pay out, as a fixed point number with the same number of decimals
    /// as the token's accounting context.
    /// @param currency The expected currency of the amount to pay out. Must match the currency of one of the
    /// project's current ruleset's payout limits.
    /// @return amountPaidOut The total amount that was paid out.
    function _sendPayoutsOf(
        uint256 projectId,
        address token,
        uint256 amount,
        uint256 currency
    )
        internal
        returns (uint256 amountPaidOut)
    {
        // Cache the message sender.
        address sender = _msgSender();

        // Keep a reference to the ruleset.
        JBRuleset memory ruleset;

        // Record the payout.
        (ruleset, amountPaidOut) =
            STORE.recordPayoutFor({projectId: projectId, token: token, amount: amount, currency: currency});

        // If nothing to pay out (e.g. payout limit already used or not configured), return early.
        if (amountPaidOut == 0) return amountPaidOut;

        // Get a reference to the project's owner.
        // The owner will receive tokens minted by paying the platform fee and receive any leftover funds not sent to
        // payout splits.
        address payable projectOwner = payable(_ownerOf(projectId));

        // If the ruleset requires privileged payout distribution, ensure the caller has the permission.
        if (ruleset.ownerMustSendPayouts()) {
            // Enforce permissions.
            _requirePermissionFrom({
                account: projectOwner, projectId: projectId, permissionId: JBPermissionIds.SEND_PAYOUTS
            });
        }

        // Send payouts to the splits and get a reference to the amount left over after the splits have been paid.
        // Also get a reference to the amount which was paid out to splits that is eligible for fees.
        (uint256 leftoverPayoutAmount, uint256 amountEligibleForFees) = JBPayoutSplitGroupLib.sendPayoutsToSplitGroupOf({
            splits: SPLITS,
            store: STORE,
            projectId: projectId,
            token: token,
            rulesetId: ruleset.id,
            amount: amountPaidOut,
            caller: sender
        });

        // Send any leftover funds to the project owner and update the fee tracking accordingly.
        if (leftoverPayoutAmount != 0) {
            // Keep a reference to the fee for the leftover payout amount.
            uint256 fee =
                _isFeeless({addr: projectOwner, projectId: projectId}) ? 0 : _feeAmountFrom(leftoverPayoutAmount);

            uint256 netLeftoverPayoutAmount;
            unchecked {
                netLeftoverPayoutAmount = leftoverPayoutAmount - fee;
            }

            // Failed owner transfer consumes the payout limit by design. Same pattern as split payouts:
            // the try-catch prevents revert, failed amount is returned to project balance, and the owner can retry
            // via addToBalanceOf or in the next cycle.
            try this.executeTransferTo({addr: projectOwner, token: token, amount: netLeftoverPayoutAmount}) {
                if (fee > 0) {
                    amountEligibleForFees += leftoverPayoutAmount;
                    leftoverPayoutAmount = netLeftoverPayoutAmount;
                }
            } catch (bytes memory reason) {
                emit PayoutTransferReverted({
                    projectId: projectId,
                    addr: projectOwner,
                    token: token,
                    amount: netLeftoverPayoutAmount,
                    fee: fee,
                    reason: reason,
                    caller: sender
                });

                // Add balance back to the project.
                _recordAddedBalanceFor({projectId: projectId, token: token, amount: leftoverPayoutAmount});
            }
        }

        // Cap fee-free surplus at remaining balance. Non-fee-free funds leave first.
        // Placed after all payouts settle so the cap reflects post-payout state.
        _capFeeFreeSurplus({projectId: projectId, token: token});

        // Take the fee.
        uint256 feeTaken = _takeFeeFrom({
            projectId: projectId,
            token: token,
            amount: amountEligibleForFees,
            beneficiary: projectOwner,
            shouldHoldFees: ruleset.holdFees()
        });

        emit SendPayouts({
            rulesetId: ruleset.id,
            rulesetCycleNumber: ruleset.cycleNumber,
            projectId: projectId,
            projectOwner: projectOwner,
            amount: amount,
            amountPaidOut: amountPaidOut,
            fee: feeTaken,
            netLeftoverPayoutAmount: leftoverPayoutAmount,
            caller: sender
        });
    }

    /// @notice Takes a fee into the platform's project (with the `JBConstants.FEE_BENEFICIARY_PROJECT_ID`).
    /// @param projectId The ID of the project paying the fee.
    /// @param token The address of the token that the fee is paid in.
    /// @param amount The fee's token amount, as a fixed point number with the same number of decimals as the token's
    /// accounting context.
    /// @param beneficiary The address to mint the platform's project's tokens for.
    /// @param shouldHoldFees If fees should be tracked and held instead of processing them immediately.
    /// @return feeAmount The fee withheld from the current outflow. If immediate fee processing fails, `_processFee`
    /// credits this amount back to the payer project while the current outflow continues.
    function _takeFeeFrom(
        uint256 projectId,
        address token,
        uint256 amount,
        address beneficiary,
        bool shouldHoldFees
    )
        internal
        returns (uint256 feeAmount)
    {
        // Calculate the standard fee from the gross amount.
        feeAmount = _feeAmountFrom(amount);

        if (shouldHoldFees) {
            // The held-fee record stores the basis amount in a `uint224`. Reject a basis that wouldn't fit so it
            // can't silently truncate and corrupt the eventual fee processing/refund.
            _checkFitsIn({value: amount, max: type(uint224).max});

            // Store the gross amount so future repayments can recover the corresponding fee.
            _heldFeesOf[projectId][token].push(
                JBFee({
                    // forge-lint: disable-next-line(unsafe-typecast)
                    amount: uint224(amount),
                    beneficiary: beneficiary,
                    // forge-lint: disable-next-line(unsafe-typecast)
                    unlockTimestamp: uint48(block.timestamp + _FEE_HOLDING_SECONDS)
                })
            );

            emit HoldFee({
                projectId: projectId,
                token: token,
                amount: amount,
                fee: JBConstants.STANDARD_FEE,
                beneficiary: beneficiary,
                caller: _msgSender()
            });
        } else {
            // Resolve the fee project's terminal for this token and process the fee immediately.
            IJBTerminal feeTerminal =
                _primaryTerminalOf({projectId: JBConstants.FEE_BENEFICIARY_PROJECT_ID, token: token});

            _processFee({
                projectId: projectId,
                token: token,
                amount: feeAmount,
                beneficiary: beneficiary,
                feeTerminal: feeTerminal,
                wasHeld: false
            });
        }
    }

    /// @notice Transfers tokens.
    /// @param from The address the transfer should originate from.
    /// @param to The address the transfer should go to.
    /// @param token The token to transfer.
    /// @param amount The number of tokens to transfer, as a fixed point number with the same number of decimals
    /// as this terminal.
    function _transferFrom(address from, address payable to, address token, uint256 amount) internal {
        if (from == address(this)) {
            // If the token is the native token, transfer natively.
            if (token == JBConstants.NATIVE_TOKEN) return Address.sendValue({recipient: to, amount: amount});

            return IERC20(token).safeTransfer({to: to, value: amount});
        }

        // If there's sufficient approval, transfer normally.
        if (IERC20(token).allowance({owner: address(from), spender: address(this)}) >= amount) {
            return IERC20(token).safeTransferFrom({from: from, to: to, value: amount});
        }

        // Make sure the amount being paid is less than the maximum permit2 allowance.
        _checkFitsIn({value: amount, max: type(uint160).max});

        // Otherwise we attempt to use the PERMIT2 method.
        // forge-lint: disable-next-line(unsafe-typecast)
        PERMIT2.transferFrom({from: from, to: to, amount: uint160(amount), token: token});
    }

    /// @notice Allows a project to send out funds from its surplus up to the current surplus allowance.
    /// @dev Only a project's owner or an operator with the owner's `USE_ALLOWANCE` permission can use the allowance.
    /// @dev Incurs the protocol fee unless the caller is a feeless address.
    /// @param projectId The ID of the project to use the surplus allowance of.
    /// @param owner The project's owner.
    /// @param token The token to pay out from the surplus.
    /// @param amount The amount of terminal tokens to use from the project's current surplus allowance, as a fixed
    /// point number with the same number of decimals as the token's accounting context.
    /// @param currency The expected currency of the amount to pay out. Must match the currency of one of the
    /// project's current ruleset's surplus allowances.
    /// @param beneficiary The address to send the funds to.
    /// @param feeBeneficiary The address to send the tokens resulting from paying the fee.
    /// @param memo A memo to pass along to the emitted event.
    /// @return netAmountPaidOut The amount of tokens paid out.
    function _useAllowanceOf(
        uint256 projectId,
        address owner,
        address token,
        uint256 amount,
        uint256 currency,
        address payable beneficiary,
        address payable feeBeneficiary,
        string memory memo
    )
        internal
        returns (uint256 netAmountPaidOut)
    {
        // Keep a reference to the ruleset.
        JBRuleset memory ruleset;

        // Keep a reference to the amount paid out before fees.
        uint256 amountPaidOut;

        // Record the use of the allowance.
        (ruleset, amountPaidOut) =
            STORE.recordUsedAllowanceOf({projectId: projectId, token: token, amount: amount, currency: currency});

        // Cap fee-free surplus at remaining balance. Non-fee-free funds leave first.
        _capFeeFreeSurplus({projectId: projectId, token: token});

        // Take a fee from the `amountPaidOut`, if needed.
        // The net amount is the final amount withdrawn after the fee has been taken.
        netAmountPaidOut = amountPaidOut
            - (_isFeeless({addr: owner, projectId: projectId}) || _isFeeless({addr: beneficiary, projectId: projectId})
                    ? 0
                    : _takeFeeFrom({
                        projectId: projectId,
                        token: token,
                        amount: amountPaidOut,
                        // The `feeBeneficiary` will receive the fee-project tokens minted in exchange for the
                        // platform fee paid in terminal tokens.
                        beneficiary: feeBeneficiary,
                        shouldHoldFees: ruleset.holdFees()
                    }));

        emit UseAllowance({
            rulesetId: ruleset.id,
            rulesetCycleNumber: ruleset.cycleNumber,
            projectId: projectId,
            beneficiary: beneficiary,
            feeBeneficiary: feeBeneficiary,
            amount: amount,
            amountPaidOut: amountPaidOut,
            netAmountPaidOut: netAmountPaidOut,
            memo: memo,
            caller: _msgSender()
        });

        // Transfer any remaining balance to the beneficiary.
        if (netAmountPaidOut != 0) {
            _transferFrom({from: address(this), to: beneficiary, token: token, amount: netAmountPaidOut});
        }
    }

    //*********************************************************************//
    // -------------------------- internal views ------------------------- //
    //*********************************************************************//

    /// @notice Logic to be triggered after transferring tokens from this terminal.
    /// @dev Clears any allowance granted by `_beforeTransferTo` so receivers cannot retain pull access after the call.
    /// @param to The address whose temporary pull allowance should be cleared.
    /// @param token The token whose temporary allowance should be cleared.
    function _afterTransferTo(address to, address token) internal view {
        // Native-token transfers use `msg.value`, so there is no ERC-20 approval to clear.
        if (token == JBConstants.NATIVE_TOKEN) return;

        // Revert if the callee returned without consuming the full forwarded ERC-20 amount.
        uint256 allowance = IERC20(token).allowance({owner: address(this), spender: to});
        if (allowance != 0) revert JBMultiTerminal_TemporaryAllowanceNotConsumed(token, to, allowance);
    }

    /// @notice Returns a project's accounting context for a token, reverting if it is not accepted.
    /// @param projectId The ID of the project to get the accounting context for.
    /// @param token The token to get the accounting context for.
    /// @return context The project's accounting context for the token.
    function _accountingContextOf(
        uint256 projectId,
        address token
    )
        internal
        view
        returns (JBAccountingContext memory context)
    {
        // Keep a reference to the accounting context configured for the token.
        context = STORE.accountingContextOf({terminal: address(this), projectId: projectId, token: token});

        // Revert if the token is not accepted by the project.
        if (context.token == address(0)) revert JBMultiTerminal_TokenNotAccepted(token);
    }

    /// @notice Checks this terminal's balance of a specific token.
    /// @param token The address of the token to get this terminal's balance of.
    /// @return This terminal's balance.
    function _balanceOf(address token) internal view returns (uint256) {
        // If the `token` is native, get the native token balance.
        return token == JBConstants.NATIVE_TOKEN ? address(this).balance : IERC20(token).balanceOf(address(this));
    }

    /// @dev `ERC-2771` specifies the context as being a single address (20 bytes).
    function _contextSuffixLength() internal view override(ERC2771Context, Context) returns (uint256) {
        return super._contextSuffixLength();
    }

    /// @notice Returns the current controller of a project.
    /// @param projectId The ID of the project to get the controller of.
    /// @return controller The project's controller.
    function _controllerOf(uint256 projectId) internal view returns (IJBController) {
        return IJBController(address(DIRECTORY.controllerOf(projectId)));
    }

    /// @notice Returns a flag indicating if interacting with an address should not incur fees.
    /// @dev Forwards `_msgSender()` (the outer caller of the terminal, with ERC-2771 forwarders unwrapped) to the
    /// registry so an installed feeless hook can scope its grant by caller — e.g. recognise an ecosystem router
    /// that wraps cash-out → pay and grant it fee-free cash-outs only when it itself is the caller.
    /// @param addr The address to check.
    /// @param projectId The ID of the project to check the per-project feeless status for.
    /// @return A flag indicating if the address should not incur fees (globally or for the project).
    function _isFeeless(address addr, uint256 projectId) internal view returns (bool) {
        return FEELESS_ADDRESSES.isFeelessFor({addr: addr, projectId: projectId, caller: _msgSender()});
    }

    /// @notice The calldata. Preferred to use over `msg.data`.
    /// @return calldata The `msg.data` of this call.
    function _msgData() internal view override(ERC2771Context, Context) returns (bytes calldata) {
        return ERC2771Context._msgData();
    }

    /// @notice The message's sender. Preferred to use over `msg.sender`.
    /// @return sender The address which sent this call.
    function _msgSender() internal view override(ERC2771Context, Context) returns (address sender) {
        return ERC2771Context._msgSender();
    }

    /// @notice The owner of a project.
    /// @param projectId The ID of the project to get the owner of.
    /// @return The owner of the project.
    function _ownerOf(uint256 projectId) internal view returns (address) {
        return PROJECTS.ownerOf(projectId);
    }

    /// @notice The primary terminal of a project for a token.
    /// @param projectId The ID of the project to get the primary terminal of.
    /// @param token The token to get the primary terminal of.
    /// @return The primary terminal of the project for the token.
    function _primaryTerminalOf(uint256 projectId, address token) internal view returns (IJBTerminal) {
        return DIRECTORY.primaryTerminalOf({projectId: projectId, token: token});
    }

    /// @notice Packages a payment amount with the token's accounting context.
    /// @param projectId The ID of the project the token amount belongs to.
    /// @param token The token to pay with.
    /// @param value The token amount's value.
    /// @return tokenAmount The packaged token amount.
    function _tokenAmountOf(
        uint256 projectId,
        address token,
        uint256 value
    )
        internal
        view
        returns (JBTokenAmount memory tokenAmount)
    {
        // Keep a reference to the token's accounting context.
        JBAccountingContext memory context = _accountingContextOf({projectId: projectId, token: token});

        // Bundle the amount info into a `JBTokenAmount` struct.
        tokenAmount =
            JBTokenAmount({token: token, decimals: context.decimals, currency: context.currency, value: value});
    }

    /// @notice Returns a holder's total token balance for a project.
    /// @param holder The holder to get a balance for.
    /// @param projectId The ID of the project to get a balance for.
    /// @return balance The holder's total project token balance.
    function _totalBalanceOf(address holder, uint256 projectId) internal view returns (uint256 balance) {
        return TOKENS.totalBalanceOf({holder: holder, projectId: projectId});
    }

    //*********************************************************************//
    // -------------------------- private helpers ------------------------ //
    //*********************************************************************//

    /// @notice Revert if a value doesn't fit within a maximum, so a later narrowing cast can't silently truncate it.
    /// @param value The value to bound.
    /// @param max The largest value that fits the target width.
    function _checkFitsIn(uint256 value, uint256 max) private pure {
        if (value > max) revert JBMultiTerminal_OverflowAlert(value, max);
    }

    /// @notice The terminal fee charged from a pre-fee `amount`.
    /// @param amount The amount before the fee is applied.
    /// @return The fee amount.
    function _feeAmountFrom(uint256 amount) private pure returns (uint256) {
        return JBFees.standardFeeAmountFrom(amount);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {JBPermissionIds} from "@bananapus/permission-ids-v6/src/JBPermissionIds.sol";
import {ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";

import {IJBPermissions} from "./interfaces/IJBPermissions.sol";
import {JBPermissionsData} from "./structs/JBPermissionsData.sol";

/// @notice The permission system for Juicebox. Any address can authorize another address (an "operator") to perform
/// specific actions on its behalf — like queuing rulesets, distributing payouts, or managing terminals.
/// @dev Permissions are stored as a packed `uint256` bitmap: each of the 256 bits represents one permission's
/// on/off state. Project ID 0 is a wildcard that grants an operator access across all projects — use with caution.
/// @dev The ROOT permission (ID 1) implicitly grants every other permission for the scoped project.
contract JBPermissions is ERC2771Context, IJBPermissions {
    //*********************************************************************//
    // --------------------------- custom errors ------------------------- //
    //*********************************************************************//

    /// @notice Thrown when attempting to set the reserved permission ID 0.
    error JBPermissions_NoZeroPermission(address account, address operator, uint256 projectId);

    /// @notice Thrown when a permission ID is greater than the maximum of 255.
    error JBPermissions_PermissionIdOutOfBounds(uint256 permissionId);

    /// @notice Thrown when the caller is not the account and lacks ROOT permission to set permissions on its behalf.
    error JBPermissions_Unauthorized(address account, address operator, uint256 projectId, uint256 permissionId);

    //*********************************************************************//
    // ------------------------- public constants ------------------------ //
    //*********************************************************************//

    /// @notice Project ID 0 acts as a wildcard for permissions across all projects owned by the account.
    /// @dev Setting permissions for project ID 0 is powerful and should be done carefully.
    uint256 public constant override WILDCARD_PROJECT_ID = 0;

    //*********************************************************************//
    // --------------------- public stored properties -------------------- //
    //*********************************************************************//

    /// @notice The packed permission bitmap that an account has granted to an operator for a specific project.
    /// @dev Each bit in the returned `uint256` corresponds to a permission ID (0–255). A `1` bit means the permission
    /// is granted. See `JBPermissionIds` for the meaning of each ID.
    /// @custom:param operator The address of the operator.
    /// @custom:param account The address of the account operated on behalf of.
    /// @custom:param projectId The project ID the permissions are scoped to. An ID of 0 grants permissions across all
    /// projects.
    mapping(address operator => mapping(address account => mapping(uint256 projectId => uint256)))
        public
        override permissionsOf;

    //*********************************************************************//
    // ---------------------------- constructor -------------------------- //
    //*********************************************************************//

    /// @param trustedForwarder The trusted forwarder for the ERC2771Context.
    constructor(address trustedForwarder) ERC2771Context(trustedForwarder) {}

    //*********************************************************************//
    // ---------------------- external transactions ---------------------- //
    //*********************************************************************//

    /// @notice Grant or revoke permissions for an operator on a specific project.
    /// @dev Only the account itself can set permissions without restriction. A ROOT operator on a specific project can
    /// set non-ROOT permissions for that same project on the account's behalf, but cannot grant ROOT or set wildcard
    /// (project ID 0) permissions — preventing privilege escalation.
    /// @param account The account to configure operator permissions for.
    /// @param permissionsData The operator address, project scope, and permission IDs to set.
    function setPermissionsFor(address account, JBPermissionsData calldata permissionsData) external override {
        // Pack the permission IDs into a uint256.
        uint256 packed = _packedPermissions(permissionsData.permissionIds);

        // Make sure the 0 permission is not set.
        if (_includesPermission({permissions: packed, permissionId: 0})) {
            revert JBPermissions_NoZeroPermission({
                account: account, operator: permissionsData.operator, projectId: permissionsData.projectId
            });
        }

        // Cache the sender.
        address msgSender = _msgSender();

        // Enforce permissions. ROOT operators are allowed to set permissions so long as they are not setting another
        // ROOT permission or setting permissions for a wildcard project ID.
        if (
            msgSender != account
                && (_includesPermission({permissions: packed, permissionId: JBPermissionIds.ROOT})
                    || permissionsData.projectId == WILDCARD_PROJECT_ID
                    || !hasPermission({
                        operator: msgSender,
                        account: account,
                        projectId: permissionsData.projectId,
                        permissionId: JBPermissionIds.ROOT,
                        includeRoot: true,
                        includeWildcardProjectId: true
                    }))
        ) {
            revert JBPermissions_Unauthorized({
                account: account,
                operator: msgSender,
                projectId: permissionsData.projectId,
                permissionId: JBPermissionIds.ROOT
            });
        }

        // Store the new value.
        permissionsOf[permissionsData.operator][account][permissionsData.projectId] = packed;

        emit OperatorPermissionsSet({
            operator: permissionsData.operator,
            account: account,
            projectId: permissionsData.projectId,
            permissionIds: permissionsData.permissionIds,
            packed: packed,
            caller: msgSender
        });
    }

    //*********************************************************************//
    // ------------------------- external views -------------------------- //
    //*********************************************************************//

    /// @notice Check whether an operator has *all* of the specified permissions for an account and project.
    /// @param operator The address to check permissions for.
    /// @param account The account that granted (or didn't grant) the permissions.
    /// @param projectId The project ID to check within. Pass 0 to check the wildcard scope directly.
    /// @param permissionIds The permission IDs that must all be present.
    /// @param includeRoot If `true`, returns `true` immediately when the operator has the ROOT permission.
    /// @param includeWildcardProjectId If `true`, also checks wildcard (project 0) permissions as a fallback.
    /// @return Whether the operator holds every requested permission.
    function hasPermissions(
        address operator,
        address account,
        uint256 projectId,
        uint256[] calldata permissionIds,
        bool includeRoot,
        bool includeWildcardProjectId
    )
        external
        view
        override
        returns (bool)
    {
        // If the ROOT permission is set and should be included, return true.
        if (
            includeRoot
                && (_includesPermission({
                        permissions: permissionsOf[operator][account][projectId], permissionId: JBPermissionIds.ROOT
                    })
                    || (includeWildcardProjectId
                        && _includesPermission({
                            permissions: permissionsOf[operator][account][WILDCARD_PROJECT_ID],
                            permissionId: JBPermissionIds.ROOT
                        })))
        ) {
            return true;
        }

        // Keep a reference to the permission item being checked.
        uint256 operatorAccountProjectPermissions = permissionsOf[operator][account][projectId];

        // Keep a reference to the wildcard project permissions.
        uint256 operatorAccountWildcardProjectPermissions =
            includeWildcardProjectId ? permissionsOf[operator][account][WILDCARD_PROJECT_ID] : 0;

        // Returns true for empty permission arrays by design (vacuous truth). An empty set of
        // required permissions is trivially satisfied. Callers should validate non-empty permission arrays if needed.
        for (uint256 i; i < permissionIds.length;) {
            // Set the permission being iterated on.
            uint256 permissionId = permissionIds[i];

            // Indexes above 255 don't exist
            if (permissionId > 255) revert JBPermissions_PermissionIdOutOfBounds(permissionId);

            // Check each permissionId
            if (
                !_includesPermission({permissions: operatorAccountProjectPermissions, permissionId: permissionId})
                    && !_includesPermission({
                        permissions: operatorAccountWildcardProjectPermissions, permissionId: permissionId
                    })
            ) {
                return false;
            }
            unchecked {
                ++i;
            }
        }
        return true;
    }

    //*********************************************************************//
    // -------------------------- public views --------------------------- //
    //*********************************************************************//

    /// @notice Check whether an operator has a single permission for an account and project.
    /// @param operator The address to check.
    /// @param account The account that granted (or didn't grant) the permission.
    /// @param projectId The project ID to check within. Pass 0 to check the wildcard scope directly.
    /// @param permissionId The specific permission ID to look for (0–255).
    /// @param includeRoot If `true`, returns `true` immediately when the operator has the ROOT permission.
    /// @param includeWildcardProjectId If `true`, also checks wildcard (project 0) permissions as a fallback.
    /// @return Whether the operator holds the requested permission.
    function hasPermission(
        address operator,
        address account,
        uint256 projectId,
        uint256 permissionId,
        bool includeRoot,
        bool includeWildcardProjectId
    )
        public
        view
        override
        returns (bool)
    {
        // Indexes above 255 don't exist
        if (permissionId > 255) revert JBPermissions_PermissionIdOutOfBounds(permissionId);

        // Cache both permission slots upfront to avoid redundant storage reads.
        uint256 projectPermissions = permissionsOf[operator][account][projectId];
        uint256 wildcardPermissions =
            includeWildcardProjectId ? permissionsOf[operator][account][WILDCARD_PROJECT_ID] : 0;

        // If the ROOT permission is set and should be included, return true.
        if (
            includeRoot
                && (_includesPermission({permissions: projectPermissions, permissionId: JBPermissionIds.ROOT})
                    || _includesPermission({permissions: wildcardPermissions, permissionId: JBPermissionIds.ROOT}))
        ) {
            return true;
        }

        // Otherwise return the t/f flag of the specified id.
        return _includesPermission({permissions: projectPermissions, permissionId: permissionId})
            || _includesPermission({permissions: wildcardPermissions, permissionId: permissionId});
    }

    //*********************************************************************//
    // -------------------------- internal views ------------------------- //
    //*********************************************************************//

    /// @notice Checks if a permission is included in a packed permissions data.
    /// @param permissions The packed permissions to check.
    /// @param permissionId The ID of the permission to check for.
    /// @return A flag indicating whether the permission is included.
    function _includesPermission(uint256 permissions, uint256 permissionId) internal pure returns (bool) {
        return ((permissions >> permissionId) & 1) == 1;
    }

    /// @notice Converts an array of permission IDs to a packed `uint256`.
    /// @param permissionIds The IDs of the permissions to pack.
    /// @return packed The packed value.
    function _packedPermissions(uint8[] calldata permissionIds) internal pure returns (uint256 packed) {
        for (uint256 i; i < permissionIds.length;) {
            // Set the permission being iterated on.
            uint256 permissionId = permissionIds[i];

            // Turn on the bit at the ID.
            // forge-lint: disable-next-line(incorrect-shift)
            packed |= 1 << permissionId;
            unchecked {
                ++i;
            }
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Context, ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import {mulDiv} from "@prb/math/src/Common.sol";

import {JBControlled} from "./abstract/JBControlled.sol";
import {JBPermissioned} from "./abstract/JBPermissioned.sol";
import {IJBDirectory} from "./interfaces/IJBDirectory.sol";
import {IJBPermissions} from "./interfaces/IJBPermissions.sol";
import {IJBPriceFeed} from "./interfaces/IJBPriceFeed.sol";
import {IJBPrices} from "./interfaces/IJBPrices.sol";
import {IJBProjects} from "./interfaces/IJBProjects.sol";

/// @notice Resolves protocol currency conversions from append-only project and default price feeds.
/// @dev Each feed prices one unit of `unitCurrency` in `pricingCurrency`. Feeds cannot be changed or removed once
/// added. Later feeds for the same exact pair act as backups when earlier feeds revert or return zero. Project-specific
/// feeds are checked before project ID 0 defaults, and inverse prices are derived at read time when only the opposite
/// direction is configured. If no configured feed returns a non-zero price, the read reverts instead of guessing.
contract JBPrices is JBControlled, JBPermissioned, ERC2771Context, Ownable, IJBPrices {
    //*********************************************************************//
    // --------------------------- custom errors ------------------------- //
    //*********************************************************************//

    /// @notice Thrown when adding a price feed that is already registered for the same currency pair.
    error JBPrices_PriceFeedAlreadyAdded(IJBPriceFeed feed);

    /// @notice Thrown when no configured price feed can be found for the requested currency pair.
    error JBPrices_PriceFeedNotFound(uint256 projectId, uint256 pricingCurrency, uint256 unitCurrency);

    /// @notice Thrown when the provided price feed is the zero address.
    error JBPrices_ZeroPriceFeed();

    /// @notice Thrown when the pricing currency provided is zero.
    error JBPrices_ZeroPricingCurrency(uint256 projectId, uint256 pricingCurrency);

    /// @notice Thrown when the unit currency provided is zero.
    error JBPrices_ZeroUnitCurrency(uint256 projectId, uint256 unitCurrency);

    //*********************************************************************//
    // ------------------------- public constants ------------------------ //
    //*********************************************************************//

    /// @notice The ID to store default values in.
    uint256 public constant override DEFAULT_PROJECT_ID = 0;

    //*********************************************************************//
    // ---------------- public immutable stored properties --------------- //
    //*********************************************************************//

    /// @notice Mints ERC-721s that represent project ownership and transfers.
    IJBProjects public immutable override PROJECTS;

    //*********************************************************************//
    // -------------------- internal stored properties ------------------- //
    //*********************************************************************//

    /// @notice Price feeds available to each project for each exact currency pair.
    /// @dev The array is append-only. Index 0 remains the primary feed, and later indexes are backups.
    /// @custom:param projectId The ID of the project the feed applies to. Project ID 0 stores protocol defaults.
    /// @custom:param pricingCurrency The currency the feed's returned price is denominated in.
    /// @custom:param unitCurrency The currency whose unit is priced by the feed.
    mapping(
        uint256 projectId => mapping(uint256 pricingCurrency => mapping(uint256 unitCurrency => IJBPriceFeed[]))
    ) internal _priceFeedsFor;

    //*********************************************************************//
    // ---------------------------- constructor -------------------------- //
    //*********************************************************************//

    /// @notice Initializes the price registry and its permissioned dependencies.
    /// @param directory A contract storing directories of terminals and controllers for each project.
    /// @param permissions A contract storing permissions.
    /// @param projects A contract which mints ERC-721s that represent project ownership and transfers.
    /// @param owner The address that will own the contract.
    /// @param trustedForwarder The trusted forwarder for the ERC2771Context.
    constructor(
        IJBDirectory directory,
        IJBPermissions permissions,
        IJBProjects projects,
        address owner,
        address trustedForwarder
    )
        JBControlled(directory)
        JBPermissioned(permissions)
        Ownable(owner)
        ERC2771Context(trustedForwarder)
    {
        PROJECTS = projects;
    }

    //*********************************************************************//
    // ---------------------- external transactions ---------------------- //
    //*********************************************************************//

    /// @notice Adds an append-only price feed for a project's exact currency pair.
    /// @dev Project ID 0 stores protocol defaults and can only be configured by this contract's owner. Non-zero
    /// project IDs can only be configured by that project's controller. The feed is stored only for the exact
    /// `pricingCurrency`/`unitCurrency` direction; the opposite direction is derived by `pricePerUnitOf` when needed.
    /// @dev Later feeds for the same exact pair are backups. The existing feeds remain preferred, and this function
    /// rejects duplicate feed addresses for the exact pair.
    /// @param projectId The ID of the project to add the feed for, or 0 to add a protocol default.
    /// @param pricingCurrency The currency that the feed's returned price is denominated in.
    /// @param unitCurrency The currency whose unit is priced by the feed.
    /// @param feed The price feed to add.
    function addPriceFeedFor(
        uint256 projectId,
        uint256 pricingCurrency,
        uint256 unitCurrency,
        IJBPriceFeed feed
    )
        external
        override
    {
        // Project 0 configures defaults for every project; each other project delegates feed configuration to its
        // controller.
        projectId == DEFAULT_PROJECT_ID ? _checkOwner() : _onlyControllerOf(projectId);

        if (pricingCurrency == 0) {
            revert JBPrices_ZeroPricingCurrency({projectId: projectId, pricingCurrency: pricingCurrency});
        }

        if (unitCurrency == 0) revert JBPrices_ZeroUnitCurrency({projectId: projectId, unitCurrency: unitCurrency});

        if (feed == IJBPriceFeed(address(0))) revert JBPrices_ZeroPriceFeed();

        // Only exact-direction duplicates are rejected. Opposite-direction feeds can coexist and are used when deriving
        // inverse prices.
        _requireNewPriceFeed({
            projectId: projectId, pricingCurrency: pricingCurrency, unitCurrency: unitCurrency, feed: feed
        });

        // Keep existing feeds immutable: appending preserves the primary feed and adds this feed as the last fallback.
        _priceFeedsFor[projectId][pricingCurrency][unitCurrency].push(feed);

        emit AddPriceFeed({
            projectId: projectId,
            pricingCurrency: pricingCurrency,
            unitCurrency: unitCurrency,
            feed: feed,
            caller: _msgSender()
        });
    }

    //*********************************************************************//
    // ----------------------- external views ---------------------------- //
    //*********************************************************************//

    /// @notice Returns the feed stored at an exact pair's index.
    /// @dev This view does not apply inverse or project-default fallback lookup. It reverts with Solidity's default
    /// array bounds check if `index` is not configured.
    /// @param projectId The ID of the project whose feed should be returned.
    /// @param pricingCurrency The currency that the feed's returned price is denominated in.
    /// @param unitCurrency The currency whose unit is priced by the feed.
    /// @param index The index of the feed to return.
    /// @return feed The configured price feed for the exact pair at `index`.
    function priceFeedAt(
        uint256 projectId,
        uint256 pricingCurrency,
        uint256 unitCurrency,
        uint256 index
    )
        external
        view
        override
        returns (IJBPriceFeed feed)
    {
        return _priceFeedsFor[projectId][pricingCurrency][unitCurrency][index];
    }

    /// @notice Returns the number of feeds configured for an exact currency pair.
    /// @dev This count does not include feeds configured for the inverse direction or project ID 0 defaults.
    /// @param projectId The ID of the project whose feed count should be returned.
    /// @param pricingCurrency The currency that the feeds' returned prices are denominated in.
    /// @param unitCurrency The currency whose unit is priced by the feeds.
    /// @return count The number of configured price feeds for the exact pair.
    function priceFeedCountFor(
        uint256 projectId,
        uint256 pricingCurrency,
        uint256 unitCurrency
    )
        external
        view
        override
        returns (uint256 count)
    {
        return _priceFeedsFor[projectId][pricingCurrency][unitCurrency].length;
    }

    /// @notice Returns the primary feed for an exact currency pair, or zero if none is configured.
    /// @dev This view does not apply inverse or project-default fallback lookup. Use `pricePerUnitOf` to resolve a
    /// usable price through the full backup path.
    /// @param projectId The ID of the project whose primary feed should be returned.
    /// @param pricingCurrency The currency that the feed's returned price is denominated in.
    /// @param unitCurrency The currency whose unit is priced by the feed.
    /// @return feed The first configured price feed for the exact pair, or the zero address if none exists.
    function priceFeedFor(
        uint256 projectId,
        uint256 pricingCurrency,
        uint256 unitCurrency
    )
        external
        view
        override
        returns (IJBPriceFeed feed)
    {
        return _priceFeedsFor[projectId][pricingCurrency][unitCurrency].length == 0
            ? IJBPriceFeed(address(0))
            : _priceFeedsFor[projectId][pricingCurrency][unitCurrency][0];
    }

    //*********************************************************************//
    // -------------------------- public views --------------------------- //
    //*********************************************************************//

    /// @notice Returns the price of one `unitCurrency` unit denominated in `pricingCurrency`.
    /// @dev Lookup order is project direct feeds, project inverse feeds, default direct feeds, then default inverse
    /// feeds. Each feed list is tried in registration order, skipping feeds that revert or return zero. Reverts with
    /// `JBPrices_PriceFeedNotFound` if no configured feed in that lookup path returns a non-zero price.
    /// @param projectId The ID of the project to check first. Project ID 0 feeds are used as defaults.
    /// @param pricingCurrency The currency that the returned price is denominated in.
    /// @param unitCurrency The currency whose unit is being priced.
    /// @param decimals The number of decimals the returned fixed point price should use.
    /// @return price The `pricingCurrency` price of one `unitCurrency`, using `decimals` fixed point precision.
    function pricePerUnitOf(
        uint256 projectId,
        uint256 pricingCurrency,
        uint256 unitCurrency,
        uint256 decimals
    )
        public
        view
        override
        returns (uint256 price)
    {
        // Same-currency conversions are always 1 in the requested fixed-point precision.
        if (pricingCurrency == unitCurrency) return 10 ** decimals;

        bool found;

        // Project-specific feeds take priority over defaults, including their configured backups.
        (price, found) = _pricePerUnitOf({
            projectId: projectId, pricingCurrency: pricingCurrency, unitCurrency: unitCurrency, decimals: decimals
        });
        if (found) return price;

        if (projectId != DEFAULT_PROJECT_ID) {
            // Project 0 feeds are the shared defaults. Avoid checking them twice when project ID 0 was requested.
            (price, found) = _pricePerUnitOf({
                projectId: DEFAULT_PROJECT_ID,
                pricingCurrency: pricingCurrency,
                unitCurrency: unitCurrency,
                decimals: decimals
            });
            if (found) return price;
        }

        revert JBPrices_PriceFeedNotFound({
            projectId: projectId, pricingCurrency: pricingCurrency, unitCurrency: unitCurrency
        });
    }

    //*********************************************************************//
    // ----------------------- internal helpers -------------------------- //
    //*********************************************************************//

    /// @notice Reverts if `feed` is already configured for an exact currency pair.
    /// @param projectId The ID of the project whose pair should be checked.
    /// @param pricingCurrency The currency that the feed's returned price is denominated in.
    /// @param unitCurrency The currency whose unit is priced by the feed.
    /// @param feed The price feed to check.
    function _requireNewPriceFeed(
        uint256 projectId,
        uint256 pricingCurrency,
        uint256 unitCurrency,
        IJBPriceFeed feed
    )
        internal
        view
    {
        IJBPriceFeed[] storage feeds = _priceFeedsFor[projectId][pricingCurrency][unitCurrency];
        uint256 numberOfFeeds = feeds.length;

        for (uint256 i; i < numberOfFeeds;) {
            if (feeds[i] == feed) revert JBPrices_PriceFeedAlreadyAdded({feed: feed});

            unchecked {
                ++i;
            }
        }
    }

    //*********************************************************************//
    // ----------------------- internal views ---------------------------- //
    //*********************************************************************//

    /// @notice Returns the ERC-2771 context suffix length.
    /// @dev `ERC-2771` specifies the context as being a single address (20 bytes).
    /// @return contextSuffixLength The context suffix length.
    function _contextSuffixLength()
        internal
        view
        override(ERC2771Context, Context)
        returns (uint256 contextSuffixLength)
    {
        return super._contextSuffixLength();
    }

    /// @notice The calldata. Preferred to use over `msg.data`.
    /// @return data The `msg.data` of this call.
    function _msgData() internal view override(ERC2771Context, Context) returns (bytes calldata data) {
        return ERC2771Context._msgData();
    }

    /// @notice The message's sender. Preferred to use over `msg.sender`.
    /// @return sender The address which sent this call.
    function _msgSender() internal view override(ERC2771Context, Context) returns (address sender) {
        return ERC2771Context._msgSender();
    }

    /// @notice Returns the first non-zero direct price from `feeds`.
    /// @dev Feeds are tried in registration order. A feed that reverts or returns zero is treated as unavailable.
    /// @param feeds The direct price feeds to try.
    /// @param decimals The number of decimals the returned fixed point price should use.
    /// @return price The first non-zero price returned by the feeds.
    /// @return found Whether a usable price was found.
    function _priceFrom(
        IJBPriceFeed[] storage feeds,
        uint256 decimals
    )
        internal
        view
        returns (uint256 price, bool found)
    {
        uint256 numberOfFeeds = feeds.length;
        for (uint256 i; i < numberOfFeeds;) {
            // Try each feed independently so one unavailable oracle does not block later backups.
            try feeds[i].currentUnitPrice(decimals) returns (uint256 returnedPrice) {
                if (returnedPrice != 0) return (returnedPrice, true);
            } catch {}

            unchecked {
                ++i;
            }
        }
    }

    /// @notice Returns the first non-zero inverse price from `feeds`.
    /// @dev Feeds are tried in registration order. A feed that reverts, returns zero, or inverts to zero at the
    /// requested precision is treated as unavailable.
    /// @param feeds The opposite-direction price feeds to invert.
    /// @param decimals The number of decimals the returned fixed point price should use.
    /// @return price The first non-zero inverse price returned by the feeds.
    /// @return found Whether a usable inverse price was found.
    function _priceFromInverse(
        IJBPriceFeed[] storage feeds,
        uint256 decimals
    )
        internal
        view
        returns (uint256 price, bool found)
    {
        uint256 numberOfFeeds = feeds.length;
        for (uint256 i; i < numberOfFeeds;) {
            // Each opposite-direction feed is optional; continue to backups if it cannot produce a usable price.
            try feeds[i].currentUnitPrice(decimals) returns (uint256 inversePrice) {
                if (inversePrice != 0) {
                    // Convert "unit per pricing" into "pricing per unit" using the same fixed-point precision.
                    uint256 invertedPrice = mulDiv({x: 10 ** decimals, y: 10 ** decimals, denominator: inversePrice});
                    if (invertedPrice != 0) return (invertedPrice, true);
                }
            } catch {}

            unchecked {
                ++i;
            }
        }
    }

    /// @notice Returns a non-zero price from a project's direct or inverse feeds.
    /// @dev Direct feeds are preferred over inverse feeds for the same project and pair.
    /// @param projectId The ID of the project whose feeds should be checked.
    /// @param pricingCurrency The currency that the returned price should be denominated in.
    /// @param unitCurrency The currency whose unit is being priced.
    /// @param decimals The number of decimals the returned fixed point price should use.
    /// @return price The first usable direct or inverse price.
    /// @return found Whether a usable price was found.
    function _pricePerUnitOf(
        uint256 projectId,
        uint256 pricingCurrency,
        uint256 unitCurrency,
        uint256 decimals
    )
        internal
        view
        returns (uint256 price, bool found)
    {
        (price, found) =
            _priceFrom({feeds: _priceFeedsFor[projectId][pricingCurrency][unitCurrency], decimals: decimals});
        if (found) return (price, true);

        (price, found) =
            _priceFromInverse({feeds: _priceFeedsFor[projectId][unitCurrency][pricingCurrency], decimals: decimals});
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import {ERC721, Context} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";

import {IJBPayerTracker} from "./interfaces/IJBPayerTracker.sol";
import {IJBProjects} from "./interfaces/IJBProjects.sol";
import {IJBTokenUriResolver} from "./interfaces/IJBTokenUriResolver.sol";
import {JBPayerTrackerLib} from "./libraries/JBPayerTrackerLib.sol";

/// @notice Each Juicebox project is an ERC-721 NFT. Whoever holds the NFT owns the project and can configure its
/// rulesets, terminals, and permissions. Projects are created with `createFor` and the resulting token ID is used as
/// the project's ID across the entire protocol.
contract JBProjects is ERC721, ERC2771Context, Ownable, IJBProjects, IJBPayerTracker {
    //*********************************************************************//
    // --------------------------- custom errors ------------------------- //
    //*********************************************************************//

    /// @notice Thrown when the configured creation fee exceeds the allowed maximum.
    error JBProjects_CreationFeeExceedsMax(uint256 fee, uint256 max);

    /// @notice Thrown when the native value sent does not equal the required creation fee.
    error JBProjects_InvalidCreationFee(uint256 value, uint256 requiredFee);

    /// @notice Thrown when a non-zero creation fee is configured without a fee receiver.
    error JBProjects_ZeroCreationFeeReceiver();

    //*********************************************************************//
    // ------------------------- public constants ------------------------ //
    //*********************************************************************//

    /// @notice The maximum native-token fee the owner can require to create a project.
    /// @dev Hardcoded as a cap on the owner's `setCreationFee` authority so the fee can never become an effective
    /// barrier to project creation.
    uint256 public constant override MAX_CREATION_FEE = 0.001 ether;

    //*********************************************************************//
    // --------------------- public stored properties -------------------- //
    //*********************************************************************//

    /// @notice The native-token fee required to create a project.
    uint256 public override creationFee;

    /// @notice The address that receives project creation fees.
    address payable public override creationFeeReceiver;

    /// @notice The number of projects that have been created using this contract.
    /// @dev The count is incremented with each new project created.
    /// @dev The resulting ERC-721 token ID for each project is the newly incremented count value.
    uint256 public override count;

    /// @notice The contract resolving each project ID to its ERC721 URI.
    IJBTokenUriResolver public override tokenUriResolver;

    //*********************************************************************//
    // ------------------- public transient properties ------------------- //
    //*********************************************************************//

    /// @notice The account that paid the creation fee for the project currently being created.
    /// @dev Resolved from the `createFor` caller: a caller that itself implements `IJBPayerTracker` (a deployer or
    /// `JBController` forwarding a user's fee) advertises its upstream payer, so the chain resolves to the true
    /// originator; a direct caller is the payer itself. Set while the fee transfer runs so a `pay`-routing fee
    /// receiver (e.g. `JBProjectPayer`) credits the fee payer instead of an intermediary. Cleared back to
    /// `address(0)` once the transfer returns.
    address public transient override originalPayer;

    //*********************************************************************//
    // -------------------------- constructor ---------------------------- //
    //*********************************************************************//

    /// @param owner The owner of the contract who can set metadata.
    /// @param feeProjectOwner The address that will receive the fee-project. If `address(0)` the fee-project will not
    /// be minted.
    /// @param trustedForwarder The trusted forwarder for the ERC2771Context.
    constructor(
        address owner,
        address feeProjectOwner,
        address trustedForwarder
    )
        ERC721("Juicebox Projects", "JUICEBOX")
        Ownable(owner)
        ERC2771Context(trustedForwarder)
    {
        if (feeProjectOwner != address(0)) {
            createFor(feeProjectOwner);
        }
    }

    //*********************************************************************//
    // ---------------------- external transactions ---------------------- //
    //*********************************************************************//

    /// @notice Set the native-token fee required to create a project and the address that receives it.
    /// @dev Only this contract's owner can change the fee. A non-zero fee requires a non-zero receiver. The fee may
    /// not exceed `MAX_CREATION_FEE`.
    /// @param fee The required creation fee. Set to 0 to disable creation fees. Must be `<= MAX_CREATION_FEE`.
    /// @param receiver The address that receives project creation fees.
    function setCreationFee(uint256 fee, address payable receiver) external override onlyOwner {
        // Enforce the hardcoded ceiling so the owner can never price project creation out of reach.
        if (fee > MAX_CREATION_FEE) revert JBProjects_CreationFeeExceedsMax({fee: fee, max: MAX_CREATION_FEE});

        // Non-zero fees need somewhere to go.
        if (fee != 0 && receiver == address(0)) revert JBProjects_ZeroCreationFeeReceiver();

        // Store the fee configuration.
        creationFee = fee;
        creationFeeReceiver = receiver;

        emit SetCreationFee({fee: fee, receiver: receiver, caller: _msgSender()});
    }

    /// @notice Set the contract that resolves project NFT metadata (the `tokenURI`). This controls what artwork and
    /// JSON metadata is returned for each project's ERC-721 token.
    /// @dev Only this contract's owner can change the resolver.
    /// @param resolver The address of the new resolver.
    function setTokenUriResolver(IJBTokenUriResolver resolver) external override onlyOwner {
        // Store the new resolver.
        tokenUriResolver = resolver;

        emit SetTokenUriResolver({resolver: resolver, caller: _msgSender()});
    }

    //*********************************************************************//
    // ----------------------- public transactions ----------------------- //
    //*********************************************************************//

    /// @notice Create a new project for the specified owner, which mints an NFT (ERC-721) into their wallet.
    /// @dev Anyone can create a project on an owner's behalf.
    /// @dev Requires exactly `creationFee` native tokens. The fee is forwarded after the project NFT is minted.
    /// @param owner The address that will be the owner of the project.
    /// @return projectId The token ID of the newly created project.
    function createFor(address owner) public payable override returns (uint256 projectId) {
        // Keep a reference to the fee. It must be paid exactly to avoid accidental overpayment.
        uint256 fee = creationFee;
        if (msg.value != fee) revert JBProjects_InvalidCreationFee({value: msg.value, requiredFee: fee});

        // Increment the count, which will be used as the ID.
        projectId = ++count;

        emit Create({projectId: projectId, owner: owner, caller: _msgSender()});

        // Mint the project.
        _safeMint({to: owner, tokenId: projectId});

        // Forward the fee if one is configured.
        if (fee != 0) {
            address payable receiver = creationFeeReceiver;
            if (receiver == address(0)) revert JBProjects_ZeroCreationFeeReceiver();

            // Resolve and expose the fee payer so a `pay`-routing fee receiver credits the account that paid the
            // fee, not an intermediary. The caller may itself be an `IJBPayerTracker` (a deployer/controller
            // forwarding a user's fee), in which case its upstream payer is used. Cleared immediately after.
            originalPayer = JBPayerTrackerLib.resolve(_msgSender());
            Address.sendValue({recipient: receiver, amount: fee});
            originalPayer = address(0);
        }
    }

    //*********************************************************************//
    // -------------------------- public views --------------------------- //
    //*********************************************************************//

    /// @notice Indicates whether this contract adheres to the specified interface.
    /// @dev See {IERC165-supportsInterface}.
    /// @param interfaceId The ID of the interface to check for adherence to.
    /// @return A flag indicating if the provided interface ID is supported.
    function supportsInterface(bytes4 interfaceId) public view virtual override(IERC165, ERC721) returns (bool) {
        return interfaceId == type(IJBProjects).interfaceId || interfaceId == type(IJBPayerTracker).interfaceId
            || super.supportsInterface(interfaceId);
    }

    /// @notice Returns the URI where the ERC-721 standard JSON of a project is hosted.
    /// @param projectId The ID of the project to get a URI of.
    /// @return The token URI to use for the provided `projectId`.
    function tokenURI(uint256 projectId) public view override returns (string memory) {
        // Keep a reference to the resolver.
        IJBTokenUriResolver resolver = tokenUriResolver;

        // If there's no resolver, there's no URI.
        if (resolver == IJBTokenUriResolver(address(0))) return "";

        // Return the resolved URI.
        return resolver.getUri(projectId);
    }

    //*********************************************************************//
    // -------------------------- internal views ------------------------- //
    //*********************************************************************//

    /// @dev `ERC-2771` specifies the context as being a single address (20 bytes).
    function _contextSuffixLength() internal view override(ERC2771Context, Context) returns (uint256) {
        return super._contextSuffixLength();
    }

    /// @notice The calldata. Preferred to use over `msg.data`.
    /// @return calldata The `msg.data` of this call.
    function _msgData() internal view override(ERC2771Context, Context) returns (bytes calldata) {
        return ERC2771Context._msgData();
    }

    /// @notice The message's sender. Preferred to use over `msg.sender`.
    /// @return sender The address which sent this call.
    function _msgSender() internal view override(ERC2771Context, Context) returns (address sender) {
        return ERC2771Context._msgSender();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {mulDiv} from "@prb/math/src/Common.sol";

import {JBControlled} from "./abstract/JBControlled.sol";
import {JBApprovalStatus} from "./enums/JBApprovalStatus.sol";
import {IJBDirectory} from "./interfaces/IJBDirectory.sol";
import {IJBRulesetApprovalHook} from "./interfaces/IJBRulesetApprovalHook.sol";
import {IJBRulesets} from "./interfaces/IJBRulesets.sol";
import {JBConstants} from "./libraries/JBConstants.sol";
import {JBRuleset} from "./structs/JBRuleset.sol";
import {JBRulesetWeightCache} from "./structs/JBRulesetWeightCache.sol";

/// @notice Stores and manages the economic rules for every Juicebox project. A "ruleset" defines how a project behaves
/// for a period of time: its token issuance weight, cash-out tax rate, payout limits, reserved rate, and more.
/// Projects queue future rulesets to schedule changes; once a ruleset's duration expires, the next approved ruleset
/// takes effect automatically.
/// @dev Rulesets form a linked list via `basedOnId`. Each ruleset ID is the unix timestamp when it was first stored.
/// Weight decays across cycles using `weightCutPercent` — if many cycles elapse, the decay is computed iteratively
/// (capped at 20,000 iterations; use `updateRulesetWeightCache` for longer gaps). Approval hooks can gate whether a
/// queued ruleset actually takes effect.
contract JBRulesets is JBControlled, IJBRulesets {
    //*********************************************************************//
    // --------------------------- custom errors ------------------------- //
    //*********************************************************************//

    /// @notice Thrown when the approval hook is not a contract or does not support the `IJBRulesetApprovalHook`
    /// interface.
    error JBRulesets_InvalidRulesetApprovalHook(IJBRulesetApprovalHook hook);

    /// @notice Thrown when the ruleset duration exceeds the uint32 maximum.
    error JBRulesets_InvalidRulesetDuration(uint256 duration, uint256 limit);

    /// @notice Thrown when the ruleset's start plus duration exceeds the uint48 maximum.
    error JBRulesets_InvalidRulesetEndTime(uint256 timestamp, uint256 limit);

    /// @notice Thrown when the ruleset weight exceeds the uint112 maximum.
    error JBRulesets_InvalidWeight(uint256 weight, uint256 limit);

    /// @notice Thrown when the weight cut percent exceeds 100%.
    error JBRulesets_InvalidWeightCutPercent(uint256 percent);

    /// @notice Thrown when too many weight-cut iterations remain and the weight cache must be populated first.
    error JBRulesets_WeightCacheRequired(uint256 projectId);

    //*********************************************************************//
    // ------------------------- internal constants ----------------------- //
    //*********************************************************************//

    /// @notice The maximum number of weight cut iterations allowed per call.
    /// If more cycles are needed, callers must populate the cache via updateRulesetWeightCache() first.
    uint256 internal constant _WEIGHT_CUT_MULTIPLE_CACHE_LOOKUP_THRESHOLD = 20_000;

    //*********************************************************************//
    // --------------------- public stored properties -------------------- //
    //*********************************************************************//

    /// @notice The ID of the ruleset with the latest start time for a specific project, whether the ruleset has been
    /// approved or not.
    /// @dev If a project has multiple rulesets queued, `latestRulesetIdOf` is the last "changeable" cycle.
    /// @custom:param projectId The ID of the project to get the latest ruleset ID of.
    /// @return latestRulesetIdOf The `rulesetId` of the project's latest ruleset.
    mapping(uint256 projectId => uint256) public override latestRulesetIdOf;

    //*********************************************************************//
    // --------------------- internal stored properties ------------------- //
    //*********************************************************************//

    /// @notice The metadata for each ruleset, packed into one storage slot.
    /// @custom:param projectId The ID of the project to get metadata of.
    /// @custom:param rulesetId The ID of the ruleset to get metadata of.
    mapping(uint256 projectId => mapping(uint256 rulesetId => uint256)) internal _metadataOf;

    /// @notice The mechanism-added properties to manage and schedule each ruleset, packed into one storage slot.
    /// @custom:param projectId The ID of the project to get the intrinsic properties of.
    /// @custom:param rulesetId The ID of the ruleset to get the intrinsic properties of.
    mapping(uint256 projectId => mapping(uint256 rulesetId => uint256)) internal _packedIntrinsicPropertiesOf;

    /// @notice The user-defined properties of each ruleset, packed into one storage slot.
    /// @custom:param projectId The ID of the project to get the user-defined properties of.
    /// @custom:param rulesetId The ID of the ruleset to get the user-defined properties of.
    mapping(uint256 projectId => mapping(uint256 rulesetId => uint256)) internal _packedUserPropertiesOf;

    /// @notice Cached weight values to derive rulesets from.
    /// @custom:param projectId The ID of the project to which the cache applies.
    /// @custom:param rulesetId The ID of the ruleset to which the cache applies.
    mapping(uint256 projectId => mapping(uint256 rulesetId => JBRulesetWeightCache)) internal _weightCacheOf;

    //*********************************************************************//
    // -------------------------- constructor ---------------------------- //
    //*********************************************************************//

    /// @param directory A contract storing directories of terminals and controllers for each project.
    // solhint-disable-next-line no-empty-blocks
    constructor(IJBDirectory directory) JBControlled(directory) {}

    //*********************************************************************//
    // ---------------------- external transactions ---------------------- //
    //*********************************************************************//

    /// @notice Queues a new ruleset for a project. The ruleset takes effect after the current one ends (or immediately
    /// if the current ruleset has `duration = 0`). Must be approved by the previous ruleset's approval hook.
    /// @dev Only the project's current controller can call this.
    /// @dev A latest queued ruleset with `ApprovalExpected` can still be replaced within its scheduled cycle, but can
    /// be used as the base for a later cycle because it is expected to become `Approved` unless replaced. A latest
    /// queued ruleset with `Approved` is final for its scheduled cycle; later queued rulesets derive from it.
    /// @param projectId The ID of the project to queue the ruleset for.
    /// @param duration How long the ruleset lasts (seconds). 0 = no auto-cycling (stays active until explicitly
    /// replaced). When a duration ends without a queued replacement, the ruleset rolls over with decayed weight.
    /// @param weight Tokens minted per unit paid (18 decimals). Terminals divide payment amount by weight to determine
    /// issuance. A value of 1 means "inherit decayed weight from previous ruleset".
    /// @param weightCutPercent How much to reduce weight each auto-cycle, out of
    /// `JBConstants.MAX_WEIGHT_CUT_PERCENT`. Only applies when no explicit replacement is queued. 0 = no decay.
    /// 100,000,000 = 10% cut per cycle.
    /// @param approvalHook A contract that gates whether the *next* queued ruleset can take effect (e.g. `JBDeadline`
    /// for minimum notice periods). Set to address(0) for no approval gate.
    /// @param metadata Packed 256-bit field decoded by `JBRulesetMetadataResolver`. Not used by `JBRulesets` itself.
    /// @param mustStartAtOrAfter The earliest unix timestamp the ruleset can start.
    /// @return The struct of the new ruleset.
    function queueFor(
        uint256 projectId,
        uint256 duration,
        uint256 weight,
        uint256 weightCutPercent,
        IJBRulesetApprovalHook approvalHook,
        uint256 metadata,
        uint256 mustStartAtOrAfter
    )
        external
        override
        onlyControllerOf(projectId)
        returns (JBRuleset memory)
    {
        // Duration must fit in a uint32.
        if (duration > type(uint32).max) revert JBRulesets_InvalidRulesetDuration(duration, type(uint32).max);

        // Weight cut percent must be less than or equal to 100%.
        if (weightCutPercent > JBConstants.MAX_WEIGHT_CUT_PERCENT) {
            revert JBRulesets_InvalidWeightCutPercent({percent: weightCutPercent});
        }

        // Weight must fit into a uint112.
        if (weight > type(uint112).max) revert JBRulesets_InvalidWeight(weight, type(uint112).max);

        // If the start date is not set, set it to be the current timestamp.
        if (mustStartAtOrAfter == 0) {
            mustStartAtOrAfter = block.timestamp;
        }

        // Make sure the min start date fits in a uint48, and that the start date of the following ruleset will also fit
        // within the max.
        if (mustStartAtOrAfter + duration > type(uint48).max) {
            revert JBRulesets_InvalidRulesetEndTime({timestamp: mustStartAtOrAfter + duration, limit: type(uint48).max});
        }

        // Approval hook should be a valid contract, supporting the correct interface
        if (approvalHook != IJBRulesetApprovalHook(address(0))) {
            // Revert if there isn't a contract at the address
            if (address(approvalHook).code.length == 0) revert JBRulesets_InvalidRulesetApprovalHook(approvalHook);

            // Make sure the approval hook supports the expected interface.
            try approvalHook.supportsInterface(type(IJBRulesetApprovalHook).interfaceId) returns (bool doesSupport) {
                if (!doesSupport) revert JBRulesets_InvalidRulesetApprovalHook(approvalHook); // Contract exists at the
                // address but
                // with the
                // wrong interface
            } catch {
                revert JBRulesets_InvalidRulesetApprovalHook({hook: approvalHook}); // No ERC165 support
            }
        }

        // Get a reference to the latest ruleset's ID.
        uint256 latestId = latestRulesetIdOf[projectId];

        // The new rulesetId timestamp is now, or an increment from now if the current timestamp is taken.
        // forge-lint: disable-next-line(block-timestamp)
        uint256 rulesetId = latestId >= block.timestamp ? latestId + 1 : block.timestamp;

        // Set up the ruleset by configuring intrinsic properties.
        _configureIntrinsicPropertiesFor({
            projectId: projectId, rulesetId: rulesetId, weight: weight, mustStartAtOrAfter: mustStartAtOrAfter
        });

        // Efficiently stores the ruleset's user-defined properties.
        // If all user config properties are zero, no need to store anything as the default value will have the same
        // outcome.
        if (approvalHook != IJBRulesetApprovalHook(address(0)) || duration > 0 || weightCutPercent > 0) {
            // approval hook in bits 0-159 bytes.
            uint256 packed = uint160(address(approvalHook));

            // duration in bits 160-191 bytes.
            packed |= duration << 160;

            // weightCutPercent in bits 192-223 bytes.
            packed |= weightCutPercent << 192;

            // Set in storage.
            _packedUserPropertiesOf[projectId][rulesetId] = packed;
        }

        // Set the metadata if needed.
        if (metadata > 0) _metadataOf[projectId][rulesetId] = metadata;

        emit RulesetQueued({
            rulesetId: rulesetId,
            projectId: projectId,
            duration: duration,
            weight: weight,
            weightCutPercent: weightCutPercent,
            approvalHook: approvalHook,
            metadata: metadata,
            mustStartAtOrAfter: mustStartAtOrAfter,
            caller: msg.sender
        });

        // Return the struct for the new ruleset's ID, with metadata.
        return _getStructFor({projectId: projectId, rulesetId: rulesetId, withMetadata: true});
    }

    /// @notice Cache the value of the ruleset weight for a specific ruleset.
    /// @dev The caller should pass the ruleset ID that `currentOf()` actually uses. When a queued ruleset is rejected
    /// by an approval hook, `currentOf()` falls back to the base ruleset, not the rejected latest.
    /// @param projectId The ID of the project having its ruleset weight cached.
    /// @param rulesetId The ID of the ruleset to update the cache for.
    function updateRulesetWeightCache(uint256 projectId, uint256 rulesetId) external override {
        // Get the target ruleset.
        JBRuleset memory targetRuleset =
            _getStructFor({projectId: projectId, rulesetId: rulesetId, withMetadata: false});

        // Nothing to cache if the target ruleset doesn't have a duration or a weight cut percent.
        if (targetRuleset.duration == 0 || targetRuleset.weightCutPercent == 0) return;

        // Get a reference to the current cache.
        JBRulesetWeightCache storage cache = _weightCacheOf[projectId][targetRuleset.id];

        // Determine the largest start timestamp the cache can be filled to.
        // Cap the advance to the cache lookup threshold per call to stay within the iteration limit in
        // deriveWeightFrom.
        // Multiple calls are needed to advance the cache for large cycle gaps.
        uint256 maxStart = targetRuleset.start + (cache.weightCutMultiple + _WEIGHT_CUT_MULTIPLE_CACHE_LOOKUP_THRESHOLD)
            * targetRuleset.duration;

        // Determine the start timestamp to derive a weight from for the cache.
        // forge-lint: disable-next-line(block-timestamp)
        uint256 start = block.timestamp < maxStart ? block.timestamp : maxStart;

        // The difference between the start of the latest queued ruleset and the start of the ruleset we're caching the
        // weight of.
        uint256 startDistance = start - targetRuleset.start;

        // Calculate the weight cut multiple.
        uint168 weightCutMultiple;
        unchecked {
            // forge-lint: disable-next-line(unsafe-typecast)
            weightCutMultiple = uint168(startDistance / targetRuleset.duration);
        }

        // Store the new values.
        cache.weight = uint112(
            deriveWeightFrom({
                projectId: projectId,
                baseRulesetStart: targetRuleset.start,
                baseRulesetDuration: targetRuleset.duration,
                baseRulesetWeight: targetRuleset.weight,
                baseRulesetWeightCutPercent: targetRuleset.weightCutPercent,
                baseRulesetCacheId: targetRuleset.id,
                start: start
            })
        );
        cache.weightCutMultiple = weightCutMultiple;

        emit WeightCacheUpdated({
            projectId: projectId, weight: cache.weight, weightCutMultiple: weightCutMultiple, caller: msg.sender
        });
    }

    //*********************************************************************//
    // ------------------------- external views -------------------------- //
    //*********************************************************************//

    /// @notice Returns a paginated history of a project's rulesets, sorted newest-first.
    /// @param projectId The ID of the project to get the rulesets of.
    /// @param startingId The ID of the ruleset to begin with. This will be the latest ruleset in the result. If 0 is
    /// passed, the project's latest ruleset will be used.
    /// @param size The maximum number of rulesets to return.
    /// @return rulesets The rulesets as an array of `JBRuleset` structs.
    function allOf(
        uint256 projectId,
        uint256 startingId,
        uint256 size
    )
        external
        view
        override
        returns (JBRuleset[] memory rulesets)
    {
        // If no starting ID was provided, set it to the latest ruleset's ID.
        if (startingId == 0) startingId = latestRulesetIdOf[projectId];

        // Keep a reference to the number of rulesets being returned.
        uint256 count = 0;

        // Keep a reference to the starting ruleset (metadata not needed — only counting).
        JBRuleset memory ruleset = _getStructFor({projectId: projectId, rulesetId: startingId, withMetadata: false});

        // First, count the number of rulesets to include in the result by iterating backwards from the starting
        // ruleset.
        while (ruleset.id != 0 && count < size) {
            // Increment the counter.
            count++;

            // Iterate to the ruleset it was based on.
            ruleset = _getStructFor({projectId: projectId, rulesetId: ruleset.basedOnId, withMetadata: false});
        }

        // Keep a reference to the array of rulesets that'll be populated.
        rulesets = new JBRuleset[](count);

        // Return an empty array if there are no rulesets to return.
        if (count == 0) {
            return rulesets;
        }

        // Reset the ruleset being iterated on to the starting ruleset, now with metadata for the return array.
        ruleset = _getStructFor({projectId: projectId, rulesetId: startingId, withMetadata: true});

        // Set the counter.
        uint256 i;

        // Populate the array of rulesets to return.
        while (i < count) {
            // Add the ruleset to the array.
            rulesets[i++] = ruleset;

            // Get the ruleset it was based on if needed, with metadata for the return array.
            if (i != count) {
                ruleset = _getStructFor({projectId: projectId, rulesetId: ruleset.basedOnId, withMetadata: true});
            }
        }
    }

    /// @notice Whether the project's most recently queued ruleset has been approved, rejected, or is still pending.
    /// @param projectId The ID of the project to check the approval status of.
    /// @return The project's current approval status.
    function currentApprovalStatusForLatestRulesetOf(uint256 projectId)
        external
        view
        override
        returns (JBApprovalStatus)
    {
        // Get a reference to the latest ruleset ID.
        uint256 rulesetId = latestRulesetIdOf[projectId];

        // Resolve the struct for the latest ruleset, with metadata (forwarded to the external approval hook).
        JBRuleset memory ruleset = _getStructFor({projectId: projectId, rulesetId: rulesetId, withMetadata: true});

        return _approvalStatusOf({projectId: projectId, ruleset: ruleset});
    }

    /// @notice Returns the ruleset currently governing a project. If the stored ruleset has auto-cycled, simulates
    /// cycling with weight decay and returns the simulated current cycle.
    /// @dev Returns an empty ruleset (all zeros) if the project has never had a ruleset queued.
    /// @dev Payout limits reset each cycle (keyed by `cycleNumber`), but the `rulesetId` stays the same across
    /// auto-cycles of the same stored ruleset.
    /// @param projectId The ID of the project to get the current ruleset of.
    /// @return ruleset The project's current ruleset.
    function currentOf(uint256 projectId) external view override returns (JBRuleset memory ruleset) {
        // If the project does not have a ruleset, return an empty struct.
        if (latestRulesetIdOf[projectId] == 0) {
            return _getStructFor({projectId: 0, rulesetId: 0, withMetadata: false});
        }

        // Get a reference to the currently approvable ruleset's ID.
        uint256 rulesetId = _currentlyApprovableRulesetIdOf(projectId);

        // If a currently approvable ruleset exists...
        if (rulesetId != 0) {
            // Resolve the struct for the currently approvable ruleset, with metadata (forwarded to external hooks
            // and potentially returned).
            ruleset = _getStructFor({projectId: projectId, rulesetId: rulesetId, withMetadata: true});

            // Get a reference to the approval status.
            JBApprovalStatus approvalStatus = _approvalStatusOf({projectId: projectId, ruleset: ruleset});

            // Check to see if this ruleset's approval hook is approved if it exists.
            // If so, return it.
            if (approvalStatus == JBApprovalStatus.Approved || approvalStatus == JBApprovalStatus.Empty) {
                return ruleset;
            }

            // If it hasn't been approved, set the ruleset configuration to be the configuration of the ruleset that
            // it's based on,
            // which carries the last approved configuration.
            rulesetId = ruleset.basedOnId;

            // Keep a reference to its ruleset, with metadata (used by `_simulateCycledRulesetBasedOn` and may be
            // returned).
            ruleset = _getStructFor({projectId: projectId, rulesetId: rulesetId, withMetadata: true});
        } else {
            // No upcoming ruleset found that is currently approvable,
            // so use the latest ruleset ID.
            rulesetId = latestRulesetIdOf[projectId];

            // Get the struct for the latest ID, with metadata (forwarded to external hooks and may be returned).
            ruleset = _getStructFor({projectId: projectId, rulesetId: rulesetId, withMetadata: true});

            // Get a reference to the approval status.
            JBApprovalStatus approvalStatus = _approvalStatusOf({projectId: projectId, ruleset: ruleset});

            // While the ruleset has an approval hook that isn't approved or if it hasn't yet started, get a reference
            // to the ruleset that the latest is based on, which has the latest approved configuration.
            while (
                (approvalStatus != JBApprovalStatus.Approved && approvalStatus != JBApprovalStatus.Empty)
                    // forge-lint: disable-next-line(block-timestamp)
                    || block.timestamp < ruleset.start
            ) {
                rulesetId = ruleset.basedOnId;
                ruleset = _getStructFor({projectId: projectId, rulesetId: rulesetId, withMetadata: true});
                approvalStatus = _approvalStatusOf({projectId: projectId, ruleset: ruleset});
            }
        }

        // If the base has no duration, it's still the current one.
        if (ruleset.duration == 0) return ruleset;

        // Return a simulation of the current ruleset.
        return _simulateCycledRulesetBasedOn({projectId: projectId, baseRuleset: ruleset, allowMidRuleset: true});
    }

    /// @notice Get the ruleset struct for a given `rulesetId` and `projectId`.
    /// @param projectId The ID of the project to which the ruleset belongs.
    /// @param rulesetId The ID of the ruleset to get the struct of.
    /// @return ruleset The ruleset struct.
    function getRulesetOf(
        uint256 projectId,
        uint256 rulesetId
    )
        external
        view
        override
        returns (JBRuleset memory ruleset)
    {
        ruleset = _getStructFor({projectId: projectId, rulesetId: rulesetId, withMetadata: true});
    }

    /// @notice The latest ruleset queued for a project. Returns the ruleset's struct and its current approval status.
    /// @dev Returns struct and status for the ruleset initialized furthest in the future (at the end of the ruleset
    /// queue).
    /// @param projectId The ID of the project to get the latest queued ruleset of.
    /// @return ruleset The project's latest queued ruleset's struct.
    /// @return approvalStatus The approval hook's status for the ruleset.
    function latestQueuedOf(uint256 projectId)
        external
        view
        override
        returns (JBRuleset memory ruleset, JBApprovalStatus approvalStatus)
    {
        // Get a reference to the latest ruleset's ID.
        uint256 rulesetId = latestRulesetIdOf[projectId];

        // Resolve the struct for the latest ruleset, with metadata (forwarded to the external approval hook and
        // returned).
        ruleset = _getStructFor({projectId: projectId, rulesetId: rulesetId, withMetadata: true});

        // Resolve the approval status.
        approvalStatus = _approvalStatusOf({projectId: projectId, ruleset: ruleset});
    }

    /// @notice Returns the ruleset that will take effect after the current one ends. This could be an explicitly queued
    /// ruleset or a simulated auto-cycle of the current one (with decayed weight).
    /// @dev Returns an empty ruleset (all zeros) if there is no upcoming ruleset.
    /// @param projectId The ID of the project to get the upcoming ruleset of.
    /// @return ruleset The struct for the project's upcoming ruleset.
    function upcomingOf(uint256 projectId) external view override returns (JBRuleset memory ruleset) {
        // If the project does not have a latest ruleset, return an empty struct.
        if (latestRulesetIdOf[projectId] == 0) {
            return _getStructFor({projectId: 0, rulesetId: 0, withMetadata: false});
        }

        // Get a reference to the upcoming approvable ruleset's ID.
        uint256 upcomingApprovableRulesetId = _upcomingApprovableRulesetIdOf(projectId);

        // Keep a reference to its approval status.
        JBApprovalStatus approvalStatus;

        // If an upcoming approvable ruleset has been queued, and its approval status is Approved or ApprovalExpected,
        // return its ruleset struct
        if (upcomingApprovableRulesetId != 0) {
            ruleset = _getStructFor({projectId: projectId, rulesetId: upcomingApprovableRulesetId, withMetadata: true});

            // Get a reference to the approval status.
            approvalStatus = _approvalStatusOf({projectId: projectId, ruleset: ruleset});

            // If the approval hook is empty, expects approval, or has approved the ruleset, return it.
            if (
                approvalStatus == JBApprovalStatus.Approved || approvalStatus == JBApprovalStatus.ApprovalExpected
                    || approvalStatus == JBApprovalStatus.Empty
            ) return ruleset;

            // Resolve the ruleset for the ruleset the upcoming approvable ruleset was based on, with metadata
            // (used by `_simulateCycledRulesetBasedOn`).
            ruleset = _getStructFor({projectId: projectId, rulesetId: ruleset.basedOnId, withMetadata: true});
        } else {
            // Resolve the ruleset for the latest queued ruleset, with metadata (forwarded to external hooks and used
            // by `_simulateCycledRulesetBasedOn`).
            ruleset = _getStructFor({projectId: projectId, rulesetId: latestRulesetIdOf[projectId], withMetadata: true});

            // If the latest ruleset starts in the future, it must start in the distant future
            // Since it's not the upcoming approvable ruleset. In this case, base the upcoming ruleset on the base
            // ruleset.
            // forge-lint: disable-next-line(block-timestamp)
            while (ruleset.start > block.timestamp) {
                ruleset = _getStructFor({projectId: projectId, rulesetId: ruleset.basedOnId, withMetadata: true});
            }
        }

        // There's no queued if the current has a duration of 0.
        if (ruleset.duration == 0) return _getStructFor({projectId: 0, rulesetId: 0, withMetadata: false});

        // Get a reference to the approval status.
        approvalStatus = _approvalStatusOf({projectId: projectId, ruleset: ruleset});

        // Check to see if this ruleset's approval hook hasn't failed.
        // If so, return a ruleset based on it.
        if (approvalStatus == JBApprovalStatus.Approved || approvalStatus == JBApprovalStatus.Empty) {
            return _simulateCycledRulesetBasedOn({projectId: projectId, baseRuleset: ruleset, allowMidRuleset: false});
        }

        // Get the ruleset of its base ruleset, which carries the last approved configuration. Metadata is needed by
        // `_simulateCycledRulesetBasedOn`.
        ruleset = _getStructFor({projectId: projectId, rulesetId: ruleset.basedOnId, withMetadata: true});

        // There's no queued if the base, which must still be the current, has a duration of 0.
        if (ruleset.duration == 0) return _getStructFor({projectId: 0, rulesetId: 0, withMetadata: false});

        // Return a simulated cycled ruleset.
        return _simulateCycledRulesetBasedOn({projectId: projectId, baseRuleset: ruleset, allowMidRuleset: false});
    }

    //*********************************************************************//
    // --------------------------- public views -------------------------- //
    //*********************************************************************//

    /// @notice The cycle number of the next ruleset given the specified ruleset.
    /// @dev Each time a ruleset starts, whether it was queued or cycled over, the cycle number is incremented by 1.
    /// @param baseRulesetCycleNumber The cycle number of the base ruleset.
    /// @param baseRulesetStart The start time of the base ruleset.
    /// @param baseRulesetDuration The duration of the base ruleset.
    /// @param start The start time of the ruleset to derive a cycle number for.
    /// @return The ruleset's cycle number.
    function deriveCycleNumberFrom(
        uint256 baseRulesetCycleNumber,
        uint256 baseRulesetStart,
        uint256 baseRulesetDuration,
        uint256 start
    )
        public
        pure
        returns (uint256)
    {
        // A subsequent ruleset to one with a duration of 0 should be the next number.
        if (baseRulesetDuration == 0) {
            return baseRulesetCycleNumber + 1;
        }

        // The difference between the start of the base ruleset and the proposed start.
        uint256 startDistance = start - baseRulesetStart;

        // Find the number of base rulesets that fit in the start distance.
        return baseRulesetCycleNumber + (startDistance / baseRulesetDuration);
    }

    /// @notice The date that is the nearest multiple of the base ruleset's duration from the start of the next cycle.
    /// @param baseRulesetStart The start time of the base ruleset.
    /// @param baseRulesetDuration The duration of the base ruleset.
    /// @param mustStartAtOrAfter The earliest timestamp the next ruleset can start at.
    /// @return start The next start time.
    function deriveStartFrom(
        uint256 baseRulesetStart,
        uint256 baseRulesetDuration,
        uint256 mustStartAtOrAfter
    )
        public
        pure
        returns (uint256 start)
    {
        // A subsequent ruleset to one with a duration of 0 should start as soon as possible.
        if (baseRulesetDuration == 0) return mustStartAtOrAfter;

        // The time when the ruleset immediately after the specified ruleset starts.
        uint256 nextImmediateStart = baseRulesetStart + baseRulesetDuration;

        // If the next immediate start is now or in the future, return it.
        if (nextImmediateStart >= mustStartAtOrAfter) {
            return nextImmediateStart;
        }

        // The amount of seconds since the `mustStartAtOrAfter` time which results in a start time that might satisfy
        // the specified limits.
        uint256 timeFromImmediateStartMultiple = (mustStartAtOrAfter - nextImmediateStart) % baseRulesetDuration;

        // A reference to the first possible start timestamp.
        start = mustStartAtOrAfter - timeFromImmediateStartMultiple;

        // Add increments of duration as necessary to satisfy the threshold.
        while (mustStartAtOrAfter > start) {
            start += baseRulesetDuration;
        }
    }

    /// @notice The accumulated weight change since the specified ruleset.
    /// @param projectId The ID of the project to which the ruleset weights apply.
    /// @param baseRulesetStart The start time of the base ruleset.
    /// @param baseRulesetDuration The duration of the base ruleset.
    /// @param baseRulesetWeight The weight of the base ruleset.
    /// @param baseRulesetWeightCutPercent The weight cut percent of the base ruleset, out of
    /// `JBConstants.MAX_WEIGHT_CUT_PERCENT`.
    /// @param baseRulesetCacheId The ID of the ruleset to base the calculation on (the previous ruleset).
    /// @param start The start time of the ruleset to derive a weight for.
    /// @return weight The derived weight, as a fixed point number with 18 decimals.
    function deriveWeightFrom(
        uint256 projectId,
        uint256 baseRulesetStart,
        uint256 baseRulesetDuration,
        uint256 baseRulesetWeight,
        uint256 baseRulesetWeightCutPercent,
        uint256 baseRulesetCacheId,
        uint256 start
    )
        public
        view
        returns (uint256 weight)
    {
        // A subsequent ruleset to one with a duration of 0 should have the next possible weight.
        if (baseRulesetDuration == 0) {
            return mulDiv({
                x: baseRulesetWeight,
                y: JBConstants.MAX_WEIGHT_CUT_PERCENT - baseRulesetWeightCutPercent,
                denominator: JBConstants.MAX_WEIGHT_CUT_PERCENT
            });
        }

        // The weight should be based off the base ruleset's weight.
        weight = baseRulesetWeight;

        // If the weight cut percent is 0, the weight doesn't change.
        if (baseRulesetWeightCutPercent == 0) return weight;

        // The difference between the start of the base ruleset and the proposed start.
        uint256 startDistance = start - baseRulesetStart;

        // Apply the base ruleset's weight cut percent for each ruleset that has passed.
        uint256 weightCutMultiple;
        unchecked {
            weightCutMultiple = startDistance / baseRulesetDuration; // Non-null duration is excluded above
        }

        // Check the cache if needed.
        if (baseRulesetCacheId > 0 && weightCutMultiple > _WEIGHT_CUT_MULTIPLE_CACHE_LOOKUP_THRESHOLD) {
            // Get a cached weight for the rulesetId.
            JBRulesetWeightCache memory cache = _weightCacheOf[projectId][baseRulesetCacheId];

            // If a cached value is available, use it.
            if (cache.weightCutMultiple > 0) {
                // Set the starting weight to be the cached value.
                weight = cache.weight;

                // Set the weight cut multiple to be the difference between the cached value and the total weight cut
                // multiple that should be applied.
                weightCutMultiple -= cache.weightCutMultiple;
            }
        }

        // If too many iterations remain after cache lookup, require the cache to be populated first.
        // This prevents gas exhaustion for short-duration rulesets with large cycle counts.
        if (weightCutMultiple > _WEIGHT_CUT_MULTIPLE_CACHE_LOOKUP_THRESHOLD) {
            revert JBRulesets_WeightCacheRequired({projectId: projectId});
        }

        // Cache the cut factor and max percent to avoid recomputing each iteration.
        uint256 cutFactor = JBConstants.MAX_WEIGHT_CUT_PERCENT - baseRulesetWeightCutPercent;
        uint256 maxPercent = JBConstants.MAX_WEIGHT_CUT_PERCENT;

        for (uint256 i; i < weightCutMultiple;) {
            // Base the new weight on the specified ruleset's weight.
            weight = mulDiv({x: weight, y: cutFactor, denominator: maxPercent});

            // The calculation doesn't need to continue if the weight is 0.
            if (weight == 0) break;
            unchecked {
                ++i;
            }
        }
    }

    //*********************************************************************//
    // ---------------------- internal transactions ---------------------- //
    //*********************************************************************//

    /// @notice Updates the latest ruleset for this project if it exists. If there is no ruleset, initializes one.
    /// @param projectId The ID of the project to update the latest ruleset for.
    /// @param rulesetId The timestamp of when the ruleset was queued.
    /// @param weight The weight to store in the queued ruleset.
    /// @param mustStartAtOrAfter The earliest timestamp the ruleset can start at.
    function _configureIntrinsicPropertiesFor(
        uint256 projectId,
        uint256 rulesetId,
        uint256 weight,
        uint256 mustStartAtOrAfter
    )
        internal
    {
        // Keep a reference to the project's latest ruleset's ID.
        uint256 latestId = latestRulesetIdOf[projectId];

        // If the project doesn't have a ruleset yet, initialize one.
        if (latestId == 0) {
            // Use an empty ruleset as the base.
            return _initializeRulesetFor({
                projectId: projectId,
                baseRuleset: _getStructFor({projectId: 0, rulesetId: 0, withMetadata: false}),
                rulesetId: rulesetId,
                mustStartAtOrAfter: mustStartAtOrAfter,
                weight: weight
            });
        }

        // Get a reference to the latest ruleset's struct, with metadata because `_approvalStatusOf` forwards the
        // struct to external approval hooks.
        JBRuleset memory baseRuleset = _getStructFor({projectId: projectId, rulesetId: latestId, withMetadata: true});

        // Get a reference to the approval status.
        JBApprovalStatus approvalStatus = _approvalStatusOf({projectId: projectId, ruleset: baseRuleset});

        // If the base ruleset has started but wasn't approved if an approval hook exists
        // OR it hasn't started but is currently approved
        // OR it hasn't started but it is likely to be approved and takes place before the proposed one,
        // set the struct to be the ruleset it's based on, which carries the latest approved ruleset.
        if (
            // forge-lint: disable-next-line(block-timestamp)
            (block.timestamp >= baseRuleset.start
                    && approvalStatus != JBApprovalStatus.Approved
                    && approvalStatus != JBApprovalStatus.Empty)
                // forge-lint: disable-next-line(block-timestamp)
                || (block.timestamp < baseRuleset.start
                    && mustStartAtOrAfter < baseRuleset.start + baseRuleset.duration
                    && approvalStatus != JBApprovalStatus.Approved)
                // forge-lint: disable-next-line(block-timestamp)
                || (block.timestamp < baseRuleset.start
                    && mustStartAtOrAfter >= baseRuleset.start + baseRuleset.duration
                    && approvalStatus != JBApprovalStatus.Approved
                    && approvalStatus != JBApprovalStatus.ApprovalExpected
                    && approvalStatus != JBApprovalStatus.Empty)
        ) {
            // Metadata not needed — the fallback ruleset is only used for intrinsic fields (start, basedOnId, etc.)
            // and not forwarded to any external approval hook.
            baseRuleset = _getStructFor({projectId: projectId, rulesetId: baseRuleset.basedOnId, withMetadata: false});
        }

        // Make sure the ruleset starts after the base ruleset.
        if (baseRuleset.start > mustStartAtOrAfter) mustStartAtOrAfter = baseRuleset.start;

        // The time when the duration of the base ruleset's approval hook has finished.
        // If the provided ruleset has no approval hook, return 0 (no constraint on start time).
        uint256 timestampAfterApprovalHook;
        if (baseRuleset.approvalHook != IJBRulesetApprovalHook(address(0))) {
            try baseRuleset.approvalHook.DURATION() returns (uint256 duration) {
                timestampAfterApprovalHook = rulesetId + duration;
            } catch {
                // If DURATION() reverts, treat as no approval hook constraint.
                timestampAfterApprovalHook = 0;
            }
        }

        _initializeRulesetFor({
            projectId: projectId,
            baseRuleset: baseRuleset,
            rulesetId: rulesetId,
            // Can only start after the approval hook.
            mustStartAtOrAfter: timestampAfterApprovalHook > mustStartAtOrAfter
                ? timestampAfterApprovalHook
                : mustStartAtOrAfter,
            weight: weight
        });
    }

    /// @notice Initializes a ruleset with the specified properties.
    /// @param projectId The ID of the project to initialize the ruleset for.
    /// @param baseRuleset The ruleset struct to base the newly initialized one on.
    /// @param rulesetId The `rulesetId` for the ruleset to initialize.
    /// @param mustStartAtOrAfter The earliest timestamp the ruleset can start at.
    /// @param weight The weight to give the newly initialized ruleset.
    function _initializeRulesetFor(
        uint256 projectId,
        JBRuleset memory baseRuleset,
        uint256 rulesetId,
        uint256 mustStartAtOrAfter,
        uint256 weight
    )
        internal
    {
        // If there is no base, initialize a first ruleset.
        if (baseRuleset.cycleNumber == 0) {
            // Set fresh intrinsic properties.
            _packAndStoreIntrinsicPropertiesOf({
                rulesetId: rulesetId,
                projectId: projectId,
                rulesetCycleNumber: 1,
                weight: weight,
                basedOnId: baseRuleset.id,
                start: mustStartAtOrAfter
            });
        } else {
            // Derive the correct next start time from the base.
            uint256 start = deriveStartFrom({
                baseRulesetStart: baseRuleset.start,
                baseRulesetDuration: baseRuleset.duration,
                mustStartAtOrAfter: mustStartAtOrAfter
            });

            // A weight of 1 is a special case that represents inheriting the cut weight of the previous
            // ruleset.
            weight = weight == 1
                ? deriveWeightFrom({
                    projectId: projectId,
                    baseRulesetStart: baseRuleset.start,
                    baseRulesetDuration: baseRuleset.duration,
                    baseRulesetWeight: baseRuleset.weight,
                    baseRulesetWeightCutPercent: baseRuleset.weightCutPercent,
                    baseRulesetCacheId: baseRuleset.id,
                    start: start
                })
                : weight;

            // Derive the correct ruleset cycle number.
            uint256 rulesetCycleNumber = deriveCycleNumberFrom({
                baseRulesetCycleNumber: baseRuleset.cycleNumber,
                baseRulesetStart: baseRuleset.start,
                baseRulesetDuration: baseRuleset.duration,
                start: start
            });

            // Update the intrinsic properties.
            _packAndStoreIntrinsicPropertiesOf({
                rulesetId: rulesetId,
                projectId: projectId,
                rulesetCycleNumber: rulesetCycleNumber,
                weight: weight,
                basedOnId: baseRuleset.id,
                start: start
            });
        }

        // Set the project's latest ruleset configuration.
        latestRulesetIdOf[projectId] = rulesetId;

        emit RulesetInitialized({
            rulesetId: rulesetId, projectId: projectId, basedOnId: baseRuleset.id, caller: msg.sender
        });
    }

    /// @notice Efficiently stores the provided intrinsic properties of a ruleset.
    /// @param rulesetId The `rulesetId` of the ruleset to pack and store for.
    /// @param projectId The ID of the project the ruleset belongs to.
    /// @param rulesetCycleNumber The cycle number of the ruleset.
    /// @param weight The weight of the ruleset.
    /// @param basedOnId The `rulesetId` of the ruleset this ruleset was based on.
    /// @param start The start time of this ruleset.
    function _packAndStoreIntrinsicPropertiesOf(
        uint256 rulesetId,
        uint256 projectId,
        uint256 rulesetCycleNumber,
        uint256 weight,
        uint256 basedOnId,
        uint256 start
    )
        internal
    {
        // `weight` in bits 0-111.
        uint256 packed = weight;

        // `basedOnId` in bits 112-159.
        packed |= basedOnId << 112;

        // `start` in bits 160-207.
        packed |= start << 160;

        // cycle number in bits 208-255.
        packed |= rulesetCycleNumber << 208;

        // Store the packed value.
        _packedIntrinsicPropertiesOf[projectId][rulesetId] = packed;
    }

    //*********************************************************************//
    // -------------------------- internal views ------------------------- //
    //*********************************************************************//

    /// @notice The approval status of a given ruleset for a given project ID.
    /// @param projectId The ID of the project the ruleset belongs to.
    /// @param ruleset The ruleset to get the approval status of.
    /// @return The approval status of the project.
    function _approvalStatusOf(uint256 projectId, JBRuleset memory ruleset) internal view returns (JBApprovalStatus) {
        // If there is no ruleset ID to check the approval hook of, the approval hook is empty.
        if (ruleset.basedOnId == 0) return JBApprovalStatus.Empty;

        // Read only the packed user properties to extract the approval hook address,
        // avoiding the cost of loading the full parent ruleset struct.
        uint256 packedUserProperties = _packedUserPropertiesOf[projectId][ruleset.basedOnId];
        // forge-lint: disable-next-line(unsafe-typecast)
        IJBRulesetApprovalHook approvalHook = IJBRulesetApprovalHook(address(uint160(packedUserProperties)));

        // If there is no approval hook, it's considered empty.
        if (approvalHook == IJBRulesetApprovalHook(address(0))) {
            return JBApprovalStatus.Empty;
        }

        // Return the approval hook's approval status.
        // Wrap in try/catch to prevent a reverting approval hook from permanently freezing the project.
        // Note: A malicious hook that consumes all gas (e.g. infinite loop) could still DoS via gas exhaustion.
        // This is accepted risk since the project owner chose their own approval hook.
        try approvalHook.approvalStatusOf({projectId: projectId, ruleset: ruleset}) returns (JBApprovalStatus status) {
            return status;
        } catch {
            return JBApprovalStatus.Failed;
        }
    }

    /// @notice The ID of the ruleset which has started and hasn't expired yet, whether or not it has been approved, for
    /// a given project. If approved, this is the active ruleset.
    /// @dev A value of 0 is returned if no ruleset was found.
    /// @dev Assumes the project has a latest ruleset.
    /// @param projectId The ID of the project to check for a currently approvable ruleset.
    /// @return The ID of a currently approvable ruleset if one exists, or 0 if one doesn't exist.
    function _currentlyApprovableRulesetIdOf(uint256 projectId) internal view returns (uint256) {
        // Get a reference to the project's latest ruleset.
        uint256 rulesetId = latestRulesetIdOf[projectId];

        // Get the struct for the latest ruleset (metadata not needed — only traversal fields are checked).
        JBRuleset memory ruleset = _getStructFor({projectId: projectId, rulesetId: rulesetId, withMetadata: false});

        // Loop through all most recently queued rulesets until an approvable one is found, or we've proven one can't
        // exist.
        do {
            // If the latest ruleset is expired, return an empty ruleset.
            // A ruleset with a duration of 0 cannot expire.
            // forge-lint: disable-next-line(block-timestamp)
            if (ruleset.duration != 0 && block.timestamp >= ruleset.start + ruleset.duration) {
                return 0;
            }

            // Return the ruleset's `rulesetId` if it has started.
            // forge-lint: disable-next-line(block-timestamp)
            if (block.timestamp >= ruleset.start) {
                return ruleset.id;
            }

            ruleset = _getStructFor({projectId: projectId, rulesetId: ruleset.basedOnId, withMetadata: false});
        } while (ruleset.cycleNumber != 0);

        return 0;
    }

    /// @notice Unpack a ruleset's packed stored values into a struct.
    /// @dev When `withMetadata` is false, one cold SLOAD (~2,100 gas) is skipped — use this for linked-list traversal
    /// where only id, start, duration, basedOnId, etc. are needed.
    /// @param projectId The ID of the project the ruleset belongs to.
    /// @param rulesetId The ID of the ruleset to get the struct for.
    /// @param withMetadata Whether to load the packed metadata from storage.
    /// @return ruleset The ruleset struct (`metadata` is 0 when `withMetadata` is false).
    function _getStructFor(
        uint256 projectId,
        uint256 rulesetId,
        bool withMetadata
    )
        internal
        view
        returns (JBRuleset memory ruleset)
    {
        // Return an empty ruleset if the specified `rulesetId` is 0.
        if (rulesetId == 0) return ruleset;

        // forge-lint: disable-next-line(unsafe-typecast)
        ruleset.id = uint48(rulesetId);

        uint256 packedIntrinsicProperties = _packedIntrinsicPropertiesOf[projectId][rulesetId];

        // `weight` in bits 0-111 bits.
        // forge-lint: disable-next-line(unsafe-typecast)
        ruleset.weight = uint112(packedIntrinsicProperties);
        // `basedOnId` in bits 112-159 bits.
        // forge-lint: disable-next-line(unsafe-typecast)
        ruleset.basedOnId = uint48(packedIntrinsicProperties >> 112);
        // `start` in bits 160-207 bits.
        // forge-lint: disable-next-line(unsafe-typecast)
        ruleset.start = uint48(packedIntrinsicProperties >> 160);
        // `cycleNumber` in bits 208-255 bits.
        // forge-lint: disable-next-line(unsafe-typecast)
        ruleset.cycleNumber = uint48(packedIntrinsicProperties >> 208);

        uint256 packedUserProperties = _packedUserPropertiesOf[projectId][rulesetId];

        // approval hook in bits 0-159 bits.
        // forge-lint: disable-next-line(unsafe-typecast)
        ruleset.approvalHook = IJBRulesetApprovalHook(address(uint160(packedUserProperties)));
        // `duration` in bits 160-191 bits.
        // forge-lint: disable-next-line(unsafe-typecast)
        ruleset.duration = uint32(packedUserProperties >> 160);
        // weight cut percent in bits 192-223 bits.
        // forge-lint: disable-next-line(unsafe-typecast)
        ruleset.weightCutPercent = uint32(packedUserProperties >> 192);

        // Load metadata only when needed — saves one cold SLOAD (~2,100 gas) for traversal-only paths.
        if (withMetadata) ruleset.metadata = _metadataOf[projectId][rulesetId];
    }

    /// @notice A simulated view of the ruleset that would be created if the provided one cycled over (if the project
    /// doesn't queue a new ruleset).
    /// @dev Returns an empty ruleset if a ruleset can't be simulated based on the provided one.
    /// @dev Assumes a simulated ruleset will never be based on a ruleset with a duration of 0.
    /// @param projectId The ID of the project of the ruleset.
    /// @param baseRuleset The ruleset that the simulated ruleset should be based on.
    /// @param allowMidRuleset A flag indicating if the simulated ruleset is allowed to already be mid ruleset.
    /// @return A simulated ruleset struct: the next ruleset by default. This will be overwritten if a new ruleset is
    /// queued for the project.
    function _simulateCycledRulesetBasedOn(
        uint256 projectId,
        JBRuleset memory baseRuleset,
        bool allowMidRuleset
    )
        internal
        view
        returns (JBRuleset memory)
    {
        // Get the distance from the current time to the start of the next possible ruleset.
        // If the simulated ruleset must not yet have started, the start time of the simulated ruleset must be in the
        // future.
        uint256 mustStartAtOrAfter = !allowMidRuleset
            ? block.timestamp + 1
            // forge-lint: disable-next-line(block-timestamp)
            : baseRuleset.duration >= block.timestamp ? 1 : block.timestamp - baseRuleset.duration + 1;

        // Calculate what the start time should be.
        uint256 start = deriveStartFrom({
            baseRulesetStart: baseRuleset.start,
            baseRulesetDuration: baseRuleset.duration,
            mustStartAtOrAfter: mustStartAtOrAfter
        });

        // Calculate what the cycle number should be.
        uint256 rulesetCycleNumber = deriveCycleNumberFrom({
            baseRulesetCycleNumber: baseRuleset.cycleNumber,
            baseRulesetStart: baseRuleset.start,
            baseRulesetDuration: baseRuleset.duration,
            start: start
        });

        return JBRuleset({
            // forge-lint: disable-next-line(unsafe-typecast)
            cycleNumber: uint48(rulesetCycleNumber),
            id: baseRuleset.id,
            basedOnId: baseRuleset.basedOnId,
            // forge-lint: disable-next-line(unsafe-typecast)
            start: uint48(start),
            duration: baseRuleset.duration,
            weight: uint112(
                deriveWeightFrom({
                    projectId: projectId,
                    baseRulesetStart: baseRuleset.start,
                    baseRulesetDuration: baseRuleset.duration,
                    baseRulesetWeight: baseRuleset.weight,
                    baseRulesetWeightCutPercent: baseRuleset.weightCutPercent,
                    baseRulesetCacheId: baseRuleset.id,
                    start: start
                })
            ),
            weightCutPercent: baseRuleset.weightCutPercent,
            approvalHook: baseRuleset.approvalHook,
            metadata: baseRuleset.metadata
        });
    }

    /// @notice The ruleset up next for a project, if one exists, whether or not that ruleset has been approved.
    /// @dev A value of 0 is returned if no ruleset was found.
    /// @dev Assumes the project has a `latestRulesetIdOf` value.
    /// @param projectId The ID of the project to check for an upcoming approvable ruleset.
    /// @return rulesetId The `rulesetId` of the upcoming approvable ruleset if one exists, or 0 if one doesn't exist.
    function _upcomingApprovableRulesetIdOf(uint256 projectId) internal view returns (uint256 rulesetId) {
        // Get a reference to the ID of the project's latest ruleset.
        rulesetId = latestRulesetIdOf[projectId];

        // Get the struct for the latest ruleset (metadata not needed — only traversal fields are checked).
        JBRuleset memory ruleset = _getStructFor({projectId: projectId, rulesetId: rulesetId, withMetadata: false});

        // There is no upcoming ruleset if the latest ruleset has already started.
        // forge-lint: disable-next-line(block-timestamp)
        if (block.timestamp >= ruleset.start) return 0;

        // If this is the first ruleset, it is queued.
        if (ruleset.cycleNumber == 1) return rulesetId;

        // Get a reference to the ID of the ruleset the latest ruleset was based on.
        uint256 basedOnId = ruleset.basedOnId;

        // Get the necessary properties for the base ruleset.
        JBRuleset memory baseRuleset;

        // Find the base ruleset that is not still queued.
        while (true) {
            baseRuleset = _getStructFor({projectId: projectId, rulesetId: basedOnId, withMetadata: false});

            // If the base ruleset starts in the future,
            // forge-lint: disable-next-line(block-timestamp)
            if (block.timestamp < baseRuleset.start) {
                // Set the `rulesetId` to the one found.
                rulesetId = baseRuleset.id;
                // Check the ruleset it was based on in the next iteration.
                basedOnId = baseRuleset.basedOnId;
            } else {
                // Break out of the loop when a base ruleset which has already started is found.
                break;
            }
        }

        // Get the ruleset struct for the ID found (metadata not needed — only `start` and `duration` are checked).
        ruleset = _getStructFor({projectId: projectId, rulesetId: rulesetId, withMetadata: false});

        // If the latest ruleset doesn't start until after another base ruleset return 0.
        // forge-lint: disable-next-line(block-timestamp)
        if (baseRuleset.duration != 0 && block.timestamp < ruleset.start - baseRuleset.duration) {
            return 0;
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {JBControlled} from "./abstract/JBControlled.sol";
import {IJBDirectory} from "./interfaces/IJBDirectory.sol";
import {IJBSplitHook} from "./interfaces/IJBSplitHook.sol";
import {IJBSplits} from "./interfaces/IJBSplits.sol";
import {JBConstants} from "./libraries/JBConstants.sol";
import {JBSplit} from "./structs/JBSplit.sol";
import {JBSplitGroup} from "./structs/JBSplitGroup.sol";

/// @notice Manages how a project distributes its payouts and reserved tokens. Each "split" specifies a recipient and
/// their share (as a fraction of 1,000,000,000). Splits can be locked until a timestamp — locked splits cannot be
/// removed or reduced until the lock expires, providing recipients with guaranteed revenue streams.
/// @dev Splits are organized by project, ruleset, and group. Ruleset 0 is the fallback used when no splits are set for
/// the active ruleset. The payout group ID is derived from the token address to distribute.
contract JBSplits is JBControlled, IJBSplits {
    //*********************************************************************//
    // --------------------------- custom errors ------------------------- //
    //*********************************************************************//

    /// @notice Thrown when a new set of splits omits a still-locked split from the previous set.
    error JBSplits_PreviousLockedSplitsNotIncluded(uint256 projectId, uint256 rulesetId);

    /// @notice Thrown when the splits in a group sum to more than 100%.
    error JBSplits_TotalPercentExceeds100(uint256 projectId, uint256 rulesetId, uint256 groupId, uint256 percentTotal);

    /// @notice Thrown when a split is configured with a percent of zero.
    error JBSplits_ZeroSplitPercent(uint256 projectId, uint256 rulesetId, uint256 groupId, uint256 splitIndex);

    //*********************************************************************//
    // ------------------------- public constants ------------------------ //
    //*********************************************************************//

    /// @notice The ID of the ruleset that will be checked if nothing was found in the provided rulesetId.
    uint256 public constant override FALLBACK_RULESET_ID = 0;

    //*********************************************************************//
    // --------------------- internal stored properties ------------------ //
    //*********************************************************************//

    /// @notice Packed split data given the split's project, ruleset, and group IDs, as well as the split's index within
    /// that group.
    /// @dev `preferAddToBalance` in bit 0, `percent` in bits 1-32, `projectId` in bits 33-88, and `beneficiary` in bits
    /// 89-248
    /// @custom:param projectId The ID of the project that the split applies to.
    /// @custom:param rulesetId The ID of the ruleset that the group is in.
    /// @custom:param groupId The ID of the group the split is in.
    /// @custom:param index The split's index within the group (in the order that the split were set).
    /// @custom:return The split's `preferAddToBalance`, `percent`, `projectId`, and `beneficiary` packed into one
    /// `uint256`.
    mapping(
        uint256 projectId => mapping(uint256 rulesetId => mapping(uint256 groupId => mapping(uint256 index => uint256)))
    ) internal _packedSplitParts1Of;

    /// @notice More packed split data given the split's project, ruleset, and group IDs, as well as the split's index
    /// within that group.
    /// @dev `lockedUntil` in bits 0-47, `hook` address in bits 48-207.
    /// @dev This packed data is often 0.
    /// @custom:param projectId The ID of the project that the ruleset applies to.
    /// @custom:param rulesetId The ID of the ruleset that the group is in.
    /// @custom:param groupId The ID of the group the split is in.
    /// @custom:param index The split's index within the group (in the order that the split were set).
    /// @custom:return The split's `lockedUntil` and `hook` packed into one `uint256`.
    mapping(
        uint256 projectId => mapping(uint256 rulesetId => mapping(uint256 groupId => mapping(uint256 index => uint256)))
    ) internal _packedSplitParts2Of;

    /// @notice The number of splits currently stored in a group given a project ID, ruleset ID, and group ID.
    /// @custom:param projectId The ID of the project the split applies to.
    /// @custom:param rulesetId The ID of the ruleset that the group is specified within.
    /// @custom:param groupId The ID of the group to count this splits of.
    mapping(uint256 projectId => mapping(uint256 rulesetId => mapping(uint256 groupId => uint256))) internal
        _splitCountOf;

    //*********************************************************************//
    // -------------------------- constructor ---------------------------- //
    //*********************************************************************//

    /// @param directory A contract storing directories of terminals and controllers for each project.
    constructor(IJBDirectory directory) JBControlled(directory) {}

    //*********************************************************************//
    // ---------------------- external transactions ---------------------- //
    //*********************************************************************//

    /// @notice Configure how a project distributes funds to its split recipients. Each split group defines a list of
    /// recipients (with percentage shares) for a specific purpose (e.g. payouts in ETH, reserved token distribution).
    /// @dev Only the project's controller can set splits — unless the group ID encodes `msg.sender` in its lower 160
    /// bits with non-zero upper 96 bits, which enables self-managed splits (e.g. hooks managing their own groups).
    /// @dev Locked splits cannot be removed or reduced until their lock expires. The new groups must include all
    /// currently-locked splits.
    /// @param projectId The ID of the project to set the split groups of.
    /// @param rulesetId The ID of the ruleset the split groups should be active in. Pass 0 to set the default splits
    /// (used when no ruleset-specific splits are configured). The default's default is the project's owner.
    /// @param splitGroups An array of split groups to set.
    function setSplitGroupsOf(
        uint256 projectId,
        uint256 rulesetId,
        JBSplitGroup[] calldata splitGroups
    )
        external
        override
    {
        // Cache whether the controller check has already passed to avoid repeated external calls.
        bool controllerChecked;

        // Set each grouped splits. Access calldata directly to avoid copying each split group to memory.
        for (uint256 i; i < splitGroups.length;) {
            // Self-auth: lower 160 bits must match msg.sender AND upper 96 bits must be non-zero.
            // GroupIds with zero upper bits are reserved for protocol use (e.g. terminal payout groups)
            // and always require controller authorization to prevent token contracts from hijacking payouts.
            bool isSelfManaged =
                splitGroups[i].groupId >> 160 != 0 && address(uint160(splitGroups[i].groupId)) == msg.sender;

            if (!isSelfManaged && !controllerChecked) {
                _onlyControllerOf(projectId);
                controllerChecked = true;
            }

            // Set the splits for the group.
            _setSplitsOf({
                projectId: projectId,
                rulesetId: rulesetId,
                groupId: splitGroups[i].groupId,
                splits: splitGroups[i].splits
            });
            unchecked {
                ++i;
            }
        }
    }

    //*********************************************************************//
    // ------------------------- external views -------------------------- //
    //*********************************************************************//

    /// @notice Get the list of split recipients for a project's group within a given ruleset. Falls back to the
    /// default splits (ruleset 0) if none are set for the specific ruleset.
    /// @param projectId The ID of the project to get splits for.
    /// @param rulesetId The ruleset to look up splits in. Falls back to ruleset 0 if none are found.
    /// @param groupId The split group ID (e.g. token address for payout groups, or a custom ID for reserved tokens).
    /// @return splits An array of all splits for the project.
    function splitsOf(
        uint256 projectId,
        uint256 rulesetId,
        uint256 groupId
    )
        external
        view
        override
        returns (JBSplit[] memory splits)
    {
        splits = _getStructsFor({projectId: projectId, rulesetId: rulesetId, groupId: groupId});

        // Use the default splits if there aren't any for the ruleset.
        if (splits.length == 0) {
            splits = _getStructsFor({projectId: projectId, rulesetId: FALLBACK_RULESET_ID, groupId: groupId});
        }
    }

    //*********************************************************************//
    // ---------------------- internal transactions ---------------------- //
    //*********************************************************************//

    /// @notice Sets the splits for a group given a project, ruleset, and group ID.
    /// @dev The new splits must include any currently set splits that are locked.
    /// @dev The sum of the split `percent`s within one group must be less than 100%.
    /// @param projectId The ID of the project to set splits for.
    /// @param rulesetId The ID of the ruleset the splits should be considered active within.
    /// @param groupId The ID of the group to set the splits within.
    /// @param splits An array of splits to set.
    function _setSplitsOf(uint256 projectId, uint256 rulesetId, uint256 groupId, JBSplit[] memory splits) internal {
        // Get a reference to the current split structs within the project, ruleset, and group.
        JBSplit[] memory currentSplits = _getStructsFor({projectId: projectId, rulesetId: rulesetId, groupId: groupId});

        // Keep a reference to the current number of splits within the group.
        uint256 numberOfCurrentSplits = currentSplits.length;

        // Check to see if all locked splits are included in the array of splits which is being set.
        // Duplicate locked splits must be preserved with the same multiplicity. Otherwise a table with two identical
        // locked splits could be collapsed into one matching split and one unrelated split while each old split sees
        // the same new match.
        for (uint256 i; i < numberOfCurrentSplits;) {
            // If not locked, continue.
            // forge-lint: disable-next-line(block-timestamp)
            if (block.timestamp < currentSplits[i].lockedUntil) {
                uint256 requiredCount;
                for (uint256 j; j < numberOfCurrentSplits;) {
                    if (
                        // forge-lint: disable-next-line(block-timestamp)
                        block.timestamp < currentSplits[j].lockedUntil
                            && _isLockedSplitIncluded({split: currentSplits[j], lockedSplit: currentSplits[i]})
                    ) {
                        ++requiredCount;
                    }
                    unchecked {
                        ++j;
                    }
                }

                if (_includedLockedSplitCount({splits: splits, lockedSplit: currentSplits[i]}) < requiredCount) {
                    revert JBSplits_PreviousLockedSplitsNotIncluded({projectId: projectId, rulesetId: rulesetId});
                }
            }
            unchecked {
                ++i;
            }
        }

        // Add up all the `percent`s to make sure their total is under 100%.
        uint256 percentTotal;

        // Keep a reference to the number of splits to set.
        uint256 numberOfSplits = splits.length;

        for (uint256 i; i < numberOfSplits;) {
            // Set the split being iterated on.
            JBSplit memory split = splits[i];

            // The percent should be greater than 0.
            if (split.percent == 0) {
                revert JBSplits_ZeroSplitPercent({
                    projectId: projectId, rulesetId: rulesetId, groupId: groupId, splitIndex: i
                });
            }

            // Add to the `percent` total.
            percentTotal += split.percent;

            // Ensure the total does not exceed 100%.
            if (percentTotal > JBConstants.SPLITS_TOTAL_PERCENT) {
                revert JBSplits_TotalPercentExceeds100({
                    projectId: projectId, rulesetId: rulesetId, groupId: groupId, percentTotal: percentTotal
                });
            }

            uint256 packedSplitParts1;

            // Pack `percent` in bits 0-31.
            packedSplitParts1 = split.percent;
            // Pack `projectId` in bits 32-95.
            packedSplitParts1 |= uint256(split.projectId) << 32;
            // Pack `beneficiary` in bits 96-255.
            packedSplitParts1 |= uint256(uint160(address(split.beneficiary))) << 96;

            // Store the first split part.
            _packedSplitParts1Of[projectId][rulesetId][groupId][i] = packedSplitParts1;

            // If there's data to store in the second packed split part, pack and store.
            if (split.preferAddToBalance || split.lockedUntil > 0 || split.hook != IJBSplitHook(address(0))) {
                // Pack `preferAddToBalance` in bit 0.
                uint256 packedSplitParts2 = split.preferAddToBalance ? 1 : 0;
                // Pack `lockedUntil` in bits 1-48.
                packedSplitParts2 |= uint256(split.lockedUntil) << 1;
                // Pack `hook` in bits 49-208.
                packedSplitParts2 |= uint256(uint160(address(split.hook))) << 49;

                // Store the second split part.
                _packedSplitParts2Of[projectId][rulesetId][groupId][i] = packedSplitParts2;
            } else if (_packedSplitParts2Of[projectId][rulesetId][groupId][i] > 0) {
                // If there's a value stored in the indexed position, delete it.
                delete _packedSplitParts2Of[projectId][rulesetId][groupId][i];
            }

            emit SetSplit({
                projectId: projectId, rulesetId: rulesetId, groupId: groupId, split: split, caller: msg.sender
            });
            unchecked {
                ++i;
            }
        }

        // Store the number of splits for the project, ruleset, and group.
        _splitCountOf[projectId][rulesetId][groupId] = numberOfSplits;

        // Clean up stale storage slots if the new split count is less than the previous count.
        // This zeroes out leftover packed data to reclaim gas via storage refunds.
        for (uint256 i = numberOfSplits; i < numberOfCurrentSplits;) {
            delete _packedSplitParts1Of[projectId][rulesetId][groupId][i];
            delete _packedSplitParts2Of[projectId][rulesetId][groupId][i];
            unchecked {
                ++i;
            }
        }
    }

    //*********************************************************************//
    // -------------------------- internal views ------------------------- //
    //*********************************************************************//

    /// @notice Unpack an array of `JBSplit` structs for all of the splits in a group, given project, ruleset, and group
    /// IDs.
    /// @param projectId The ID of the project the splits belong to.
    /// @param rulesetId The ID of the ruleset the group of splits should be considered active within.
    /// @param groupId The ID of the group to get the splits structs of.
    /// @return splits The split structs, as an array of `JBSplit`s.
    function _getStructsFor(
        uint256 projectId,
        uint256 rulesetId,
        uint256 groupId
    )
        internal
        view
        returns (JBSplit[] memory)
    {
        // Get a reference to the number of splits that need to be added to the returned array.
        uint256 splitCount = _splitCountOf[projectId][rulesetId][groupId];

        // Initialize an array to be returned that has the appropriate length.
        JBSplit[] memory splits = new JBSplit[](splitCount);

        // Loop through each split and unpack the values into structs.
        for (uint256 i; i < splitCount;) {
            // Get a reference to the first part of the split's packed data.
            uint256 packedSplitPart1 = _packedSplitParts1Of[projectId][rulesetId][groupId][i];

            // Populate the split struct.
            JBSplit memory split;

            // `percent` in bits 0-31.
            // forge-lint: disable-next-line(unsafe-typecast)
            split.percent = uint32(packedSplitPart1);
            // `projectId` in bits 32-95.
            // forge-lint: disable-next-line(unsafe-typecast)
            split.projectId = uint64(packedSplitPart1 >> 32);
            // `beneficiary` in bits 96-255.
            // forge-lint: disable-next-line(unsafe-typecast)
            split.beneficiary = payable(address(uint160(packedSplitPart1 >> 96)));

            // Get a reference to the second part of the split's packed data.
            uint256 packedSplitPart2 = _packedSplitParts2Of[projectId][rulesetId][groupId][i];

            // If there's anything in it, unpack.
            if (packedSplitPart2 > 0) {
                // `preferAddToBalance` in bit 0.
                split.preferAddToBalance = packedSplitPart2 & 1 == 1;
                // `lockedUntil` in bits 1-48.
                // forge-lint: disable-next-line(unsafe-typecast)
                split.lockedUntil = uint48(packedSplitPart2 >> 1);
                // `hook` in bits 49-208.
                // forge-lint: disable-next-line(unsafe-typecast)
                split.hook = IJBSplitHook(address(uint160(packedSplitPart2 >> 49)));
            }

            // Add the split to the value being returned.
            splits[i] = split;
            unchecked {
                ++i;
            }
        }

        return splits;
    }

    /// @notice Count the splits in the provided array that include the locked split.
    /// @param splits The array of splits to check within.
    /// @param lockedSplit The locked split.
    /// @return count The number of matching splits.
    function _includedLockedSplitCount(
        JBSplit[] memory splits,
        JBSplit memory lockedSplit
    )
        internal
        pure
        returns (uint256 count)
    {
        // Keep a reference to the number of splits.
        uint256 numberOfSplits = splits.length;

        for (uint256 i; i < numberOfSplits;) {
            if (_isLockedSplitIncluded({split: splits[i], lockedSplit: lockedSplit})) ++count;
            unchecked {
                ++i;
            }
        }
    }

    /// @notice Determine if a split satisfies the locked split's immutable fields and lock length.
    /// @param split The split to check.
    /// @param lockedSplit The locked split.
    /// @return A flag indicating whether the split includes the locked split.
    function _isLockedSplitIncluded(JBSplit memory split, JBSplit memory lockedSplit) internal pure returns (bool) {
        // Allow the lock to be extended.
        return split.percent == lockedSplit.percent && split.beneficiary == lockedSplit.beneficiary
            && split.hook == lockedSplit.hook && split.projectId == lockedSplit.projectId
            && split.preferAddToBalance == lockedSplit.preferAddToBalance
            && split.lockedUntil >= lockedSplit.lockedUntil;
    }
}

