    /// @notice Resolve the original payer when called through an intermediary.
    /// @dev Registry-style forwarders record the original payer in transient storage via `IJBPayerTracker`. When
    /// present, that address is used for refunds instead of the intermediary.
    /// @param fallback_ The default address to use when no original payer is available.
    /// @return The original payer, or `fallback_` if none is available.
    function _resolveOriginalPayer(address fallback_) internal view returns (address) {
        // Only attempt the call if msg.sender is a contract (EOAs have no code and would revert).
        if (msg.sender.code.length > 0) {
            try IJBPayerTracker(msg.sender).originalPayer() returns (address payer) {
                if (payer != address(0)) return payer;
            } catch {}
        }
        return fallback_;
    }

    /// @notice Route a payment using the destination token that yields the highest previewed beneficiary output.
    /// @param destProjectId The project to route the payment to.
    /// @param tokenIn The token currently held by the router for this payment.
    /// @param amount The amount of `tokenIn` available to route.
    /// @param beneficiary The address whose beneficiary token count to maximize.
    /// @param metadata Metadata forwarded into route discovery and the final destination payment.
    /// @param refundTo The address to receive any leftover input tokens from partial fills.
    /// @return destTerminal The terminal selected for the winning route.
    /// @return tokenOut The token `destTerminal` should receive for the winning route.
    /// @return amountOut The amount of `tokenOut` that will be delivered to `destTerminal`.
    function _routeForPay(
        uint256 destProjectId,
        address tokenIn,
        uint256 amount,
        address beneficiary,
        bytes calldata metadata,
        address payable refundTo
    )
        internal
        returns (IJBTerminal destTerminal, address tokenOut, uint256 amountOut)
    {
        // Read the destination project's terminal list in best-effort mode so a bad directory read degrades into
        // "no terminals" instead of bricking pay-route selection.
        IJBTerminal[] memory terminals = _terminalsOf({projectId: destProjectId, shouldIgnoreFailure: true});

        // Fall back to ordinary routing when the destination project exposes no direct terminals to score.
        if (terminals.length == 0) {
            return _route({
                destProjectId: destProjectId, tokenIn: tokenIn, amount: amount, metadata: metadata, refundTo: refundTo
            });
        }

        // Preview the best candidate route so execution can target the destination token with the highest payout.
        (destTerminal, tokenOut,,,,,) = _previewBestPayRoute({
            projectId: destProjectId, tokenIn: tokenIn, amount: amount, beneficiary: beneficiary, metadata: metadata
        });

        // Execute the winning route by converting into the preview-selected destination token.
        // Pass the preview-resolved destTerminal so execution skips the redundant directory lookup.
        return _routeToDestination({
            destProjectId: destProjectId,
            tokenIn: tokenIn,
            amount: amount,
            tokenOut: tokenOut,
            previewedDestTerminal: destTerminal,
            metadata: metadata,
            refundTo: refundTo
        });
    }

    /// @notice Estimate the amount a buyback-hook cash-out preview would actually deliver to the router.
    /// @param reclaimAmount The raw reclaim amount returned by the terminal preview before hook-aware normalization.
    /// @param hookSpecifications The hook specifications returned alongside the terminal cash-out preview.
    /// @return effectiveAmount The highest user-visible reclaim amount implied by the raw preview and understood
    /// buyback-hook metadata.
    function _effectivePreviewCashOutAmount(
        uint256 reclaimAmount,
        JBCashOutHookSpecification[] memory hookSpecifications
    )
        internal
        view
        returns (uint256 effectiveAmount)
    {
        // Start from the raw reclaim amount surfaced directly by the destination terminal preview.
        effectiveAmount = reclaimAmount;

        for (uint256 i; i < hookSpecifications.length;) {
            // Inspect one hook specification at a time so only understood buyback hooks can raise the preview.
            JBCashOutHookSpecification memory specification = hookSpecifications[i];

            // Ignore no-op hooks and hooks the router does not recognize as the canonical buyback hook.
            if (specification.noop || address(specification.hook) != BUYBACK_HOOK) {
                unchecked {
                    ++i;
                }
                continue;
            }

            // Decode only the buyback field used for route scoring. `minimumSwapAmountOut` is executable because the
            // hook will enforce it; the later raw quote word is diagnostic and can overstate what execution can prove.
            (uint256 minimumSwapAmountOut,,,,,,,) =
                abi.decode(specification.metadata, (uint256, uint256, uint256, int24, uint128, PoolId, uint256, bool));

            // Keep whichever understood executable hook commitment implies the strongest cash-out output.
            if (minimumSwapAmountOut > effectiveAmount) effectiveAmount = minimumSwapAmountOut;

            unchecked {
                ++i;
            }
        }
    }

    /// @notice Preview the best pay route using the resolver helper.
    /// @param projectId The destination project to pay.
    /// @param tokenIn The token currently available to route.
    /// @param amount The amount of `tokenIn` to preview.
    /// @param beneficiary The address whose minted token count to optimize.
    /// @param metadata Metadata forwarded into route and pay previews.
    /// @return destTerminal The terminal chosen for the best previewed route.
    /// @return tokenOut The token `destTerminal` would receive.
    /// @return amountOut The amount of `tokenOut` that would be paid.
    /// @return ruleset The ruleset returned by the chosen terminal preview.
    /// @return beneficiaryTokenCount The effective beneficiary token count for the chosen route.
    /// @return reservedTokenCount The effective reserved token count for the chosen route.
    /// @return hookSpecifications The hook specifications returned by the chosen terminal preview.
    function _previewBestPayRoute(
        uint256 projectId,
        address tokenIn,
        uint256 amount,
        address beneficiary,
        bytes calldata metadata
    )
        internal
        view
        returns (
            IJBTerminal destTerminal,
            address tokenOut,
            uint256 amountOut,
            JBRuleset memory ruleset,
            uint256 beneficiaryTokenCount,
            uint256 reservedTokenCount,
            JBPayHookSpecification[] memory hookSpecifications
        )
    {
        // Delegate the heavy preview-selection logic to the helper contract so the router stays within runtime size.
        // Pass `wrappedNativeToken` once (single SLOAD) so the resolver does not have to call back into the router for
        // it on every normalization step.
        return _PAY_ROUTE_RESOLVER.previewBestPayRoute({
            router: IJBPayRoutePreviewer(address(this)),
            wrappedNativeToken: address(wrappedNativeToken),
            projectId: projectId,
            tokenIn: tokenIn,
            amount: amount,
            beneficiary: beneficiary,
            metadata: metadata
        });
    }

    /// @notice Preview the output amount for a direct token-to-token swap route.
    /// @param tokenIn The token currently available to swap.
    /// @param tokenOut The token the swap should deliver.
    /// @param amount The amount of `tokenIn` to preview.
    /// @param metadata Metadata that can provide an explicit `(tokenOut, minAmountOut)` quote for the swap.
    /// @return amountOut The predicted amount of `tokenOut` the router would receive.
    function _previewSwapAmountOut(
        address tokenIn,
        address tokenOut,
        uint256 amount,
        bytes calldata metadata
    )
        internal
        view
        returns (uint256 amountOut)
    {
        // Normalize native-token sentinels into wrapped native tokens so pool discovery and quoting use canonical pair
        // addresses. _pickPoolAndQuote already discovers the best pool and reverts with NoPoolFound when none exists,
        // so no separate liquidity guard is needed here.
        (amountOut,) = _pickPoolAndQuote({
            metadata: metadata,
            normalizedTokenIn: _normalize(tokenIn),
            amount: amount,
            normalizedTokenOut: _normalize(tokenOut)
        });
    }

    /// @notice Snapshot a destination terminal's pre-call token balance and check forwarding status.
    /// @dev Combines both the balance snapshot and forwarding probe into a single helper to avoid duplicate
    /// `_isForwardingTerminal` calls in the pay/addToBalance flows.
    /// @param terminal The destination terminal that will receive the final forwarded funds.
    /// @param token The token the terminal is expected to receive.
    /// @param projectId The project to check forwarding status for.
    /// @return receiptBaseline The terminal's balance in `token` before the final forwarded call.
    /// @return isForwarding Whether the terminal forwards calls onward.
    function _terminalReceiptBaselineOf(
        IJBTerminal terminal,
        address token,
        uint256 projectId
    )
        internal
        view
        returns (uint256 receiptBaseline, bool isForwarding)
    {
        // Skip native-token receipt enforcement because value transfers can be consumed during terminal execution.
        if (token == JBConstants.NATIVE_TOKEN) return (0, false);

        // Check forwarding status once and return it alongside the baseline.
        isForwarding = _isForwardingTerminal({terminal: terminal, projectId: projectId});

        // Skip receipt enforcement for forwarding terminals because they enforce the terminal-facing hop themselves.
        if (isForwarding) return (0, true);

        // Snapshot the terminal's ERC20 balance so final-hop receipt can be verified after the terminal pulls.
        return (IERC20(token).balanceOf(address(terminal)), false);
    }

    /// @notice Reject lossy ERC20 terminal pulls on the final forwarded hop.
    /// @param terminal The destination terminal that received the forwarded call.
    /// @param token The token the terminal was expected to pull.
    /// @param expectedAmount The nominal amount forwarded into the terminal call.
    /// @param receiptBaseline The terminal's pre-call balance in `token`.
    /// @param isForwarding Whether the terminal forwards calls onward (pre-computed by caller).
    function _enforceStandardTerminalReceipt(
        IJBTerminal terminal,
        address token,
        uint256 expectedAmount,
        uint256 receiptBaseline,
        bool isForwarding
    )
        internal
        view
    {
        // Native-token final hops are excluded because their value transfer is not observable via ERC20 balances.
        if (token == JBConstants.NATIVE_TOKEN) return;

        // Forwarding terminals are responsible for enforcing the final terminal-facing ERC20 receipt themselves.
        if (isForwarding) return;

        // Revert when the terminal received less ERC20 than promised, which indicates a lossy token path.
        uint256 actualAmount = IERC20(token).balanceOf(address(terminal)) - receiptBaseline;
        if (actualAmount < expectedAmount) {
            revert JBRouterTerminal_NonStandardTerminalToken({
                terminal: address(terminal), token: token, expectedAmount: expectedAmount, actualAmount: actualAmount
            });
        }
    }

    /// @notice Whether a terminal forwards terminal-facing calls onward instead of acting as the final receiver.
    /// @param terminal The terminal to check for forwarding behavior.
    /// @param projectId The project to resolve forwarding target for.
    /// @return isForwarding A flag indicating whether receipt enforcement should be delegated to `terminal`.
    function _isForwardingTerminal(IJBTerminal terminal, uint256 projectId) internal view returns (bool isForwarding) {
        // Probe via staticcall so non-forwarding terminals degrade cleanly.
        (bool success, bytes memory data) =
            address(terminal).staticcall(abi.encodeCall(IJBForwardingTerminal.terminalOf, (projectId)));

        // Treat terminals that do not implement the capability or return zero as final receivers.
        if (!success || data.length < 32) return false;

        return address(abi.decode(data, (IJBTerminal))) != address(0);
    }

    /// @notice Return a project's primary terminal only if the router can safely forward into it.
    /// @dev Inlined from the resolver to avoid a cross-contract roundtrip (saves 3 external calls per lookup).
    /// @param projectId The project to check the primary terminal for.
    /// @param token The token that terminal should accept.
    /// @return terminal The usable primary terminal, or address(0) if none is usable.
    function _usablePrimaryTerminalOf(uint256 projectId, address token) internal view returns (IJBTerminal terminal) {
        // Primary-terminal discovery can call into every registered destination terminal. Treat a broken terminal in
        // that list as "no usable terminal" for this candidate so one bad terminal cannot DoS route discovery.
        try DIRECTORY.primaryTerminalOf({projectId: projectId, token: token}) returns (IJBTerminal resolvedTerminal) {
            terminal = resolvedTerminal;
        } catch {
            return IJBTerminal(address(0));
        }

        // Drop terminals that would route straight back into the router (circular).
        if (
            address(terminal) == address(0)
                || JBForwardingCheck.isCircularTerminal({
                    target: address(this), projectId: projectId, terminal: terminal
                })
        ) {
            return IJBTerminal(address(0));
        }

        // Check if the terminal is a forwarding layer that routes back into this router.
        (bool ok, bytes memory data) =
            address(terminal).staticcall(abi.encodeCall(IJBForwardingTerminal.terminalOf, (projectId)));
        if (ok && data.length >= 32 && address(abi.decode(data, (IJBTerminal))) == address(this)) {
            return IJBTerminal(address(0));
        }
    }

    /// @notice Resolve which source project a routed token should cash out from.
    /// @param token The current route token that may be a JB project token.
    /// @return sourceProjectId The project to cash out from, or 0 if the token is not a JB project token.
    function _sourceProjectIdOf(address token) internal view returns (uint256 sourceProjectId) {
        if (token != JBConstants.NATIVE_TOKEN) sourceProjectId = _projectIdOf(token);
    }

    /// @notice Accept a token paid in by the caller.
    /// @param token The address of the token to accept.
    /// @param amount The amount of tokens to accept.
    /// @param metadata The metadata in which `permit2` context is provided.
    /// @return The amount of tokens accepted.
    function _acceptFundsFor(address token, uint256 amount, bytes calldata metadata) internal returns (uint256) {
        // Cache _msgSender() once to avoid repeated ERC-2771 context resolution.
        address sender = _msgSender();

        // If native tokens are being paid in, return the `msg.value`.
        if (token == JBConstants.NATIVE_TOKEN) return msg.value;

        // Otherwise, the `msg.value` should be 0.
        if (msg.value != 0) revert JBRouterTerminal_NoMsgValueAllowed(msg.value);

        // Unpack the `JBSingleAllowance` to use given by the frontend.
        (bool exists, bytes memory parsedMetadata) = _getDataFor({metadata: metadata, id: _PERMIT2_ID});

        // If the metadata contained permit data, use it to set the allowance.
        if (exists) {
            // Keep a reference to the allowance context parsed from the metadata.
            (JBSingleAllowance memory allowance) = abi.decode(parsedMetadata, (JBSingleAllowance));

            // Make sure the permit allowance is enough for this payment. If not, revert early.
            if (amount > allowance.amount) revert JBRouterTerminal_PermitAllowanceNotEnough(amount, allowance.amount);

            // Keep a reference to the permit rules.
            IAllowanceTransfer.PermitSingle memory permitSingle = IAllowanceTransfer.PermitSingle({
                details: IAllowanceTransfer.PermitDetails({
                    token: token, amount: allowance.amount, expiration: allowance.expiration, nonce: allowance.nonce
                }),
                spender: address(this),
                sigDeadline: allowance.sigDeadline
            });

            try PERMIT2.permit({owner: sender, permitSingle: permitSingle, signature: allowance.signature}) {}
            catch (bytes memory reason) {
                emit Permit2AllowanceFailed({token: token, owner: sender, reason: reason, caller: sender});
            }
        }

        // Fee-on-transfer tokens are not supported by design. The router uses balance-delta
        // checks for its own accounting but relies on underlying terminal behavior for FoT tokens. Projects
        // should avoid configuring FoT tokens.
        // Measure balance before transfer to determine actual tokens received (handles fee-on-transfer tokens).
        uint256 balanceBefore = IERC20(token).balanceOf(address(this));

        // Transfer the tokens from the sender to this terminal.
        _transferFrom({from: sender, to: payable(address(this)), token: token, amount: amount});

        // Return the actual amount received (balance delta), not the user-supplied amount.
        return IERC20(token).balanceOf(address(this)) - balanceBefore;
    }

    /// @notice Run the common post-transfer cleanup after forwarding funds into a destination terminal.
    /// @param destTerminal The terminal that received the forwarded call.
    /// @param token The token that was forwarded into the destination terminal.
    function _afterTransferFor(IJBTerminal destTerminal, address token) internal {
        // Revoke any leftover allowance the destination terminal did not pull so routed calls do not leave approvals
        // hanging around after the terminal finishes its pull.
        if (token != JBConstants.NATIVE_TOKEN) IERC20(token).forceApprove({spender: address(destTerminal), value: 0});
    }

    /// @notice Logic to trigger before transferring tokens from this terminal.
    /// @param to The address to transfer tokens to.
    /// @param token The token to transfer.
    /// @param amount The amount of tokens to transfer.
    /// @return payValue The amount that will be paid as a `msg.value`.
    function _beforeTransferFor(address to, address token, uint256 amount) internal returns (uint256) {
        // If the token is the native token, return the amount as msg.value.
        if (token == JBConstants.NATIVE_TOKEN) return amount;

        // Reset-then-set: avoid reverts from tokens that disallow non-zero to non-zero approval changes.
        IERC20(token).forceApprove({spender: to, value: amount});

        return 0;
    }

    /// @notice Snapshot the normalized input-token balance used to measure refundable leftovers for one route.
    /// @param tokenIn The token to route.
    /// @param amount The fresh route input amount currently held by the router.
    /// @return baseline The normalized input-token balance attributable only to pre-existing funds.
    function _refundBalanceBaselineOf(address tokenIn, uint256 amount) internal view returns (uint256 baseline) {
        // Start from the router's normalized input-token balance before the route consumes any of it.
        baseline = IERC20(_normalize(tokenIn)).balanceOf(address(this));

        // Exclude the fresh ERC-20 route input so only pre-existing balances count toward refundable leftovers.
        if (tokenIn != JBConstants.NATIVE_TOKEN) baseline -= amount;
    }

    /// @notice Recursively cash out JB project tokens until reaching a token the destination accepts or a base token.
    /// @param destProjectId The ID of the destination project.
    /// @param token The current token to process.
    /// @param amount The amount of the current token.
    /// @param metadata Bytes in `JBMetadataResolver`'s format (may contain a `cashOut` reclaim floor).
    /// @param refundTo The address that should receive any unsold source project tokens returned by a partial
    /// buyback-hook cash-out fill (otherwise they would strand in this router).
    /// @return destTerminal The terminal that accepts the final token (address(0) if no direct acceptance found).
    /// @return finalToken The token after all cashouts.
    /// @return finalAmount The amount of the final token.
    function _cashOutLoop(
        uint256 destProjectId,
        address token,
        uint256 amount,
        bytes calldata metadata,
        address preferredToken,
        address payable refundTo
    )
        internal
        returns (IJBTerminal destTerminal, address finalToken, uint256 finalAmount)
    {
        // Apply the caller's reclaim minimum only to the first cashout hop.
        // The metadata encodes one concrete token amount, so carrying it across later hops would mix incompatible
        // units once the route changes assets (for example, project token -> ETH -> USDC).
        // That means later hops intentionally run without this metadata-level reclaim floor.
        uint256 minTokensReclaimed = _minReclaimedFrom(metadata);

        // Walk the cashout path hop by hop until we reach a directly acceptable destination asset or exhaust the
        // bounded iteration limit.
        for (uint256 i; i < _MAX_CASHOUT_ITERATIONS;) {
            address routeToken;
            (destTerminal, routeToken) =
                _findRouteTerminal({destProjectId: destProjectId, token: token, preferredToken: preferredToken});
            if (address(destTerminal) != address(0)) {
                if (preferredToken != address(0)) {
                    (routeToken, amount) =
                        _alignTokenToPreferredToken({token: token, amount: amount, preferredToken: preferredToken});
                }
                return (destTerminal, routeToken, amount);
            }

            uint256 sourceProjectId = _sourceProjectIdOf(token);

            // If it's not a JB project token, return as-is (caller handles the swap).
            if (sourceProjectId == 0) return (IJBTerminal(address(0)), token, amount);

            // Find which terminal to cash out from and which token to reclaim.
            (address tokenToReclaim, IJBCashOutTerminal cashOutTerminal) = _findCashOutPath({
                sourceProjectId: sourceProjectId, destProjectId: destProjectId, preferredToken: preferredToken
            });

            _claimRouterCreditsFor({projectId: sourceProjectId});

            uint256 cashOutCount = amount;
            uint256 balanceBefore = _balanceOf({token: tokenToReclaim, account: address(this)});

            // Snapshot the source project-token balance so the unsold residue a partial buyback fill returns to this
            // router can be measured precisely below (only this hop's residue, never pre-existing balances).
            uint256 sourceBalanceBefore = _balanceOf({token: token, account: address(this)});

            // Cash out the source project's tokens.
            // Don't rely on the terminal return value here. Buyback-hook sell-side execution returns 0 reclaimAmount
            // from nana-core, then transfers the real proceeds during the hook callback.
            // Pass minTokensReclaimed=0 to the terminal because the buyback hook's sell-side delivers tokens via
            // callback (reclaimAmount=0 from the terminal's perspective), which would fail the terminal's own min
            // check. The router enforces the user's minimum via the balance-delta check below instead.
            // Still forward the original metadata on the first hop so the source hook can use the same user floor
            // when choosing between direct cash-out and its own routed cash-out path.
            bytes memory hopMetadata = i == 0 ? metadata : bytes("");
            cashOutTerminal.cashOutTokensOf({
                holder: address(this),
                projectId: sourceProjectId,
                cashOutCount: amount,
                tokenToReclaim: tokenToReclaim,
                minTokensReclaimed: 0,
                beneficiary: payable(address(this)),
                metadata: hopMetadata
            });

            // Measure the reclaimed-token balance delta so fee-on-transfer behavior cannot fake delivery.
            amount = _balanceOf({token: tokenToReclaim, account: address(this)}) - balanceBefore;

            // A non-zero cashout that delivers no reclaim tokens means this hop cannot safely continue.
            if (cashOutCount != 0 && amount == 0) {
                revert JBRouterTerminal_CashOutDidNotDeliver({
                    sourceToken: token, tokenToReclaim: tokenToReclaim, cashOutCount: cashOutCount
                });
            }

            // Enforce the caller's first-hop reclaim floor against the actual balance delta received.
            if (amount < minTokensReclaimed) {
                revert JBRouterTerminal_SlippageExceeded({amountOut: amount, minAmountOut: minTokensReclaimed});
            }

            // Refund any unsold source project tokens the buyback hook returned on a partial fill. The terminal burned
            // `cashOutCount` source tokens before the hook ran, so the post-cash-out source balance is
            // `sourceBalanceBefore - cashOutCount + unsold`; recovering `unsold` refunds exactly this hop's residue to
            // the route's refund recipient instead of stranding it, without sweeping any pre-existing balance.
            uint256 sourceResidue =
                _balanceOf({token: token, account: address(this)}) + cashOutCount - sourceBalanceBefore;
            if (sourceResidue != 0) {
                _transferFrom({from: address(this), to: refundTo, token: token, amount: sourceResidue});
            }

            // Clear the reclaim minimum after the first hop.
            // Multi-hop routes can change token units between hops, so there is no sound generic way to rescale a
            // single metadata amount across the remaining path.
            minTokensReclaimed = 0;

            // Update for next iteration.
            token = tokenToReclaim;

            unchecked {
                ++i;
            }
        }

        // If we reach here, the loop exceeded the maximum iteration count.
        revert JBRouterTerminal_CashOutLoopLimit({maxIterations: _MAX_CASHOUT_ITERATIONS});
    }

    /// @notice Converts this router's internal project-token credits into ERC-20s before a source cash-out.
    /// @dev Core burns holder credits before ERC-20 balances. Normalizing first keeps a source cash-out scoped to
    /// transferable token balances already visible to the router.
    /// @param projectId The Juicebox project whose tokens are being cashed out.
    function _claimRouterCreditsFor(uint256 projectId) internal {
        uint256 creditCount = TOKENS.creditBalanceOf({holder: address(this), projectId: projectId});
        if (creditCount == 0) return;

        IJBController controller = IJBController(address(DIRECTORY.controllerOf(projectId)));
        controller.claimTokensFor({
            holder: address(this), projectId: projectId, tokenCount: creditCount, beneficiary: address(this)
        });
    }

    /// @notice Convert tokenIn to tokenOut. No-op if same, wrap/unwrap for native/wrapped-native, or swap via Uniswap.
    /// @param tokenIn The token to convert from.
    /// @param tokenOut The token to convert into.
    /// @param amount The amount to convert.
    /// @param metadata Bytes in `JBMetadataResolver`'s format (may contain a `pay` swap quote).
    /// @param refundTo The address to receive leftover input tokens from partial fills.
    /// @return The amount of tokenOut produced.
    function _convert(
        address tokenIn,
        address tokenOut,
        uint256 amount,
        bytes calldata metadata,
        address payable refundTo,
        uint256 refundBalanceBaseline
    )
        internal
        returns (uint256)
    {
        // Exact same token — no conversion needed.
        if (tokenIn == tokenOut) return amount;

        address nIn = _normalize(tokenIn);
        address nOut = _normalize(tokenOut);

        if (nIn == nOut) {
            // Same underlying token; wrap or unwrap.
            if (tokenIn == JBConstants.NATIVE_TOKEN) _wrapNativeToken(amount);
            else _unwrapNativeToken(amount);
            return amount;
        }

        // Different tokens — swap via Uniswap (V3 or V4).
        return _handleSwap({
            tokenIn: tokenIn,
            tokenOut: tokenOut,
            amount: amount,
            metadata: metadata,
            refundTo: refundTo,
            refundBalanceBaseline: refundBalanceBaseline
        });
    }

    /// @notice Discover a pool, get a quote, and execute the swap (dispatches to V3 or V4).
    /// @dev Separated from _handleSwap to manage stack depth.
    /// @param normalizedTokenIn The normalized token to swap in.
    /// @param normalizedTokenOut The normalized token to swap out.
    /// @param amount The amount of `normalizedTokenIn` to swap.
    /// @param metadata Bytes in `JBMetadataResolver`'s format, used for quote overrides.
    /// @param callbackData ABI-encoded callback data for the V3 swap path.
    /// @return amountOut The amount of `normalizedTokenOut` produced by the swap.
    function _executeSwap(
        address normalizedTokenIn,
        address normalizedTokenOut,
        bool canUseExistingNativeBalance,
        uint256 amount,
        bytes calldata metadata,
        bytes memory callbackData
    )
        internal
        returns (uint256 amountOut)
    {
        // Discover the best pool for the pair and compute the minimum acceptable output for the swap.
        (uint256 minAmountOut, PoolInfo memory pool) = _pickPoolAndQuote({
            metadata: metadata,
            normalizedTokenIn: normalizedTokenIn,
            amount: amount,
            normalizedTokenOut: normalizedTokenOut
        });

        // Dispatch to the V4 execution path when the chosen pool lives in the PoolManager.
        if (pool.isV4) {
            return _executeV4Swap({
                key: pool.v4Key,
                normalizedTokenIn: normalizedTokenIn,
                canUseExistingNativeBalance: canUseExistingNativeBalance,
                amount: amount,
                minAmountOut: minAmountOut
            });
        } else {
            // Otherwise execute the swap against the discovered V3 pool.
            return _executeV3Swap({
                pool: pool.v3Pool,
                normalizedTokenIn: normalizedTokenIn,
                normalizedTokenOut: normalizedTokenOut,
                amount: amount,
                minAmountOut: minAmountOut,
                callbackData: callbackData
            });
        }
    }

    /// @notice Execute a swap through a V3 pool.
    /// @param pool The V3 pool to swap through.
    /// @param normalizedTokenIn The normalized token to sell.
    /// @param normalizedTokenOut The normalized token to buy.
    /// @param amount The exact input amount to swap.
    /// @param minAmountOut The minimum acceptable output after slippage protection.
    /// @param callbackData ABI-encoded data that the V3 callback will use to settle the input side.
    /// @return amountOut The amount of `normalizedTokenOut` the pool returned.
    function _executeV3Swap(
        IUniswapV3Pool pool,
        address normalizedTokenIn,
        address normalizedTokenOut,
        uint256 amount,
        uint256 minAmountOut,
        bytes memory callbackData
    )
        internal
        returns (uint256 amountOut)
    {
        // Determine swap direction using Uniswap's canonical token ordering so both the pool call and
        // sqrt-price limit are computed against the same side of the pair.
        bool zeroForOne = normalizedTokenIn < normalizedTokenOut;

        // Ask the pool to execute an exact-input swap. The callback settles the input token after the pool
        // computes how much of the output side it owes this router.
        // Use extreme sqrtPriceLimitX96 values to allow the swap to execute fully. Slippage is enforced
        // by the post-swap minAmountOut check below, which is more correct than deriving a price limit
        // from average execution rate.
        // Authorize this pool for the synchronous callback window opened by `swap`.
        _v3ExpectedPool = address(pool);
        (int256 amount0, int256 amount1) = pool.swap({
            recipient: address(this),
            zeroForOne: zeroForOne,
            // forge-lint: disable-next-line(unsafe-typecast)
            amountSpecified: int256(amount),
            sqrtPriceLimitX96: zeroForOne ? TickMath.MIN_SQRT_RATIO + 1 : TickMath.MAX_SQRT_RATIO - 1,
            data: callbackData
        });
        // Close the callback window before enforcing realized output.
        _v3ExpectedPool = address(0);

        // Uniswap returns signed deltas for both sides of the swap. The output side is negative because the
        // pool sent tokens out to the router, so negate the selected leg to recover the positive amount received.
        amountOut = uint256(-(zeroForOne ? amount1 : amount0));

        // Enforce slippage protection via realized output vs minimum acceptable output.
        // This is strictly more correct than sqrtPriceLimitX96 (which conflates marginal and average price).
        if (amountOut < minAmountOut) {
            revert JBRouterTerminal_SlippageExceeded({amountOut: amountOut, minAmountOut: minAmountOut});
        }
    }

    /// @notice Execute a swap through a V4 pool via PoolManager.unlock().
    /// @param key The V4 pool key describing the pool to swap through.
    /// @param normalizedTokenIn The normalized token to swap in.
    /// @param canUseExistingNativeBalance Whether raw ETH already held by the router can fund the input side.
    /// @param amount The amount of `normalizedTokenIn` to swap.
    /// @param minAmountOut The minimum acceptable amount out for the swap.
    /// @return amountOut The amount produced by the V4 swap.
    function _executeV4Swap(
        PoolKey memory key,
        address normalizedTokenIn,
        bool canUseExistingNativeBalance,
        uint256 amount,
        uint256 minAmountOut
    )
        internal
        returns (uint256 amountOut)
    {
        // Convert wrapped-native-token addresses to V4's native representation (address(0)) for currency comparison.
        address v4In = normalizedTokenIn == address(wrappedNativeToken) ? address(0) : normalizedTokenIn;

        // Determine the V4 swap direction by comparing the input token to currency0 in the pool key.
        bool zeroForOne = Currency.unwrap(key.currency0) == v4In;

        // Use extreme sqrtPriceLimitX96 to allow full swap execution. Slippage is enforced by
        // the post-swap minAmountOut check in the unlock callback.
        uint160 sqrtPriceLimitX96 = zeroForOne ? TickMath.MIN_SQRT_RATIO + 1 : TickMath.MAX_SQRT_RATIO - 1;

        // V4 sign convention: negative = exact input, positive = exact output.
        // Ask the PoolManager to unlock and call back into this router to execute the swap atomically.
        // The router only reaches this path with uint256 amounts that fit the signed exact-input convention.
        // forge-lint: disable-next-line(unsafe-typecast)
        int256 exactInputAmount = -int256(amount);
        bytes memory result = poolManager.unlock(
            abi.encode(key, zeroForOne, exactInputAmount, sqrtPriceLimitX96, minAmountOut, canUseExistingNativeBalance)
        );

        // Decode and return the amount-out value surfaced by the unlock callback.
        amountOut = abi.decode(result, (uint256));
    }

    /// @notice Execute a Uniswap swap from tokenIn to tokenOut (V3 or V4).
    /// @param tokenIn The token to swap from.
    /// @param tokenOut The token to swap into.
    /// @param amount The amount of tokenIn to swap.
    /// @param metadata Bytes in `JBMetadataResolver`'s format (may contain a `pay` swap quote).
    /// @param refundTo The address to receive leftover input tokens from partial fills.
    /// @return amountOut The amount of tokenOut received.
    function _handleSwap(
        address tokenIn,
        address tokenOut,
        uint256 amount,
        bytes calldata metadata,
        address payable refundTo,
        uint256 refundBalanceBaseline
    )
        internal
        returns (uint256 amountOut)
    {
        address normalizedTokenIn = _normalize(tokenIn);
        uint256 nativeBalanceBaseline;
        if (tokenIn == JBConstants.NATIVE_TOKEN) nativeBalanceBaseline = address(this).balance - amount;

        // Execute the swap in a scoped block to manage stack depth.
        amountOut = _executeSwap({
            normalizedTokenIn: normalizedTokenIn,
            normalizedTokenOut: _normalize(tokenOut),
            canUseExistingNativeBalance: tokenIn == JBConstants.NATIVE_TOKEN,
            amount: amount,
            metadata: metadata,
            callbackData: abi.encode(tokenIn)
        });

        // For native token inputs, wrap any raw ETH remaining from partial fills so the leftover check catches it.
        // In partial fills, the swap callback only wraps the amount the pool consumed, leaving excess as raw ETH.
        if (tokenIn == JBConstants.NATIVE_TOKEN && address(this).balance > nativeBalanceBaseline) {
            _wrapNativeToken(address(this).balance - nativeBalanceBaseline);
        }

        // Unwrap if output is native token.
        if (tokenOut == JBConstants.NATIVE_TOKEN) _unwrapNativeToken(amountOut);

        // Refund only the leftover portion attributable to this swap. Pre-existing balances are not part of the
        // caller's route and should not be swept into the current refund.
        uint256 balanceAfter = IERC20(normalizedTokenIn).balanceOf(address(this));
        if (balanceAfter > refundBalanceBaseline) {
            uint256 refundAmount = balanceAfter - refundBalanceBaseline;
            if (tokenIn == JBConstants.NATIVE_TOKEN) {
                _unwrapNativeToken(refundAmount);
                // Try native refund; fall back to wrapped native token if the recipient cannot accept native tokens.
                (bool success,) = refundTo.call{value: refundAmount}("");
                if (!success) {
                    _wrapNativeToken(refundAmount);
                    IERC20(address(wrappedNativeToken)).safeTransfer({to: refundTo, value: refundAmount});
                }
            } else {
                _transferFrom({from: address(this), to: refundTo, token: tokenIn, amount: refundAmount});
            }
        }
    }

    /// @notice Core routing logic shared by pay() and addToBalanceOf().
    /// @dev Determines whether to forward directly, cashout JB tokens, swap via Uniswap, or a combination.
    /// @param destProjectId The ID of the destination project.
    /// @param tokenIn The address of the token to route.
    /// @param amount The amount of tokens to route.
    /// @param metadata Bytes in `JBMetadataResolver`'s format.
    /// @param refundTo The address to receive leftover input tokens from partial fills.
    /// @return destTerminal The terminal to forward funds to.
    /// @return tokenOut The token the destination project accepts.
    /// @return amountOut The amount of tokenOut to forward.
    function _route(
        uint256 destProjectId,
        address tokenIn,
        uint256 amount,
        bytes calldata metadata,
        address payable refundTo
    )
        internal
        returns (IJBTerminal destTerminal, address tokenOut, uint256 amountOut)
    {
        // Route any project-token source through cashout before resolving the destination token.
        (destTerminal, tokenIn, amount) = _routeInputFromSource({
            destProjectId: destProjectId,
            tokenIn: tokenIn,
            amount: amount,
            metadata: metadata,
            preferredToken: address(0),
            refundTo: refundTo
        });

        // If the cashout loop found a destination terminal, the route is already complete.
        if (address(destTerminal) != address(0)) return (destTerminal, tokenIn, amount);

        // Resolve what token the destination project accepts and which terminal to use.
        (tokenOut, destTerminal) = _PAY_ROUTE_RESOLVER.resolveTokenOut({
            router: IJBPayRoutePreviewer(address(this)),
            wrappedNativeToken: address(wrappedNativeToken),
            projectId: destProjectId,
            tokenIn: tokenIn,
            metadata: metadata
        });

        // Convert the post-cashout route input into the resolved destination token and refund any leftover input.
        amountOut = _finalizeResolvedRoute({
            tokenIn: tokenIn,
            tokenOut: tokenOut,
            amount: amount,
            metadata: metadata,
            refundTo: refundTo,
            refundBalanceBaseline: _refundBalanceBaselineOf({tokenIn: tokenIn, amount: amount})
        });
    }

    /// @notice Route funds to a specific destination token.
    /// @param destProjectId The project to route the payment to.
    /// @param tokenIn The token currently held by the router for this route.
    /// @param amount The amount of `tokenIn` available to route.
    /// @param tokenOut The destination token for the project to receive.
    /// @param metadata Metadata forwarded into any source cashout and swap logic.
    /// @param refundTo The address to receive any leftover input tokens from partial fills.
    /// @return destTerminal The terminal that accepts the resolved destination token.
    /// @return resolvedTokenOut The concrete destination token the router routed into.
    /// @return amountOut The amount of `resolvedTokenOut` that will be delivered to `destTerminal`.
    function _routeToDestination(
        uint256 destProjectId,
        address tokenIn,
        uint256 amount,
        address tokenOut,
        IJBTerminal previewedDestTerminal,
        bytes calldata metadata,
        address payable refundTo
    )
        internal
        returns (IJBTerminal destTerminal, address resolvedTokenOut, uint256 amountOut)
    {
        // Start from the caller-requested destination token.
        resolvedTokenOut = tokenOut;

        // Reuse the terminal already resolved during preview to avoid a redundant directory lookup.
        destTerminal = previewedDestTerminal;

        // Hold the terminal surfaced by a source-project cashout path, if that path reaches the destination directly.
        IJBTerminal cashOutResolvedTerminal;

        // First route through any source-project cashout path so project-token inputs are converted before swap logic.
        (cashOutResolvedTerminal, tokenIn, amount) = _routeInputFromSource({
            destProjectId: destProjectId,
            tokenIn: tokenIn,
            amount: amount,
            metadata: metadata,
            preferredToken: tokenOut,
            refundTo: refundTo
        });

        // Return early when the source cashout path already reached the final destination terminal.
        if (address(cashOutResolvedTerminal) != address(0)) return (cashOutResolvedTerminal, tokenOut, amount);

        // Convert the post-cashout route input into the resolved destination token and refund any leftover input.
        amountOut = _finalizeResolvedRoute({
            tokenIn: tokenIn,
            tokenOut: tokenOut,
            amount: amount,
            metadata: metadata,
            refundTo: refundTo,
            refundBalanceBaseline: _refundBalanceBaselineOf({tokenIn: tokenIn, amount: amount})
        });
    }

    /// @notice Route the current input through a project-token cashout first when the route starts from a JB token.
    /// @param destProjectId The destination project to reach.
    /// @param tokenIn The current route input token.
    /// @param amount The current route input amount.
    /// @param metadata Metadata that may include a `cashOut` reclaim floor.
    /// @param preferredToken The preferred token to target during any cashout loop.
    /// @param refundTo The address that should receive any unsold source project tokens from a partial buyback fill.
    /// @return resolvedTerminal The terminal found by the cashout loop, or address(0) if conversion should continue.
    /// @return routedTokenIn The token that remains to be routed after the cashout step.
    /// @return routedAmountIn The amount of `routedTokenIn` that remains to be routed.
    function _routeInputFromSource(
        uint256 destProjectId,
        address tokenIn,
        uint256 amount,
        bytes calldata metadata,
        address preferredToken,
        address payable refundTo
    )
        internal
        returns (IJBTerminal resolvedTerminal, address routedTokenIn, uint256 routedAmountIn)
    {
        // Leave the route unchanged when the input is not a JB project token.
        if (_sourceProjectIdOf(tokenIn) == 0) return (resolvedTerminal, tokenIn, amount);

        // Cash out through the discovered source project before the caller continues with direct routing or swaps.
        return _cashOutLoop({
            destProjectId: destProjectId,
            token: tokenIn,
            amount: amount,
            metadata: metadata,
            preferredToken: preferredToken,
            refundTo: refundTo
        });
    }

    /// @notice Convert a route whose destination token is already resolved into that destination token.
    /// @param tokenIn The post-cashout route input token.
    /// @param tokenOut The resolved destination token to convert into.
    /// @param amount The amount of `tokenIn` available to convert.
    /// @param metadata Metadata forwarded into swap execution.
    /// @param refundTo The address that should receive any leftover input tokens from partial fills.
    /// @param refundBalanceBaseline The normalized input-token balance baseline for partial-fill refunds.
    /// @return amountOut The amount of `tokenOut` produced for the destination terminal.
    function _finalizeResolvedRoute(
        address tokenIn,
        address tokenOut,
        uint256 amount,
        bytes calldata metadata,
        address payable refundTo,
        uint256 refundBalanceBaseline
    )
        internal
        returns (uint256 amountOut)
    {
        // Convert tokenIn -> tokenOut (no-op if they match, wrap/unwrap, or swap).
        amountOut = _convert({
            tokenIn: tokenIn,
            tokenOut: tokenOut,
            amount: amount,
            metadata: metadata,
            refundTo: refundTo,
            refundBalanceBaseline: refundBalanceBaseline
        });
    }

    /// @notice Settle the input side of a V4 swap by transferring the owed input asset into the PoolManager.
    /// @param currency The V4 currency to settle with the PoolManager.
    /// @param amount The amount of `currency` to settle.
    /// @param canUseExistingNativeBalance Whether already-held raw native tokens can be used before unwrapping.
    function _settleV4(Currency currency, uint256 amount, bool canUseExistingNativeBalance) internal {
        if (Currency.unwrap(currency) == address(0)) {
            // Native-funded routes may spend the ETH they already hold.
            // Wrapped-native-funded routes must not consume unrelated raw native tokens already sitting on the router.
            if (canUseExistingNativeBalance) {
                // Only unwrap the shortfall so routes funded by direct native tokens do not churn through wrapping
                // unnecessarily.
                uint256 deficit = amount > address(this).balance ? amount - address(this).balance : 0;
                if (deficit > 0) _unwrapNativeToken(deficit);
            } else {
                // Wrapped-native-funded routes should unwrap the full amount because they are not allowed to consume
                // ambient native tokens.
                _unwrapNativeToken(amount);
            }
            // Native settlement uses `msg.value` because PoolManager expects ETH to accompany the settle call.
            poolManager.settle{value: amount}();
        } else {
            // ERC20 settlement requires PoolManager to observe the token first (`sync`), then receive the transfer,
            // then finalize the accounting with `settle`.
            poolManager.sync(currency);
            IERC20(Currency.unwrap(currency)).safeTransfer({to: address(poolManager), value: amount});
            poolManager.settle();
        }
    }

    /// @notice Take the output side of a V4 swap by pulling the owed asset from the PoolManager.
    /// @param currency The V4 currency to take from the PoolManager.
    /// @param amount The amount of `currency` to take.
    function _takeV4(Currency currency, uint256 amount) internal {
        // Pull the owed output asset into the router before any later wrapping/unwrapping or forwarding logic runs.
        poolManager.take({currency: currency, to: address(this), amount: amount});

        // If native token output, wrap it (downstream _handleSwap unwraps if needed).
        if (Currency.unwrap(currency) == address(0)) _wrapNativeToken(amount);
    }

    /// @notice Transfer tokens from one address to another using direct approval, `safeTransfer`, or Permit2 fallback.
    /// @param from The address to transfer tokens from.
    /// @param to The address to transfer tokens to.
    /// @param token The address of the token to transfer.
    /// @param amount The amount of tokens to transfer.
    function _transferFrom(address from, address payable to, address token, uint256 amount) internal {
        if (from == address(this)) {
            // If the token is native token, assume the `sendValue` standard.
            if (token == JBConstants.NATIVE_TOKEN) return Address.sendValue({recipient: to, amount: amount});

            // If the transfer is from this terminal, use `safeTransfer`.
            return IERC20(token).safeTransfer({to: to, value: amount});
        }

        // If there's sufficient approval, transfer normally.
        if (IERC20(token).allowance({owner: address(from), spender: address(this)}) >= amount) {
            return IERC20(token).safeTransferFrom({from: from, to: to, value: amount});
        }

        // Otherwise, attempt to use the `permit2` method.
        if (amount > type(uint160).max) revert JBRouterTerminal_AmountOverflow(amount);
        // forge-lint: disable-next-line(unsafe-typecast)
        PERMIT2.transferFrom({from: from, to: to, amount: uint160(amount), token: token});
    }

    /// @notice Convert native tokens and wrapped native tokens into the preferred concrete asset when both normalize to
    /// the same token. @param token The token currently held by the router.
    /// @param amount The amount of `token` currently held.
    /// @param preferredToken The exact token the downstream route expects.
    /// @return alignedToken The token to surface to downstream routing.
    /// @return alignedAmount The amount of `alignedToken`.
    function _alignTokenToPreferredToken(
        address token,
        uint256 amount,
        address preferredToken
    )
        internal
        returns (address alignedToken, uint256 alignedAmount)
    {
        // Leave exact-token matches untouched.
        if (token == preferredToken) return (token, amount);

        // Wrap native tokens when the preferred token is the ERC-20 wrapper.
        if (token == JBConstants.NATIVE_TOKEN && preferredToken == address(wrappedNativeToken)) {
            _wrapNativeToken(amount);
            return (preferredToken, amount);
        }

        // Unwrap wrapped native tokens when the preferred token is the native-token sentinel.
        if (token == address(wrappedNativeToken) && preferredToken == JBConstants.NATIVE_TOKEN) {
            _unwrapNativeToken(amount);
            return (preferredToken, amount);
        }

        // Return all other token pairs unchanged.
        return (token, amount);
    }

    /// @notice Wrap native tokens into their ERC-20 wrapped representation.
    /// @param amount The amount of native tokens to wrap.
    function _wrapNativeToken(uint256 amount) internal {
        wrappedNativeToken.deposit{value: amount}();
    }

    /// @notice Unwrap wrapped native tokens into native tokens.
    /// @param amount The amount of wrapped native tokens to unwrap.
    function _unwrapNativeToken(uint256 amount) internal {
        wrappedNativeToken.withdraw(amount);
    }

    //*********************************************************************//
    // ------------------------- internal views -------------------------- //
    //*********************************************************************//

    /// @notice Look up a pool address from the V3 factory.
    /// @param tokenA One token in the pair.
    /// @param tokenB The other token in the pair.
    /// @param fee The fee tier to query.
    /// @return The pool address, or address(0) if none exists.
    function _getPool(address tokenA, address tokenB, uint24 fee) internal view returns (address) {
        return factory.getPool({tokenA: tokenA, tokenB: tokenB, fee: fee});
    }

    /// @notice Look up the in-range liquidity of a V4 pool.
    /// @param id The pool ID to query.
    /// @return The pool's current in-range liquidity.
    function _getLiquidity(PoolId id) internal view returns (uint128) {
        return poolManager.getLiquidity(id);
    }

    /// @notice Read slot0 from a V4 pool.
    /// @param id The pool ID to query.
    /// @return sqrtPriceX96 The current sqrt price.
    /// @return tick The current tick.
    /// @return protocolFee The protocol fee.
    /// @return lpFee The LP fee.
    function _getSlot0(PoolId id)
        internal
        view
        returns (uint160 sqrtPriceX96, int24 tick, uint24 protocolFee, uint24 lpFee)
    {
        return poolManager.getSlot0(id);
    }

    /// @notice Look up the primary terminal for a project and token.
    /// @param projectId The ID of the project to look up.
    /// @param token The token to look up.
    /// @return The primary terminal, or IJBTerminal(address(0)) if none.
    function _primaryTerminalOf(uint256 projectId, address token) internal view returns (IJBTerminal) {
        return DIRECTORY.primaryTerminalOf({projectId: projectId, token: token});
    }

    /// @notice Look up the project ID for a token.
    /// @param token The token address to query.
    /// @return The project ID, or 0 if the token is not a JB project token.
    function _projectIdOf(address token) internal view returns (uint256) {
        return TOKENS.projectIdOf(IJBToken(token));
    }

    /// @notice Read a project's terminal list from the directory.
    /// @param projectId The project to read terminals for.
    /// @param shouldIgnoreFailure Whether a reverting directory call should degrade into an empty list.
    /// @return terminals The project's terminal list, or an empty list if `shouldIgnoreFailure` is true and the call
    /// failed.
    function _terminalsOf(
        uint256 projectId,
        bool shouldIgnoreFailure
    )
        internal
        view
        returns (IJBTerminal[] memory terminals)
    {
        // Use the direct directory view when failures should surface to the caller.
        if (!shouldIgnoreFailure) return DIRECTORY.terminalsOf(projectId);

        // Fall back to a low-level staticcall so no-code or reverting directories degrade into an empty list.
        (bool success, bytes memory data) =
            address(DIRECTORY).staticcall(abi.encodeCall(IJBDirectory.terminalsOf, (projectId)));

        // Return the default empty array when the best-effort lookup failed or returned no payload.
        if (!success || data.length == 0) return terminals;

        // Decode and return the terminal list when the best-effort lookup succeeded.
        return abi.decode(data, (IJBTerminal[]));
    }

    /// @notice Find the highest liquidity across all V3 fee tiers and V4 pools for a token pair.
    /// @param tokenA One token in the pair.
    /// @param tokenB The other token in the pair.
    /// @return bestLiquidity The highest liquidity found, or 0 if no pool exists.
    function _bestPoolLiquidity(address tokenA, address tokenB) internal view returns (uint128 bestLiquidity) {
        PoolInfo memory pool = _discoverPool({normalizedTokenIn: tokenA, normalizedTokenOut: tokenB});
        if (pool.isV4) return _getLiquidity(pool.v4Key.toId());
        if (address(pool.v3Pool) != address(0)) return pool.v3Pool.liquidity();
    }

    /// @notice Return the ERC-2771 context suffix length used by the inherited forwarder-aware context.
    /// @return suffixLength The number of bytes appended to calldata for the forwarded sender.
    /// @dev ERC-2771 specifies the context as a single address, which is always 20 bytes.
    function _contextSuffixLength() internal view override returns (uint256) {
        return super._contextSuffixLength();
    }

    /// @notice Check whether a cashout route can complete at the current destination.
    /// @dev Shared by _cashOutLoop and _previewCashOutLoop to keep destination logic in sync.
    /// @param destProjectId The destination project to check.
    /// @param token The current token in the route.
    /// @param preferredToken The caller's preferred output token (or address(0) for none).
    /// @return terminal The usable terminal if a route was found, or IJBTerminal(address(0)).
    /// @return resultToken The token accepted by the terminal.
    function _findRouteTerminal(
        uint256 destProjectId,
        address token,
        address preferredToken
    )
        internal
        view
        returns (IJBTerminal terminal, address resultToken)
    {
        if (preferredToken != address(0)) {
            // Same-routing-asset check: exact match, or both normalize to the same wrapped-native form.
            if (token == preferredToken || _normalize(token) == _normalize(preferredToken)) {
                terminal = _usablePrimaryTerminalOf({projectId: destProjectId, token: preferredToken});
                if (address(terminal) != address(0)) return (terminal, preferredToken);
            }
        } else {
            terminal = _usablePrimaryTerminalOf({projectId: destProjectId, token: token});
            if (address(terminal) != address(0)) return (terminal, token);
        }
    }

    /// @notice Search Uniswap V3 and V4 for the best pool between two tokens.
    /// @dev Returns the pool with the highest liquidity across both protocols.
    /// @param normalizedTokenIn The input token (wrapped if native).
    /// @param normalizedTokenOut The output token (wrapped if native).
    /// @return bestPool The pool with the highest liquidity.
    function _discoverPool(
        address normalizedTokenIn,
        address normalizedTokenOut
    )
        internal
        view
        returns (PoolInfo memory bestPool)
    {
        // Search V3 for the deepest pool and its liquidity.
        uint128 bestLiquidity;
        (bestPool.v3Pool, bestLiquidity) =
            _discoverV3PoolAndLiquidity({normalizedTokenIn: normalizedTokenIn, normalizedTokenOut: normalizedTokenOut});

        // Search V4, promoting a V4 pool only when it is deeper than the best V3 pool found above.
        bestPool = _discoverV4Pool({
            normalizedTokenIn: normalizedTokenIn,
            normalizedTokenOut: normalizedTokenOut,
            currentBestLiquidity: bestLiquidity,
            bestPool: bestPool
        });
    }

    /// @notice Find the highest-liquidity Uniswap V3 pool for a token pair across the common fee tiers.
    /// @param normalizedTokenIn The input token (wrapped if native).
    /// @param normalizedTokenOut The output token (wrapped if native).
    /// @return pool The V3 pool with the highest liquidity, or address(0) if none exists.
    function _discoverV3Pool(
        address normalizedTokenIn,
        address normalizedTokenOut
    )
        internal
        view
        returns (IUniswapV3Pool pool)
    {
        (pool,) =
            _discoverV3PoolAndLiquidity({normalizedTokenIn: normalizedTokenIn, normalizedTokenOut: normalizedTokenOut});
    }

    /// @notice Find the highest-liquidity Uniswap V3 pool for a token pair along with its liquidity.
    /// @param normalizedTokenIn The input token (wrapped if native).
    /// @param normalizedTokenOut The output token (wrapped if native).
    /// @return pool The V3 pool with the highest liquidity, or address(0) if none exists.
    /// @return liquidity The liquidity of the returned pool, or 0 if none exists.
    function _discoverV3PoolAndLiquidity(
        address normalizedTokenIn,
        address normalizedTokenOut
    )
        internal
        view
        returns (IUniswapV3Pool pool, uint128 liquidity)
    {
        for (uint256 i; i < 4;) {
            address poolAddr = _getPool({tokenA: normalizedTokenIn, tokenB: normalizedTokenOut, fee: _feeTier(i)});

            if (poolAddr == address(0)) {
                unchecked {
                    ++i;
                }
                continue;
            }

            uint128 poolLiquidity = IUniswapV3Pool(poolAddr).liquidity();

            if (poolLiquidity > liquidity) {
                liquidity = poolLiquidity;
                pool = IUniswapV3Pool(poolAddr);
            }

            unchecked {
                ++i;
            }
        }
    }

    /// @notice Search supported V4 pools and update the best pool candidate if a deeper V4 pool exists.
    /// @param normalizedTokenIn The normalized input token to search pools for.
    /// @param normalizedTokenOut The normalized output token to search pools for.
    /// @param currentBestLiquidity The highest liquidity found so far from prior discovery passes.
    /// @param bestPool The current best pool candidate to preserve unless a better V4 pool is found.
    /// @return updatedBestPool The winning pool after evaluating all supported V4 fee, tick-spacing, and hook
    /// combinations.
    function _discoverV4Pool(
        address normalizedTokenIn,
        address normalizedTokenOut,
        uint128 currentBestLiquidity,
        PoolInfo memory bestPool
    )
        internal
        view
        returns (PoolInfo memory updatedBestPool)
    {
        // Preserve the caller's current best pool unless a deeper V4 pool is found below.
        updatedBestPool = bestPool;

        // Exit early on chains where V4 is not deployed.
        if (address(poolManager) == address(0)) return updatedBestPool;

        // Convert wrapped native token -> address(0) for V4 native representation.
        address v4In = normalizedTokenIn == address(wrappedNativeToken) ? address(0) : normalizedTokenIn;
        address v4Out = normalizedTokenOut == address(wrappedNativeToken) ? address(0) : normalizedTokenOut;

        // Sort currencies (currency0 < currency1).
        (address sorted0, address sorted1) = v4In < v4Out ? (v4In, v4Out) : (v4Out, v4In);

        for (uint256 i; i < 4;) {
            for (uint256 j; j < 2;) {
                // Probe vanilla pools first, then the configured hooked-pool family if one exists.
                IHooks hooks = j == 0 ? IHooks(address(0)) : IHooks(univ4Hook);
                if (j != 0 && address(hooks) == address(0)) {
                    unchecked {
                        ++j;
                    }
                    continue;
                }

                // Build the V4 pool key for the current fee / tick-spacing / hook combination.
                // Fee tiers and tick spacings are returned from pure functions (no SLOAD).
                PoolKey memory key;
                {
                    (uint24 fee, int24 tickSpacing) = _v4FeeAndTickSpacing(i);
                    key = PoolKey({
                        currency0: _wrapCurrency(sorted0),
                        currency1: _wrapCurrency(sorted1),
                        fee: fee,
                        tickSpacing: tickSpacing,
                        hooks: hooks
                    });
                }

                // Cache key.toId() to avoid recomputing the same hash twice per inner iteration.
                PoolId id = key.toId();

                // Probe slot0 first so uninitialized pools can be skipped without treating them as valid candidates.
                (uint160 sqrtPriceX96,,,) = _getSlot0(id);
                if (sqrtPriceX96 == 0) {
                    unchecked {
                        ++j;
                    }
                    continue;
                }

                // Read the current in-range liquidity for the initialized pool.
                uint128 poolLiquidity = _getLiquidity(id);
                if (poolLiquidity > currentBestLiquidity) {
                    // Promote this V4 pool when it beats every candidate seen so far.
                    currentBestLiquidity = poolLiquidity;
                    updatedBestPool.isV4 = true;
                    updatedBestPool.v3Pool = IUniswapV3Pool(address(0));
                    updatedBestPool.v4Key = key;
                }

                unchecked {
                    ++j;
                }
            }

            unchecked {
                ++i;
            }
        }
    }

    /// @notice Find which terminal to cash out from and which token to reclaim.
    /// @dev Prioritizes: 1) tokens the destination directly accepts, 2) base tokens that can exit the recursion
    /// immediately, 3) JB project tokens (recursable) only when no direct or base-token exit exists.
    /// @param sourceProjectId The ID of the project to cash out tokens from.
    /// @param destProjectId The ID of the destination project.
    /// @return tokenToReclaim The token to reclaim from the cash out.
    /// @return cashOutTerminal The terminal to cash out from.
    function _findCashOutPath(
        uint256 sourceProjectId,
        uint256 destProjectId,
        address preferredToken
    )
        internal
        view
        returns (address tokenToReclaim, IJBCashOutTerminal cashOutTerminal)
    {
        CashOutPathCandidates memory candidates;

        // Read the source project's terminals in strict mode because cashout-path discovery should revert on
        // directory failure instead of silently changing recursion behavior.
        IJBTerminal[] memory terminals = _terminalsOf({projectId: sourceProjectId, shouldIgnoreFailure: false});

        for (uint256 i; i < terminals.length;) {
            // External calls to codeless entries return empty data and can fail in the caller's decode frame, outside
            // try/catch. Skip them before probing terminal capabilities.
            if (address(terminals[i]).code.length == 0) {
                unchecked {
                    ++i;
                }
                continue;
            }

            // Check if this terminal supports the IJBCashOutTerminal interface.
            try IERC165(address(terminals[i])).supportsInterface(type(IJBCashOutTerminal).interfaceId) returns (
                bool supported
            ) {
                if (!supported) {
                    unchecked {
                        ++i;
                    }
                    continue;
                }
            } catch {
                unchecked {
                    ++i;
                }
                continue;
            }

            IJBCashOutTerminal terminal = IJBCashOutTerminal(address(terminals[i]));
            JBAccountingContext[] memory contexts;
            try terminals[i].accountingContextsOf(sourceProjectId) returns (JBAccountingContext[] memory ctx) {
                contexts = ctx;
            } catch {
                unchecked {
                    ++i;
                }
                continue;
            }

            for (uint256 j; j < contexts.length;) {
                address contextToken = contexts[j].token;

                if (preferredToken != address(0) && contextToken == preferredToken) {
                    // Only treat the preferred token as a direct completion when its destination terminal is usable.
                    IJBTerminal preferredTerminal =
                        _usablePrimaryTerminalOf({projectId: destProjectId, token: contextToken});
                    if (address(preferredTerminal) != address(0)) return (contextToken, terminal);
                }

                // Priority 1: Does the destination project directly accept this token through a usable terminal?
                IJBTerminal destTerminal = _usablePrimaryTerminalOf({projectId: destProjectId, token: contextToken});
                _recordCashOutPathCandidate({
                    candidates: candidates, contextToken: contextToken, terminal: terminal, destTerminal: destTerminal
                });

                unchecked {
                    ++j;
                }
            }

            unchecked {
                ++i;
            }
        }

        // Prefer the token that the destination project can already accept directly.
        if (address(candidates.directFallbackTerminal) != address(0)) {
            return (candidates.directFallbackToken, candidates.directFallbackTerminal);
        }

        // Otherwise return the first base token discovered and let the router handle the remaining swap route.
        if (address(candidates.baseFallbackTerminal) != address(0)) {
            return (candidates.baseFallbackToken, candidates.baseFallbackTerminal);
        }

        // Otherwise fall back to a JB project token so the router can recurse through another cashout hop.
        if (address(candidates.fallbackTerminal) != address(0)) {
            return (candidates.fallbackToken, candidates.fallbackTerminal);
        }

        // Revert when no terminal exposed any reclaimable token that can advance the route.
        revert JBRouterTerminal_NoCashOutPath({sourceProjectId: sourceProjectId, destProjectId: destProjectId});
    }

    /// @notice Record a reclaim token as a direct, recursive, or base fallback during cashout-path discovery.
    /// @dev Mutates `candidates` in place (memory struct passed by reference) — no return value needed.
    /// @param candidates The current fallback candidates accumulated so far. Updated in-place by this call.
    /// @param contextToken The token exposed by the current cashout terminal accounting context.
    /// @param terminal The cashout terminal that can reclaim `contextToken`.
    /// @param destTerminal The destination project's direct terminal for `contextToken`, if any.
    function _recordCashOutPathCandidate(
        CashOutPathCandidates memory candidates,
        address contextToken,
        IJBCashOutTerminal terminal,
        IJBTerminal destTerminal
    )
        internal
        view
    {
        // Treat native ETH as a non-recursive base asset. For ERC-20s, detect whether the token is itself a JB
        // project token so recursive and base fallbacks stay disjoint.
        bool isJbProjectToken;
        if (contextToken != JBConstants.NATIVE_TOKEN) {
            isJbProjectToken = _projectIdOf(contextToken) != 0;
        }

        // Record the first directly accepted token only when its destination terminal is actually usable.
        if (address(destTerminal) != address(0) && address(candidates.directFallbackTerminal) == address(0)) {
            candidates.directFallbackToken = contextToken;
            candidates.directFallbackTerminal = terminal;
        }

        // Record the first JB project token so the router can recurse through another cashout hop if no direct or
        // base-token exit ends up existing.
        if (address(candidates.fallbackTerminal) == address(0) && isJbProjectToken) {
            candidates.fallbackToken = contextToken;
            candidates.fallbackTerminal = terminal;
        }

        // Record the first non-JB base-token fallback so the router can at least continue via a swap route.
        if (address(candidates.baseFallbackTerminal) == address(0) && !isJbProjectToken) {
            candidates.baseFallbackToken = contextToken;
            candidates.baseFallbackTerminal = terminal;
        }
    }

    /// @notice Get the slippage tolerance for a given swap using the continuous sigmoid formula.
    /// @param amountIn The amount of tokens to swap.
    /// @param liquidity The pool's in-range liquidity.
    /// @param tokenOut The output token.
    /// @param tokenIn The input token.
    /// @param arithmeticMeanTick The TWAP arithmetic mean tick (or spot tick for V4).
    /// @param poolFeeBps The pool fee in basis points.
    /// @return The slippage tolerance in basis points of _SLIPPAGE_DENOMINATOR.
    function _getSlippageTolerance(
        uint256 amountIn,
        uint128 liquidity,
        address tokenOut,
        address tokenIn,
        int24 arithmeticMeanTick,
        uint256 poolFeeBps
    )
        internal
        pure
        returns (uint256)
    {
        // Identify token0 so the quote logic can determine the swap direction in canonical pool order.
        (address token0,) = tokenOut < tokenIn ? (tokenOut, tokenIn) : (tokenIn, tokenOut);

        // Record whether the swap moves from token0 to token1, which the impact helper needs for its math.
        bool zeroForOne = tokenIn == token0;

        // Convert the quoted tick into the corresponding sqrt price used by the impact model.
        uint160 sqrtP = TickMath.getSqrtRatioAtTick(arithmeticMeanTick);

        // Fall back to the full denominator if the tick maps to zero, which effectively means "100% slippage guard".
        if (sqrtP == 0) return _SLIPPAGE_DENOMINATOR;

        // Estimate the trade's price impact from size, liquidity, price, and swap direction.
        uint256 impact =
            JBSwapLib.calculateImpact({amountIn: amountIn, liquidity: liquidity, sqrtP: sqrtP, zeroForOne: zeroForOne});

        // Convert the estimated impact into the bounded sigmoid slippage tolerance used by the router.
        return JBSwapLib.getSlippageTolerance({impact: impact, poolFeeBps: poolFeeBps});
    }

    /// @notice Get a TWAP-based quote with dynamic slippage for a V3 pool.
    /// @param pool The V3 pool to quote.
    /// @param normalizedTokenIn The normalized token to swap in.
    /// @param normalizedTokenOut The normalized token to swap out.
    /// @param amount The amount of `normalizedTokenIn` to quote.
    /// @return minAmountOut The minimum amount out implied by the TWAP quote and dynamic slippage model.
    function _getV3TwapQuote(
        IUniswapV3Pool pool,
        address normalizedTokenIn,
        address normalizedTokenOut,
        uint256 amount
    )
        internal
        view
        returns (uint256 minAmountOut)
    {
        // Convert the V3 fee tier into basis points so the slippage helper can incorporate pool fees consistently.
        uint256 feeBps = uint256(pool.fee()) / 100;

        // Read the oldest observation age to determine how much TWAP history the pool can support.
        uint32 oldestObservation = OracleLibrary.getOldestObservationSecondsAgo(address(pool));

        // Abort when the pool has no oracle history at all, since no TWAP can be formed.
        if (oldestObservation == 0) revert JBRouterTerminal_NoObservationHistory({pool: address(pool)});

        // Start from the default TWAP window.
        uint256 twapWindow = DEFAULT_TWAP_WINDOW;

        // Clamp the TWAP window down when the pool's observation history is shorter than the default window.
        if (oldestObservation < twapWindow) twapWindow = oldestObservation;

        // Enforce a minimum TWAP window to prevent manipulation of short-history pools.
        if (twapWindow < MIN_TWAP_WINDOW) {
            revert JBRouterTerminal_InsufficientTwapHistory({
                pool: address(pool), twapWindow: twapWindow, minTwapWindow: MIN_TWAP_WINDOW
            });
        }

        // Query the V3 oracle for the arithmetic-mean tick and in-range liquidity over the chosen TWAP window.
        (
            int24 arithmeticMeanTick,
            uint128 liquidity
            // forge-lint: disable-next-line(unsafe-typecast)
        ) = OracleLibrary.consult({pool: address(pool), secondsAgo: uint32(twapWindow)});

        // Abort when the chosen TWAP window has no in-range liquidity.
        if (liquidity == 0) {
            revert JBRouterTerminal_NoLiquidity({pool: address(pool), poolId: PoolId.wrap(bytes32(0))});
        }

        // Convert the TWAP tick and liquidity into a minimum amount out using the router's dynamic slippage model.
        minAmountOut = _quoteWithSlippage({
            amount: amount,
            liquidity: liquidity,
            tokenIn: normalizedTokenIn,
            tokenOut: normalizedTokenOut,
            tick: arithmeticMeanTick,
            poolFeeBps: feeBps
        });
    }

    /// @notice Get an automatic V4 quote with dynamic slippage.
    /// @dev Prefers a hook-provided geomean/TWAP quote when available. For a pool with no such oracle it falls back to
    /// the pool's spot tick ONLY when `_strictSwapQuote` is false (the `pay` leg — backstopped end-to-end by
    /// `minReturnedTokens` — and off-chain previews). When `_strictSwapQuote` is true (the `addToBalanceOf` and
    /// cash-out-swap legs, which have no downstream backstop) it instead reverts
    /// `JBRouterTerminal_ManipulationResistantQuoteRequired`, forcing the caller to supply a `pay` quote. The spot
    /// fallback is a bounded-convenience path, not a fully manipulation-resistant one.
    ///
    /// SECURITY NOTE: The spot price read from `poolManager.getSlot0(id)` is an instantaneous value
    /// that can be manipulated within the same block (e.g. via sandwich attacks or flash loans). Unlike V3 pools,
    /// V4 vanilla pools do not expose a built-in TWAP oracle, so there is no manipulation-resistant price source
    /// available on-chain for automatic quoting.
    ///
    /// Accepted operating envelope:
    ///   1. This path is intended mainly for routine flows against sufficiently deep pools where the cost of
    ///      manipulating the spot price is expected to outweigh likely extractable value.
    ///   2. Deep liquidity reduces practical risk, but does NOT remove the underlying same-block manipulation surface.
    ///   3. Thin pools, newly initialized pools, and unusually large swaps should not rely on this fallback.
    ///
    /// Mitigations in place:
    ///   1. Users SHOULD provide a `pay` swap quote in the payment metadata (obtained from an off-chain
    ///      quoter or RPC simulation). The quote must encode the output token and minimum output amount. When present,
    ///      this function is bypassed entirely — see `_pickPoolAndQuote`.
    ///   2. When a hook implements `IGeomeanOracle.observe(...)`, this uses its oracle-derived tick, not spot price.
    ///   3. The spot fallback uses a fixed 15% haircut instead of the sigmoid formula, because both spot price and
    ///      instantaneous liquidity can be JIT-manipulated. TWAP-backed quotes still use the sigmoid tolerance model.
    ///   4. Pool discovery (`_discoverPool`) may select a V3 pool with TWAP if it has more liquidity, avoiding
    ///      this V4 spot-price path altogether.
    ///   5. On legs with no downstream `minReturnedTokens` backstop (`addToBalanceOf`, and cash-out routes that
    ///      settle via add-to-balance), `_strictSwapQuote` is set and this spot fallback is REFUSED: the call reverts
    ///      `JBRouterTerminal_ManipulationResistantQuoteRequired` unless the caller supplied a `pay` quote.
    ///
    /// Despite these mitigations, the spot-based fallback does NOT provide full MEV protection. Integrators and
    /// front-ends should supply `pay` swap-quote metadata for V4 swaps whenever possible so the user's slippage
    /// tolerance reflects a recent, off-chain-verified price. When no external quote can be provided, this fallback
    /// remains available as a bounded convenience path ONLY for the backstopped `pay` leg and off-chain previews; the
    /// un-backstopped `addToBalanceOf` and cash-out-swap legs refuse it (mitigation 5).
    /// @param key The V4 pool key describing the pool to quote against.
    /// @param normalizedTokenIn The normalized token to sell into the pool.
    /// @param normalizedTokenOut The normalized token to buy from the pool.
    /// @param amount The exact input amount to quote.
    /// @return minAmountOut The quoted minimum output after the router's slippage model is applied.
    function _getV4SpotQuote(
        PoolKey memory key,
        address normalizedTokenIn,
        address normalizedTokenOut,
        uint256 amount
    )
        internal
        view
        returns (uint256 minAmountOut)
    {
        PoolId id = key.toId();

        // The tick used for quoting — prefer TWAP over spot for MEV resistance.
        int24 tick;

        // Track whether the oracle hook provided a TWAP so we know whether to fall back to spot.
        bool usedTwap;

        // If the pool has a hook, try querying it as a geomean oracle (e.g., JBUniswapV4Hook implements this).
        if (address(key.hooks) != address(0)) {
            IGeomeanOracle oracle = IGeomeanOracle(address(key.hooks));
            uint32 quoteWindow = _TWAP_WINDOW;
            bool shouldObserve = true;

            // Prefer the full router window, but use the retained best-effort window when the hook reports partial
            // coverage. Hooks that do not expose this newer interface keep the previous observe-only behavior.
            try oracle.observationCoverageOf({key: key}) returns (uint32 oldestSecondsAgo) {
                if (oldestSecondsAgo == 0) {
                    shouldObserve = false;
                } else if (oldestSecondsAgo < quoteWindow) {
                    quoteWindow = oldestSecondsAgo;
                }
            } catch {}

            if (shouldObserve) {
                // Build the two-element lookback array: [quoteWindow seconds ago, current block time].
                uint32[] memory secondsAgos = new uint32[](2);
                secondsAgos[0] = quoteWindow;
                secondsAgos[1] = 0;

                // Ask the hook for cumulative tick data over the retained window. Silently catch if unsupported.
                try oracle.observe({key: key, secondsAgos: secondsAgos}) returns (
                    int56[] memory tickCumulatives, uint160[] memory
                ) {
                    // Guard against malicious/broken hooks returning fewer elements than requested.
                    // An OOB access in the try-success block panics and is NOT caught by catch{}.
                    if (tickCumulatives.length >= 2) {
                        // Derive the arithmetic mean tick: (cumulative_now - cumulative_start) / elapsed_seconds.
                        int56 tickDelta = tickCumulatives[1] - tickCumulatives[0];
                        // quoteWindow is bounded by `_TWAP_WINDOW`, a small protocol constant.
                        // forge-lint: disable-next-line(unsafe-typecast)
                        int56 period = int56(int32(quoteWindow));
                        // Cumulative values come from Uniswap observations, whose average tick is int24-bounded.
                        // forge-lint: disable-next-line(unsafe-typecast)
                        tick = int24(tickDelta / period);
                        // Round towards negative infinity for negative ticks (Uniswap convention).
                        if (tickDelta < 0 && (tickDelta % period != 0)) tick--;
                        usedTwap = true;
                    }
                } catch {}
            }
        }

        // If no TWAP was available (no hook, or hook doesn't implement observe), there is no manipulation-resistant
        // price source for this pool. For legs with a downstream backstop (pay's `minReturnedTokens`) or for off-chain
        // previews, fall back to the instantaneous spot tick (a bounded-convenience path). For legs with NO downstream
        // backstop (`addToBalanceOf`, and cash-out routes that settle via add-to-balance), refuse: a self-referential
        // spot floor against an attacker-initialized vanilla pool offers no real protection, so require the caller to
        // supply a `pay` quote instead.
        if (!usedTwap) {
            if (_strictSwapQuote) revert JBRouterTerminal_ManipulationResistantQuoteRequired({poolId: id});
            (, tick,,) = _getSlot0(id);
        }

        uint128 liquidity = _getLiquidity(id);

        if (liquidity == 0) revert JBRouterTerminal_NoLiquidity({pool: address(0), poolId: id});

        // V4 uses address(0) for native tokens; map the wrapped native token so OracleLibrary token sorting matches the
        // pool.
        normalizedTokenIn = normalizedTokenIn == address(wrappedNativeToken) ? address(0) : normalizedTokenIn;
        normalizedTokenOut = normalizedTokenOut == address(wrappedNativeToken) ? address(0) : normalizedTokenOut;

        if (!usedTwap) {
            // Without TWAP, instantaneous liquidity and spot price are both JIT-manipulable.
            // Use a fixed conservative slippage tolerance (15%) instead of the sigmoid formula, which
            // an attacker could deflate by inflating liquidity via just-in-time provisioning.
            uint256 fixedSlippage = 1500; // 15% in basis points of _SLIPPAGE_DENOMINATOR (10_000)

            // Quote the gross output at the spot tick.
            if (amount > type(uint128).max) revert JBRouterTerminal_AmountOverflow(amount);

            minAmountOut = OracleLibrary.getQuoteAtTick({
                tick: tick,
                // forge-lint: disable-next-line(unsafe-typecast)
                baseAmount: uint128(amount),
                baseToken: normalizedTokenIn,
                quoteToken: normalizedTokenOut
            });

            // Apply the fixed slippage tolerance.
            minAmountOut -= (minAmountOut * fixedSlippage) / _SLIPPAGE_DENOMINATOR;
        } else {
            minAmountOut = _quoteWithSlippage({
                amount: amount,
                liquidity: liquidity,
                tokenIn: normalizedTokenIn,
                tokenOut: normalizedTokenOut,
                tick: tick,
                poolFeeBps: uint256(key.fee) / 100
            });
        }
    }

    /// @notice Parse the optional `cashOut` metadata (the minimum-reclaim floor).
    /// @param metadata The metadata to inspect for minimum reclaim amounts.
    /// @return minTokensReclaimed The minimum reclaim amount, or 0 if none is specified.
    function _minReclaimedFrom(bytes calldata metadata) internal view returns (uint256 minTokensReclaimed) {
        (bool exists, bytes memory minData) = _getDataFor({metadata: metadata, id: _CASH_OUT_ID});
        if (exists) minTokensReclaimed = abi.decode(minData, (uint256));
    }

    /// @notice The calldata. Preferred to use over `msg.data`.
    /// @return calldata The `msg.data` of this call.
    function _msgData() internal view override returns (bytes calldata) {
        return ERC2771Context._msgData();
    }

    /// @notice The message's sender. Preferred to use over `msg.sender`.
    /// @return sender The address which sent this call.
    function _msgSender() internal view override returns (address sender) {
        return ERC2771Context._msgSender();
    }

    /// @notice Return the balance of an account for a token, using ETH balance for the native token sentinel.
    /// @param token The token to read the balance of.
    /// @param account The account to read the balance of.
    /// @return balance The account's balance in `token`.
    function _balanceOf(address token, address account) internal view returns (uint256) {
        // Read raw ETH balance for the native-token sentinel and ERC20 balance otherwise.
        return token == JBConstants.NATIVE_TOKEN ? account.balance : IERC20(_normalize(token)).balanceOf(account);
    }

    /// @notice Normalize a token address by replacing the native token sentinel with the wrapped native token.
    /// @param token The token to normalize.
    /// @return normalizedToken The normalized token address.
    function _normalize(address token) internal view returns (address) {
        // Replace the native-token sentinel with the wrapped native token so both share one routing representation.
        return token == JBConstants.NATIVE_TOKEN ? address(wrappedNativeToken) : token;
    }

    /// @notice Discover a pool and compute the minimum acceptable output for a swap. Uses a user-provided quote if
    /// available, otherwise falls back to TWAP (V3) or automatic V4 quoting with dynamic slippage.
    /// @dev For V4 pools without TWAP-capable hooks, `minAmountOut` is derived from the same-block spot tick, which is
    /// manipulable via sandwich attacks. This is an accepted risk for integrations that cannot source external quotes,
    /// especially when routing through deep pools and routine swap sizes, but it should not be treated as full MEV
    /// protection. Integrators should still supply `pay` swap-quote metadata whenever they can.
    ///
    /// Priority for `minAmountOut`:
    ///   1. **User-provided quote** — If a `pay` swap quote is present in `metadata`, it is used after confirming the
    ///      quote's output token matches the selected route. This is the recommended path for MEV protection,
    ///      especially for V4 pools.
    ///   2. **V3 TWAP** — If the best pool is V3, uses a manipulation-resistant time-weighted average price.
    ///   3. **V4 automatic quote** — If the best pool is V4, first attempts a hook-provided oracle quote and
    ///      otherwise falls back to the instantaneous `getSlot0` tick. The spot fallback is manipulable within the
    ///      same block (see `_getV4SpotQuote` security note). The sigmoid slippage formula provides a floor but not
    ///      full MEV protection.
    ///
    /// @param metadata Bytes in `JBMetadataResolver`'s format (may contain a `pay` swap quote).
    /// @param normalizedTokenIn The normalized input token address.
    /// @param amount The amount of tokens to swap.
    /// @param normalizedTokenOut The normalized output token address.
    /// @return minAmountOut The minimum acceptable output.
    /// @return pool The pool to swap in (V3 or V4).
    function _pickPoolAndQuote(
        bytes calldata metadata,
        address normalizedTokenIn,
        uint256 amount,
        address normalizedTokenOut
    )
        internal
        view
        returns (uint256 minAmountOut, PoolInfo memory pool)
    {
        // Discover the best pool across V3 and V4 fee tiers.
        pool = _discoverPool({normalizedTokenIn: normalizedTokenIn, normalizedTokenOut: normalizedTokenOut});
        if (!pool.isV4 && address(pool.v3Pool) == address(0)) {
            revert JBRouterTerminal_NoPoolFound({tokenIn: normalizedTokenIn, tokenOut: normalizedTokenOut});
        }

        // `pay` is encoded as `(tokenOut, minAmountOut)`. Binding the quote to its output token prevents
        // metadata quoted for one route from being replayed against another route with a weaker floor.
        (bool exists, bytes memory quote) = _getDataFor({metadata: metadata, id: _PAY_ID});

        if (exists) {
            (address quotedTokenOut, uint256 quotedMinAmountOut) = abi.decode(quote, (address, uint256));
            // Normalize ETH/WETH before comparing because pool routes use WETH internally for native-token swaps.
            if (_normalize(quotedTokenOut) != normalizedTokenOut) {
                revert JBRouterTerminal_QuoteTokenMismatch({
                    quotedTokenOut: quotedTokenOut, expectedTokenOut: normalizedTokenOut
                });
            }
            minAmountOut = quotedMinAmountOut;
        }

        // Treat a decoded value of 0 the same as "not provided" so that a stale or default-zero quote
        // does not silently disable slippage protection. Fall through to automatic quoting.
        if (minAmountOut != 0) {
            // User-provided quote is valid; skip automatic quoting.
        } else if (pool.isV4) {
            minAmountOut = _getV4SpotQuote({
                key: pool.v4Key,
                normalizedTokenIn: normalizedTokenIn,
                normalizedTokenOut: normalizedTokenOut,
                amount: amount
            });
        } else {
            minAmountOut = _getV3TwapQuote({
                pool: pool.v3Pool,
                normalizedTokenIn: normalizedTokenIn,
                normalizedTokenOut: normalizedTokenOut,
                amount: amount
            });
        }
    }

    /// @notice A view-only mirror of `_cashOutLoop`.
    /// @param destProjectId The ID of the destination project.
    /// @param token The current token to process.
    /// @param amount The amount of the current token.
    /// @param metadata Bytes in `JBMetadataResolver`'s format.
    /// @return destTerminal The terminal that accepts the final token, if found.
    /// @return finalToken The token after all cash-out steps.
    /// @return finalAmount The amount of the final token.
    function _previewCashOutLoop(
        uint256 destProjectId,
        address token,
        uint256 amount,
        bytes calldata metadata,
        address preferredToken
    )
        internal
        view
        returns (IJBTerminal destTerminal, address finalToken, uint256 finalAmount)
    {
        // Track the one-time minimum reclaim amount that the caller may require on the first hop.
        // Preview mirrors execution by not attempting to rescale this amount across later hops once the route changes
        // token units.
        uint256 minTokensReclaimed = _minReclaimedFrom(metadata);

        // Walk the same cash-out path execution would take, bounded to prevent circular routes.
        for (uint256 i; i < _MAX_CASHOUT_ITERATIONS;) {
            address routeToken;
            (destTerminal, routeToken) =
                _findRouteTerminal({destProjectId: destProjectId, token: token, preferredToken: preferredToken});
            if (address(destTerminal) != address(0)) return (destTerminal, routeToken, amount);

            uint256 sourceProjectId = _sourceProjectIdOf(token);

            // If this is no longer a JB project token, stop cashing out and let the caller continue routing from it.
            if (sourceProjectId == 0) return (IJBTerminal(address(0)), token, amount);

            // Hold the token produced by the next previewed cashout hop.
            address tokenToReclaim;

            // Preview the next cashout hop to learn which base token and amount would come out.
            (tokenToReclaim, amount) = _previewCashOutStep({
                sourceProjectId: sourceProjectId,
                destProjectId: destProjectId,
                amount: amount,
                metadata: i == 0 ? metadata : bytes(""),
                preferredToken: preferredToken
            });

            // Enforce the caller's minimum reclaim amount only on the first hop.
            if (amount < minTokensReclaimed) {
                revert JBRouterTerminal_SlippageExceeded({amountOut: amount, minAmountOut: minTokensReclaimed});
            }

            // Clear the reclaim minimum after the first hop because later hops may operate in different token units.
            minTokensReclaimed = 0;

            // Continue previewing from the token reclaimed in this hop.
            token = tokenToReclaim;

            unchecked {
                ++i;
            }
        }

        // If no terminal was reached within the iteration cap, treat the route as non-converging.
        revert JBRouterTerminal_CashOutLoopLimit({maxIterations: _MAX_CASHOUT_ITERATIONS});
    }

    /// @notice Preview a single cashout hop in the recursive cashout path.
    /// @param sourceProjectId The project to cash out tokens from.
    /// @param destProjectId The final destination project to pay.
    /// @param amount The amount of source-project tokens to cash out.
    /// @param metadata Metadata forwarded into the source terminal preview for this hop.
    /// @return tokenToReclaim The token that would be reclaimed from the source terminal.
    /// @return reclaimAmount The amount of that token that would be reclaimed.
    function _previewCashOutStep(
        uint256 sourceProjectId,
        uint256 destProjectId,
        uint256 amount,
        bytes memory metadata,
        address preferredToken
    )
        internal
        view
        returns (address tokenToReclaim, uint256 reclaimAmount)
    {
        // Hold the terminal that would process this cashout hop.
        IJBCashOutTerminal cashOutTerminal;

        // Resolve both the reclaim token and the terminal the router would use for this hop.
        (tokenToReclaim, cashOutTerminal) = _findCashOutPath({
            sourceProjectId: sourceProjectId, destProjectId: destProjectId, preferredToken: preferredToken
        });

        // Ask that terminal how much of the reclaim token this cashout count would return.
        JBCashOutHookSpecification[] memory hookSpecifications;
        (, reclaimAmount,, hookSpecifications) = cashOutTerminal.previewCashOutFrom({
            holder: address(this),
            projectId: sourceProjectId,
            cashOutCount: amount,
            tokenToReclaim: tokenToReclaim,
            beneficiary: payable(address(this)),
            metadata: metadata
        });

        // Deployment config makes this router a feeless cash-out beneficiary, so previews use the terminal's raw
        // reclaim amount and avoid carrying fee-discovery bytecode in the router.
        reclaimAmount =
            _effectivePreviewCashOutAmount({reclaimAmount: reclaimAmount, hookSpecifications: hookSpecifications});
    }

    /// @notice Get a minimum-amount-out quote at the given tick, applying dynamic slippage.
    /// @param amount The input amount.
    /// @param liquidity The pool's in-range liquidity.
    /// @param tokenIn The input token address for sorting and quoting.
    /// @param tokenOut The output token address for sorting and quoting.
    /// @param tick The tick to quote at (TWAP mean tick or spot tick).
    /// @param poolFeeBps The pool fee in basis points.
    /// @return minAmountOut The quoted output amount after slippage.
    function _quoteWithSlippage(
        uint256 amount,
        uint128 liquidity,
        address tokenIn,
        address tokenOut,
        int24 tick,
        uint256 poolFeeBps
    )
        internal
        pure
        returns (uint256 minAmountOut)
    {
        // Derive the sigmoid slippage tolerance for this quoted trade shape.
        uint256 slippageTolerance = _getSlippageTolerance({
            amountIn: amount,
            liquidity: liquidity,
            tokenOut: tokenOut,
            tokenIn: tokenIn,
            arithmeticMeanTick: tick,
            poolFeeBps: poolFeeBps
        });

        // Treat a full-denominator slippage tolerance as "no safe output" and surface 0 immediately.
        if (slippageTolerance >= _SLIPPAGE_DENOMINATOR) return 0;

        // Uniswap's quote helper accepts only uint128 base amounts.
        if (amount > type(uint128).max) revert JBRouterTerminal_AmountOverflow(amount);

        // Quote the gross output at the supplied tick before applying the router's slippage buffer.
        minAmountOut = OracleLibrary.getQuoteAtTick({
            tick: tick,
            // forge-lint: disable-next-line(unsafe-typecast)
            baseAmount: uint128(amount),
            baseToken: tokenIn,
            quoteToken: tokenOut
        });

        // Discount the gross quote by the computed slippage tolerance to get the enforceable minimum.
        minAmountOut -= (minAmountOut * slippageTolerance) / _SLIPPAGE_DENOMINATOR;
    }

    /// @notice Read a metadata entry from the router's metadata namespace.
    /// @param metadata The metadata blob to query.
    /// @param id The pre-computed metadata ID to look up.
    /// @return exists Whether the metadata entry was present.
    /// @return data The raw metadata payload for `id`.
    function _getDataFor(bytes calldata metadata, bytes4 id) internal pure returns (bool exists, bytes memory data) {
        return JBMetadataResolver.getDataFor({id: id, metadata: metadata});
    }

    /// @notice Wrap an address into a Uniswap V4 `Currency`.
    /// @param token The token address to wrap.
    /// @return currency The wrapped currency value.
    function _wrapCurrency(address token) internal pure returns (Currency currency) {
        return Currency.wrap(token);
    }

    /// @notice Return the V3 fee tier at the given index.
    /// @dev Replaces the storage array `_FEE_TIERS` with a pure function (no SLOAD).
    /// @param index The tier index (0-3), ordered by commonality: 0.3%, 0.05%, 1%, 0.01%.
    /// @return fee The fee value.
    function _feeTier(uint256 index) internal pure returns (uint24 fee) {
        if (index == 0) return 3000;
        if (index == 1) return 500;
        if (index == 2) return 10_000;
        return 100;
    }

    /// @notice Return the V4 fee and tick spacing at the given index.
    /// @dev Replaces the storage arrays `_V4_FEES` and `_V4_TICK_SPACINGS` with a single pure function (no SLOAD).
    /// @param index The tier index (0-3).
    /// @return fee The V4 fee value.
    /// @return tickSpacing The V4 tick spacing value.
    function _v4FeeAndTickSpacing(uint256 index) internal pure returns (uint24 fee, int24 tickSpacing) {
        if (index == 0) return (3000, 60);
        if (index == 1) return (500, 10);
        if (index == 2) return (10_000, 200);
        return (100, 1);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IJBDirectory} from "@bananapus/core-v6/src/interfaces/IJBDirectory.sol";
import {IJBPayerTracker} from "@bananapus/core-v6/src/interfaces/IJBPayerTracker.sol";
import {IJBPermitTerminal} from "@bananapus/core-v6/src/interfaces/IJBPermitTerminal.sol";
import {IJBTerminal} from "@bananapus/core-v6/src/interfaces/IJBTerminal.sol";
import {IJBToken} from "@bananapus/core-v6/src/interfaces/IJBToken.sol";
import {JBConstants} from "@bananapus/core-v6/src/libraries/JBConstants.sol";
import {JBMetadataResolver} from "@bananapus/core-v6/src/libraries/JBMetadataResolver.sol";
import {JBAccountingContext} from "@bananapus/core-v6/src/structs/JBAccountingContext.sol";
import {JBPayHookSpecification} from "@bananapus/core-v6/src/structs/JBPayHookSpecification.sol";
import {JBRuleset} from "@bananapus/core-v6/src/structs/JBRuleset.sol";
import {JBSingleAllowance} from "@bananapus/core-v6/src/structs/JBSingleAllowance.sol";
import {ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";
import {IAllowanceTransfer} from "@uniswap/permit2/src/interfaces/IAllowanceTransfer.sol";
import {IPermit2} from "@uniswap/permit2/src/interfaces/IPermit2.sol";
import {IUniswapV3Pool} from "@uniswap/v3-core/contracts/interfaces/IUniswapV3Pool.sol";

import {IJBForwardingTerminal} from "./interfaces/IJBForwardingTerminal.sol";
import {IJBRouterTerminal} from "./interfaces/IJBRouterTerminal.sol";
import {JBRouterTerminal} from "./JBRouterTerminal.sol";
import {IJBRouterTerminalGateway} from "./interfaces/IJBRouterTerminalGateway.sol";

import {JBForwardingCheck} from "./libraries/JBForwardingCheck.sol";

import {JBPendingRouterTerminalCall} from "./structs/JBPendingRouterTerminalCall.sol";
import {JBPendingRouterTerminalCallFailure} from "./structs/JBPendingRouterTerminalCallFailure.sol";
import {PoolInfo} from "./structs/PoolInfo.sol";

/// @notice A router-terminal gateway which retains an original input token when the fallible routing call fails.
/// @dev The registry points to this contract, which forwards atomically into an immutable `JBRouterTerminal`.
contract JBRouterTerminalGateway is ERC2771Context, IJBRouterTerminalGateway {
    // A library that adds default safety checks to ERC20 functionality.
    using SafeERC20 for IERC20;

    //*********************************************************************//
    // --------------------------- custom errors ------------------------- //
    //*********************************************************************//

    /// @notice Thrown when an amount exceeds the maximum width Permit2 can transfer.
    error JBRouterTerminalGateway_AmountOverflow(uint256 amount);

    /// @notice Thrown when the live block gas limit cannot support the minimum qualified call budget.
    error JBRouterTerminalGateway_BlockGasLimitTooLow(uint256 maximum, uint256 minimum);

    /// @notice Thrown when a supplied call, memo, and metadata do not match a pending call's stored commitment.
    error JBRouterTerminalGateway_CallDataMismatch(bytes32 expectedCommitment, bytes32 actualCommitment);

    /// @notice Thrown when a qualified attempt was not supplied enough gas.
    error JBRouterTerminalGateway_InsufficientRetryGas(uint256 available, uint256 required);

    /// @notice Thrown when native tokens are sent on an ERC20 call.
    error JBRouterTerminalGateway_NoMsgValueAllowed(uint256 value);

    /// @notice Thrown when a pending call has not accumulated enough matching failures to be finalized.
    error JBRouterTerminalGateway_PendingCallNotFinalizable(bytes32 id, uint32 failureCount);

    /// @notice Thrown when a pending call does not exist.
    error JBRouterTerminalGateway_PendingCallNotFound(bytes32 id);

    /// @notice Thrown when another qualified attempt is made before the retry delay has elapsed.
    error JBRouterTerminalGateway_PendingCallNotReady(bytes32 id, uint256 nextAttemptAt);

    /// @notice Thrown when ordinary processing is attempted after a call has qualified for finalization.
    error JBRouterTerminalGateway_PendingCallRequiresFinalization(bytes32 id);

    /// @notice Thrown when the payment amount exceeds the Permit2 allowance provided in metadata.
    error JBRouterTerminalGateway_PermitAllowanceNotEnough(uint256 amount, uint256 allowance);

    /// @notice Thrown when a callback-capable token re-enters the inbound balance-delta measurement.
    error JBRouterTerminalGateway_ReentrantTokenTransfer(address token);

    /// @notice Thrown when no non-circular registered source-project terminal accepts a refund.
    error JBRouterTerminalGateway_RefundFailed(address originalTerminal, address primaryTerminal);

    /// @notice Thrown when a caller-specified gas limit exceeds the live chain's executable budget.
    error JBRouterTerminalGateway_RetryGasLimitTooHigh(uint256 gasLimit, uint256 maximum);

    /// @notice Thrown when a caller-specified gas limit is below the budget required by the failure state.
    error JBRouterTerminalGateway_RetryGasLimitTooLow(uint256 gasLimit, uint256 minimum);

    /// @notice Thrown when a call which is not eligible for retention cannot be settled synchronously.
    error JBRouterTerminalGateway_RouteFailed(bytes32 errorHash);

    /// @notice Thrown when the immutable directory or router is the zero address.
    error JBRouterTerminalGateway_ZeroAddress();

    //*********************************************************************//
    // ------------------------- public constants ------------------------ //
    //*********************************************************************//

    /// @notice The number of matching, time-separated qualified failures required before finalization.
    uint256 public constant override FINALIZATION_FAILURE_COUNT = 3;

    /// @notice The base and minimum gas forwarded by a qualified retry or final attempt.
    uint256 public constant override QUALIFIED_CALL_GAS = 5_000_000;

    /// @notice The minimum delay between qualified failures and before finalization.
    uint256 public constant override RETRY_DELAY = 1 days;

    //*********************************************************************//
    // ----------------------- internal constants ------------------------ //
    //*********************************************************************//

    /// @notice Gas retained around an attempted route for cleanup and durable failure accounting.
    uint256 internal constant _FAILURE_GAS_RESERVE = 750_000;

    /// @notice The longest memo a retained call may carry. Retriers resupply the memo as calldata, and a very long one
    /// would push the top retry rung past what a single transaction can carry, locking custody.
    uint256 internal constant _MAX_RETAINED_MEMO_LENGTH = 4096;

    /// @notice The stable fingerprint used when an attempt consumes its complete forwarded gas budget.
    bytes32 internal constant _GAS_EXHAUSTED_ERROR_HASH = keccak256("JBRouterTerminalGateway: gas exhausted");

    /// @notice The EIP-7825 per-transaction gas cap (2^24). No transaction can carry more gas than this even when the
    /// block gas limit is larger, so the retry ladder must stop here or its top rungs become unexecutable.
    uint256 internal constant _TRANSACTION_GAS_CAP = 16_777_216;

    /// @notice Block gas retained for transaction overhead, EIP-150 withholding, and durable failure accounting.
    uint256 internal constant _TRANSACTION_GAS_RESERVE = 1_500_000;

    //*********************************************************************//
    // --------------- public immutable stored properties ---------------- //
    //*********************************************************************//

    /// @notice The immutable directory used to resolve a source project's current accounting terminal for refunds.
    IJBDirectory public immutable override DIRECTORY;

    /// @notice The Permit2 contract used for gasless ERC-20 approvals and transfers.
    IPermit2 public immutable override PERMIT2;

    /// @notice The immutable router terminal this gateway calls atomically.
    IJBRouterTerminal public immutable override ROUTER;

    //*********************************************************************//
    // -------------- internal immutable stored properties -------------- //
    //*********************************************************************//

    /// @notice Pre-computed metadata ID for `permit2` allowances addressed to this gateway.
    bytes4 internal immutable _PERMIT2_ID;

    //*********************************************************************//
    // --------------------- public stored properties -------------------- //
    //*********************************************************************//

    /// @notice The total number of pending-call identifiers issued.
    uint256 public override pendingCallCount;

    //*********************************************************************//
    // -------------------- internal stored properties ------------------- //
    //*********************************************************************//

    /// @notice The hash commitment binding each retained call, its memo, and its metadata.
    /// @dev Only the commitment is stored so the gas-constrained queue path writes a single slot. Retriers supply the
    /// full call from the queue event and are authenticated against this hash.
    mapping(bytes32 id => bytes32) internal _pendingCallCommitmentOf;

    /// @notice Qualified failure state for each retained call.
    mapping(bytes32 id => JBPendingRouterTerminalCallFailure) internal _pendingCallFailureOf;

    //*********************************************************************//
    // ------------------- transient stored properties ------------------- //
    //*********************************************************************//

    /// @notice Whether an ERC-20 transfer is inside its inbound balance-delta measurement.
    bool internal transient _acceptingToken;

    /// @notice The original payer propagated into the downstream router during an active attempt.
    address public transient override originalPayer;

    //*********************************************************************//
    // -------------------------- constructor ---------------------------- //
    //*********************************************************************//

    /// @param directory The immutable directory used to resolve project accounting terminals.
    /// @param permit2 The Permit2 singleton used for gasless ERC-20 approvals and transfers.
    /// @param router The immutable router terminal to call atomically.
    /// @param trustedForwarder The trusted ERC-2771 forwarder used by the surrounding protocol.
    constructor(
        IJBDirectory directory,
        IPermit2 permit2,
        IJBRouterTerminal router,
        address trustedForwarder
    )
        ERC2771Context(trustedForwarder)
    {
        // Both are load-bearing and unchangeable afterwards: without a router there is nothing to forward into, and
        // without a directory a retained call could never be refunded to its source project.
        if (address(directory) == address(0) || address(router) == address(0)) {
            revert JBRouterTerminalGateway_ZeroAddress();
        }

        // Refuse an installation whose chain cannot execute even the base recovery attempt. Custody would still be
        // takeable while every path out of it reverted.
        uint256 maximumGasLimit = _maximumQualifiedCallGas(block.gaslimit);
        if (maximumGasLimit < QUALIFIED_CALL_GAS) {
            revert JBRouterTerminalGateway_BlockGasLimitTooLow({maximum: maximumGasLimit, minimum: QUALIFIED_CALL_GAS});
        }

        DIRECTORY = directory;
        PERMIT2 = permit2;
        ROUTER = router;

        // Namespace the Permit2 metadata ID to this address so allowances signed for the Router or Registry are not
        // consumed here, and vice versa.
        _PERMIT2_ID = JBMetadataResolver.getId("permit2");
    }

    //*********************************************************************//
    // ---------------------- external transactions ---------------------- //
    //*********************************************************************//

    /// @notice Empty implementation because accounting contexts are delegated to `ROUTER`.
    /// @param projectId The ID of the project whose accounting contexts would otherwise be configured.
    /// @param accountingContexts Ignored because the immutable router derives accounting contexts at runtime.
    function addAccountingContextsFor(
        uint256 projectId,
        JBAccountingContext[] calldata accountingContexts
    )
        external
        override
    {}

    /// @notice Route an add-to-balance call, retaining failed input only when source-project metadata opts in.
    /// @dev The opt-in is metadata which is exactly 32 bytes encoding a nonzero raw source project ID. Calls without
    /// the opt-in revert synchronously when the routed attempt fails.
    /// @param projectId The ID of the destination project.
    /// @param token The address of the token to pay in.
    /// @param amount The amount of tokens to send.
    /// @param shouldReturnHeldFees Whether held fees should be returned based on the amount added.
    /// @param memo A memo to pass along to the emitted event.
    /// @param metadata Bytes in `JBMetadataResolver`'s format, or exactly 32 bytes naming the source project.
    function addToBalanceOf(
        uint256 projectId,
        address token,
        uint256 amount,
        bool shouldReturnHeldFees,
        string calldata memo,
        bytes calldata metadata
    )
        external
        payable
        override
    {
        // Resolve the upstream payer before taking custody, because a forwarding caller only exposes it for the
        // duration of its own call. This address becomes the preferred refund terminal if the route never settles.
        address refundTo = _resolveOriginalPayer(_msgSender());

        // Take custody up front so a later Router failure rolls back to this token rather than to a swapped one. The
        // amount is re-measured from the balance delta, which is what a fee-on-transfer input actually delivered.
        amount = _acceptFundsFor({token: token, amount: amount, metadata: metadata});

        // Read the escrow opt-in. Zero means this caller never asked for custody and expects a synchronous revert.
        uint256 sourceProjectId = _sourceProjectIdFrom(metadata);

        JBPendingRouterTerminalCall memory call = JBPendingRouterTerminalCall({
            amount: amount,
            // Add-to-balance has no beneficiary; the destination project's balance is the sole recipient.
            beneficiary: address(0),
            preferAddToBalance: true,
            projectId: projectId,
            refundTo: refundTo,
            shouldReturnHeldFees: shouldReturnHeldFees,
            sourceProjectId: sourceProjectId,
            token: token
        });

        // Decide on custody while gas is plentiful, so the failure path's fixed reserve cannot be starved by directory
        // reads.
        bool shouldRetain = bytes(memo).length <= _MAX_RETAINED_MEMO_LENGTH && _shouldRetain(call);

        // Try the route inside this transaction first. Nothing is retained when it settles.
        (bool success, bytes32 errorHash,, bool gasExhausted) =
            _attempt({call: call, minReturnedTokens: 0, memo: memo, metadata: metadata, gasLimit: 0});
        if (success) return;

        // Queue under the same class a retry would record, so the event stream never shows a phantom class change.
        if (gasExhausted) errorHash = _GAS_EXHAUSTED_ERROR_HASH;

        // Calls without a usable source-project opt-in retain synchronous failure semantics.
        if (!shouldRetain) revert JBRouterTerminalGateway_RouteFailed(errorHash);

        // The opt-in was given, so absorb the failure instead of bubbling it into the caller's catch boundary. The
        // input stays in custody and recovery becomes permissionless.
        _queue({call: call, memo: memo, metadata: metadata, errorHash: errorHash});
    }

    /// @notice Make one final qualified attempt, refunding only after the same failure class is reproduced.
    /// @dev Callable permissionlessly once `FINALIZATION_FAILURE_COUNT` matching failures have accumulated and the
    /// retry delay has elapsed. A changed failure class resets the streak instead of refunding. The supplied call,
    /// memo, and metadata are read from the queue event and authenticated against the stored commitment.
    /// @param id The pending call identifier.
    /// @param call The retained call, as emitted when it was queued.
    /// @param memo The original memo bound by the pending call.
    /// @param metadata The original metadata bound by the pending call.
    /// @return wasRefunded Whether the retained input was refunded.
    /// @return beneficiaryTokenCount The project tokens returned if the final `pay` attempt succeeded.
    function finalizePendingCall(
        bytes32 id,
        JBPendingRouterTerminalCall calldata call,
        string calldata memo,
        bytes calldata metadata
    )
        external
        override
        returns (bool wasRefunded, uint256 beneficiaryTokenCount)
    {
        return _finalizePendingCall({id: id, call: call, gasLimit: 0, memo: memo, metadata: metadata});
    }

    /// @notice Make one final qualified attempt with an expanded gas budget.
    /// @dev Behaves like `finalizePendingCall` but forwards a caller-selected budget, which must satisfy the pending
    /// call's escalating minimum and fit under the live chain's executable transaction budget.
    /// @param id The pending call identifier.
    /// @param call The retained call, as emitted when it was queued.
    /// @param gasLimit The gas to forward, which must satisfy the pending call's escalating minimum.
    /// @param memo The original memo bound by the pending call.
    /// @param metadata The original metadata bound by the pending call.
    /// @return wasRefunded Whether the retained input was refunded.
    /// @return beneficiaryTokenCount The project tokens returned if the final `pay` attempt succeeded.
    function finalizePendingCallWithGas(
        bytes32 id,
        JBPendingRouterTerminalCall calldata call,
        uint256 gasLimit,
        string calldata memo,
        bytes calldata metadata
    )
        external
        override
        returns (bool wasRefunded, uint256 beneficiaryTokenCount)
    {
        return _finalizePendingCall({id: id, call: call, gasLimit: gasLimit, memo: memo, metadata: metadata});
    }

    /// @notice Empty implementation because the gateway only escrows retained calls, not project balances.
    /// @param projectId The project whose balance migration was requested.
    /// @param token The token whose balance migration was requested.
    /// @param to The destination terminal that would receive migrated funds.
    /// @return balance Always returns 0 because the gateway does not hold project balances.
    function migrateBalanceOf(
        uint256 projectId,
        address token,
        IJBTerminal to
    )
        external
        pure
        override
        returns (uint256 balance)
    {
        projectId;
        token;
        to;
        return 0;
    }

    /// @notice Route a payment, retaining failed zero-minimum input only when source-project metadata opts in.
    /// @dev Retention requires `minReturnedTokens == 0` and metadata which is exactly 32 bytes encoding a nonzero raw
    /// source project ID. All other failed payments revert synchronously.
    /// @param projectId The ID of the destination project to pay.
    /// @param token The address of the token to pay with.
    /// @param amount The amount of tokens to send.
    /// @param beneficiary The address to receive any tokens minted by the destination project.
    /// @param minReturnedTokens The minimum number of destination project tokens expected in return.
    /// @param memo A memo to pass along to the emitted event.
    /// @param metadata Bytes in `JBMetadataResolver`'s format, or exactly 32 bytes naming the source project.
    /// @return beneficiaryTokenCount The number of tokens minted for the beneficiary.
    function pay(
        uint256 projectId,
        address token,
        uint256 amount,
        address beneficiary,
        uint256 minReturnedTokens,
        string calldata memo,
        bytes calldata metadata
    )
        external
        payable
        override
        returns (uint256 beneficiaryTokenCount)
    {
        // Resolve the upstream payer before taking custody, because a forwarding caller only exposes it for the
        // duration of its own call. This address becomes the preferred refund terminal if the route never settles.
        address refundTo = _resolveOriginalPayer(_msgSender());

        // Take custody up front so a later Router failure rolls back to this token rather than to a swapped one. The
        // amount is re-measured from the balance delta, which is what a fee-on-transfer input actually delivered.
        amount = _acceptFundsFor({token: token, amount: amount, metadata: metadata});

        // Read the escrow opt-in. Zero means this caller never asked for custody and expects a synchronous revert.
        uint256 sourceProjectId = _sourceProjectIdFrom(metadata);

        JBPendingRouterTerminalCall memory call = JBPendingRouterTerminalCall({
            amount: amount,
            beneficiary: beneficiary,
            preferAddToBalance: false,
            projectId: projectId,
            refundTo: refundTo,
            // Held-fee handling belongs to add-to-balance; a payment never asks for it.
            shouldReturnHeldFees: false,
            sourceProjectId: sourceProjectId,
            token: token
        });

        // Decide on custody while gas is plentiful, so the failure path's fixed reserve cannot be starved by directory
        // reads. A caller who priced a minimum is asking to fail now rather than to be settled later at an unknown
        // rate.
        bool shouldRetain =
            minReturnedTokens == 0 && bytes(memo).length <= _MAX_RETAINED_MEMO_LENGTH && _shouldRetain(call);

        // Try the route inside this transaction first, honoring the caller's minimum. Nothing is retained when it
        // settles, and the minimum is only ever enforced here because retained calls always carry a zero minimum.
        (bool success, bytes32 errorHash, uint256 count, bool gasExhausted) =
            _attempt({call: call, minReturnedTokens: minReturnedTokens, memo: memo, metadata: metadata, gasLimit: 0});
        if (success) return count;

        // Queue under the same class a retry would record, so the event stream never shows a phantom class change.
        if (gasExhausted) errorHash = _GAS_EXHAUSTED_ERROR_HASH;

        // Preserve minimums and calls without a usable source-project opt-in instead of silently expanding custody.
        if (!shouldRetain) revert JBRouterTerminalGateway_RouteFailed(errorHash);

        // The opt-in was given, so absorb the failure instead of bubbling it into the caller's catch boundary. The
        // input stays in custody and recovery becomes permissionless.
        _queue({call: call, memo: memo, metadata: metadata, errorHash: errorHash});
    }

    /// @notice Make a permissionless attempt using the default qualified gas budget.
    /// @dev Once `FINALIZATION_FAILURE_COUNT` matching failures have accumulated, further attempts must go through
    /// `finalizePendingCall`. The supplied call, memo, and metadata are read from the queue event and authenticated
    /// against the stored commitment.
    /// @param id The pending call identifier.
    /// @param call The retained call, as emitted when it was queued.
    /// @param memo The original memo bound by the pending call.
    /// @param metadata The original metadata bound by the pending call.
    /// @return beneficiaryTokenCount The project tokens returned if a routed `pay` succeeds.
    function processPendingCall(
        bytes32 id,
        JBPendingRouterTerminalCall calldata call,
        string calldata memo,
        bytes calldata metadata
    )
        external
        override
        returns (uint256 beneficiaryTokenCount)
    {
        return _processPendingCall({id: id, call: call, gasLimit: 0, memo: memo, metadata: metadata});
    }

    /// @notice Make a permissionless attempt with an expanded qualified gas budget.
    /// @dev Behaves like `processPendingCall` but forwards a caller-selected budget, which must satisfy the pending
    /// call's escalating minimum and fit under the live chain's executable transaction budget.
    /// @param id The pending call identifier.
    /// @param call The retained call, as emitted when it was queued.
    /// @param gasLimit The gas to forward, which must satisfy the pending call's escalating minimum.
    /// @param memo The original memo bound by the pending call.
    /// @param metadata The original metadata bound by the pending call.
    /// @return beneficiaryTokenCount The project tokens returned if a routed `pay` succeeds.
    function processPendingCallWithGas(
        bytes32 id,
        JBPendingRouterTerminalCall calldata call,
        uint256 gasLimit,
        string calldata memo,
        bytes calldata metadata
    )
        external
        override
        returns (uint256 beneficiaryTokenCount)
    {
        return _processPendingCall({id: id, call: call, gasLimit: gasLimit, memo: memo, metadata: metadata});
    }

    //*********************************************************************//
    // ------------------------- external views -------------------------- //
    //*********************************************************************//

    /// @notice Delegate the accounting-context lookup to the immutable router.
    /// @param projectId The ID of the project to get the accounting context for.
    /// @param token The address of the token to get the accounting context for.
    /// @return context The accounting context reported by the immutable router.
    function accountingContextForTokenOf(
        uint256 projectId,
        address token
    )
        external
        view
        override
        returns (JBAccountingContext memory context)
    {
        return ROUTER.accountingContextForTokenOf({projectId: projectId, token: token});
    }

    /// @notice Delegate the accounting-context lookup to the immutable router.
    /// @param projectId The project whose accounting contexts were requested.
    /// @return contexts The accounting contexts reported by the immutable router.
    function accountingContextsOf(uint256 projectId)
        external
        view
        override
        returns (JBAccountingContext[] memory contexts)
    {
        return ROUTER.accountingContextsOf(projectId);
    }

    /// @notice Delegate the surplus lookup to the immutable router.
    /// @param projectId The project whose surplus was requested.
    /// @param tokens The token set the caller wanted surplus measured against.
    /// @param decimals The fixed-point precision the caller wanted the surplus returned in.
    /// @param currency The currency the caller wanted the surplus returned in.
    /// @return surplus The surplus reported by the immutable router.
    function currentSurplusOf(
        uint256 projectId,
        address[] calldata tokens,
        uint256 decimals,
        uint256 currency
    )
        external
        view
        override
        returns (uint256 surplus)
    {
        return ROUTER.currentSurplusOf({projectId: projectId, tokens: tokens, decimals: decimals, currency: currency});
    }

    /// @notice Delegate best-pool discovery to the immutable router.
    /// @param normalizedTokenIn The input token (wrapped if native).
    /// @param normalizedTokenOut The output token (wrapped if native).
    /// @return pool The best pool found by the immutable router.
    function discoverBestPool(
        address normalizedTokenIn,
        address normalizedTokenOut
    )
        external
        view
        override
        returns (PoolInfo memory pool)
    {
        return ROUTER.discoverBestPool({normalizedTokenIn: normalizedTokenIn, normalizedTokenOut: normalizedTokenOut});
    }

    /// @notice Delegate V3 pool discovery to the immutable router.
    /// @param normalizedTokenIn The input token (wrapped if native).
    /// @param normalizedTokenOut The output token (wrapped if native).
    /// @return pool The V3 pool with the highest liquidity found by the immutable router.
    function discoverPool(
        address normalizedTokenIn,
        address normalizedTokenOut
    )
        external
        view
        override
        returns (IUniswapV3Pool pool)
    {
        return ROUTER.discoverPool({normalizedTokenIn: normalizedTokenIn, normalizedTokenOut: normalizedTokenOut});
    }

    /// @notice Return the hash commitment of a call retained after its atomic router attempt failed.
    /// @dev The full call, memo, and metadata are emitted by the queue event; only their hash is stored.
    /// @param id The pending call identifier.
    /// @return commitment The retained call's commitment, or zero when no call is pending under `id`.
    function pendingCallCommitmentOf(bytes32 id) external view override returns (bytes32 commitment) {
        return _pendingCallCommitmentOf[id];
    }

    /// @notice Return a retained call's consecutive matching failure state.
    /// @param id The pending call identifier.
    /// @return failure The matching failure state.
    function pendingCallFailureOf(bytes32 id)
        external
        view
        override
        returns (JBPendingRouterTerminalCallFailure memory failure)
    {
        return _pendingCallFailureOf[id];
    }

    /// @notice Delegate payment previewing to the immutable router.
    /// @param projectId The ID of the destination project to pay.
    /// @param token The token to provide to the router.
    /// @param amount The amount of tokens which would be sent.
    /// @param beneficiary The address which would receive any tokens minted by the destination project.
    /// @param metadata Bytes in `JBMetadataResolver`'s format.
    /// @return ruleset The destination project's ruleset the payment would be made under.
    /// @return beneficiaryTokenCount The number of tokens which would be minted for the beneficiary.
    /// @return reservedTokenCount The number of tokens which would be reserved by the destination project.
    /// @return hookSpecifications The pay hooks the destination project's ruleset would invoke.
    function previewPayFor(
        uint256 projectId,
        address token,
        uint256 amount,
        address beneficiary,
        bytes calldata metadata
    )
        external
        view
        override
        returns (
            JBRuleset memory ruleset,
            uint256 beneficiaryTokenCount,
            uint256 reservedTokenCount,
            JBPayHookSpecification[] memory hookSpecifications
        )
    {
        return ROUTER.previewPayFor({
            projectId: projectId, token: token, amount: amount, beneficiary: beneficiary, metadata: metadata
        });
    }

    /// @notice Return the terminal this gateway forwards into.
    /// @dev One hop only, never the end of the chain. `JBForwardingCheck` walks forwarders link by link to detect
    /// cycles, so naming a terminal further downstream would hide the router from that walk and let a route that
    /// returns to the router read as non-circular.
    /// @param projectId Ignored because every project forwards to the same immutable router.
    /// @return terminal The immutable router terminal.
    function terminalOf(uint256 projectId) external view override returns (IJBTerminal terminal) {
        projectId;
        return ROUTER;
    }

    //*********************************************************************//
    // -------------------------- public views --------------------------- //
    //*********************************************************************//

    /// @notice Return the largest qualified call budget executable under the live chain's block gas limit.
    /// @return gasLimit The maximum gas which may be forwarded while preserving accounting reserves.
    function maximumQualifiedCallGas() public view override returns (uint256 gasLimit) {
        return _maximumQualifiedCallGas(block.gaslimit);
    }

    /// @notice Indicates whether this gateway implements an interface.
    /// @param interfaceId The interface identifier to test.
    /// @return supported Whether the gateway implements `interfaceId`.
    function supportsInterface(bytes4 interfaceId) public pure override returns (bool supported) {
        return interfaceId == type(IJBForwardingTerminal).interfaceId
            || interfaceId == type(IJBPayerTracker).interfaceId || interfaceId == type(IJBPermitTerminal).interfaceId
            || interfaceId == type(IJBRouterTerminal).interfaceId
            || interfaceId == type(IJBRouterTerminalGateway).interfaceId || interfaceId == type(IJBTerminal).interfaceId
            || interfaceId == type(IERC165).interfaceId;
    }

    //*********************************************************************//
    // ---------------------- internal transactions ---------------------- //
    //*********************************************************************//

    /// @notice Accept an input token from the gateway's resolved ERC-2771 caller.
    /// @param token The token to accept, or the native-token sentinel.
    /// @param amount The maximum token amount to pull from the caller.
    /// @param metadata Metadata which may contain a Permit2 allowance addressed to this gateway.
    /// @return acceptedAmount The amount which actually arrived after the transfer.
    function _acceptFundsFor(
        address token,
        uint256 amount,
        bytes calldata metadata
    )
        internal
        returns (uint256 acceptedAmount)
    {
        // Native input arrives with the call itself, so the delivered amount is simply what was attached.
        if (token == JBConstants.NATIVE_TOKEN) return msg.value;

        // An ERC-20 call has no use for attached native tokens, and accepting them would strand value the gateway
        // has no pending record for.
        if (msg.value != 0) revert JBRouterTerminalGateway_NoMsgValueAllowed(msg.value);

        // Resolve the owner through ERC-2771 so a meta-transaction pulls from the signer, not the forwarder.
        address sender = _msgSender();

        // Metadata may carry a Permit2 allowance addressed to this gateway. The ID is namespaced to this address, so
        // an allowance signed for the Router or Registry is not visible here and is left untouched.
        (bool exists, bytes memory parsedMetadata) =
            JBMetadataResolver.getDataFor({id: _PERMIT2_ID, metadata: metadata});
        if (exists) {
            JBSingleAllowance memory allowance = abi.decode(parsedMetadata, (JBSingleAllowance));

            // Refuse to pull more than the signer authorized, rather than letting the transfer below silently draw on
            // a pre-existing allowance the signer did not intend for this payment.
            if (amount > allowance.amount) {
                revert JBRouterTerminalGateway_PermitAllowanceNotEnough({amount: amount, allowance: allowance.amount});
            }

            IAllowanceTransfer.PermitSingle memory permitSingle = IAllowanceTransfer.PermitSingle({
                details: IAllowanceTransfer.PermitDetails({
                    token: token, amount: allowance.amount, expiration: allowance.expiration, nonce: allowance.nonce
                }),
                // The gateway spends the allowance itself; it never delegates the pull to the Router.
                spender: address(this),
                sigDeadline: allowance.sigDeadline
            });

            // A failed permit is not fatal: the signer may already hold a direct allowance, or have had this nonce
            // consumed by an earlier transaction. Record the reason and let the transfer below decide.
            try PERMIT2.permit({owner: sender, permitSingle: permitSingle, signature: allowance.signature}) {}
            catch (bytes memory reason) {
                emit Permit2AllowanceFailed({token: token, owner: sender, reason: reason, caller: sender});
            }
        }

        // Snapshot the balance so fee-on-transfer inputs use the amount which actually arrives.
        uint256 balanceBefore = IERC20(token).balanceOf(address(this));

        // Keep callback-capable tokens from nesting another intake inside this balance-delta measurement. Without
        // this, a token that calls back mid-transfer could have a second deposit land between the snapshot and the
        // reading below, so both calls would measure it and custody would owe more than it holds.
        if (_acceptingToken) revert JBRouterTerminalGateway_ReentrantTokenTransfer(token);
        _acceptingToken = true;

        // Pull the input only after closing the reentrant measurement window.
        _transferFrom({from: sender, to: address(this), token: token, amount: amount});
        acceptedAmount = IERC20(token).balanceOf(address(this)) - balanceBefore;

        // Re-open intake after the post-transfer balance has fixed this call's accepted amount.
        _acceptingToken = false;
    }

    /// @notice Attempt a retained call atomically against the immutable router.
    /// @dev Scopes an exact router allowance and the transient `originalPayer` around the bounded call, restoring any
    /// enclosing values so nested forwarding hooks cannot clobber their outer attempt.
    /// @param call The call to attempt.
    /// @param minReturnedTokens The minimum project-token count required by a routed `pay` call. Always zero for
    /// retries because nonzero-minimum payments are never retained.
    /// @param memo The memo to pass along to the router.
    /// @param metadata The metadata to pass along to the router.
    /// @param gasLimit The gas to forward, or zero to forward all remaining gas minus the failure-accounting reserve.
    /// @return success Whether the router call succeeded.
    /// @return errorHash The selector-level fingerprint of the failure, if any.
    /// @return beneficiaryTokenCount The project tokens returned by a successful `pay` call.
    /// @return gasExhausted Whether a failed call surfaced no error data, the shape of out-of-gas anywhere in the
    /// route.
    function _attempt(
        JBPendingRouterTerminalCall memory call,
        uint256 minReturnedTokens,
        string calldata memo,
        bytes calldata metadata,
        uint256 gasLimit
    )
        internal
        returns (bool success, bytes32 errorHash, uint256 beneficiaryTokenCount, bool gasExhausted)
    {
        // No custody may leave while an inbound balance-delta measurement is open. A callback-capable token could
        // otherwise settle an older pending call from inside a new deposit's transfer, so the outgoing amount would be
        // subtracted from the incoming one and part of the new deposit would be left with no pending record.
        if (_acceptingToken) revert JBRouterTerminalGateway_ReentrantTokenTransfer(call.token);

        // Rebuild the exact terminal call the payer originally made, so a retry days later is indistinguishable from
        // the first attempt apart from its gas budget.
        bytes memory routerCall;
        if (call.preferAddToBalance) {
            routerCall = abi.encodeCall(
                IJBTerminal.addToBalanceOf,
                (call.projectId, call.token, call.amount, call.shouldReturnHeldFees, memo, metadata)
            );
        } else {
            routerCall = abi.encodeCall(
                IJBTerminal.pay,
                (call.projectId, call.token, call.amount, call.beneficiary, minReturnedTokens, memo, metadata)
            );
        }

        uint256 previousAllowance;
        uint256 value;
        if (call.token == JBConstants.NATIVE_TOKEN) {
            // Native input is handed over with the call; there is no allowance to manage.
            value = call.amount;
        } else {
            // Approve exactly this attempt's amount so a Router bug cannot reach the rest of pooled custody.
            // Preserve an enclosing same-token attempt's allowance across legitimate nested forwarding hooks.
            previousAllowance = IERC20(call.token).allowance({owner: address(this), spender: address(ROUTER)});
            IERC20(call.token).forceApprove({spender: address(ROUTER), value: call.amount});
        }

        if (gasLimit == 0) {
            uint256 available = gasleft();
            // A zero-gas attempt keeps an underfunded retention-qualified call inside the custody boundary; ordinary
            // callers still revert below instead of entering escrow. Withholding the reserve is what guarantees this
            // frame survives the callee's failure with enough gas left to record it durably.
            if (available > _FAILURE_GAS_RESERVE) gasLimit = available - _FAILURE_GAS_RESERVE;
        } else {
            // A qualified attempt must be a genuine test of the route. Anything below the base budget would fail for
            // lack of gas rather than for a real reason, letting a cheap caller manufacture failure evidence.
            if (gasLimit < QUALIFIED_CALL_GAS) {
                revert JBRouterTerminalGateway_RetryGasLimitTooLow({gasLimit: gasLimit, minimum: QUALIFIED_CALL_GAS});
            }
            _requireRetryGas(gasLimit);
        }

        // Expose the original payer to the Router for the duration of the call so residue and refunds reach whoever
        // funded the input, not this gateway. Save and restore around it because a nested forwarding hook may run
        // its own attempt inside this one.
        address previousPayer = originalPayer;
        originalPayer = call.refundTo;

        (success, errorHash, beneficiaryTokenCount, gasExhausted) =
            _boundedCall({target: address(ROUTER), value: value, gasLimit: gasLimit, data: routerCall});

        originalPayer = previousPayer;
        if (call.token != JBConstants.NATIVE_TOKEN) {
            // Restore rather than clear so a nested route cannot clobber its enclosing Router pull.
            IERC20(call.token).forceApprove({spender: address(ROUTER), value: previousAllowance});
        }
    }

    /// @notice Finalize a retained call using a caller-selected qualified gas budget.
    /// @param id The pending call identifier.
    /// @param call The retained call, authenticated against the stored commitment.
    /// @param gasLimit The gas to forward, or zero to select the required minimum.
    /// @param memo The original memo bound by the pending call.
    /// @param metadata The original metadata bound by the pending call.
    /// @return wasRefunded Whether the retained input was refunded.
    /// @return beneficiaryTokenCount The project tokens returned if the final `pay` attempt succeeded.
    function _finalizePendingCall(
        bytes32 id,
        JBPendingRouterTerminalCall calldata call,
        uint256 gasLimit,
        string calldata memo,
        bytes calldata metadata
    )
        internal
        returns (bool wasRefunded, uint256 beneficiaryTokenCount)
    {
        // Authenticate the caller-supplied call against the stored commitment before acting on any of its fields.
        bytes32 commitment = _requirePendingCall({id: id, call: call, memo: memo, metadata: metadata});
        JBPendingRouterTerminalCallFailure memory failure = _pendingCallFailureOf[id];

        // Refunding is only justified once the route has proven itself broken the same way three times over three
        // days. Anything less is still ordinary retry territory.
        if (failure.count < FINALIZATION_FAILURE_COUNT) {
            revert JBRouterTerminalGateway_PendingCallNotFinalizable({id: id, failureCount: failure.count});
        }

        // Space this attempt a day from the last so the evidence spans changing chain conditions rather than one
        // unlucky block.
        _requireReady({id: id, lastFailureAt: failure.lastFailureAt});
        gasLimit = _qualifiedGasLimit({failure: failure, requestedGasLimit: gasLimit});

        // Clear the pending record before interacting, so a re-entrant caller finds nothing to claim twice. Every exit
        // below either settles, rewrites it, or reverts the whole transaction and restores it.
        delete _pendingCallCommitmentOf[id];

        // Retained calls always carry a zero minimum, so the final attempt has no slippage floor of its own.
        (bool success, bytes32 errorHash, uint256 count, bool gasExhausted) =
            _attempt({call: call, minReturnedTokens: 0, memo: memo, metadata: metadata, gasLimit: gasLimit});

        // A late success is still a success: the payment lands where it was always headed and nothing is refunded.
        if (success) {
            delete _pendingCallFailureOf[id];
            emit JBRouterTerminalGateway_ProcessPendingCall({
                id: id, call: call, beneficiaryTokenCount: count, caller: _msgSender()
            });
            return (false, count);
        }

        // Gas exhaustion is its own stable failure class, so each matching retry must use a larger budget.
        if (gasExhausted) errorHash = _GAS_EXHAUSTED_ERROR_HASH;

        // A different failure than the qualifying streak means the route changed. That is new information, not the
        // confirmation a refund requires, so restore the pending call and start the evidence over.
        if (errorHash != failure.errorHash) {
            _pendingCallCommitmentOf[id] = commitment;
            _recordFailure({id: id, errorHash: errorHash, gasLimit: gasLimit, previous: failure});
            return (false, 0);
        }

        // The same failure reproduced under a qualified budget. Treat the destination as unreachable and return the
        // input to the project that was named when custody was taken.
        delete _pendingCallFailureOf[id];
        _refund(call);

        emit JBRouterTerminalGateway_RefundPendingCall({id: id, call: call, caller: _msgSender()});
        return (true, 0);
    }

    /// @notice Process a retained call using a caller-selected qualified gas budget.
    /// @param id The pending call identifier.
    /// @param call The retained call, authenticated against the stored commitment.
    /// @param gasLimit The gas to forward, or zero to select the required minimum.
    /// @param memo The original memo bound by the pending call.
    /// @param metadata The original metadata bound by the pending call.
    /// @return beneficiaryTokenCount The project tokens returned if a routed `pay` succeeds.
    function _processPendingCall(
        bytes32 id,
        JBPendingRouterTerminalCall calldata call,
        uint256 gasLimit,
        string calldata memo,
        bytes calldata metadata
    )
        internal
        returns (uint256 beneficiaryTokenCount)
    {
        // Authenticate the caller-supplied call against the stored commitment before acting on any of its fields.
        bytes32 commitment = _requirePendingCall({id: id, call: call, memo: memo, metadata: metadata});
        JBPendingRouterTerminalCallFailure memory failure = _pendingCallFailureOf[id];

        // Once the streak qualifies, the next attempt is the one that can release custody, so it must run through
        // the finalizer where a matching failure refunds instead of silently adding a fourth identical data point.
        if (failure.count >= FINALIZATION_FAILURE_COUNT) {
            revert JBRouterTerminalGateway_PendingCallRequiresFinalization(id);
        }

        // The first attempt after queuing runs immediately; every counted one after it waits a day so the streak
        // spans changing chain conditions rather than one unlucky block.
        if (failure.count != 0) _requireReady({id: id, lastFailureAt: failure.lastFailureAt});
        gasLimit = _qualifiedGasLimit({failure: failure, requestedGasLimit: gasLimit});

        // Clear the pending record before interacting, so a re-entrant caller finds nothing to claim twice. Every exit
        // below either settles, rewrites it, or reverts the whole transaction and restores it.
        delete _pendingCallCommitmentOf[id];

        // Retained calls always carry a zero minimum, so a retry has no slippage floor of its own.
        (bool success, bytes32 errorHash, uint256 count, bool gasExhausted) =
            _attempt({call: call, minReturnedTokens: 0, memo: memo, metadata: metadata, gasLimit: gasLimit});

        // The route recovered — settle into the destination and drop the failure history with the pending record.
        if (success) {
            delete _pendingCallFailureOf[id];
            emit JBRouterTerminalGateway_ProcessPendingCall({
                id: id, call: call, beneficiaryTokenCount: count, caller: _msgSender()
            });
            return count;
        }

        // Gas exhaustion advances only after the failure state has enforced the next larger budget.
        if (gasExhausted) errorHash = _GAS_EXHAUSTED_ERROR_HASH;

        // Still failing, so restore custody and fold this attempt into the streak that governs the next budget.
        _pendingCallCommitmentOf[id] = commitment;
        _recordFailure({id: id, errorHash: errorHash, gasLimit: gasLimit, previous: failure});
    }

    /// @notice Queue a failed call, retaining its original input token behind a single-slot hash commitment.
    /// @dev The full call, memo, and metadata are emitted rather than stored so the gas-constrained queue path writes
    /// one storage slot; retriers read them back from the event.
    /// @param call The call to retain.
    /// @param memo The original memo bound into the commitment.
    /// @param metadata The original metadata bound into the commitment.
    /// @param errorHash The selector-level fingerprint of the initial downstream error.
    function _queue(
        JBPendingRouterTerminalCall memory call,
        string calldata memo,
        bytes calldata metadata,
        bytes32 errorHash
    )
        internal
    {
        // A monotonic counter keeps each retained call's custody isolated, so two identical failed fees from the same
        // project never collide into one claim.
        bytes32 id = bytes32(++pendingCallCount);

        // This runs in the gas the failed route left behind, so store only the hash. The event below carries
        // everything a retrier needs to reconstruct and re-present the call.
        _pendingCallCommitmentOf[id] = _commitmentOf({call: call, memo: memo, metadata: metadata});

        emit JBRouterTerminalGateway_QueuePendingCall({
            id: id, call: call, memo: memo, metadata: metadata, errorHash: errorHash, caller: _msgSender()
        });
    }

    /// @notice Record a qualified failure, resetting the streak whenever the failure class changes.
    /// @param id The pending call identifier.
    /// @param errorHash The selector-level or gas-exhaustion failure-class fingerprint.
    /// @param gasLimit The qualified budget forwarded by the attempt.
    /// @param previous The pending call's failure state before this attempt.
    function _recordFailure(
        bytes32 id,
        bytes32 errorHash,
        uint256 gasLimit,
        JBPendingRouterTerminalCallFailure memory previous
    )
        internal
    {
        // Only an unbroken run of the same failure justifies giving up on a route, so a changed class restarts the
        // count at this attempt rather than carrying forward evidence about a failure mode that no longer occurs.
        uint32 count = errorHash == previous.errorHash ? previous.count + 1 : 1;

        // Day-scale spacing is the only thing this timestamp gates, so validator-scale drift cannot matter.
        // forge-lint: disable-next-line(block-timestamp)
        uint48 failedAt = uint48(block.timestamp);

        // The budget floor only ever rises, regardless of which class this attempt produced.
        uint64 highestGasLimit = previous.highestGasLimit;
        // forge-lint: disable-next-line(unsafe-typecast)
        if (gasLimit > highestGasLimit) highestGasLimit = uint64(gasLimit);

        _pendingCallFailureOf[id] = JBPendingRouterTerminalCallFailure({
            count: count, errorHash: errorHash, lastFailureAt: failedAt, highestGasLimit: highestGasLimit
        });

        emit JBRouterTerminalGateway_RecordTerminalCallFailure({
            id: id,
            errorHash: errorHash,
            count: count,
            nextAttemptAt: uint256(failedAt) + RETRY_DELAY,
            caller: _msgSender()
        });
    }

    /// @notice Refund a finalized call through an active source-project accounting terminal.
    /// @dev Prefers the still-registered original source terminal, then the token's current primary terminal, then any
    /// other registered non-circular terminal. Reverts if every candidate rejects the refund.
    /// @param call The retained call whose original input must be refunded.
    function _refund(JBPendingRouterTerminalCall memory call) internal {
        // Every candidate below is credited through project accounting, never by raw transfer, so the refund lands as
        // recorded project balance rather than as tokens sitting above a terminal's books.
        IJBTerminal originalTerminal = IJBTerminal(call.refundTo);

        // Prefer the source terminal while it remains registered for the project, preserving the original destination.
        if (
            DIRECTORY.isTerminalOf({projectId: call.sourceProjectId, terminal: originalTerminal})
                && _tryRefund({call: call, terminal: originalTerminal})
        ) {
            return;
        }

        // If that terminal was removed or rejects the token, use the project's current token-specific primary terminal.
        IJBTerminal primaryTerminal = DIRECTORY.primaryTerminalOf({projectId: call.sourceProjectId, token: call.token});
        if (
            address(primaryTerminal) != address(0) && primaryTerminal != originalTerminal
                && _tryRefund({call: call, terminal: primaryTerminal})
        ) {
            return;
        }

        // Search the remaining registered terminals so a circular or stale primary cannot permanently trap custody.
        IJBTerminal[] memory terminals = DIRECTORY.terminalsOf(call.sourceProjectId);
        for (uint256 i; i < terminals.length; i++) {
            IJBTerminal terminal = terminals[i];
            if (terminal == originalTerminal || terminal == primaryTerminal) continue;
            if (_tryRefund({call: call, terminal: terminal})) return;
        }

        // Nothing accepted the refund. Revert so custody, the pending record, and the qualifying streak all roll back
        // intact and the attempt can be repeated once the project's terminals change.
        revert JBRouterTerminalGateway_RefundFailed({
            originalTerminal: address(originalTerminal), primaryTerminal: address(primaryTerminal)
        });
    }

    /// @notice Pull an ERC-20 through direct approval when available, otherwise through Permit2.
    /// @param from The ERC-2771-resolved token owner.
    /// @param to The address which receives the token.
    /// @param token The ERC-20 token to transfer.
    /// @param amount The token amount to transfer.
    function _transferFrom(address from, address to, address token, uint256 amount) internal {
        // A direct allowance is the cheaper path and the one most payers already hold, so try it before Permit2.
        if (IERC20(token).allowance({owner: from, spender: address(this)}) >= amount) {
            return IERC20(token).safeTransferFrom({from: from, to: to, value: amount});
        }

        // Permit2 settles in 160 bits, so a wider amount cannot be pulled through it at all. Reject rather than
        // truncate, which would move less than the payment the caller asked to make.
        if (amount > type(uint160).max) revert JBRouterTerminalGateway_AmountOverflow(amount);
        // forge-lint: disable-next-line(unsafe-typecast)
        PERMIT2.transferFrom({from: from, to: to, amount: uint160(amount), token: token});
    }

    /// @notice Attempt a project-accounting refund without letting one terminal block an alternate terminal.
    /// @param call The retained call whose original input must be refunded.
    /// @param terminal The candidate source-project terminal to credit.
    /// @return success Whether the candidate accepted and accounted for the complete refund.
    function _tryRefund(JBPendingRouterTerminalCall memory call, IJBTerminal terminal) internal returns (bool success) {
        // Skip a candidate whose forwarding chain leads back here: crediting it would hand custody straight back to
        // this gateway as a fresh unrecorded deposit rather than reaching the project's books.
        if (
            address(terminal) == address(0)
                || JBForwardingCheck.isCircularTerminal({
                    target: address(this), projectId: call.sourceProjectId, terminal: terminal
                })
        ) {
            return false;
        }

        uint256 value;
        if (call.token == JBConstants.NATIVE_TOKEN) {
            value = call.amount;
        } else {
            // Approve exactly this refund so a rejecting candidate is left with no standing claim on custody.
            IERC20(call.token).forceApprove({spender: address(terminal), value: call.amount});
        }

        // Expose the original payer for the same reason `_attempt` does: a forwarding candidate that routes the refund
        // must send any residue to whoever funded the input, never to this gateway.
        address previousPayer = originalPayer;
        originalPayer = call.refundTo;

        // Call low-level so one uncooperative terminal reverting cannot abort the search across the remaining
        // candidates. The caller reverts only if every one of them fails.
        (success,) = address(terminal).call{value: value}(
            abi.encodeCall(
                IJBTerminal.addToBalanceOf,
                (call.sourceProjectId, call.token, call.amount, false, string(""), bytes(""))
            )
        );

        originalPayer = previousPayer;

        // Always close the exact approval before trying another terminal or returning.
        if (call.token != JBConstants.NATIVE_TOKEN) {
            IERC20(call.token).forceApprove({spender: address(terminal), value: 0});
        }
    }

    //*********************************************************************//
    // ----------------------- internal helpers -------------------------- //
    //*********************************************************************//

    /// @notice Call the router while matching failures by selector without copying encoded error arguments.
    /// @dev Empty return data is reported as gas exhaustion. Shorter-than-selector data is hashed as-is; return data at
    /// least four bytes long is matched by selector.
    /// @param target The address to call.
    /// @param value The native-token value to send with the call.
    /// @param gasLimit The gas to forward to the call.
    /// @param data The calldata to send.
    /// @return success Whether the call succeeded.
    /// @return errorHash The selector-level fingerprint of the failure, if any.
    /// @return result The first return word of a successful call.
    /// @return gasExhausted Whether a failed call surfaced no error data, the shape of out-of-gas anywhere in the
    /// route.
    function _boundedCall(
        address target,
        uint256 value,
        uint256 gasLimit,
        bytes memory data
    )
        internal
        returns (bool success, bytes32 errorHash, uint256 result, bool gasExhausted)
    {
        // Assembly keeps the callee's return data from being copied into memory wholesale, so a failing route cannot
        // inflate this frame's memory cost and consume the reserve that the failure accounting depends on.
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            // Bound the call so a route that runs away on gas fails here rather than taking the whole transaction.
            success := call(gasLimit, target, value, add(data, 0x20), mload(data), ptr, 0x20)
            // Only a full word is a usable `pay` result; a shorter return cannot be a token count.
            let size := returndatasize()
            if and(success, gt(size, 0x1f)) { result := mload(ptr) }

            // A failed call with no error data is treated as gas exhaustion. Out-of-gas anywhere in the route surfaces
            // as an empty revert bubbled through frames that still hold their EIP-150 sixty-fourth, so the budget
            // consumed here can never prove where it ran out. A bare `revert()` shares the shape and simply climbs the
            // same ladder; that costs retriers gas, whereas mistaking exhaustion for a stable route failure would
            // refund a route that only needed a larger budget.
            gasExhausted := and(iszero(success), iszero(size))

            // Fingerprint only the selector. Custom errors embed dynamic arguments — amounts, addresses, block
            // numbers — that differ between otherwise identical failures, and hashing those would make every attempt
            // look like a new failure class and reset the streak forever.
            let copySize := size
            if gt(copySize, 4) { copySize := 4 }

            returndatacopy(ptr, 0, copySize)
            errorHash := keccak256(ptr, copySize)
            mstore(0x40, add(ptr, 0x20))
        }
    }

    /// @notice Derive the largest call budget which preserves the transaction's accounting reserves.
    /// @dev Bounds the block limit by the EIP-7825 per-transaction cap, reserves gas for transaction overhead and
    /// failure accounting, then applies the EIP-150 forwarding ratio.
    /// @param blockGasLimit The block gas limit from which to derive an executable call budget.
    /// @return gasLimit The maximum call budget supported by `blockGasLimit`.
    function _maximumQualifiedCallGas(uint256 blockGasLimit) internal pure returns (uint256 gasLimit) {
        // A block larger than one transaction can carry does not make a larger attempt executable.
        if (blockGasLimit > _TRANSACTION_GAS_CAP) blockGasLimit = _TRANSACTION_GAS_CAP;

        // A chain whose whole block cannot cover the reserve can execute no qualified attempt at all.
        if (blockGasLimit <= _TRANSACTION_GAS_RESERVE) return 0;

        // Reserve room for transaction overhead and durable failure accounting, then apply the 63/64 rule so the
        // remainder is gas a `CALL` can actually forward rather than gas the caller merely holds.
        return (blockGasLimit - _TRANSACTION_GAS_RESERVE) * 63 / 64;
    }

    /// @notice Resolve the minimum escalating gas budget for a qualified attempt on the live chain.
    /// @dev Consecutive gas exhaustion targets 5M, 10M, 15M, then 20M gas, capped by the executable transaction budget.
    /// @param failure The pending call's current matching failure state.
    /// @param requestedGasLimit The explicit caller-selected budget, or zero to select the required minimum.
    /// @return gasLimit The validated gas budget to forward.
    function _qualifiedGasLimit(
        JBPendingRouterTerminalCallFailure memory failure,
        uint256 requestedGasLimit
    )
        internal
        view
        returns (uint256 gasLimit)
    {
        return _qualifiedGasLimitFor({
            failure: failure, requestedGasLimit: requestedGasLimit, maximumGasLimit: maximumQualifiedCallGas()
        });
    }

    /// @notice Resolve a qualified gas budget against a supplied executable maximum.
    /// @param failure The pending call's current matching failure state.
    /// @param requestedGasLimit The explicit caller-selected budget, or zero to select the required minimum.
    /// @param maximumGasLimit The maximum budget executable under the live block gas limit.
    /// @return gasLimit The validated gas budget to forward.
    function _qualifiedGasLimitFor(
        JBPendingRouterTerminalCallFailure memory failure,
        uint256 requestedGasLimit,
        uint256 maximumGasLimit
    )
        internal
        pure
        returns (uint256 gasLimit)
    {
        // Without room for the base budget there is no such thing as a qualified attempt on this chain, so refuse
        // rather than let an underpowered call masquerade as evidence the route is broken.
        if (maximumGasLimit < QUALIFIED_CALL_GAS) {
            revert JBRouterTerminalGateway_BlockGasLimitTooLow({maximum: maximumGasLimit, minimum: QUALIFIED_CALL_GAS});
        }

        // Repeating a budget that already ran out proves nothing new, so each consecutive exhaustion demands a step
        // larger one. Other failure classes are about the route itself and stay at the base budget.
        uint256 minimum = QUALIFIED_CALL_GAS;
        if (failure.errorHash == _GAS_EXHAUSTED_ERROR_HASH) minimum *= uint256(failure.count) + 1;

        // Never go back below a budget already tried, other than to the live ceiling below: a route that only shows
        // its real failure past the base budget
        // would otherwise alternate between exhaustion and that failure, resetting the streak forever.
        if (minimum < failure.highestGasLimit) minimum = failure.highestGasLimit;

        // The ladder stops at whatever the chain can actually execute; demanding more would strand the call.
        if (minimum > maximumGasLimit) minimum = maximumGasLimit;

        // Zero means the caller wants whatever the failure state currently requires.
        if (requestedGasLimit == 0) return minimum;

        // Floor and ceiling both matter: below the minimum an attempt is not a fair test of the route, and above the
        // executable maximum it can never be included in a block.
        if (requestedGasLimit < minimum) {
            revert JBRouterTerminalGateway_RetryGasLimitTooLow({gasLimit: requestedGasLimit, minimum: minimum});
        }
        if (requestedGasLimit > maximumGasLimit) {
            revert JBRouterTerminalGateway_RetryGasLimitTooHigh({gasLimit: requestedGasLimit, maximum: maximumGasLimit});
        }
        return requestedGasLimit;
    }

    //*********************************************************************//
    // ----------------------- internal views ---------------------------- //
    //*********************************************************************//

    /// @notice Hash a retained call together with its original memo and metadata into its stored commitment.
    /// @param call The retained call.
    /// @param memo The original memo bound by the pending call.
    /// @param metadata The original metadata bound by the pending call.
    /// @return commitment The commitment binding the call, memo, and metadata.
    function _commitmentOf(
        JBPendingRouterTerminalCall memory call,
        string calldata memo,
        bytes calldata metadata
    )
        internal
        pure
        returns (bytes32 commitment)
    {
        return keccak256(abi.encode(call, memo, metadata));
    }

    /// @notice Require a pending call and authenticate the supplied call, memo, and metadata against its commitment.
    /// @param id The pending call identifier.
    /// @param call The retained call as supplied by the retrier.
    /// @param memo The memo which must match the memo bound into the commitment.
    /// @param metadata The metadata which must match the metadata bound into the commitment.
    /// @return commitment The authenticated commitment stored under `id`.
    function _requirePendingCall(
        bytes32 id,
        JBPendingRouterTerminalCall calldata call,
        string calldata memo,
        bytes calldata metadata
    )
        internal
        view
        returns (bytes32 commitment)
    {
        // A zero commitment means nothing is pending here: never queued, already settled, or already refunded.
        commitment = _pendingCallCommitmentOf[id];
        if (commitment == bytes32(0)) revert JBRouterTerminalGateway_PendingCallNotFound(id);

        // Everything about the call arrived from an untrusted caller, so re-derive the hash and require an exact
        // match. This is what stops a retrier from redirecting the beneficiary, the amount, or the refund creditor.
        bytes32 actualCommitment = _commitmentOf({call: call, memo: memo, metadata: metadata});
        if (actualCommitment != commitment) {
            revert JBRouterTerminalGateway_CallDataMismatch({
                expectedCommitment: commitment, actualCommitment: actualCommitment
            });
        }
    }

    /// @notice Require the retry delay to have elapsed.
    /// @param id The pending call identifier.
    /// @param lastFailureAt The timestamp of the pending call's latest qualified failure.
    function _requireReady(bytes32 id, uint48 lastFailureAt) internal view {
        uint256 nextAttemptAt = uint256(lastFailureAt) + RETRY_DELAY;
        // forge-lint: disable-next-line(block-timestamp)
        if (block.timestamp < nextAttemptAt) {
            revert JBRouterTerminalGateway_PendingCallNotReady({id: id, nextAttemptAt: nextAttemptAt});
        }
    }

    /// @notice Require enough gas to forward a qualified attempt while retaining the failure-accounting reserve.
    /// @param gasLimit The gas which must be forwardable by `CALL` after the EIP-150 withholding margin.
    function _requireRetryGas(uint256 gasLimit) internal view {
        uint256 available = gasleft();
        // Include the EIP-150 withholding margin so the requested amount is actually forwarded by `CALL`.
        uint256 required = gasLimit + (gasLimit + 62) / 63 + _FAILURE_GAS_RESERVE;
        if (available < required) {
            revert JBRouterTerminalGateway_InsufficientRetryGas({available: available, required: required});
        }
    }

    /// @notice Resolve an upstream payer exposed by a forwarding caller.
    /// @param fallback_ The payer to use when the caller does not expose an upstream payer.
    /// @return payer The forwarding caller's `originalPayer` when nonzero, otherwise `fallback_`.
    function _resolveOriginalPayer(address fallback_) internal view returns (address payer) {
        // The Registry forwards on a payer's behalf, so asking it who it is acting for recovers the terminal or
        // protocol payer that actually funded the input. Probe defensively: most callers are not forwarders, and a
        // caller that answers badly must degrade to itself rather than take the payment down.
        // A high-level `try` would not cover a caller whose fallback answers the selector with empty data: the decode
        // of that empty return reverts in this frame, outside the catch. Probe raw and require a full word instead.
        if (msg.sender.code.length != 0) {
            (bool ok, bytes memory data) = msg.sender.staticcall(abi.encodeCall(IJBPayerTracker.originalPayer, ()));
            if (ok && data.length >= 32) {
                address original = abi.decode(data, (address));
                if (original != address(0)) return original;
            }
        }
        return fallback_;
    }

    /// @notice Decide whether a call carrying the source-project opt-in should be retained if its route fails.
    /// @dev The opt-in metadata shape is also what core's own infrastructure sends when it pays on a project's behalf,
    /// and two of those callers already catch a synchronous failure better than custody could. Both are recognized by
    /// properties nobody upstream can shape: `JBController` distributes reserved splits in the source project's own
    /// token, which no terminal of that project can ever book, so custody would be a permanent lock; `JBMultiTerminal`
    /// restores a failed payout split fee-free, so a registered source terminal retains only fees to the fee project,
    /// the forgiveness this contract exists to close. Fees are retained unconditionally beyond that: a retained fee is
    /// at worst delayed, while a forgiven one is gone. Other payers, such as protocol contracts with their own catch
    /// boundary, retain.
    /// @param call The call.
    /// @return shouldRetain Whether a failed route should be queued for permissionless recovery.
    function _shouldRetain(JBPendingRouterTerminalCall memory call) internal view returns (bool shouldRetain) {
        // Zero means this caller never asked for custody and expects a synchronous revert.
        if (call.sourceProjectId == 0) return false;

        // A project's own token has no accounting context on any of its terminals: a refund could never land.
        if (
            JBRouterTerminal(payable(address(ROUTER))).TOKENS().projectIdOf(IJBToken(call.token))
                == call.sourceProjectId
        ) {
            return false;
        }

        // `refundTo` is the resolved upstream payer. A source terminal's own catch already restores payout splits.
        if (
            call.projectId != JBConstants.FEE_BENEFICIARY_PROJECT_ID
                && DIRECTORY.isTerminalOf({projectId: call.sourceProjectId, terminal: IJBTerminal(call.refundTo)})
        ) {
            return false;
        }
        return true;
    }

    /// @notice Decode the raw source-project metadata used by core terminal fees and project payouts.
    /// @dev Core's fee and payout paths send exactly `abi.encodePacked(sourceProjectId)`, so anything of another
    /// length was never an opt-in. `JBMetadataResolver`-formatted metadata is longer and is therefore ignored here.
    /// @param metadata The metadata to decode, which opts in only when it is exactly 32 bytes.
    /// @return sourceProjectId The decoded source project ID, or zero when the metadata is not an opt-in.
    function _sourceProjectIdFrom(bytes calldata metadata) internal pure returns (uint256 sourceProjectId) {
        if (metadata.length != 32) return 0;

        assembly ("memory-safe") {
            sourceProjectId := calldataload(metadata.offset)
        }

        // A word too large to be an issued project ID is a coincidence — a hash, a packed address, a bitfield — not
        // a
        // request for custody. Reject it so such calls keep synchronous failure semantics instead of escrowing funds
        // against a project that can never be minted to receive them. `uint64` is core's own project-ID width.
        if (sourceProjectId > type(uint64).max) return 0;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {JBPermissioned} from "@bananapus/core-v6/src/abstract/JBPermissioned.sol";
import {IJBPermissions} from "@bananapus/core-v6/src/interfaces/IJBPermissions.sol";
import {IJBProjects} from "@bananapus/core-v6/src/interfaces/IJBProjects.sol";
import {IJBTerminal} from "@bananapus/core-v6/src/interfaces/IJBTerminal.sol";
import {JBConstants} from "@bananapus/core-v6/src/libraries/JBConstants.sol";
import {JBMetadataResolver} from "@bananapus/core-v6/src/libraries/JBMetadataResolver.sol";
import {JBAccountingContext} from "@bananapus/core-v6/src/structs/JBAccountingContext.sol";
import {JBPayHookSpecification} from "@bananapus/core-v6/src/structs/JBPayHookSpecification.sol";
import {JBRuleset} from "@bananapus/core-v6/src/structs/JBRuleset.sol";
import {JBSingleAllowance} from "@bananapus/core-v6/src/structs/JBSingleAllowance.sol";
import {JBPermissionIds} from "@bananapus/permission-ids-v6/src/JBPermissionIds.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {Context} from "@openzeppelin/contracts/utils/Context.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";
import {IAllowanceTransfer} from "@uniswap/permit2/src/interfaces/IAllowanceTransfer.sol";
import {IPermit2} from "@uniswap/permit2/src/interfaces/IPermit2.sol";

import {IJBForwardingTerminal} from "./interfaces/IJBForwardingTerminal.sol";
import {IJBPayerTracker} from "@bananapus/core-v6/src/interfaces/IJBPayerTracker.sol";
import {IJBRouterTerminalRegistry} from "./interfaces/IJBRouterTerminalRegistry.sol";

import {JBForwardingCheck} from "./libraries/JBForwardingCheck.sol";

import {DefaultTerminalSegment} from "./structs/DefaultTerminalSegment.sol";

/// @notice A forwarding layer that lets each project choose which router terminal receives its payments, with an
/// owner-managed default for projects that have not opted in. Projects can lock their choice to guarantee permanence.
contract JBRouterTerminalRegistry is IJBRouterTerminalRegistry, JBPermissioned, Ownable, ERC2771Context {
    // A library that adds default safety checks to ERC20 functionality.
    using SafeERC20 for IERC20;

    //*********************************************************************//
    // --------------------------- custom errors ------------------------- //
    //*********************************************************************//

    /// @notice Thrown when an amount exceeds the maximum width a forwarded terminal call can represent.
    error JBRouterTerminalRegistry_AmountOverflow(uint256 amount);

    /// @notice Thrown when attempting to disallow the terminal that is currently set as the default.
    error JBRouterTerminalRegistry_CannotDisallowDefaultTerminal(IJBTerminal terminal);

    /// @notice Thrown when a terminal would forward a project back into this registry, directly or transitively.
    error JBRouterTerminalRegistry_CircularForward(IJBTerminal terminal);

    /// @notice Thrown when native tokens are sent on a call that does not accept them.
    error JBRouterTerminalRegistry_NoMsgValueAllowed(uint256 value);

    /// @notice Thrown when the payment amount exceeds the Permit2 allowance provided in the metadata.
    error JBRouterTerminalRegistry_PermitAllowanceNotEnough(uint256 amount, uint256 allowanceAmount);

    /// @notice Thrown when changing a project's terminal after its terminal choice has been permanently locked.
    error JBRouterTerminalRegistry_TerminalLocked(uint256 projectId);

    /// @notice Thrown when the project's resolved terminal does not match the terminal the caller expected to lock.
    error JBRouterTerminalRegistry_TerminalMismatch(IJBTerminal currentTerminal, IJBTerminal expectedTerminal);

    /// @notice Thrown when selecting a terminal that is not on the registry allowlist.
    error JBRouterTerminalRegistry_TerminalNotAllowed(IJBTerminal terminal);

    /// @notice Thrown when a project has no explicit terminal and no default terminal has ever been set.
    error JBRouterTerminalRegistry_TerminalNotSet(uint256 projectId);

    /// @notice Thrown when setting the default terminal to the zero address.
    error JBRouterTerminalRegistry_ZeroAddress(address terminal);

    //*********************************************************************//
    // ---------------- public immutable stored properties --------------- //
    //*********************************************************************//

    /// @notice The Juicebox project registry used to verify project existence and ownership.
    IJBProjects public immutable override PROJECTS;

    /// @notice The Permit2 contract used for token approvals and transfers.
    IPermit2 public immutable override PERMIT2;

    //*********************************************************************//
    // --------------------- public stored properties -------------------- //
    //*********************************************************************//

    /// @notice The current default terminal — applied to projects with ID strictly greater than
    /// `defaultTerminalProjectIdThreshold`. Existing projects (ID <= threshold) without an explicit
    /// terminal continue to resolve against the historical default that was current at the time
    /// their project ID range was active (see `_defaultTerminalHistory`).
    IJBTerminal public override defaultTerminal;

    /// @notice The `PROJECTS.count()` snapshot at the moment of the last `setDefaultTerminal` call.
    /// Projects with `ID <= defaultTerminalProjectIdThreshold` (i.e. already existing when the most
    /// recent default was set) DO NOT pick up `defaultTerminal` on fall-through; instead they
    /// resolve against the historical entry in `_defaultTerminalHistory` that covers their ID. The
    /// first default's segment covers every project that already existed when it was set (so those
    /// projects route through it), while later segments pin each outgoing default to its own cohort.
    /// This prevents the registry owner from silently rerouting payments for already-deployed
    /// projects via a later default change.
    uint256 public override defaultTerminalProjectIdThreshold;

    /// @notice Whether the terminal for a given project has been locked against future updates.
    /// @custom:param projectId The ID of the project to check lock state for.
    mapping(uint256 projectId => bool) public override hasLockedTerminal;

    /// @notice Whether a terminal is allowlisted for project-level selection.
    /// @custom:param terminal The terminal to check allowlist status for.
    mapping(IJBTerminal terminal => bool) public override isTerminalAllowed;

    //*********************************************************************//
    // --------------------- internal stored properties ------------------ //
    //*********************************************************************//

    /// @notice Append-only history of default-terminal cohorts captured at each `setDefaultTerminal` call. Each
    /// `segment[i]` applies to projectIds in `[<previous threshold> + 1, segment[i].maxProjectId]`. Resolution walks
    /// the array forward and returns the first segment whose `maxProjectId` covers the queried `projectId`. The first
    /// call records the projects that already existed mapped to the new default; later calls push the outgoing default
    /// onto this history before updating `defaultTerminal`.
    DefaultTerminalSegment[] internal _defaultTerminalHistory;

    /// @notice The terminal explicitly configured for a project before default-terminal fallback is applied.
    /// @custom:param projectId The ID of the project to look up the explicit terminal for.
    mapping(uint256 projectId => IJBTerminal) internal _terminalOf;

    //*********************************************************************//
    // -------------------- transient stored properties ------------------ //
    //*********************************************************************//

    /// @notice The original payer of the current transaction.
    address public transient override originalPayer;

    //*********************************************************************//
    // ---------------------------- constructor -------------------------- //
    //*********************************************************************//

    /// @notice Construct a router-terminal registry.
    /// @param permissions The permissions contract.
    /// @param projects The project registry.
    /// @param permit2 The permit2 utility.
    /// @param owner The owner of the contract.
    /// @param trustedForwarder The trusted forwarder for the contract.
    constructor(
        IJBPermissions permissions,
        IJBProjects projects,
        IPermit2 permit2,
        address owner,
        address trustedForwarder
    )
        JBPermissioned(permissions)
        ERC2771Context(trustedForwarder)
        Ownable(owner)
    {
        PROJECTS = projects;
        PERMIT2 = permit2;
    }

    //*********************************************************************//
    // ------------------------- external views -------------------------- //
    //*********************************************************************//

    /// @notice Get the accounting context for the specified project ID and token.
    /// @param projectId The ID of the project to get the accounting context for.
    /// @param token The address of the token to get the accounting context for.
    /// @return context A `JBAccountingContext` containing the accounting context for the project ID and token.
    function accountingContextForTokenOf(
        uint256 projectId,
        address token
    )
        external
        view
        override
        returns (JBAccountingContext memory context)
    {
        // Discovery view, fail-open: resolve the project's effective terminal WITHOUT reverting. When no terminal can
        // be resolved (e.g. no default terminal has been set on this chain yet), return an empty context
        // (`token == address(0)`) rather than reverting. Callers such as `JBDirectory.primaryTerminalOf` read this to
        // decide whether the registry accepts the token; an empty context means "not accepted", letting them fall
        // through to `address(0)` instead of propagating a revert that would brick the originating operation (e.g. a
        // protocol-fee cash out/payout routed to project #1). Transactional paths keep `_requireResolvedTerminalOf`
        // and still revert before accepting funds or forwarding into `address(0)`.
        IJBTerminal terminal = _resolvedTerminalOf(projectId);
        if (terminal == IJBTerminal(address(0))) return context;

        // Get the accounting context for the token.
        return terminal.accountingContextForTokenOf({projectId: projectId, token: token});
    }

    /// @notice Return all the accounting contexts for a specified project ID.
    /// @param projectId The ID of the project to get the accounting contexts for.
    /// @return contexts An array of `JBAccountingContext` containing the accounting contexts for the project ID.
    function accountingContextsOf(uint256 projectId)
        external
        view
        override
        returns (JBAccountingContext[] memory contexts)
    {
        // Discovery view, fail-open: resolve WITHOUT reverting and return an empty array when no terminal can be
        // resolved on this chain (see `accountingContextForTokenOf`). Transactional paths keep
        // `_requireResolvedTerminalOf` and still revert.
        IJBTerminal terminal = _resolvedTerminalOf(projectId);
        if (terminal == IJBTerminal(address(0))) return contexts;

        // Get the accounting contexts.
        return terminal.accountingContextsOf(projectId);
    }

    /// @notice Always returns 0 because the registry only forwards funds and does not hold project balances.
    /// @param projectId Unused.
    /// @param tokens Unused.
    /// @param decimals Unused.
    /// @param currency Unused.
    /// @return currentSurplus Always 0.
    function currentSurplusOf(
        uint256 projectId,
        address[] calldata tokens,
        uint256 decimals,
        uint256 currency
    )
        external
        pure
        override
        returns (uint256)
    {
        projectId;
        tokens;
        decimals;
        currency;
        return 0;
    }

    /// @notice The default terminal that applies to a given project on fall-through, accounting for the threshold
    /// and the snapshot history. Returns zero if no default ever applied to the project's ID range.
    /// @param projectId The ID of the project to resolve the default for.
    /// @return terminal The default terminal applicable to this project (zero if none).
    function defaultTerminalFor(uint256 projectId) external view override returns (IJBTerminal terminal) {
        return _defaultTerminalFor(projectId);
    }

    /// @notice Read a default-terminal history entry. Exposes the internal append-only history.
    /// @param index The history index (0 is the oldest captured snapshot).
    /// @return segment The `maxProjectId + terminal` pair for that history slot.
    function defaultTerminalHistoryAt(uint256 index)
        external
        view
        override
        returns (DefaultTerminalSegment memory segment)
    {
        return _defaultTerminalHistory[index];
    }

    /// @notice The total number of historical default-terminal snapshots captured (= number of `setDefaultTerminal`
    /// calls after the very first one).
    /// @return length The number of entries in the default-terminal history.
    function defaultTerminalHistoryLength() external view override returns (uint256 length) {
        return _defaultTerminalHistory.length;
    }

    /// @notice Preview a payment by forwarding the call to the terminal currently resolved for the project.
    /// @dev Uses the project-specific terminal when set, otherwise falls back to `defaultTerminal`.
    /// @param projectId The ID of the project to pay.
    /// @param token The token to pay into the resolved terminal.
    /// @param amount The amount of the input token to preview.
    /// @param beneficiary The address that would receive any minted project tokens.
    /// @param metadata Extra data to forward unchanged to the resolved terminal preview.
    /// @return ruleset The ruleset the resolved terminal would use for the preview.
    /// @return beneficiaryTokenCount The number of project tokens the beneficiary would receive.
    /// @return reservedTokenCount The number of project tokens that would be reserved.
    /// @return hookSpecifications Any pay hook specifications returned by the resolved terminal.
    function previewPayFor(
        uint256 projectId,
        address token,
        uint256 amount,
        address beneficiary,
        bytes calldata metadata
    )
        external
        view
        override
        returns (
            JBRuleset memory ruleset,
            uint256 beneficiaryTokenCount,
            uint256 reservedTokenCount,
            JBPayHookSpecification[] memory hookSpecifications
        )
    {
        // Read the terminal explicitly configured for this project, falling back to the
        // threshold-resolved default if none is pinned.
        IJBTerminal terminal = _requireResolvedTerminalOf(projectId);

        // Forward the preview request unchanged to whichever terminal was resolved above.
        return terminal.previewPayFor({
            projectId: projectId, token: token, amount: amount, beneficiary: beneficiary, metadata: metadata
        });
    }

    /// @notice The concrete terminal this forwarding layer would route a project's payment into.
    /// @param projectId The project whose downstream terminal should be resolved.
    /// @return terminal The concrete terminal the forwarder would call for `projectId`.
    function terminalOf(uint256 projectId) external view override returns (IJBTerminal terminal) {
        return _resolvedTerminalOf(projectId);
    }

    //*********************************************************************//
    // -------------------------- public views --------------------------- //
    //*********************************************************************//

    /// @notice Check whether the registry supports a given interface ID.
    /// @param interfaceId The interface ID to check.
    /// @return supported Whether `interfaceId` is implemented.
    function supportsInterface(bytes4 interfaceId) public pure override returns (bool supported) {
        supported = interfaceId == type(IJBRouterTerminalRegistry).interfaceId
            || interfaceId == type(IJBForwardingTerminal).interfaceId || interfaceId == type(IJBTerminal).interfaceId
            || interfaceId == type(IERC165).interfaceId;
    }

    //*********************************************************************//
    // -------------------------- internal views ------------------------- //
    //*********************************************************************//

    /// @dev `ERC-2771` specifies the context as being a single address (20 bytes).
    function _contextSuffixLength() internal view override(ERC2771Context, Context) returns (uint256) {
        return super._contextSuffixLength();
    }

    /// @notice Prevent the registry from forwarding straight back into its immediate caller.
    /// @param terminal The terminal to check for circular forwarding.
    function _enforceNoCircularForward(IJBTerminal terminal) internal view {
        // Reject immediate caller cycles so router -> registry -> same router cannot recurse indefinitely.
        if (msg.sender == address(terminal)) revert JBRouterTerminalRegistry_CircularForward(terminal);
    }

    /// @notice The calldata. Preferred to use over `msg.data`.
    /// @return calldata The `msg.data` of this call.
    function _msgData() internal view override(ERC2771Context, Context) returns (bytes calldata) {
        return ERC2771Context._msgData();
    }

    /// @notice The message's sender. Preferred to use over `msg.sender`.
    /// @return sender The address which sent this call.
    function _msgSender() internal view override(ERC2771Context, Context) returns (address sender) {
        return ERC2771Context._msgSender();
    }

    /// @notice Returns the original payer to record in transient storage. If `_msgSender()` is a
    /// contract that exposes `IJBPayerTracker.originalPayer()` and that getter returns a non-zero
    /// value, the upstream payer is propagated so a forwarding chain (project payer -> registry
    /// -> router) refunds the true originator instead of the intermediary. Otherwise the direct
    /// caller is recorded — the common direct-call case.
    /// @return originalPayerOrSender The upstream payer if the resolved sender is a forwarding
    /// tracker that returns a non-zero address; otherwise the resolved sender itself.
    function _originalPayerOrSender() internal view returns (address originalPayerOrSender) {
        // Resolve through ERC-2771 so a trusted meta-tx forwarder is transparently unwrapped.
        address sender = _msgSender();

        // EOAs and contracts without code can't implement IJBPayerTracker — record them directly.
        if (sender.code.length == 0) return sender;

        // Probe the caller for IJBPayerTracker.originalPayer() via staticcall so a reverting or
        // non-conformant caller does not bubble up — fall back to the resolved sender on failure.
        (bool ok, bytes memory data) = sender.staticcall(abi.encodeWithSelector(IJBPayerTracker.originalPayer.selector));

        // Caller doesn't implement the interface (revert) or returned a truncated payload — treat
        // it as a direct payment from the caller itself.
        if (!ok || data.length < 32) return sender;

        // Decode the upstream payer the caller advertised. A zero value means "no upstream tracked",
        // which only happens when the caller is itself receiving a direct call — record the caller.
        address upstream = abi.decode(data, (address));
        return upstream == address(0) ? sender : upstream;
    }

    /// @notice Reject terminal choices that would forward the project back into this registry,
    /// directly or transitively. Walks up to the depth limit `JBForwardingCheck` enforces so a
    /// chain registry -> A -> B -> registry is caught (the previous one-hop probe missed those
    /// transitive cycles, letting a project lock itself into a route that always loops).
    /// @param projectId The project to validate forwarding for.
    /// @param terminal The terminal to validate.
    function _requireNonCircularTerminalFor(uint256 projectId, IJBTerminal terminal) internal view {
        // Reject direct self-selection so the registry cannot forward a project to itself.
        if (address(terminal) == address(this)) revert JBRouterTerminalRegistry_CircularForward(terminal);
        if (JBForwardingCheck.isCircularTerminal({target: address(this), projectId: projectId, terminal: terminal})) {
            revert JBRouterTerminalRegistry_CircularForward({terminal: terminal});
        }
    }

    /// @notice The default terminal that applies to a project on fall-through, taking the historical
    /// setDefaultTerminal snapshots into account so existing projects are not silently rerouted by a later default
    /// change.
    /// @param projectId The project to resolve the default for.
    /// @return terminal The default terminal applicable to this project (zero if none).
    function _defaultTerminalFor(uint256 projectId) internal view returns (IJBTerminal terminal) {
        // New projects (created after the most recent setDefaultTerminal) get the current default.
        if (projectId > defaultTerminalProjectIdThreshold) return defaultTerminal;

        // Older projects walk the history. Each segment covers a half-open range
        // `(minProjectIdExclusive, maxProjectId]`. The first segment covers every project that already existed when the
        // first default was set (mapped to that first default, so they route through it); later segments each cover the
        // cohort issued while their terminal was the active default. A project only resolves to `address(0)` here when
        // no default has ever been set.
        uint256 len = _defaultTerminalHistory.length;
        for (uint256 i; i < len; ++i) {
            DefaultTerminalSegment storage segment = _defaultTerminalHistory[i];
            if (projectId > segment.minProjectIdExclusive && projectId <= segment.maxProjectId) {
                return segment.terminal;
            }
        }
        return IJBTerminal(address(0));
    }

    /// @notice Resolve the effective terminal for a project. Falls back to the default that was current at the time
    /// the project ID range was active (NOT necessarily the registry-wide `defaultTerminal`, which only applies to
    /// projects with ID > `defaultTerminalProjectIdThreshold`).
    /// @param projectId The project to resolve the terminal for.
    /// @return terminal The project-specific terminal, or the threshold-resolved default.
    function _resolvedTerminalOf(uint256 projectId) internal view returns (IJBTerminal terminal) {
        // Start from the project-specific override, if one was configured.
        terminal = _terminalOf[projectId];

        // Fall back to the appropriate default for this project's ID cohort.
        if (terminal == IJBTerminal(address(0))) terminal = _defaultTerminalFor(projectId);
    }

    /// @notice Resolve the effective terminal for call paths that need to forward into a real terminal.
    /// @dev `terminalOf`/`defaultTerminalFor` return zero only when no default has ever been set. Transactional
    /// and passthrough view paths must fail before accepting funds or calling address(0).
    /// @param projectId The project to resolve the terminal for.
    /// @return terminal The project-specific terminal or threshold-resolved default.
    function _requireResolvedTerminalOf(uint256 projectId) internal view returns (IJBTerminal terminal) {
        terminal = _resolvedTerminalOf(projectId);
        if (terminal == IJBTerminal(address(0))) revert JBRouterTerminalRegistry_TerminalNotSet(projectId);
    }

    //*********************************************************************//
    // ---------------------- external transactions ---------------------- //
    //*********************************************************************//

    /// @notice Empty implementation to satisfy the interface.
    /// @param projectId The ID of the project whose contexts would otherwise be updated.
    /// @param accountingContexts Ignored because the registry delegates accounting contexts to the resolved terminal.
    function addAccountingContextsFor(
        uint256 projectId,
        JBAccountingContext[] calldata accountingContexts
    )
        external
        override
    {}

    /// @notice Add funds to a project's balance by forwarding them through the project's resolved router terminal.
    /// @dev Uses the project-specific terminal when set, otherwise falls back to `defaultTerminal`.
    /// @param projectId The ID of the project to add balance to.
    /// @param token The address of the token to pay in.
    /// @param amount The amount of tokens to send.
    /// @param shouldReturnHeldFees Whether held fees should be returned based on the amount added.
    /// @param memo A memo to pass along to the emitted event.
    /// @param metadata Bytes in `JBMetadataResolver`'s format (may include `permit2` allowance data).
    function addToBalanceOf(
        uint256 projectId,
        address token,
        uint256 amount,
        bool shouldReturnHeldFees,
        string calldata memo,
        bytes calldata metadata
    )
        external
        payable
        override
    {
        // Resolve the terminal that should receive this forwarded add-to-balance call before accepting funds.
        IJBTerminal terminal = _requireResolvedTerminalOf(projectId);

        // Accept the funds for the token.
        amount = _acceptFundsFor({token: token, amount: amount, metadata: metadata});

        // Trigger any pre-transfer logic.
        uint256 payValue = _beforeTransferFor({to: address(terminal), token: token, amount: amount});

        // Save any previous payer so nested reentrant calls through pay hooks restore correctly.
        address previousPayer = originalPayer;

        // Store the original payer in transient storage so downstream router terminals can refund partial-fill
        // leftovers to the true payer. If the immediate caller is itself a forwarding intermediary that exposes
        // its own original payer, propagate that — otherwise refunds in nested forwards stop at the intermediary.
        originalPayer = _originalPayerOrSender();

        // Reject forwards that would bounce straight back into this call's immediate caller.
        _enforceNoCircularForward(terminal);

        // Forward to the resolved terminal.
        terminal.addToBalanceOf{value: payValue}({
            projectId: projectId,
            token: token,
            amount: amount,
            shouldReturnHeldFees: shouldReturnHeldFees,
            memo: memo,
            metadata: metadata
        });

        // Revoke any leftover allowance the terminal did not pull.
        if (token != JBConstants.NATIVE_TOKEN) IERC20(token).forceApprove({spender: address(terminal), value: 0});

        // Restore the previous payer (supports nested reentrant calls through pay hooks).
        originalPayer = previousPayer;
    }

    /// @notice Add a terminal to the allowlist so projects can select it as their router.
    /// @dev Only the registry owner can call this.
    /// @param terminal The terminal to allow.
    function allowTerminal(IJBTerminal terminal) external onlyOwner {
        // Mark the terminal as selectable for future project-level configuration.
        isTerminalAllowed[terminal] = true;

        // Emit the allowlist update for off-chain consumers and activity logs.
        emit JBRouterTerminalRegistry_AllowTerminal({terminal: terminal, caller: _msgSender()});
    }

    /// @notice Remove a terminal from the allowlist so no new projects can select it.
    /// @dev Only the registry owner can call this. Cannot disallow the current default terminal — call
    /// `setDefaultTerminal` to change the default first.
    /// @param terminal The terminal to disallow.
    function disallowTerminal(IJBTerminal terminal) external onlyOwner {
        // Prevent disallowing the current default terminal to avoid leaving the registry in a broken state.
        if (terminal == defaultTerminal) {
            revert JBRouterTerminalRegistry_CannotDisallowDefaultTerminal({terminal: terminal});
        }

        // Remove the terminal from the allowlist so future projects cannot select it.
        isTerminalAllowed[terminal] = false;

        // Emit the allowlist update for off-chain consumers and activity logs.
        emit JBRouterTerminalRegistry_DisallowTerminal({terminal: terminal, caller: _msgSender()});
    }

    /// @notice Permanently lock a project's router terminal choice so it can never be changed again.
    /// @dev Only the project's owner or an address with the `JBPermissionIds.SET_ROUTER_TERMINAL` permission can lock.
    /// @dev Circular or self-referential terminals are rejected before the irreversible lock is written.
    /// @param projectId The ID of the project to lock the terminal for.
    /// @param expectedTerminal The terminal the caller expects to lock. Prevents race conditions where the default
    /// changes between transaction submission and execution.
    function lockTerminalFor(uint256 projectId, IJBTerminal expectedTerminal) external {
        // Enforce permissions.
        _requirePermissionFrom({
            account: PROJECTS.ownerOf(projectId),
            projectId: projectId,
            permissionId: JBPermissionIds.SET_ROUTER_TERMINAL
        });

        // Require a non-zero terminal before locking. When no explicit override is set, snapshot
        // the THRESHOLD-RESOLVED default into _terminalOf so the lock captures the default that
        // currently applies to this specific project (NOT necessarily the registry-wide default).
        IJBTerminal terminal = _terminalOf[projectId];
        if (terminal == IJBTerminal(address(0))) {
            terminal = _defaultTerminalFor(projectId);
            if (terminal == IJBTerminal(address(0))) revert JBRouterTerminalRegistry_TerminalNotSet(projectId);
            _terminalOf[projectId] = terminal;
        }

        // Verify the resolved terminal matches what the caller expects to lock.
        if (terminal != expectedTerminal) {
            revert JBRouterTerminalRegistry_TerminalMismatch({
                currentTerminal: terminal, expectedTerminal: expectedTerminal
            });
        }

        // Reject a terminal that would make this irreversible lock forward back into the registry.
        _requireNonCircularTerminalFor({projectId: projectId, terminal: terminal});

        hasLockedTerminal[projectId] = true;

        emit JBRouterTerminalRegistry_LockTerminal({projectId: projectId, caller: _msgSender()});
    }

    /// @notice Always returns 0 because the registry holds no project balances to migrate.
    /// @param projectId Unused.
    /// @param token Unused.
    /// @param to Unused.
    /// @return balance Always 0.
    function migrateBalanceOf(
        uint256 projectId,
        address token,
        IJBTerminal to
    )
        external
        pure
        override
        returns (uint256)
    {
        projectId;
        token;
        to;
        return 0;
    }

    /// @notice Pay a project by accepting the caller's tokens and forwarding them to the project's resolved router
    /// terminal.
    /// @dev Uses the project-specific terminal when set, otherwise falls back to `defaultTerminal`.
    /// @param projectId The ID of the project to pay.
    /// @param token The address of the token to pay with.
    /// @param amount The amount of tokens to send.
    /// @param beneficiary The address that will receive any project tokens minted by the destination.
    /// @param minReturnedTokens The minimum number of project tokens expected in return.
    /// @param memo A memo to pass along to the emitted event.
    /// @param metadata Bytes in `JBMetadataResolver`'s format (may include `permit2` allowance data).
    /// @return result The number of project tokens minted for the beneficiary.
    function pay(
        uint256 projectId,
        address token,
        uint256 amount,
        address beneficiary,
        uint256 minReturnedTokens,
        string calldata memo,
        bytes calldata metadata
    )
        external
        payable
        virtual
        override
        returns (uint256 result)
    {
        // Resolve the terminal that should receive this forwarded payment before accepting funds.
        IJBTerminal terminal = _requireResolvedTerminalOf(projectId);

        // Accept the funds for the token.
        amount = _acceptFundsFor({token: token, amount: amount, metadata: metadata});

        // Trigger any pre-transfer logic.
        uint256 payValue = _beforeTransferFor({to: address(terminal), token: token, amount: amount});

        // Save any previous payer so nested reentrant calls through pay hooks restore correctly.
        address previousPayer = originalPayer;

        // Store the original payer in transient storage so downstream router terminals can refund partial-fill
        // leftovers to the true payer. If the immediate caller is itself a forwarding intermediary that exposes
        // its own original payer, propagate that — otherwise refunds in nested forwards stop at the intermediary.
        originalPayer = _originalPayerOrSender();

        // Reject forwards that would bounce straight back into this call's immediate caller.
        _enforceNoCircularForward(terminal);

        // Forward the payment to the terminal.
        result = terminal.pay{value: payValue}({
            projectId: projectId,
            token: token,
            amount: amount,
            beneficiary: beneficiary,
            minReturnedTokens: minReturnedTokens,
            memo: memo,
            metadata: metadata
        });

        // Revoke any leftover allowance the terminal did not pull.
        if (token != JBConstants.NATIVE_TOKEN) IERC20(token).forceApprove({spender: address(terminal), value: 0});

        // Restore the previous payer (supports nested reentrant calls through pay hooks).
        originalPayer = previousPayer;
    }

    /// @notice Change the registry-wide default terminal for projects created AFTER this call.
    /// @dev Only the registry owner can call this. Automatically allowlists the new default.
    /// The very first call also maps every project that already existed onto the new default (via a
    /// history segment) so those pre-existing projects — including the canonical fee project (ID 1) —
    /// can route tokens through it. Existing projects (ID <= current `PROJECTS.count()` at call time)
    /// keep their historical default on later changes — the previous `defaultTerminal` is pushed onto
    /// `_defaultTerminalHistory` so fall-through resolution for those projects continues to return what
    /// was current when their cohort was last addressed. This means a later default change never
    /// silently reroutes payments for already-deployed projects that never set an explicit
    /// `_terminalOf` override.
    /// @param terminal The terminal to set as the default for future projects.
    function setDefaultTerminal(IJBTerminal terminal) external onlyOwner {
        if (address(terminal) == address(0)) revert JBRouterTerminalRegistry_ZeroAddress(address(terminal));
        if (address(terminal) == address(this)) revert JBRouterTerminalRegistry_CircularForward(terminal);

        uint256 count = PROJECTS.count();

        // Reject defaults that would route any current project back into the registry through a
        // transitive forwarding chain. Probed at the current project-count snapshot since the
        // default is what unconfigured (and all-future) projects will resolve to.
        _requireNonCircularTerminalFor({projectId: count, terminal: terminal});

        // Record a history segment for the cohort whose IDs fall in the half-open range `(prevThreshold,
        // currentCount]`. On the first call ever (`defaultTerminal == 0`) the segment maps the projects that already
        // existed — including the canonical fee project (ID 1) — onto the NEW default so they can route tokens
        // through
        // it instead of resolving to nothing. On every later call the segment instead pins the OUTGOING default to its
        // own cohort, so projects whose IDs were issued while it was active keep resolving to it and a default change
        // never silently reroutes an already-deployed project.
        _defaultTerminalHistory.push(
            DefaultTerminalSegment({
                minProjectIdExclusive: defaultTerminalProjectIdThreshold,
                maxProjectId: count,
                terminal: address(defaultTerminal) != address(0) ? defaultTerminal : terminal
            })
        );

        defaultTerminal = terminal;
        defaultTerminalProjectIdThreshold = count;

        // Allow the default terminal.
        isTerminalAllowed[terminal] = true;

        emit JBRouterTerminalRegistry_SetDefaultTerminal({terminal: terminal, caller: _msgSender()});
    }

    /// @notice Choose which router terminal a project's payments are forwarded through.
    /// @dev Only the project's owner or an address with the `JBPermissionIds.SET_ROUTER_TERMINAL` permission can set.
    /// @param projectId The ID of the project to set the terminal for.
    /// @param terminal The terminal to set for the project.
    function setTerminalFor(uint256 projectId, IJBTerminal terminal) external {
        // Make sure the terminal is not locked.
        if (hasLockedTerminal[projectId]) revert JBRouterTerminalRegistry_TerminalLocked(projectId);

        if (!isTerminalAllowed[terminal]) revert JBRouterTerminalRegistry_TerminalNotAllowed(terminal);

        // Reject a terminal that would forward this project back into the registry before saving it.
        _requireNonCircularTerminalFor({projectId: projectId, terminal: terminal});

        // Enforce permissions.
        _requirePermissionFrom({
            account: PROJECTS.ownerOf(projectId),
            projectId: projectId,
            permissionId: JBPermissionIds.SET_ROUTER_TERMINAL
        });

        _terminalOf[projectId] = terminal;

        emit JBRouterTerminalRegistry_SetTerminal({projectId: projectId, terminal: terminal, caller: _msgSender()});
    }

    //*********************************************************************//
    // ---------------------- internal transactions ---------------------- //
    //*********************************************************************//

    /// @notice Accept a token paid in by the caller.
    /// @dev Measures the actual received balance so forwarded amounts stay in sync with lossy ERC-20 transfers.
    /// @param token The address of the token to accept.
    /// @param amount The amount of tokens to accept.
    /// @param metadata The metadata in which `permit2` context is provided.
    /// @return amount The amount of tokens accepted.
    function _acceptFundsFor(address token, uint256 amount, bytes calldata metadata) internal returns (uint256) {
        // If native tokens are being paid in, return the `msg.value`.
        if (token == JBConstants.NATIVE_TOKEN) return msg.value;

        // Otherwise, the `msg.value` should be 0.
        if (msg.value != 0) revert JBRouterTerminalRegistry_NoMsgValueAllowed(msg.value);

        // Unpack the `JBSingleAllowance` to use given by the frontend.
        (bool exists, bytes memory parsedMetadata) =
            JBMetadataResolver.getDataFor({id: JBMetadataResolver.getId("permit2"), metadata: metadata});

        // If the metadata contained permit data, use it to set the allowance.
        if (exists) {
            // Keep a reference to the allowance context parsed from the metadata.
            (JBSingleAllowance memory allowance) = abi.decode(parsedMetadata, (JBSingleAllowance));

            // Make sure the permit allowance is enough for this payment.
            if (amount > allowance.amount) {
                revert JBRouterTerminalRegistry_PermitAllowanceNotEnough({
                    amount: amount, allowanceAmount: allowance.amount
                });
            }

            // Keep a reference to the permit rules.
            IAllowanceTransfer.PermitSingle memory permitSingle = IAllowanceTransfer.PermitSingle({
                details: IAllowanceTransfer.PermitDetails({
                    token: token, amount: allowance.amount, expiration: allowance.expiration, nonce: allowance.nonce
                }),
                spender: address(this),
                sigDeadline: allowance.sigDeadline
            });

            try PERMIT2.permit({owner: _msgSender(), permitSingle: permitSingle, signature: allowance.signature}) {}
            catch (bytes memory reason) {
                // Emit a failure event so callers can surface the permit2 error reason.
                emit Permit2AllowanceFailed({token: token, owner: _msgSender(), reason: reason, caller: _msgSender()});
            }
        }

        // Measure the actual received balance so downstream forwarding uses what arrived, not the caller's nominal
        // amount.
        uint256 balanceBefore = IERC20(token).balanceOf(address(this));

        // Transfer the tokens from the `_msgSender()` to this terminal.
        _transferFrom({from: _msgSender(), to: payable(address(this)), token: token, amount: amount});

        return IERC20(token).balanceOf(address(this)) - balanceBefore;
    }

    /// @notice Logic to trigger before transferring tokens from this terminal.
    /// @param to The address to transfer tokens to.
    /// @param token The token to transfer.
    /// @param amount The amount of tokens to transfer.
    /// @return payValue The amount that will be paid as a `msg.value`.
    function _beforeTransferFor(address to, address token, uint256 amount) internal virtual returns (uint256) {
        // If the token is the native token, return early.
        if (token == JBConstants.NATIVE_TOKEN) return amount;

        // Reset-then-set: avoid reverts from tokens that disallow non-zero to non-zero approval changes.
        IERC20(token).forceApprove({spender: to, value: amount});

        return 0;
    }

    /// @notice Transfer tokens from one address to another using direct approval, `safeTransfer`, or Permit2 fallback.
    /// @param from The address to transfer tokens from.
    /// @param to The address to transfer tokens to.
    /// @param token The address of the token to transfer.
    /// @param amount The amount of tokens to transfer.
    function _transferFrom(address from, address payable to, address token, uint256 amount) internal virtual {
        if (from == address(this)) {
            // If the token is native token, assume the `sendValue` standard.
            if (token == JBConstants.NATIVE_TOKEN) return Address.sendValue({recipient: to, amount: amount});

            // If the transfer is from this terminal, use `safeTransfer`.
            return IERC20(token).safeTransfer({to: to, value: amount});
        }

        // If there's sufficient approval, transfer normally.
        if (IERC20(token).allowance({owner: address(from), spender: address(this)}) >= amount) {
            return IERC20(token).safeTransferFrom({from: from, to: to, value: amount});
        }

        // Otherwise, attempt to use the `permit2` method.
        if (amount > type(uint160).max) revert JBRouterTerminalRegistry_AmountOverflow(amount);
        // forge-lint: disable-next-line(unsafe-typecast)
        PERMIT2.transferFrom({from: from, to: to, amount: uint160(amount), token: token});
    }
}

