pragma solidity 0.8.28;

// External packages (alphabetized).
import {JBPermissioned} from "@bananapus/core-v6/src/abstract/JBPermissioned.sol";
import {IJBDirectory} from "@bananapus/core-v6/src/interfaces/IJBDirectory.sol";
import {IJBPermissions} from "@bananapus/core-v6/src/interfaces/IJBPermissions.sol";
import {IJBTokens} from "@bananapus/core-v6/src/interfaces/IJBTokens.sol";
import {ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import {Context} from "@openzeppelin/contracts/utils/Context.sol";
import {LibClone} from "solady/src/utils/LibClone.sol";

// Local: contracts.
import {JBSucker} from "../JBSucker.sol";

// Local: interfaces (alphabetized).
import {IJBSucker} from "../interfaces/IJBSucker.sol";
import {IJBSuckerDeployer} from "../interfaces/IJBSuckerDeployer.sol";

/// @notice Base factory for deploying cross-chain suckers using CREATE2 clones. Each bridge-specific deployer (OP,
/// Arbitrum, CCIP) extends this contract with its own chain configuration. Setup is two-step: first the configurator
/// calls `setChainSpecificConstants` (bridge addresses, chain selectors), then `configureSingleton` (the
/// implementation to clone). After setup, anyone may call `createForSender` to deploy a new sucker for a project.
abstract contract JBSuckerDeployer is ERC2771Context, JBPermissioned, IJBSuckerDeployer {
    //*********************************************************************//
    // --------------------------- custom errors ------------------------- //
    //*********************************************************************//

    /// @notice Thrown when configuration is attempted but the deployer (singleton or layer-specific config) has already
    /// been configured.
    error JBSuckerDeployer_AlreadyConfigured(address singleton, bool layerSpecificConfigurationIsSet);

    /// @notice Thrown when a sucker is deployed before the deployer's singleton implementation has been set.
    error JBSuckerDeployer_DeployerIsNotConfigured(address singleton);

    /// @notice Thrown when the layer-specific configuration is not properly set after configuration.
    error JBSuckerDeployer_InvalidLayerSpecificConfiguration(address configurator);

    /// @notice Thrown when a sucker is deployed before the layer-specific configuration has been set.
    error JBSuckerDeployer_LayerSpecificNotConfigured(address configurator);

    /// @notice Thrown when the caller is not the address authorized to configure this deployer.
    error JBSuckerDeployer_Unauthorized(address caller, address expected);

    /// @notice Thrown when the configurator address provided is the zero address.
    error JBSuckerDeployer_ZeroConfiguratorAddress(address configurator);

    //*********************************************************************//
    // --------------- public immutable stored properties ---------------- //
    //*********************************************************************//

    /// @notice The directory of terminals and controllers for projects.
    IJBDirectory public immutable override DIRECTORY;

    /// @notice Only this address can configure this deployer, can only be used once.
    address public immutable override LAYER_SPECIFIC_CONFIGURATOR;

    /// @notice The contract that manages token minting and burning.
    IJBTokens public immutable override TOKENS;

    //*********************************************************************//
    // ---------------------- public stored properties ------------------- //
    //*********************************************************************//

    /// @notice Whether a given address was deployed by this deployer.
    /// @custom:param sucker The address to check.
    mapping(address sucker => bool) public override isSucker;

    /// @notice The singleton used to clone suckers.
    /// @dev Write-once via `configureSingleton`; the clone implementation for every sucker this deployer produces.
    JBSucker public singleton;

    //*********************************************************************//
    // ---------------------------- constructor -------------------------- //
    //*********************************************************************//

    /// @param directory The directory of terminals and controllers for projects.
    /// @param permissions The permissions contract for the deployer.
    /// @param tokens The contract that manages token minting and burning.
    /// @param configurator The address of the configurator.
    /// @param trustedForwarder The trusted forwarder for ERC-2771 meta-transactions.
    constructor(
        IJBDirectory directory,
        IJBPermissions permissions,
        IJBTokens tokens,
        address configurator,
        address trustedForwarder
    )
        ERC2771Context(trustedForwarder)
        JBPermissioned(permissions)
    {
        // Store the directory.
        DIRECTORY = directory;

        // Store the tokens contract.
        TOKENS = tokens;

        // Store the layer-specific configurator address.
        LAYER_SPECIFIC_CONFIGURATOR = configurator;

        // There has to be a configurator address or the layer specific configuration has to already be configured.
        if (configurator == address(0) && !_layerSpecificConfigurationIsSet()) {
            revert JBSuckerDeployer_ZeroConfiguratorAddress({configurator: configurator});
        }
    }

    //*********************************************************************//
    // ------------------------ internal views --------------------------- //
    //*********************************************************************//

    /// @dev ERC-2771 specifies the context as being a single address (20 bytes).
    /// @return The length of the context suffix in bytes.
    function _contextSuffixLength() internal view virtual override(ERC2771Context, Context) returns (uint256) {
        return ERC2771Context._contextSuffixLength();
    }

    /// @notice Check if the layer specific configuration is set or not. Used as a sanity check.
    /// @return A flag indicating whether the layer specific configuration has been set.
    function _layerSpecificConfigurationIsSet() internal view virtual returns (bool);

    /// @notice The calldata. Preferred to use over `msg.data`.
    /// @return calldata The `msg.data` of this call.
    function _msgData() internal view override(ERC2771Context, Context) returns (bytes calldata) {
        return ERC2771Context._msgData();
    }

    /// @notice The message's sender. Preferred to use over `msg.sender`.
    /// @return sender The address which sent this call.
    function _msgSender() internal view override(ERC2771Context, Context) returns (address sender) {
        return ERC2771Context._msgSender();
    }

    //*********************************************************************//
    // --------------------- external transactions ----------------------- //
    //*********************************************************************//

    /// @notice Set the implementation contract that all future suckers will be cloned from. Can only be called once.
    /// @dev Must be called by the layer-specific configurator after `setChainSpecificConstants`.
    /// @param _singleton The address of the singleton.
    function configureSingleton(JBSucker _singleton) external {
        // Make sure only the configurator can call this function.
        if (_msgSender() != LAYER_SPECIFIC_CONFIGURATOR) {
            revert JBSuckerDeployer_Unauthorized({caller: _msgSender(), expected: LAYER_SPECIFIC_CONFIGURATOR});
        }

        // Ensure that the layer specific configuration is set.
        if (!_layerSpecificConfigurationIsSet()) {
            revert JBSuckerDeployer_LayerSpecificNotConfigured({configurator: LAYER_SPECIFIC_CONFIGURATOR});
        }

        // Make sure the singleton is not already configured.
        if (address(singleton) != address(0)) {
            revert JBSuckerDeployer_AlreadyConfigured({
                singleton: address(singleton), layerSpecificConfigurationIsSet: _layerSpecificConfigurationIsSet()
            });
        }

        // Store the singleton.
        singleton = _singleton;
    }

    /// @notice Deploy a new sucker clone for a project via CREATE2. The same sender must call this on both chains to
    /// produce matching deterministic addresses.
    /// @dev Called by the registry during `deploySuckersFor`.
    /// @param localProjectId The project's ID on the local chain.
    /// @param salt The salt to use for the `create2` address.
    /// @param peer The remote peer address. Leave zero to use the default deterministic same-address peer.
    /// @return sucker The address of the new sucker.
    function createForSender(
        uint256 localProjectId,
        bytes32 salt,
        bytes32 peer
    )
        external
        override(IJBSuckerDeployer)
        returns (IJBSucker sucker)
    {
        // Make sure that this deployer is configured properly.
        if (address(singleton) == address(0)) {
            revert JBSuckerDeployer_DeployerIsNotConfigured({singleton: address(singleton)});
        }

        // Hash the salt with the sender address to ensure only a specific sender can create this sucker.
        salt = keccak256(abi.encodePacked(_msgSender(), salt));

        // Clone the singleton.
        sucker = IJBSucker(LibClone.cloneDeterministic({implementation: address(singleton), salt: salt}));

        // Mark it as a sucker that was deployed by this deployer.
        isSucker[address(sucker)] = true;

        // Initialize the clone.
        JBSucker(payable(address(sucker))).initialize({localProjectId: localProjectId, remotePeer: peer});
    }
}

