            try IJBSucker(allSuckers[i]).peerChainIds(true) returns (uint256[] memory chainIds) {
                chainIdsBySucker[i] = chainIds;
                totalChains += chainIds.length;
            } catch {
                chainIdsBySucker[i] = new uint256[](0);
            }
            unchecked {
                ++i;
            }
        }
    }

