    function _recordPeerChainValue(
        PeerValueScratch memory scratch,
        JBPeerChainValue memory read,
        address sucker,
        bool isActive
    )
        internal
        pure
        returns (uint256)
    {
        if (read.peerChainId == 0) revert JBSuckerRegistry_ZeroPeerChainId({sucker: sucker});
